class _DiscordHttpRateLimitFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        message = record.getMessage()
        return not (
            "We are being rate limited" in message
            and "responded with 429" in message
        )


logging.getLogger("discord.http").addFilter(_DiscordHttpRateLimitFilter())


_UNKNOWN_INTERACTION_ERROR_CODE = 10062
_UNKNOWN_WEBHOOK_ERROR_CODE = 10015


def is_unknown_interaction_error(exc: Exception) -> bool:
    """Return True when Discord rejected an expired interaction token/webhook."""
    return (
        isinstance(exc, discord.NotFound)
        and getattr(exc, "code", None)
        in {_UNKNOWN_INTERACTION_ERROR_CODE, _UNKNOWN_WEBHOOK_ERROR_CODE}
    )


async def _ignore_unknown_interaction(coro):
    try:
        return await coro
    except (aiohttp.ClientOSError, ConnectionResetError) as exc:
        # Discord occasionally resets a keep-alive connection while a component
        # response (for example, opening a modal) is being sent.  The
        # interaction cannot be retried safely after that point, but letting
        # the exception escape makes discord.py log it as an unhandled view
        # callback error.
        logging.getLogger(__name__).warning(
            "Discord connection was reset while responding to an interaction; "
            "ignoring transient error: %s",
            exc,
        )
        return None
    except discord.NotFound as exc:
        if is_unknown_interaction_error(exc):
            if getattr(exc, "code", None) == _UNKNOWN_WEBHOOK_ERROR_CODE:
                logging.getLogger(__name__).warning(
                    "Discord followup webhook expired before the bot could respond; "
                    "ignored error code %s.",
                    getattr(exc, "code", None),
                )
            else:
                logging.getLogger(__name__).warning(
                    "Discord interaction expired before the bot could respond; "
                    "ignored error code %s.",
                    getattr(exc, "code", None),
                )
            return None
        raise


_ORIGINAL_INTERACTION_RESPONSE_DEFER = discord.InteractionResponse.defer
_ORIGINAL_INTERACTION_RESPONSE_SEND_MESSAGE = discord.InteractionResponse.send_message
_ORIGINAL_INTERACTION_RESPONSE_EDIT_MESSAGE = discord.InteractionResponse.edit_message
_ORIGINAL_INTERACTION_RESPONSE_SEND_MODAL = discord.InteractionResponse.send_modal
_ORIGINAL_WEBHOOK_SEND = getattr(discord.Webhook, "send", None)


async def _safe_interaction_response_defer(self, *args, **kwargs):
    return await _ignore_unknown_interaction(
        _ORIGINAL_INTERACTION_RESPONSE_DEFER(self, *args, **kwargs)
    )


async def _safe_interaction_response_send_message(self, *args, **kwargs):
    return await _ignore_unknown_interaction(
        _ORIGINAL_INTERACTION_RESPONSE_SEND_MESSAGE(self, *args, **kwargs)
    )


async def _safe_interaction_response_edit_message(self, *args, **kwargs):
    return await _ignore_unknown_interaction(
        _ORIGINAL_INTERACTION_RESPONSE_EDIT_MESSAGE(self, *args, **kwargs)
    )


async def _safe_interaction_response_send_modal(self, *args, **kwargs):
    return await _ignore_unknown_interaction(
        _ORIGINAL_INTERACTION_RESPONSE_SEND_MODAL(self, *args, **kwargs)
    )


discord.InteractionResponse.defer = _safe_interaction_response_defer
discord.InteractionResponse.send_message = _safe_interaction_response_send_message
discord.InteractionResponse.edit_message = _safe_interaction_response_edit_message
discord.InteractionResponse.send_modal = _safe_interaction_response_send_modal


async def _safe_webhook_send(self, *args, **kwargs):
    return await _ignore_unknown_interaction(
        _ORIGINAL_WEBHOOK_SEND(self, *args, **kwargs)
    )


if _ORIGINAL_WEBHOOK_SEND is not None:
    discord.Webhook.send = _safe_webhook_send

