# ================== ERROR REPORTING ==================
# The panel may configure a private Discord channel for operational failures.
# A logging handler observes the same ERROR records that are written to the
# host console, so command, view, task, and library failures arrive there with
# their traceback without changing individual error handlers.
_discord_event_loop: asyncio.AbstractEventLoop | None = None


async def send_error_log_to_discord(message: str) -> None:
    """Deliver one console error record to the configured Discord channel."""
    channel_id = (globals().get("settings") or {}).get("error_log_channel")
    if not channel_id:
        return

    try:
        channel = bot.get_channel(int(channel_id))
        if channel is None:
            channel = await bot.fetch_channel(int(channel_id))
        if not isinstance(channel, discord.abc.Messageable):
            return
        # Discord messages are limited to 2,000 characters.  Keep the newest
        # part of a traceback, which usually contains the exception itself.
        body = message[-1_850:]
        await channel.send(f"🚨 **Ошибка бота**\n```\n{body}\n```")
    except Exception:
        # Never log delivery failures: doing so would feed this handler again.
        pass


class DiscordErrorLogHandler(logging.Handler):
    """Forward ERROR-level console records to the configured Discord channel."""

    def emit(self, record: logging.LogRecord) -> None:
        if record.name.startswith("discord.error_reporter"):
            return
        loop = _discord_event_loop
        if loop is None or loop.is_closed():
            return
        try:
            message = self.format(record)
            loop.call_soon_threadsafe(
                lambda: asyncio.create_task(send_error_log_to_discord(message))
            )
        except Exception:
            self.handleError(record)


def install_discord_error_log_handler() -> None:
    root_logger = logging.getLogger()
    # Adding a handler to an otherwise untouched root logger disables
    # logging's automatic console configuration, so preserve that output.
    if not root_logger.handlers:
        logging.basicConfig(level=logging.WARNING)
    if any(
        isinstance(handler, DiscordErrorLogHandler)
        for handler in root_logger.handlers
    ):
        return
    handler = DiscordErrorLogHandler(level=logging.ERROR)
    handler.setFormatter(logging.Formatter(
        "%(asctime)s [%(levelname)s] %(name)s: %(message)s"
    ))
    root_logger.addHandler(handler)


install_discord_error_log_handler()


