# ================== HELPERS ==================
def ensure_user(user_id: str):
    if user_id not in balances or not isinstance(balances[user_id], dict):
        balances[user_id] = {"наличка": 0, "банк": 0, "заморожено": 0, "коины": 0}
        save_json(BALANCES_FILE, balances)
    else:
        balances[user_id].setdefault("заморожено", 0)
        balances[user_id].setdefault("коины", 0)
    return balances[user_id]



def get_economy_rank(user_id: str):
    data = []
    for uid, user in balances.items():
        if uid == "валюта" or not isinstance(user, dict) or not is_registered_country_user(uid):
            continue
        total_available = int(user.get("наличка", 0)) - int(user.get("заморожено", 0)) + int(user.get("банк", 0))
        data.append((uid, total_available))
    data.sort(key=lambda row: row[1], reverse=True)
    for idx, (uid, total_available) in enumerate(data, start=1):
        if str(uid) == str(user_id):
            return idx, len(data), total_available
    return None, len(data), None


def get_user_economy_total(user_id: str) -> int:
    user = ensure_user(str(user_id))
    return int(user.get("наличка", 0)) + int(user.get("банк", 0))


def capture_economy_baseline(user_ids: set[str] | None = None):
    target_ids = set(user_ids or get_all_registered_user_ids())
    snapshots = economy_snapshots.setdefault("users", {})
    for uid in target_ids:
        if is_registered_country_user(uid):
            snapshots[str(uid)] = get_user_economy_total(str(uid))
    economy_snapshots["baseline_at"] = int(time.time())
    save_economy_snapshots()


def ensure_economy_baseline_for_user(user_id: str):
    uid = str(user_id)
    if uid not in economy_snapshots.setdefault("users", {}):
        economy_snapshots["users"][uid] = get_user_economy_total(uid)
        save_economy_snapshots()


def get_economy_change_percent(user_id: str) -> str:
    baseline = economy_snapshots.setdefault("users", {}).get(str(user_id))
    if baseline is None:
        ensure_economy_baseline_for_user(str(user_id))
        baseline = economy_snapshots["users"].get(str(user_id), 0)
    current = get_user_economy_total(str(user_id))
    try:
        base_value = int(baseline or 0)
    except (TypeError, ValueError):
        base_value = 0
    if base_value == 0:
        if current == 0:
            return "+0%"
        return "*"
    percent = round(((current - base_value) / base_value) * 100, 1)
    return f"{percent:+g}%"

def add_balance(user_id: str, amount: int):
    user = ensure_user(user_id)
    user["наличка"] += amount
    save_json(BALANCES_FILE, balances)


