def parse_yes_no(raw: str) -> bool:
    text = str(raw or "").strip().lower()
    if text in {"да", "yes", "y", "true", "1", "on"}:
        return True
    if text in {"нет", "no", "n", "false", "0", "off", "скип", ""}:
        return False
    raise ValueError("Введите `да` или `нет`.")


def bool_to_yes_no(value: bool) -> str:
    return "да" if bool(value) else "нет"


def preserve_item_in_tech_library(item_key: str, item_payload: dict, reason: str):
    if not isinstance(item_payload, dict) or not bool(item_payload.get("save_to_library", False)):
        return
    library = items_data.setdefault("tech_library", {})
    snapshot = json.loads(json.dumps(item_payload))
    snapshot["key"] = item_key
    snapshot["last_removed_at"] = int(time.time())
    snapshot["last_removed_reason"] = reason
    snapshot.pop("season", None)
    snapshot.pop("saved_season", None)
    library[item_key] = snapshot


def backfill_saved_items_to_tech_library():
    changed = False
    for item_key, item_payload in items_data.setdefault("items", {}).items():
        if not isinstance(item_payload, dict) or not bool(item_payload.get("save_to_library", False)):
            continue
        if item_key in items_data.setdefault("tech_library", {}):
            continue
        preserve_item_in_tech_library(str(item_key), item_payload, reason="сохранение в библиотеку")
        changed = True
    if changed:
        save_items()


