def parse_role_mentions(raw: str):
    if raw.lower() == "скип":
        return []
    role_ids = []
    for token in raw.split():
        token = token.replace("<@&", "").replace(">", "")
        role_ids.append(int(token))
    return role_ids


def format_interval(seconds: int) -> str:
    seconds = int(seconds)
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, secs = divmod(rem, 60)
    parts = []
    if days:
        parts.append(f"{days}д")
    if hours:
        parts.append(f"{hours}ч")
    if minutes:
        parts.append(f"{minutes}м")
    if secs or not parts:
        parts.append(f"{secs}с")
    return " ".join(parts)


def discord_time(ts: int, style: str = "t") -> str:
    return f"<t:{int(ts)}:{style}>"


def cooldown_ready_time(now_ts: int, seconds_left: int) -> str:
    return discord_time(int(now_ts) + max(0, int(seconds_left)), "t")


REQUEST_COOLDOWN_LABELS = {
    "verdicts": "вердикты",
    "spheres": "сферы",
    "companies": "компании",
    "investments": "инвестиции",
    "partnerships": "партнёрства",
    "events": "ивенты",
}


def get_request_cooldown_left(user_id: str, request_type: str, now_ts: int | None = None) -> int:
    now_ts = int(now_ts or time.time())
    cooldowns = settings.setdefault("request_cooldowns", {})
    last_submit = settings.setdefault("request_last_submit", {})
    cooldown = max(0, int(cooldowns.get(request_type, 0) or 0))
    if cooldown <= 0:
        return 0
    user_map = last_submit.get(str(user_id), {})
    if not isinstance(user_map, dict):
        return 0
    last_ts = int(user_map.get(request_type, 0) or 0)
    return max(0, cooldown - (now_ts - last_ts))


def mark_request_submitted(user_id: str, request_type: str, now_ts: int | None = None):
    settings.setdefault("request_last_submit", {}).setdefault(str(user_id), {})[request_type] = int(now_ts or time.time())
    save_json(SETTINGS_FILE, settings)


async def deny_if_request_cooldown(interaction: Interaction, request_type: str) -> bool:
    left = get_request_cooldown_left(str(interaction.user.id), request_type)
    if left <= 0:
        return False
    label = REQUEST_COOLDOWN_LABELS.get(request_type, request_type)
    await interaction.response.send_message(
        f"❌ КД на заявки типа **{label}** ещё не прошёл. Повторная подача будет доступна {cooldown_ready_time(int(time.time()), left)}.",
        ephemeral=True,
    )
    return True


def fmt_num(value: int | float) -> str:
    try:
        num = int(value)
    except Exception:
        num = 0
    return f"{num:,}".replace(",", ".")


def fmt_money(value: int | float) -> str:
    return f"{fmt_num(value)} {currency}"


def format_money_like_text(value, fallback_base: int = 1) -> str:
    text = str(value or "").strip()
    if not text:
        return "—"
    try:
        return fmt_money(parse_money_value(text, max(1, int(fallback_base or 1))))
    except Exception:
        return text


def fmt_passive_amount(value) -> str:
    text = str(value).strip()
    if text.endswith("%"):
        return text
    try:
        return fmt_money(int(float(text.replace(",", "."))))
    except Exception:
        return f"{text} {currency}" if text else f"0 {currency}"


def format_verdict_source_line(entry: dict) -> str:
    url = str(entry.get("verdict_result_url") or entry.get("verdict_message_url") or "").strip()
    if not url:
        return ""
    return f"\n-#  ➥ **Выдано вердиктом:** {url}"


def format_event_source_line(entry: dict) -> str:
    url = str(entry.get("source_event_url") or entry.get("event_url") or "").strip()
    event_id = str(entry.get("source_event_id") or entry.get("event_id") or "").strip()
    if url:
        return f"\n-#  ➥ **Выдано ивентом:** {url}"
    if event_id:
        return f"\n-#  ➥ **Выдано ивентом:** #{event_id}"
    return ""




def format_next_passive_action(entry: dict, *, default_ready: bool = False) -> str:
    try:
        cooldown = max(1, int(entry.get("cooldown", 0) or 0))
    except (TypeError, ValueError):
        return "неизвестно"
    now_ts = int(time.time())
    try:
        last_run = int(entry.get("last_run", entry.get("last_ts", 0)) or 0)
    except (TypeError, ValueError):
        last_run = 0

    # Показываем именно следующий плановый тик, а не момент просмотра
    # баланса. Если операция уже просрочена, автолуп обработает
    # накопленные циклы и следующим станет первый тик после них.
    if last_run <= 0:
        next_ts = now_ts + cooldown
    else:
        missed_cycles = max(0, (now_ts - last_run) // cooldown)
        next_ts = last_run + (missed_cycles + 1) * cooldown
    return f"<t:{int(next_ts)}:R>"


async def apply_due_money_passives_for_user(guild, user_id: str, *, now_ts: int | None = None) -> bool:
    """Apply overdue passive income/expense cycles for one user immediately."""
    now_ts = int(now_ts or time.time())
    if should_skip_afk_user(str(user_id), now_ts):
        return False
    entries = get_passive_entries(str(user_id))
    if not isinstance(entries, list):
        return False

    user = ensure_user(str(user_id))
    changed = False
    for entry in list(entries):
        try:
            expires_at = entry.get("expires_at")
            if expires_at is not None and now_ts >= int(expires_at):
                entries.remove(entry)
                changed = True
                continue

            cooldown = int(entry.get("cooldown", 0) or 0)
            amount_raw = str(entry.get("amount", 0))
            if cooldown <= 0:
                continue
            if "last_run" not in entry:
                last_ts = int(entry.get("last_ts", 0) or 0)
                entry["last_run"] = last_ts if last_ts > 0 else now_ts
                entry.pop("last_ts", None)
                changed = True
                continue
            last_run = int(entry.get("last_run", now_ts) or now_ts)
            if last_run > now_ts:
                entry["last_run"] = now_ts
                changed = True
                continue
        except (TypeError, ValueError):
            print(f"[PASSIVE_BALANCE] Некорректная пассивная операция: user={user_id} entry={entry!r}")
            continue
        if now_ts - last_run < cooldown:
            continue

        cycles = (now_ts - last_run) // cooldown
        try:
            per_cycle = parse_money_value(amount_raw, user.get("наличка", 0))
        except Exception:
            per_cycle = 0
        if per_cycle <= 0:
            entry["last_run"] = last_run + cycles * cooldown
            changed = True
            continue

        delta = per_cycle * cycles
        if entry.get("type") == "expense":
            user["наличка"] -= delta
            delta = -delta
        else:
            user["наличка"] += delta

        entry["last_run"] = last_run + cycles * cooldown
        changed = True
        await log_economy_change(
            guild,
            str(user_id),
            f"Автопассив ({'расход' if entry.get('type') == 'expense' else 'доход'}): {entry.get('description', 'без описания')}",
            cash_delta=int(delta),
        )

    return changed

def strip_legacy_tech_description(description: str) -> str:
    lines = [line.rstrip() for line in str(description or "").splitlines()]
    if len(lines) >= 2 and lines[0].startswith("Тип техники:") and lines[1].startswith("Оценка техники:"):
        lines = lines[2:]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines).strip()


def parse_production_requirements(required_item, required_quantity) -> list[tuple[str, int]]:
    """Return validated comma-separated production resources and their quantities."""
    names = [part.strip() for part in str(required_item or "").split(",") if part.strip()]
    quantities = [part.strip() for part in str(required_quantity or "").split(",") if part.strip()]
    if not names and not quantities:
        return []
    if len(names) != len(quantities):
        raise ValueError("Количество ресурсов должно соответствовать ресурсам: используйте запятую в обоих полях.")
    try:
        parsed = [max(0, int(value)) for value in quantities]
    except ValueError as exc:
        raise ValueError("Количество каждого ресурса должно быть целым числом.") from exc
    return [(name, quantity) for name, quantity in zip(names, parsed) if quantity > 0]


def format_production_requirements(required_item, required_quantity) -> str:
    requirements = parse_production_requirements(required_item, required_quantity)
    return ", ".join(f"{quantity} {name}" for name, quantity in requirements) or "—"


def format_item_production_line(item: dict) -> str:
    if item.get("item_kind") != "tech":
        return ""
    req_item = item.get("required_item") or item.get("production_required_item") or ""
    req_qty = item.get("required_quantity", item.get("production_required_quantity", 0))
    batch = max(1, int(item.get("production_batch_min", item.get("min_production", 1)) or 1))
    try:
        requirements = format_production_requirements(req_item, req_qty)
    except ValueError:
        requirements = "—"
    return f"-# **Производство:** {requirements} / {batch}шт"


def format_shop_item_description(item: dict, count: str) -> str:
    lines = [
        f"**{item['key']}** — {fmt_money(item['price'])}",
        f"-# **Количество:** {count}",
    ]
    description = strip_legacy_tech_description(str(item.get("description") or ""))
    if item.get("item_kind") == "tech":
        lines.extend(
            [
                f"-# **Тип техники:** {item.get('tech_type') or '—'}",
                f"-# **Оценка техники:** {int(item.get('tech_rating', 0) or 0)}/100",
            ]
        )
    if description:
        lines.append(f"-# **Описание:** {description.replace(chr(10), chr(10) + '-# ')}")
    production_line = format_item_production_line(item)
    if production_line:
        lines.append(production_line)
    return "\n".join(lines)


def item_required_role_ids(item: dict) -> list[int | str]:
    """Return item and category access roles without duplicates."""
    category_roles = items_data.setdefault("category_require_roles", {}).get(
        str(item.get("category")), []
    )
    return list(dict.fromkeys([*item.get("require_roles", []), *category_roles]))


def format_inventory_item_description(item: dict, quantity: int) -> str:
    """Shop-style inventory entry: quantity replaces the shop price."""
    lines = [f"**{item['key']}** — {quantity} шт."]
    description = strip_legacy_tech_description(str(item.get("description") or ""))
    if item.get("item_kind") == "tech":
        lines.extend([
            f"-# **Тип техники:** {item.get('tech_type') or '—'}",
            f"-# **Оценка техники:** {int(item.get('tech_rating', 0) or 0)}/100",
        ])
    if description:
        lines.append(f"-# **Описание:** {description.replace(chr(10), chr(10) + '-# ')}")
    production_line = format_item_production_line(item)
    if production_line:
        lines.append(production_line)
    return "\n".join(lines)


def format_full_item_info(item: dict) -> str:
    count = "∞" if int(item.get("stock", -1)) == -1 else str(item.get("stock", 0))
    lines = [format_shop_item_description(item, count)]
    if item.get("expires_at") is not None:
        lines.append(f"-# **Время жизни:** {format_seconds_left(int(item.get('expires_at', 0)) - int(time.time()))}")
    required_roles = item_required_role_ids(item)
    if required_roles:
        lines.append(f"-# **Требуемые роли:** {' '.join(f'<@&{rid}>' for rid in required_roles)}")
    return "\n".join(lines)


def split_component_text(text: str, limit: int = 4000) -> list[str]:
    """Split text for Discord TextDisplay components without exceeding its limit."""
    text = str(text or "—")
    if len(text) <= limit:
        return [text]
    chunks = []
    remaining = text
    while len(remaining) > limit:
        split_at = remaining.rfind("\n", 0, limit + 1)
        if split_at <= 0:
            split_at = remaining.rfind(" ", 0, limit + 1)
        if split_at <= 0:
            split_at = limit
        chunks.append(remaining[:split_at])
        remaining = remaining[split_at:].lstrip("\n ")
    if remaining:
        chunks.append(remaining)
    return chunks


def build_container_view(title: str, blocks: list[str] | tuple[str, ...], *, timeout: int = 180):
    """Build a Components V2 container view with text blocks separated by dividers."""
    view = LayoutViewBase(timeout=timeout)
    if shop_supports_components_v2():
        container = V2Container()
        container.add_item(V2TextDisplay(title))
        for idx, block in enumerate(blocks):
            if idx > 0:
                container.add_item(V2Separator())
            container.add_item(V2TextDisplay(str(block)))
        view.add_item(container)
    return view


def container_components_available() -> bool:
    return bool(shop_supports_components_v2())


def make_container_view(blocks: list[str] | tuple[str, ...], *, timeout: int = 180, view_cls=None, view_args: tuple = ()):
    cls = view_cls or LayoutViewBase
    if view_cls is not None and view_args:
        view = cls(*view_args)
    else:
        view = cls(timeout=timeout)
    if container_components_available():
        container = V2Container()
        for idx, block in enumerate(blocks):
            if idx > 0:
                container.add_item(V2Separator())
            container.add_item(V2TextDisplay(str(block)))
        view.add_item(container)
    add_v2_action_rows(view)
    return view



def add_v2_action_rows(view: View):
    """Wrap buttons/selects in Components V2 action rows before sending a LayoutView."""
    if not container_components_available() or V2ActionRow is None:
        return view
    interactive_types = (Button, Select, UserSelect)
    pending = [child for child in list(getattr(view, "children", [])) if isinstance(child, interactive_types)]
    if not pending:
        return view
    for child in pending:
        try:
            view.remove_item(child)
        except Exception:
            pass
    button_row = None
    for child in pending:
        # Discord renders each Components V2 action row on its own line. Keep
        # compatible buttons together while leaving selects in their own rows.
        if isinstance(child, Button):
            if button_row is None:
                button_row = V2ActionRow()
                view.add_item(button_row)
            button_row.add_item(child)
            continue
        row = V2ActionRow()
        row.add_item(child)
        view.add_item(row)
    return view

def view_has_v2_text_display(view: View) -> bool:
    if V2TextDisplay is None:
        return False
    pending = list(getattr(view, "children", []))
    while pending:
        child = pending.pop(0)
        if isinstance(child, V2TextDisplay):
            return True
        pending.extend(getattr(child, "children", []) or [])
    return False


def add_v2_text_blocks(view: View, blocks: list[str] | tuple[str, ...]):
    """Attach text blocks to a Components V2 view unless it already has text content."""
    if not container_components_available() or V2Container is None or V2TextDisplay is None:
        return view
    if view_has_v2_text_display(view):
        return view
    container = V2Container()
    for idx, block in enumerate(blocks):
        if idx > 0 and V2Separator is not None:
            container.add_item(V2Separator())
        container.add_item(V2TextDisplay(str(block)))
    try:
        view.add_item(container)
    except Exception:
        return view
    return view


def send_payload_for_container(blocks: list[str] | tuple[str, ...], *, view=None):
    if container_components_available():
        if view is None:
            view = make_container_view(blocks)
        else:
            view = add_v2_text_blocks(view, blocks)
            view = add_v2_action_rows(view)
        # Keep pings in Components V2 TextDisplay blocks visible, but suppress
        # their push and desktop notifications when a panel publishes them.
        return {
            "content": None,
            "embed": None,
            "view": view,
            "silent": True,
        }
    return {"content": "\n\n---\n\n".join(str(b) for b in blocks), "embed": None, "view": view}


def item_full_info_text(item: dict, guild: discord.Guild | None = None, selected_key: str | None = None) -> str:
    def format_roles(role_ids):
        if not role_ids:
            return "—"
        mentions = []
        for rid in role_ids:
            role = guild.get_role(int(rid)) if guild else None
            mentions.append(role.mention if role else f"<@&{rid}>")
        return ", ".join(mentions) if mentions else "—"

    key = item.get("key", selected_key or "—")
    ttl_text = "∞" if item.get("expires_at") is None else format_seconds_left(int(item.get("expires_at", 0)) - int(time.time()))
    stock_text = "∞" if int(item.get("stock", 0)) == -1 else str(item.get("stock", 0))
    category_name = items_data.get("categories", {}).get(str(item.get("category")), str(item.get("category")))
    lines = [
        f"## 📦 Информация о предмете — {key}",
        f"-# **Ключ:** {key}",
        f"-# **Цена:** {fmt_money(item.get('price', 0))}",
        f"-# **Категория:** {category_name}",
        f"-# **Количество:** {stock_text}",
        f"-# **Время жизни:** {ttl_text}",
        f"-# **Описание:** {(item.get('description') or '—')}",
    ]
    if item.get("item_kind") == "tech":
        lines.insert(4, f"-# **Тип техники:** {item.get('tech_type') or '—'}")
        lines.insert(5, f"-# **Оценка техники:** {int(item.get('tech_rating', 0) or 0)}/100")
    production_line = format_item_production_line(item)
    if production_line:
        lines.append(production_line)
    lines.extend([
        f"-# **Обязательные роли:** {format_roles(item_required_role_ids(item))}",
        f"-# **Выдаёт роли:** {format_roles(item.get('give_roles', []))}",
        f"-# **Забирает роли:** {format_roles(item.get('remove_roles', []))}",
        f"-# **Текст использования:** {item.get('use_text') or '✅'}",
        f"-# **Удалять при !вайп:** {bool_to_yes_no(item.get('wipe_delete', False))}",
        f"-# **Сохранять в библиотеку техники:** {bool_to_yes_no(item.get('save_to_library', False))}",
    ])
    return "\n".join(lines)


def item_full_info_pages(item: dict, guild: discord.Guild | None = None, selected_key: str | None = None) -> list[str]:
    """Keep the long item description on a separate Components V2 page."""
    item_for_summary = dict(item)
    description = str(item.get("description") or "—")
    item_for_summary["description"] = "Полное описание открывается на следующей странице."
    key = item.get("key", selected_key or "—")
    pages = [item_full_info_text(item_for_summary, guild, selected_key)]
    # Existing legacy entries may exceed the creation limit, so preserve their
    # complete text without ever exceeding Discord's 4000-character component
    # limit.
    max_page_size = 3900
    for start in range(0, max(1, len(description)), max_page_size):
        chunk = description[start : start + max_page_size] or "—"
        pages.append(f"## 📄 Описание предмета — {key}\n\n{chunk}")
    return pages


def build_item_info_embeds(item: dict, guild: discord.Guild | None = None, selected_key: str | None = None) -> list[Embed]:
    """Render complete item information as embeds rather than Components V2 containers."""
    embeds = []
    for page in item_full_info_pages(item, guild, selected_key):
        title, _, description = page.partition("\n")
        embeds.append(
            Embed(
                title=title.removeprefix("## ").strip()[:256] or "📦 Информация о предмете",
                description=description.strip()[:4096] or "—",
                color=0x3498DB,
            )
        )
    return embeds


async def perform_purchase(actor: discord.Member, guild: discord.Guild | None, item_key: str, quantity: int) -> tuple[bool, str]:
    user_id = str(actor.id)
    user = ensure_user(user_id)
    item = items_data.get("items", {}).get(item_key)
    if not item:
        return False, "❌ Предмет не найден в магазине."
    if not bool(item.get("can_buy", True)):
        return False, f"❌ Предмет **{item_key}** нельзя купить в магазине."
    if quantity <= 0:
        return False, "❌ Количество должно быть больше нуля."
    tech_type = str(item.get("tech_type") or "").strip()
    tech_limit = get_puppet_tech_limit(user_id, tech_type) if tech_type else None
    if tech_limit is not None:
        owned = get_owned_tech_count(user_id, tech_type)
        if owned + quantity > tech_limit:
            return False, f"❌ Лимит владельца для типа **{tech_type}**: {tech_limit} (сейчас: {owned})."
    if item["stock"] != -1 and quantity > item["stock"]:
        return False, f"❌ Доступно только {item['stock']} шт."
    total_price = int(item["price"]) * quantity
    if get_available_cash(user) < total_price:
        return False, f"❌ Недостаточно {currency}. Нужно {fmt_money(total_price)}."
    required_role_ids = item_required_role_ids(item)
    missing_roles = []
    for rid in dict.fromkeys(required_role_ids):
        role = guild.get_role(int(rid)) if guild else None
        if role and role not in actor.roles:
            missing_roles.append(role.mention)
    if missing_roles:
        return False, f"❌ Для использования предмета требуются роли: {', '.join(missing_roles)}"
    try:
        for rid in item.get("give_roles", []):
            role = guild.get_role(rid) if guild else None
            if role:
                await actor.add_roles(role)
        for rid in item.get("remove_roles", []):
            role = guild.get_role(rid) if guild else None
            if role:
                await actor.remove_roles(role)
    except discord.Forbidden:
        return False, "❌ Бот не может изменить роли: проверьте права и иерархию ролей."

    user["наличка"] -= total_price
    save_json(BALANCES_FILE, balances)
    if item["stock"] != -1:
        item["stock"] -= quantity
        save_items()
    inventory.setdefault(user_id, {})
    inventory[user_id][item_key] = inventory[user_id].get(item_key, 0) + quantity
    save_inventory()
    return True, f"✅ {actor.mention}, вы приобрели **{quantity} × {item_key}** за **{fmt_money(total_price)}**.\n{item.get('use_text') or '✅'}"


async def log_economy_change(
    guild: discord.Guild | None,
    member_id: int | str,
    reason: str,
    *,
    cash_delta: int = 0,
    bank_delta: int = 0,
    frozen_delta: int = 0,
):
    channel_id = settings.get("economy_log_channel")
    if not guild or not channel_id:
        return
    channel = guild.get_channel(int(channel_id))
    if not channel:
        return

    user = ensure_user(str(member_id))
    total_delta = int(cash_delta) + int(bank_delta) + int(frozen_delta)
    if total_delta > 0:
        color = 0x2ECC71
    elif total_delta < 0:
        color = 0xE74C3C
    else:
        color = 0x3498DB

    embed = Embed(title="📒 Лог экономики", color=color)
    embed.description = f"Участник: <@{member_id}>\nПричина: {reason}"
    embed.add_field(
        name="Изменения",
        value=(
            f"Наличка: **{cash_delta:+,}**\n"
            f"Банк: **{bank_delta:+,}**\n"
            f"Заморожено: **{frozen_delta:+,}**"
        ).replace(",", "."),
        inline=False,
    )
    embed.add_field(
        name="Текущее состояние",
        value=(
            f"Наличка: **{fmt_money(user.get('наличка', 0))}**\n"
            f"Банк: **{fmt_money(user.get('банк', 0))}**\n"
            f"Заморожено: **{fmt_money(user.get('заморожено', 0))}**"
        ),
        inline=False,
    )
    try:
        await channel.send(embed=embed)
    except Exception:
        pass



