def parse_interval(text: str) -> int:
    raw = str(text or "").strip().lower()
    if not raw:
        raise ValueError("Формат времени: 1ч 30м / 90м / 10с / 1д")

    compact = re.sub(r"\s+", "", raw)
    if compact.isdigit():
        value = int(compact)
        if value <= 0:
            raise ValueError("Значение должно быть больше 0")
        return value

    units = {
        "секунд": 1, "секунда": 1, "сек": 1, "с": 1, "sec": 1, "s": 1,
        "минут": 60, "минута": 60, "мин": 60, "м": 60, "min": 60, "m": 60,
        "часов": 3600, "час": 3600, "ч": 3600, "h": 3600,
        "дней": 86400, "день": 86400, "д": 86400, "d": 86400,
    }
    pattern = re.compile(r"(\d+)\s*(секунд|секунда|сек|с|sec|s|минут|минута|мин|м|min|m|часов|час|ч|h|дней|день|д|d)")
    total = 0
    pos = 0
    for match in pattern.finditer(raw):
        if raw[pos:match.start()].strip():
            raise ValueError("Формат времени: 1ч 30м / 90м / 10с / 1д")
        value = int(match.group(1))
        if value <= 0:
            raise ValueError("Значение должно быть больше 0")
        total += value * units[match.group(2)]
        pos = match.end()
    if raw[pos:].strip() or total <= 0:
        raise ValueError("Формат времени: 1ч 30м / 90м / 10с / 1д")
    return total


def format_duration(seconds: int) -> str:
    """Render a real production duration in concise Russian-friendly units."""
    seconds = max(0, int(seconds or 0))
    days, seconds = divmod(seconds, 86400)
    hours, seconds = divmod(seconds, 3600)
    minutes, seconds = divmod(seconds, 60)
    parts = []
    if days: parts.append(f"{days}д")
    if hours: parts.append(f"{hours}ч")
    if minutes: parts.append(f"{minutes}м")
    if seconds or not parts: parts.append(f"{seconds}с")
    return " ".join(parts)


def is_valid_unicode_select_emoji(value: str) -> bool:
    if not value or len(value) > 32:
        return False

    allowed_codepoints = {0x200D, 0x20E3, 0xFE0E, 0xFE0F}
    has_emoji_codepoint = False
    for char in value:
        codepoint = ord(char)
        if codepoint in allowed_codepoints:
            continue
        if 0x1F000 <= codepoint <= 0x1FAFF:
            has_emoji_codepoint = True
            continue
        if 0x2600 <= codepoint <= 0x27BF:
            has_emoji_codepoint = True
            continue
        if 0x1F3FB <= codepoint <= 0x1F3FF:
            continue
        if 0xE0020 <= codepoint <= 0xE007F:
            continue
        return False

    return has_emoji_codepoint


def parse_select_emoji(raw_value: str | None):
    if not raw_value:
        return None

    value = str(raw_value).strip()
    if not value:
        return None

    parsed = discord.PartialEmoji.from_str(value)
    if parsed and parsed.id is not None:
        return parsed

    if value.startswith("<") and value.endswith(">"):
        return None

    if is_valid_unicode_select_emoji(value):
        return value

    return None


