def readable_argument_name(raw_name: str) -> str:
    name = raw_name.strip().lower()
    return COMMAND_ARGUMENT_LABELS.get(name, name.replace("_", " "))


def format_command_usage(cmd_obj) -> str:
    """Build command usage with Russian argument placeholders for help/errors."""
    if not cmd_obj:
        return ""

    usage_parts = []
    for pname, param in cmd_obj.clean_params.items():
        label = readable_argument_name(pname)
        if param.kind is param.VAR_POSITIONAL:
            usage_parts.append(f"[{label} ...]")
            continue

        is_optional = param.default is not param.empty
        if param.kind is param.KEYWORD_ONLY:
            label = f"{label} (можно несколько слов)"

        usage_parts.append(f"[{label}]" if is_optional else f"<{label}>")

    return f"!{cmd_obj.qualified_name} {' '.join(usage_parts)}".strip()


def get_command_access(command_name: str):
    cmd_key = normalize_command_name(command_name)
    access = command_access.setdefault("commands", {}).setdefault(
        cmd_key,
        {"users": [], "roles": [], "denied_users": [], "denied_roles": []},
    )
    access.setdefault("users", [])
    access.setdefault("roles", [])
    access.setdefault("denied_users", [])
    access.setdefault("denied_roles", [])
    return access


def command_access_keys(command_name: str) -> list[str]:
    """Return a command and its parent groups, from most to least specific."""
    parts = normalize_command_name(command_name).split()
    return [" ".join(parts[:index]) for index in range(len(parts), 0, -1)]


def has_custom_command_access(member: discord.Member, command_name: str) -> bool:
    """Allow access granted to either a command or one of its parent groups."""
    user_id = str(member.id)
    role_ids = {str(role.id) for role in member.roles}
    for key in command_access_keys(command_name):
        access = get_command_access(key)
        if user_id in access.get("users", []) or role_ids.intersection(access.get("roles", [])):
            return True
    return False


def has_custom_command_deny(member: discord.Member, command_name: str) -> bool:
    """Apply an explicit deny from a command or one of its parent groups."""
    user_id = str(member.id)
    role_ids = {str(role.id) for role in member.roles}
    for key in command_access_keys(command_name):
        access = get_command_access(key)
        if user_id in access.get("denied_users", []) or role_ids.intersection(access.get("denied_roles", [])):
            return True
    return False



def admin_or_command_access():
    async def predicate(ctx):
        if ctx.author.guild_permissions.administrator:
            return True
        if ctx.command and has_custom_command_access(ctx.author, ctx.command.qualified_name):
            return True
        raise commands.MissingPermissions(["administrator"])
    return commands.check(predicate)

