MOSCOW_TZ = timezone(timedelta(hours=3))


def current_moscow_streak_period(now_ts: int | None = None) -> str:
    """Return the Moscow streak period that starts daily at 00:00 MSK."""
    now = datetime.fromtimestamp(now_ts or int(time.time()), tz=timezone.utc).astimezone(MOSCOW_TZ)
    return now.strftime("%Y-%m-%d")


def moscow_streak_period_expires_at(period: str) -> int:
    """Unix timestamp when a Moscow streak period stops being safe (00:00 MSK after the next period)."""
    day = datetime.strptime(period, "%Y-%m-%d").date()
    expires = datetime(day.year, day.month, day.day, 0, 0, tzinfo=MOSCOW_TZ) + timedelta(days=2)
    return int(expires.astimezone(timezone.utc).timestamp())


def format_discord_time(ts: int, style: str = "R") -> str:
    return f"<t:{int(ts)}:{style}>"


def streak_expire_text(period: str) -> str:
    expires = moscow_streak_period_expires_at(period)
    return f"{format_discord_time(expires, 'F')} ({format_discord_time(expires, 'R')})"


def streak_period_gap(previous_period: str | None, current_period: str) -> int:
    if not previous_period:
        return 1
    try:
        prev = datetime.strptime(previous_period, "%Y-%m-%d").date()
        cur = datetime.strptime(current_period, "%Y-%m-%d").date()
        return (cur - prev).days
    except Exception:
        return 1


async def advance_news_streak(member: discord.Member):
    uid = str(member.id)
    if not is_registered_country_user(uid):
        return
    now_ts = int(time.time())
    st = ensure_player_state(uid)
    current_period = current_moscow_streak_period(now_ts)
    last_period = st.get("last_news_streak_period")
    last = int(st.get("last_news_at", 0) or 0)

    if not last_period and last:
        last_period = current_moscow_streak_period(last)

    if last_period == current_period:
        st["last_news_at"] = now_ts
        st["last_news_streak_period"] = current_period
        st["streak_warning_sent"] = False
        save_player_state()
        return

    if streak_period_gap(last_period, current_period) > 1:
        st["news_streak"] = 0

    st["news_streak"] = int(st.get("news_streak", 0) or 0) + 1
    st["last_news_at"] = now_ts
    st["last_news_streak_period"] = current_period
    st["streak_warning_sent"] = False
    reward = 20 if st["news_streak"] % 10 == 0 else 5
    ensure_user(uid)["коины"] = int(ensure_user(uid).get("коины", 0)) + reward
    save_json(BALANCES_FILE, balances)
    save_player_state()
    try:
        await member.send(embed=Embed(title="<:feuer:1543301108137730199> Стрик продлён", description=f"Ваш стрик новостей: **{st['news_streak']}**. Начислено **+{reward}** {settings.get('coin_currency', 'Alta-коинов')}. Следующее продление будет доступно после **00:00 МСК** следующего дня. Стрик сгорит {streak_expire_text(current_period)}.", color=0xF39C12))
    except Exception:
        pass

@tasks.loop(minutes=1)
async def economy_baseline_scheduler():
    now = datetime.now(MOSCOW_TZ)
    if now.hour != 0 or now.minute != 0:
        return
    today_key = now.strftime("%Y-%m-%d")
    if economy_snapshots.get("last_daily_key") == today_key:
        return
    capture_economy_baseline(get_all_registered_user_ids())
    economy_snapshots["last_daily_key"] = today_key
    save_economy_snapshots()


@tasks.loop(hours=1)
async def news_streak_watchdog():
    now_ts = int(time.time())
    for guild in bot.guilds:
        for uid, st in list(player_state.setdefault("users", {}).items()):
            if not isinstance(st, dict) or not is_registered_country_user(uid):
                continue
            streak = int(st.get("news_streak", 0) or 0)
            last = int(st.get("last_news_at", 0) or 0)
            if streak <= 0 or last <= 0:
                continue
            last_period = st.get("last_news_streak_period") or current_moscow_streak_period(last)
            expires_at = moscow_streak_period_expires_at(last_period)
            warn_at = expires_at - 86400
            if now_ts >= expires_at:
                st["news_streak"] = 0
                st["streak_warning_sent"] = False
                save_player_state()
            elif now_ts >= warn_at and not st.get("streak_warning_sent"):
                member = guild.get_member(int(uid)) if str(uid).isdigit() else None
                if member:
                    try:
                        await member.send(embed=Embed(title="⚠️ Стрик может сгореть", description=f"Опубликуйте новость до {streak_expire_text(last_period)}, чтобы сохранить стрик активности.", color=0xF1C40F))
                    except Exception:
                        pass
                st["streak_warning_sent"] = True
                save_player_state()


