def format_rp_year_embed(
    year: int,
    quarter_index: int,
    science_limit: int,
    total_population: int,
    total_science: int,
    registered_count: int,
    elapsed_seconds: int = 0,
    cooldown_seconds: int | None = None,
):
    seasons = [
        ("🌱 Весна", 0x55AA55, "Рост, обновление и новые возможности."),
        ("☀️ Лето", 0xF1C40F, "Пик активности, энергии и побед."),
        ("🍂 Осень", 0xE67E22, "Время зрелых решений и результатов."),
        ("❄️ Зима", 0x5DADE2, "Пауза, переоценка и подготовка к рывку."),
    ]
    rp = investments.setdefault('rp_year', {})
    cooldown_seconds = max(1, int(cooldown_seconds or rp.get('cooldown', 86400) or 86400))
    month, day = rp_date_from_progress(int(year), int(elapsed_seconds or 0), cooldown_seconds)
    # Seasons follow calendar months: winter begins on 1 January, not spring.
    season_index = 3 if month in {12, 1, 2} else 0 if month in {3, 4, 5} else 1 if month in {6, 7, 8} else 2
    season_name, color, mood = seasons[season_index]
    em = Embed(
        title="🗓 RP-календарь",
        description=(
            f"**Игровой год:** {int(year)}\n"
            f"**Дата:** {day:02d}.{month:02d}.{int(year)}\n"
            f"**Пора года:** {season_name}\n"
            f"**Следующий год:** <t:{int(rp.get('next_tick_at', int(time.time())))}:R>\n\n"
            f"{mood}"
        ),
        color=color,
    )
    em.add_field(name="🔬 Лимит науки", value=fmt_num(max(0, int(science_limit))), inline=False)
    em.add_field(name="🏘 Общее население", value=fmt_num(max(0, int(total_population))), inline=True)
    em.add_field(name="🧪 Общая наука", value=fmt_num(max(0, int(total_science))), inline=True)
    em.add_field(name="👥 Зарегистрировано", value=fmt_num(max(0, int(registered_count))), inline=True)
    return em




def is_rp_leap_year(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def rp_days_in_year(year: int) -> int:
    return 366 if is_rp_leap_year(int(year)) else 365


def rp_date_from_progress(year: int, elapsed: int, cooldown: int) -> tuple[int, int]:
    days_total = rp_days_in_year(int(year))
    day_of_year = min(days_total - 1, max(0, int(elapsed * days_total / max(1, cooldown))))
    month_days = [31, 29 if is_rp_leap_year(int(year)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    month = 1
    for days in month_days:
        if day_of_year < days:
            return month, day_of_year + 1
        day_of_year -= days
        month += 1
    return 12, 31


def rp_date_to_day_index(year: int, month: int, day: int) -> int:
    month_days = [31, 29 if is_rp_leap_year(int(year)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month < 1 or month > 12:
        raise ValueError("Месяц RP-даты должен быть от 1 до 12")
    max_day = month_days[month - 1]
    if day < 1 or day > max_day:
        raise ValueError(f"День RP-даты для месяца {month:02d} должен быть от 1 до {max_day}")
    return sum(month_days[:month - 1]) + day - 1


def parse_server_event_rp_date_to_ts(raw: str) -> int | None:
    raw = str(raw or "").strip()
    if not raw:
        return None
    match = re.fullmatch(r"(\d{1,2})\.(\d{1,2})\.(\d{1,6})(?:\s+(\d{1,2}):(\d{2}))?", raw)
    if not match:
        raise ValueError("RP-дата должна быть в формате ДД.ММ.ГГГГ или ДД.ММ.ГГГГ ЧЧ:ММ")
    day, month, year = int(match.group(1)), int(match.group(2)), int(match.group(3))
    hour = int(match.group(4)) if match.group(4) is not None else 23
    minute = int(match.group(5)) if match.group(5) is not None else 59
    if hour < 0 or hour > 23 or minute < 0 or minute > 59:
        raise ValueError("Время RP-даты должно быть в формате ЧЧ:ММ")
    day_index = rp_date_to_day_index(year, month, day)
    rp = investments.setdefault("rp_year", {})
    current_year_raw = rp.get("year")
    if current_year_raw is None or not str(current_year_raw).strip():
        raise ValueError("Сначала запустите RP-календарь и задайте текущий RP-год")
    current_year = int(current_year_raw)
    cooldown = max(60, int(rp.get("cooldown", 86400) or 86400))
    next_tick = int(rp.get("next_tick_at") or 0)
    if next_tick <= 0:
        raise ValueError("RP-календарь ещё не запущен: неизвестно время следующего года")
    current_year_start = next_tick - cooldown
    days_total = rp_days_in_year(year)
    day_fraction = (hour * 60 + minute) / (24 * 60)
    target_offset = int(((day_index + day_fraction) / days_total) * cooldown)
    return current_year_start + ((year - current_year) * cooldown) + target_offset


def server_event_schedule_text(req: dict) -> str:
    rp_date = str(req.get("schedule_date") or "").strip()
    send_at = req.get("send_at")
    if rp_date and send_at:
        return f"RP {rp_date} ({event_schedule_text(send_at)})"
    return event_schedule_text(send_at)


def get_population_growth_percent(happiness: int) -> int:
    table = {
        0: None,
        5: -10,
        10: -8,
        15: -7,
        20: -6,
        25: -5,
        30: -4,
        35: -3,
        40: -2,
        45: -1,
        50: 0,
        55: 1,
        60: 2,
        65: 3,
        70: 4,
        75: 5,
        80: 6,
        85: 7,
        90: 8,
        95: 9,
        100: 10,
    }
    step = max(0, min(100, int(happiness)))
    step = (step // 5) * 5
    if step == 0:
        return None
    return table.get(step, 0)


ARMY_RATIO_ROLE_THRESHOLDS = (5, 10, 15, 20, 25, 30)


def get_army_ratio_percent(population_value: int, soldiers: int) -> float:
    soldiers = max(0, int(soldiers or 0))
    population_value = max(0, int(population_value or 0))
    total = population_value + soldiers
    if soldiers <= 0 or total <= 0:
        return 0.0
    return (soldiers / total) * 100


def get_mobilization_happiness_penalty(population_value: int, soldiers: int) -> int:
    pct = get_army_ratio_percent(population_value, soldiers)
    if pct < 10:
        return 0
    if pct < 15:
        return 10
    if pct < 20:
        return 15
    return 20


def get_army_ratio_role_config(threshold: int) -> dict:
    configs = seasons_data.setdefault("army_ratio_roles", {})
    config = configs.setdefault(str(int(threshold)), {"roles": []})
    config.setdefault("roles", [])
    return config


def get_user_army_ratio_role_config(user_id: str) -> tuple[int, dict | None, float]:
    pop = load_json(POPULATION_FILE, {})
    st = ensure_player_state(str(user_id))
    ratio = get_army_ratio_percent(int(pop.get(str(user_id), 0) or 0), int(st.get("soldiers", 0) or 0))
    best_threshold = 0
    best_config = None
    for threshold in ARMY_RATIO_ROLE_THRESHOLDS:
        config = get_army_ratio_role_config(threshold)
        if ratio >= threshold and config.get("roles"):
            best_threshold = threshold
            best_config = config
    return best_threshold, best_config, ratio


async def sync_member_army_ratio_roles(member: discord.Member) -> tuple[int, float, list[discord.Role], list[discord.Role]]:
    target_threshold, target_config, ratio = get_user_army_ratio_role_config(str(member.id))
    configured_role_ids = {
        str(role_id)
        for config in seasons_data.setdefault("army_ratio_roles", {}).values()
        for role_id in config.get("roles", [])
    }
    target_role_ids = {str(role_id) for role_id in (target_config or {}).get("roles", [])}
    to_remove = [
        role for role in member.roles
        if str(role.id) in configured_role_ids and str(role.id) not in target_role_ids
    ]
    to_add = [
        role for role_id in target_role_ids
        if str(role_id).isdigit()
        if (role := member.guild.get_role(int(role_id))) and role not in member.roles
    ]
    reason = f"Автосинхронизация доли армии: {ratio:.1f}% ({target_threshold or 'нет порога'}%)"
    if to_remove:
        await member.remove_roles(*to_remove, reason=reason)
    if to_add:
        await member.add_roles(*to_add, reason=reason)
    return target_threshold, ratio, to_add, to_remove


async def sync_army_ratio_roles_for_user(guild: discord.Guild, user_id: str):
    member = guild.get_member(int(user_id)) if guild and str(user_id).isdigit() else None
    if not member or member.bot:
        return None
    return await sync_member_army_ratio_roles(member)


async def sync_guild_army_ratio_roles(guild: discord.Guild) -> dict[str, int]:
    stats = {"checked": 0, "changed": 0, "added": 0, "removed": 0, "failed": 0}
    for member in guild.members:
        if member.bot:
            continue
        stats["checked"] += 1
        try:
            _, _, roles_added, roles_removed = await sync_member_army_ratio_roles(member)
        except (discord.Forbidden, discord.HTTPException):
            stats["failed"] += 1
            continue
        if roles_added or roles_removed:
            stats["changed"] += 1
            stats["added"] += len(roles_added)
            stats["removed"] += len(roles_removed)
    return stats


def mark_request_processed_embed(embed: Embed, status_text: str):
    if not embed:
        embed = Embed(title="Заявка")
    fields = [f for f in embed.fields if f.name != "Статус"]
    embed.clear_fields()
    for f in fields:
        embed.add_field(name=f.name, value=f.value, inline=f.inline)
    embed.add_field(name="Статус", value=status_text, inline=False)
    return embed


def get_available_cash(user: dict) -> int:
    return int(user.get("наличка", 0)) - int(user.get("заморожено", 0))


def parse_money_value(value_text: str, base_amount: int) -> int:
    text = str(value_text).strip().lower().replace(" ", "").replace("_", "")
    if not text:
        raise ValueError("empty money value")
    if text.endswith("%"):
        pct_raw = text[:-1]
        pct = float(pct_raw.replace(",", "."))
        return int(round(base_amount * pct / 100.0))

    multipliers = (
        ("кк", 1_000_000),
        ("kk", 1_000_000),
        ("млн", 1_000_000),
        ("m", 1_000_000),
        ("к", 1_000),
        ("k", 1_000),
    )
    multiplier = 1
    for suffix, suffix_multiplier in multipliers:
        if text.endswith(suffix):
            multiplier = suffix_multiplier
            text = text[: -len(suffix)]
            break

    if not text:
        raise ValueError("empty money value")

    # Discord users commonly enter thousands as `10.000.000`; treat dots as
    # group separators when every group after the first has exactly 3 digits.
    if "." in text and "," not in text:
        parts = text.split(".")
        if len(parts) > 1 and all(part.isdigit() for part in parts) and all(len(part) == 3 for part in parts[1:]):
            text = "".join(parts)
    if "," in text and "." not in text:
        parts = text.split(",")
        if len(parts) > 1 and all(part.isdigit() for part in parts) and all(len(part) == 3 for part in parts[1:]):
            text = "".join(parts)
        else:
            text = text.replace(",", ".")

    return int(float(text) * multiplier)


def apply_freeze_roles_for_member(
    guild: discord.Guild, member: discord.Member, now_ts: int, income_pool: int
):
    user_id = str(member.id)
    user = ensure_user(user_id)
    frozen_total = 0
    frozen_details = []
    freeze_cfg = role_income.setdefault("freeze_roles", {})
    freeze_last = role_income.setdefault("freeze_last_claim", {}).setdefault(
        user_id, {}
    )

    for rid, freeze_data in freeze_cfg.items():
        role = guild.get_role(int(rid))
        if not role or role not in member.roles:
            continue

        cooldown = int(freeze_data.get("cooldown", 0))
        if cooldown <= 0:
            continue

        last = int(freeze_last.get(rid, 0))
        if now_ts - last < cooldown:
            continue

        try:
            requested = parse_money_value(
                str(freeze_data.get("value", 0)), user.get("наличка", 0)
            )
        except Exception:
            requested = 0

        if requested <= 0:
            freeze_last[rid] = now_ts
            continue

        available_income = max(0, income_pool)
        moved = min(available_income, requested)
        freeze_last[rid] = now_ts
        if moved <= 0:
            continue

        user["заморожено"] = user.get("заморожено", 0) + moved
        income_pool -= moved
        frozen_total += moved
        frozen_details.append(f"• {role.mention}: +{fmt_money(moved)} в заморозку")

    return frozen_total, frozen_details, income_pool


def format_seconds_left(seconds: int) -> str:
    return format_interval(max(0, int(seconds)))


def resolve_role_from_text(guild: discord.Guild, text: str):
    query = str(text or "").strip()
    if not query:
        return None

    if query.startswith("<@&") and query.endswith(">"):
        query = query[3:-1]
    if query.isdigit():
        role = guild.get_role(int(query))
        if role:
            return role

    lowered = query.casefold()
    exact = discord.utils.find(lambda r: r.name.casefold() == lowered, guild.roles)
    if exact:
        return exact
    return discord.utils.find(lambda r: lowered in r.name.casefold(), guild.roles)


def parse_accum_limit(value: str) -> dict:
    raw = str(value or "").strip().lower()
    if raw in ("", "0", "нет", "no", "none", "off"):
        return {"type": "none", "value": 0}
    if any(ch.isalpha() for ch in raw):
        secs = parse_interval(raw)
        if secs <= 0:
            raise ValueError("Лимит времени должен быть больше 0.")
        return {"type": "time", "value": int(secs)}
    cycles = int(raw)
    if cycles <= 0:
        raise ValueError("Лимит пропусков должен быть больше 0.")
    return {"type": "cycles", "value": cycles}


def compute_accumulative_income(cfg: dict, user_cash: int, elapsed_cycles: int) -> int:
    if elapsed_cycles <= 0:
        return 0
    try:
        base_amount = parse_money_value(str(cfg.get("amount", 0)), user_cash)
    except Exception:
        base_amount = 0
    if base_amount <= 0:
        return 0

    cut = max(0, int(cfg.get("accum_cut", 0)))
    total = 0
    for cycle_idx in range(1, elapsed_cycles + 1):
        if cut <= 0 or cycle_idx <= 2:
            cycle_amount = base_amount
        else:
            missed = cycle_idx - 2
            cut_total = cut * (missed * (missed + 1) // 2)
            cycle_amount = base_amount - cut_total
        total += max(0, cycle_amount)
    return int(max(0, total))


def add_embed_lines_chunked(
    embed: Embed,
    field_name: str,
    lines: list[str],
    inline: bool = False,
    limit: int = 1024,
):
    if not lines:
        return

    chunks = []
    current = ""
    for raw_line in lines:
        line = str(raw_line) if raw_line is not None else " "
        candidate = line if not current else f"{current}\n{line}"

        if len(candidate) <= limit:
            current = candidate
            continue

        if current:
            chunks.append(current)

        while len(line) > limit:
            chunks.append(line[:limit])
            line = line[limit:]
        current = line

    if current:
        chunks.append(current)

    for idx, chunk in enumerate(chunks):
        chunk_name = field_name if idx == 0 else f"{field_name} (продолжение {idx + 1})"
        embed.add_field(name=chunk_name, value=chunk or " ", inline=inline)


def chunk_lines_for_embed(lines: list[str], limit: int = 1024) -> list[str]:
    if not lines:
        return []

    pages = []
    current = ""
    for raw_line in lines:
        line = str(raw_line) if raw_line is not None else " "
        candidate = line if not current else f"{current}\n{line}"
        if len(candidate) <= limit:
            current = candidate
            continue

        if current:
            pages.append(current)

        while len(line) > limit:
            pages.append(line[:limit])
            line = line[limit:]
        current = line

    if current:
        pages.append(current)

    return pages




def snapshot_player_statistics(
    user_id: str,
    reason: str = "auto_update",
    save: bool = True,
    save_country: bool = True,
):
    """Persist current non-coin gameplay statistics for unexpected leaves and later restores."""
    uid = str(user_id)
    population_data = load_json(POPULATION_FILE, {})
    players = load_json(PLAYER_STATS_FILE, {})
    balance_snapshot = make_json_snapshot(balances.get(uid, {})) if isinstance(balances.get(uid), dict) else {}
    if isinstance(balance_snapshot, dict):
        balance_snapshot.pop("коины", None)
    snapshot = {
        "updated_at": int(time.time()),
        "reason": reason,
        "balances": balance_snapshot,
        "inventory": make_json_snapshot(inventory.get(uid, {})),
        "server_inventory": make_json_snapshot(server_inventory.setdefault("users", {}).get(uid, {})),
        "factories": make_json_snapshot(factories_data.setdefault("users", {}).get(uid, [])),
        "population": make_json_snapshot(population_data.get(uid)),
        "player_stats": make_json_snapshot(players.get(uid, {})),
        "passive_entries": make_json_snapshot(passive_flows.setdefault("users", {}).get(uid, [])),
        "player_state": make_json_snapshot(player_state.setdefault("users", {}).get(uid, {})),
        "season_progress": make_json_snapshot({
            season: progress.get(uid, {})
            for season, progress in seasons_data.setdefault("season_user_progress", {}).items()
            if isinstance(progress, dict) and uid in progress
        }),
    }
    snapshot_country_statistics_for_user(
        uid, reason=reason, snapshot=snapshot, save=save_country
    )
    if save:
        save_stats_library()
    return snapshot


def snapshot_country_statistics_for_user(
    user_id: str,
    reason: str = "auto_update",
    snapshot: dict | None = None,
    save: bool = True,
) -> bool:
    """Persist current gameplay progress by country/season, not only by Discord user."""
    uid = str(user_id)
    profile = country_owners.setdefault("user_profiles", {}).get(uid, {})
    registrations = profile.get("registrations", {}) if isinstance(profile, dict) else {}
    season_country_to_user, season_user_to_country = ensure_registration_maps()
    if not registrations:
        registrations = {}
        for season_key, user_map in season_user_to_country.items():
            country_name = user_map.get(uid) if isinstance(user_map, dict) else None
            if country_name:
                registrations[str(season_key)] = {"country": country_name, "season": str(season_key)}

    if not registrations:
        return False

    snapshot = make_json_snapshot(snapshot) if isinstance(snapshot, dict) else snapshot_player_statistics(uid, reason=reason)
    changed = False
    country_library = stats_library.setdefault("countries", {})
    orphaned = country_owners.setdefault("orphaned_country_stats", {})
    for season_key, reg in list(registrations.items()):
        if not isinstance(reg, dict):
            continue
        country_name = str(reg.get("country") or "").strip()
        season_key = str(reg.get("season") or season_key or "").strip()
        if not country_name or not season_key:
            continue
        key = country_archive_key(country_name, season_key)
        country_snapshot = make_json_snapshot(snapshot)
        country_snapshot.update({
            "time": int(time.time()),
            "updated_at": int(time.time()),
            "reason": reason,
            "country": country_name,
            "season": season_key,
        })
        country_library[key] = country_snapshot
        orphaned[key] = country_snapshot
        changed = True
    if changed:
        save_country_owners()
    return changed


def wipe_user_data(user_id: str, guild: discord.Guild = None):
    snapshot_player_statistics(user_id, reason="before_wipe_user_data")
    archive_country_stats_for_user(user_id, reason="wipe_user_data")
    user_had_registration = user_has_any_registration(user_id)
    state = ensure_player_state(user_id)
    pre_reg_roles = list(state.get("pre_reg_role_ids", []))
    prev_user = (
        balances.get(user_id, {}) if isinstance(balances.get(user_id), dict) else {}
    )
    balances[user_id] = {
        "наличка": 0,
        "банк": 0,
        "заморожено": 0,
        "коины": int(prev_user.get("коины", 0)),
    }
    inventory.pop(user_id, None)
    pop = load_json(POPULATION_FILE, {})
    pop.pop(user_id, None)
    players = load_json(PLAYER_STATS_FILE, {})
    players.pop(user_id, None)
    passive_flows.setdefault("users", {}).pop(user_id, None)
    for _season_map in seasons_data.setdefault("season_user_progress", {}).values():
        _season_map.pop(user_id, None)
    preserved_state = dict(state)
    state["posts_count"] = 0
    player_state.setdefault("users", {}).pop(user_id, None)
    preserve_moderator_audit_fields(user_id, preserved_state)
    investments.setdefault("users", {}).pop(user_id, None)
    server_inventory.setdefault("users", {}).pop(user_id, None)
    factories_data.setdefault("users", {}).pop(user_id, None)
    remove_active_investments_for_user(user_id)
    investments["requests"] = {
        rid: req
        for rid, req in investments.setdefault("requests", {}).items()
        if user_id != str((req or {}).get("author_id", ""))
    }
    companies_data["companies"] = {
        cid: c
        for cid, c in companies_data.setdefault("companies", {}).items()
        if str(c.get("owner_id")) != user_id
    }
    companies_data["requests"] = {
        rid: r
        for rid, r in companies_data.setdefault("requests", {}).items()
        if user_id
        not in {
            str(r.get("author_id", "")),
            str(r.get("owner_id", "")),
            str(r.get("buyer_id", "")),
            str(r.get("decision_user_id", "")),
        }
    }
    with suppress_auto_snapshots():
        remove_user_registration(user_id)
        remove_relations_for_subject(user_id)
        save_json(BALANCES_FILE, balances)
        save_inventory()
        save_json(POPULATION_FILE, pop)
        save_json(PLAYER_STATS_FILE, players)
        save_passive_flows()
        save_seasons_data()
        save_player_state()
        save_server_inventory()
        save_factories_data()
        save_investments()
        save_companies_data()
        save_country_owners()
        save_relations_data()

    if guild is not None:
        member = guild.get_member(int(user_id))
        if member:
            if user_had_registration:
                try:
                    asyncio.create_task(
                        restore_member_roles_after_wipe(
                            member, pre_reg_roles, reason="Вайп игрока"
                        )
                    )
                except Exception:
                    pass
            try:
                asyncio.create_task(member.edit(nick=None, reason="Вайп игрока"))
            except Exception:
                pass





def make_json_snapshot(data):
    return json.loads(json.dumps(data))


def country_archive_key(country_name: str, season_name: str) -> str:
    return f"{str(season_name or '').strip()}::{str(country_name or '').strip()}"


def archive_country_stats_for_user(user_id: str, reason: str = "unregister"):
    uid = str(user_id)
    profile = country_owners.setdefault("user_profiles", {}).get(uid, {})
    registrations = profile.get("registrations", {}) if isinstance(profile, dict) else {}
    season_country_to_user, season_user_to_country = ensure_registration_maps()
    if not registrations:
        registrations = {}
        for season_key, user_map in season_user_to_country.items():
            country_name = user_map.get(uid) if isinstance(user_map, dict) else None
            if country_name:
                registrations[str(season_key)] = {"country": country_name, "season": str(season_key)}

    if not registrations:
        return

    population_data = load_json(POPULATION_FILE, {})
    players = load_json(PLAYER_STATS_FILE, {})
    archived = country_owners.setdefault("orphaned_country_stats", {})
    for season_key, reg in list(registrations.items()):
        if not isinstance(reg, dict):
            continue
        country_name = str(reg.get("country") or "").strip()
        season_key = str(reg.get("season") or season_key or "").strip()
        if not country_name or not season_key:
            continue
        snapshot = {
            "time": int(time.time()),
            "reason": reason,
            "country": country_name,
            "season": season_key,
            "balances": make_json_snapshot({k: v for k, v in (balances.get(uid, {}) if isinstance(balances.get(uid), dict) else {}).items() if k != "коины"}),
            "inventory": make_json_snapshot(inventory.get(uid, {})),
            "server_inventory": make_json_snapshot(server_inventory.setdefault("users", {}).get(uid, {})),
            "factories": make_json_snapshot(factories_data.setdefault("users", {}).get(uid, [])),
            "population": make_json_snapshot(population_data.get(uid)),
            "player_stats": make_json_snapshot(players.get(uid, {})),
            "passive_entries": make_json_snapshot(get_passive_entries(uid)),
            "season_progress": make_json_snapshot(
                seasons_data.setdefault("season_user_progress", {}).get(season_key, {}).get(uid, {})
            ),
            "player_state": make_json_snapshot(player_state.setdefault("users", {}).get(uid, {})),
            "investments": make_json_snapshot(investments.setdefault("users", {}).get(uid, {})),
            "active_investments": make_json_snapshot({
                str(inv_id): inv for inv_id, inv in get_active_investments_for_user(uid)
            }),
            "companies": make_json_snapshot({
                cid: c for cid, c in companies_data.setdefault("companies", {}).items()
                if str(c.get("owner_id")) == uid
            }),
        }
        has_data = any(bool(snapshot.get(k)) for k in (
            "balances", "inventory", "population", "player_stats", "passive_entries",
            "server_inventory", "factories", "season_progress", "player_state", "investments", "active_investments", "companies",
        ))
        if has_data:
            key = country_archive_key(country_name, season_key)
            archived[key] = snapshot
            stats_library.setdefault("countries", {})[key] = make_json_snapshot(snapshot)
    save_stats_library()


def apply_archived_country_stats(user_id: str, snapshot: dict):
    uid = str(user_id)
    season_key = str(snapshot.get("season", "")).strip()
    old_coins = int((balances.get(uid, {}) if isinstance(balances.get(uid), dict) else {}).get("коины", 0) or 0)
