    restored_balances["коины"] = old_coins
    balances[uid] = restored_balances
    inventory[uid] = make_json_snapshot(snapshot.get("inventory", {}))
    server_inventory.setdefault("users", {})[uid] = make_json_snapshot(snapshot.get("server_inventory", {}))
    factories_data.setdefault("users", {})[uid] = make_json_snapshot(snapshot.get("factories", []))
    population_data = load_json(POPULATION_FILE, {})
    if snapshot.get("population") is not None:
        population_data[uid] = snapshot.get("population")
    players = load_json(PLAYER_STATS_FILE, {})
    players[uid] = make_json_snapshot(snapshot.get("player_stats", {}))
    passive_flows.setdefault("users", {})[uid] = make_json_snapshot(snapshot.get("passive_entries", []))
    if season_key:
        seasons_data.setdefault("season_user_progress", {}).setdefault(season_key, {})[uid] = make_json_snapshot(snapshot.get("season_progress", {}))
    state = make_json_snapshot(snapshot.get("player_state", {}))
    state.pop("pre_reg_role_ids", None)
    player_state.setdefault("users", {})[uid] = state
    investments.setdefault("users", {})[uid] = make_json_snapshot(snapshot.get("investments", {}))
    for inv_id, inv in make_json_snapshot(snapshot.get("active_investments", {})).items():
        if isinstance(inv, dict):
            inv["user_id"] = uid
            investments.setdefault("active_investments", {})[str(inv_id)] = inv
    for cid, company in make_json_snapshot(snapshot.get("companies", {})).items():
        if isinstance(company, dict):
            company["owner_id"] = uid
            companies_data.setdefault("companies", {})[str(cid)] = company
    save_json(BALANCES_FILE, balances); save_inventory(); save_json(POPULATION_FILE, population_data); save_json(PLAYER_STATS_FILE, players)
    save_passive_flows(); save_seasons_data(); save_player_state(); save_server_inventory(); save_factories_data(); save_investments(); save_companies_data(); save_relations_data()


