def _cleanup_expired_server_items(user_id: str):
    user_slots = server_inventory.setdefault("users", {}).get(str(user_id), {})
    now_ts = int(time.time())
    changed = False
    for key in list(user_slots.keys()):
        entry = user_slots.get(key, {})
        expires_at = entry.get("expires_at")
        qty = int(entry.get("qty", 0))
        if qty <= 0 or (expires_at is not None and int(expires_at) <= now_ts):
            user_slots.pop(key, None)
            changed = True
    if changed:
        if not user_slots:
            server_inventory.setdefault("users", {}).pop(str(user_id), None)
        save_server_inventory()


def get_server_item_qty(user_id: str, item_key: str) -> int:
    _cleanup_expired_server_items(user_id)
    entry = (
        server_inventory.setdefault("users", {}).get(str(user_id), {}).get(item_key, {})
    )
    return int(entry.get("qty", 0))


def consume_server_item(user_id: str, item_key: str, qty: int) -> bool:
    _cleanup_expired_server_items(user_id)
    user_slots = server_inventory.setdefault("users", {}).get(str(user_id), {})
    entry = user_slots.get(item_key)
    if not entry:
        return False
    current = int(entry.get("qty", 0))
    if current < qty:
        return False
    entry["qty"] = current - qty
    if entry["qty"] <= 0:
        user_slots.pop(item_key, None)
    if not user_slots:
        server_inventory.setdefault("users", {}).pop(str(user_id), None)
    save_server_inventory()
    return True


def resolve_item_key(query: str):
    items = list(items_data.get("items", {}).keys())
    if not items:
        return []
    q = query.strip().lower()
    exact = [k for k in items if k.lower() == q]
    if exact:
        return exact
    starts = [k for k in items if k.lower().startswith(q)]
    if starts:
        return starts
    contains = [k for k in items if q in k.lower()]
    return contains


def resolve_member_matches(guild: discord.Guild, raw: str) -> list[discord.Member]:
    """Find members by mention, ID, Discord username, or server nickname.

    Exact matches take precedence over partial ones.  This is important when a
    short nickname is also the beginning of another player's nickname: typing
    the full nickname should never unexpectedly select the other player.
    """
    text = (raw or "").strip()
    if not text or guild is None:
        return []
    if text.startswith("@") and not text.startswith("<@"):
        text = text[1:].strip()

    mention_match = re.fullmatch(r"<@!?(\d+)>", text)
    if mention_match:
        text = mention_match.group(1)
    if text.isdigit():
        member = guild.get_member(int(text))
        return [member] if member else []

    query = text.casefold()

    def names(member: discord.Member) -> tuple[str, ...]:
        # display_name is the server nickname when one is set.  global_name is
        # included for Discord's newer display-name field without relying on a
        # particular discord.py version.
        return tuple({
            str(member.name or "").casefold(),
            str(member.display_name or "").casefold(),
            str(getattr(member, "global_name", "") or "").casefold(),
            str(member).casefold(),
        })

    members = list(guild.members)
    exact = [member for member in members if query in names(member)]
    if exact:
        return exact
    starts = [member for member in members if any(name.startswith(query) for name in names(member))]
    if starts:
        return starts
    return [member for member in members if any(query in name for name in names(member))]


def resolve_member_query(guild: discord.Guild, raw: str) -> discord.Member | None:
    """Return a member only when the query resolves without ambiguity."""
    matches = resolve_member_matches(guild, raw)
    return matches[0] if len(matches) == 1 else None


def member_match_label(member: discord.Member) -> str:
    """A concise label that lets moderators distinguish same-name members."""
    username = str(member.name or "—")
    nickname = str(member.display_name or username)
    if nickname.casefold() == username.casefold():
        return f"{nickname} (`{member.id}`)"
    return f"{nickname} — @{username} (`{member.id}`)"


async def resolve_member_query_interactively(ctx: commands.Context, raw: str) -> discord.Member | None:
    """Resolve a player query and ask the command author to choose if needed."""
    matches = resolve_member_matches(ctx.guild, raw)
    if len(matches) <= 1:
        return matches[0] if matches else None

    shown = matches[:20]
    options = "\n".join(f"{index}. {member_match_label(member)}" for index, member in enumerate(shown, 1))
    await ctx.send(
        embed=Embed(
            title="🔎 Уточнение игрока",
            description=(
                f"По запросу **{raw.strip()}** найдено несколько игроков. "
                f"Отправьте номер нужного игрока в течение 60 секунд:\n\n{options}"
            ),
            color=0xFFA500,
        )
    )

    def choice_check(message: discord.Message) -> bool:
        return message.author == ctx.author and message.channel == ctx.channel

    try:
        answer = await bot.wait_for("message", check=choice_check, timeout=60)
        index = int(answer.content.strip()) - 1
        if not 0 <= index < len(shown):
            raise ValueError
    except (asyncio.TimeoutError, ValueError):
        return None
    return shown[index]


class MemberQueryConverter(commands.Converter):
    """Member converter with partial username/nickname matching and a choice prompt."""
    async def convert(self, ctx: commands.Context, argument: str) -> discord.Member:
        member = await resolve_member_query_interactively(ctx, argument)
        if member is None:
            raise commands.MemberNotFound(argument)
        return member


