async def restore_verdict_request_views():
    """Восстанавливает меню рассмотрения/просмотра заявок вердикта после рестарта."""
    requests_map = verdicts_data.get("requests", {})
    if not isinstance(requests_map, dict) or not requests_map:
        return

    for req_id, req in list(requests_map.items()):
        if not isinstance(req, dict):
            continue

        ch = await get_channel_safe(req.get("request_channel_id"))
        mid = req.get("request_message_id")
        if not ch or not mid:
            continue

        try:
            msg = await ch.fetch_message(int(mid))
            is_unreviewed = _is_unreviewed_verdict(req)
            if container_components_available():
                blocks = build_verdict_request_message_blocks(
                    req, getattr(ch, "guild", None), verdict_request_status_text(req)
                )
                view = make_container_view(
                    blocks,
                    view_cls=VerdictReviewView if is_unreviewed else VerdictResultView,
                    view_args=(str(req_id),),
                    timeout=None,
                )
                await msg.edit(content=None, embed=None, view=view)
            else:
                view = VerdictReviewView(str(req_id)) if is_unreviewed else VerdictResultView(str(req_id))
                await msg.edit(view=view)
        except Exception:
            pass


