@bot.check
async def only_allowed_guild(ctx):
    return bool(ctx.guild and ctx.guild.id == ALLOWED_GUILD)


@bot.check
async def check_custom_command_denies(ctx):
    if not ctx.command:
        return True

    # Явно выданный доступ через !разрешить должен иметь приоритет,
    # иначе пользователь получает ошибку даже после выдачи доступа.
    if has_custom_command_access(ctx.author, ctx.command.qualified_name):
        return True

    if has_custom_command_deny(ctx.author, ctx.command.qualified_name):
        raise CommandDenied("Вам запрещено использовать эту команду.")
    return True


@bot.check
async def check_disabled_systems(ctx):
    if not ctx.command:
        return True

    exempt_commands = {
        "включить",
        "отключить",
        "разрешить",
        "запретить",
        "разрешения",
        "пинг",
        "привет",
        "хелп",
    }
    cmd_name = normalize_command_name(ctx.command.qualified_name)
    if cmd_name in exempt_commands:
        return True

    reason = get_command_disabled_reason(cmd_name)
    if reason:
        raise SystemDisabled(reason)
    return True


def serialize_channel_overwrites(channel) -> dict[str, dict[str, int | str]]:
    """Store permission overwrites so a schedule never destroys channel setup."""
    result = {}
    for target, overwrite in channel.overwrites.items():
        allow, deny = overwrite.pair()
        target_type = "role" if isinstance(target, discord.Role) else "member"
        result[str(target.id)] = {
            "type": target_type,
            "allow": allow.value,
            "deny": deny.value,
        }
    return result


def restore_channel_overwrites(guild: discord.Guild, snapshot: dict) -> dict:
    overwrites = {}
    for target_id, data in snapshot.items():
        if not isinstance(data, dict):
            continue
        try:
            numeric_id = int(target_id)
            allow = discord.Permissions(int(data.get("allow", 0)))
            deny = discord.Permissions(int(data.get("deny", 0)))
        except (TypeError, ValueError):
            continue
        target = guild.get_role(numeric_id) if data.get("type") == "role" else guild.get_member(numeric_id)
        if target:
            overwrites[target] = discord.PermissionOverwrite.from_pair(allow, deny)
    return overwrites


async def apply_channel_schedule(channel, schedule: dict) -> bool:
    """Apply the scheduled public access state and return whether it changed."""
    try:
        open_times = [int(value) for value in schedule["open_times"]]
        close_times = [int(value) for value in schedule["close_times"]]
        if (
            not open_times
            or len(open_times) != len(close_times)
            or any(not 0 <= value < 24 * 60 for value in open_times + close_times)
            or any(opens_at == closes_at for opens_at, closes_at in zip(open_times, close_times))
        ):
            return False
        desired_open = is_channel_schedule_open(open_times, close_times)
    except (KeyError, TypeError, ValueError):
        return False
    if schedule.get("is_open") is desired_open:
        return False

    guild = channel.guild
    overwrites = restore_channel_overwrites(guild, schedule.get("overwrites", {}))
    if not desired_open:
        # Deny the two relevant permissions to every configured audience. Server
        # administrators retain Discord's built-in administrator bypass.
        targets = list(guild.roles) + [member for member in guild.members if member != guild.me]
        for target in targets:
            overwrite = overwrites.get(target, discord.PermissionOverwrite())
            overwrite.update(view_channel=False, send_messages=False)
            overwrites[target] = overwrite
    await channel.edit(
        overwrites=overwrites,
        reason="Расписание открытости канала",
    )
    schedule["is_open"] = desired_open
    return True


@tasks.loop(minutes=1)
async def channel_schedule_runner():
    changed = False
    schedules = settings.setdefault("channel_schedules", {})
    for channel_id, schedule in list(schedules.items()):
        if not isinstance(schedule, dict):
            schedules.pop(channel_id, None)
            changed = True
            continue
        try:
            channel = bot.get_channel(int(channel_id))
            if channel is None:
                continue
            if await apply_channel_schedule(channel, schedule):
                changed = True
        except (discord.Forbidden, discord.HTTPException) as exc:
            logging.getLogger(__name__).warning(
                "Could not apply channel schedule for %s: %s", channel_id, exc
            )
        except Exception:
            logging.getLogger(__name__).exception(
                "Unexpected error while applying channel schedule for %s", channel_id
            )
    if changed:
        save_json(SETTINGS_FILE, settings)


