@tasks.loop(minutes=5)
async def scheduled_events_runner():
    now_ts = int(time.time())
    changed = False
    for sid, req in list(events_data.setdefault("scheduled", {}).items()):
        if int(req.get("send_at") or 0) > now_ts:
            continue
        guild = bot.get_guild(int(req.get("guild_id") or ALLOWED_GUILD))
        if req.get("type") == "server":
            ok, _ = await publish_server_event(guild, req)
        else:
            ok, _ = await send_player_event_request(guild, req)
        req["status"] = "sent" if ok else "schedule_failed"
        events_data.setdefault("requests", {})[str(sid)] = req
        events_data.setdefault("scheduled", {}).pop(str(sid), None)
        changed = True
    if changed:
        save_events_data()


@tasks.loop(minutes=1)
async def verdict_request_watchdog():
    """Repeat unanswered pings and release drafts whose curator timed out."""
    now_ts = int(time.time())
    changed = False
    for req_id, req in list(verdicts_data.setdefault("requests", {}).items()):
        if not isinstance(req, dict) or str(req.get("status")) != "pending":
            continue
        claim_until = int(req.get("claim_until") or 0)
        if req.get("claimed_by") and claim_until <= now_ts:
            req.pop("claimed_by", None)
            req.pop("claim_until", None)
            req.pop("status_text", None)
            req["draft"] = {"verdict_text": "", "ops": []}
            guild = bot.get_guild(ALLOWED_GUILD)
            if guild:
                await _edit_verdict_request_message(
                    guild, req, "**Сейчас не рассматривается**",
                    discord.Color.orange(), view=VerdictReviewView(str(req_id)),
                )
            changed = True
        # Only unclaimed requests are "unprocessed" for the six-hour reminder.
        if req.get("claimed_by") or now_ts - int(req.get("created_at") or now_ts) < 6 * 3600:
            continue
        if now_ts - int(req.get("last_reminded_at") or 0) < 6 * 3600:
            continue
        channel = await get_channel_safe(req.get("request_channel_id"))
        if not channel:
            continue
        try:
            old = await channel.fetch_message(int(req.get("request_message_id")))
            await old.delete()
        except (discord.NotFound, discord.Forbidden, discord.HTTPException, TypeError, ValueError):
            pass
        blocks = build_verdict_request_message_blocks(req, getattr(channel, "guild", None))
        if container_components_available():
            message = await channel.send(**send_payload_for_container(blocks, view=make_container_view(blocks, view_cls=VerdictReviewView, view_args=(str(req_id),), timeout=None)))
        else:
            embed = Embed(title=f"📨 Заявка на вердикт #{req_id}", color=0x3498DB)
            embed.add_field(name="От", value=f"<@{req.get('author_id')}>", inline=False)
            embed.add_field(name="Ссылка", value=str(req.get("message_link") or "—"), inline=False)
            embed.add_field(name="Статус", value=verdict_request_status_text(req), inline=False)
            message = await channel.send(content=verdict_ping_roles_line(channel.guild) or None, embed=embed, view=VerdictReviewView(str(req_id)))
        req["request_channel_id"] = message.channel.id
        req["request_message_id"] = message.id
        req["last_reminded_at"] = now_ts
        changed = True
    if changed:
        save_verdicts_data()


