@bot.command(name="ролл")
async def ролл(ctx, *, query: str = ""):
    query = str(query or "").strip()
    if not query:
        await ctx.send(
            embed=Embed(
                title="🎲 Ролл",
                description=(
                    "Укажите вариант ролла:\n"
                    "• `!ролл 100` — число от 0 до 100\n"
                    "• `!ролл 75-100` — число от 75 до 100\n"
                    "• `!ролл ответ1, ответ2, ответ3` — случайный ответ из списка\n"
                    "• `!ролл 5 100` — 5 роллов от 0 до 100\n"
                    "• `!ролл 5 75-100` — 5 роллов от 75 до 100"
                ),
                color=0xff9000,
            )
        )
        return

    def parse_range(raw: str):
        raw = raw.strip()
        if re.fullmatch(r"-?\d+", raw):
            end = int(raw)
            return (0, end) if end >= 0 else (end, 0)
        match = re.fullmatch(r"(-?\d+)\s*-\s*(-?\d+)", raw)
        if match:
            start, end = int(match.group(1)), int(match.group(2))
            return (min(start, end), max(start, end))
        return None

    parts = query.split(maxsplit=1)
    rolls_count = None
    range_part = query
    if len(parts) == 2 and re.fullmatch(r"\d+", parts[0]):
        possible_count = int(parts[0])
        possible_range = parse_range(parts[1])
        if possible_range is not None:
            rolls_count = possible_count
            range_part = parts[1]

    number_range = parse_range(range_part)
    if number_range is not None:
        count = rolls_count or 1
        if count < 1 or count > 10:
            await ctx.send("❌ Количество роллов должно быть от 1 до 10.")
            return
        start, end = number_range
        results = [random.randint(start, end) for _ in range(count)]
        description = (
            f"Диапазон: **{start}–{end}**\n"
            + (f"Роллов: **{count}**\n" if count > 1 else "")
            + "\n".join(f"**{idx}.** {value}" for idx, value in enumerate(results, start=1))
        )
        await ctx.send(embed=Embed(title="🎲 Ролл", description=description, color=0xcc0c43))
        return

    answers = [part.strip() for part in query.split(",") if part.strip()]
    if len(answers) < 2:
        await ctx.send("❌ Для ролла ответов укажите минимум 2 варианта через запятую.")
        return
    choice = random.choice(answers)
    await ctx.send(
        embed=Embed(
            title="🎲 Ролл",
            description=f"Вариантов: **{len(answers)}**\nРезультат: **{choice}**",
            color=0xcc0c43,
        )
    )


