    class TechLibraryView(View):
        def __init__(self, owner_id: int):
            super().__init__(timeout=600)
            self.owner_id = owner_id
            self.selected_key = None
            self.item_select = Select(
                placeholder="Выберите предмет из библиотеки",
                options=self._build_item_options(),
                min_values=1,
                max_values=1,
            )
            self.item_select.callback = self.item_callback
            self.add_item(self.item_select)

        def _library_keys(self) -> list[str]:
            return sorted(
                [str(key) for key, entry in items_data.get("tech_library", {}).items() if isinstance(entry, dict)],
                key=lambda x: x.casefold(),
            )

        def _build_item_options(self):
            keys = self._library_keys()
            if not keys:
                return [SelectOption(label="Библиотека пустая", value="__empty__")]
            return [SelectOption(label=k[:100], value=k) for k in keys[:25]]

        def build_embed(self):
            library_total = len(items_data.get("tech_library", {}))
            selected_text = self.selected_key or "—"
            return Embed(
                title="📚 Библиотека техники",
                description=(
                    "Техника рассортирована по алфавиту. Выберите предмет из списка ниже, "
                    "чтобы открыть красивую карточку техники и вернуть её в магазин при необходимости.\n\n"
                    f"**Выбран предмет:** {selected_text}\n"
                    f"**Всего в библиотеке:** {library_total}"
                ),
                color=0x3498DB,
            )

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != self.owner_id:
                await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True)
                return False
            return True

        async def item_callback(self, interaction: Interaction):
            selected = self.item_select.values[0]
            if selected == "__empty__":
                await interaction.response.send_message("Библиотека пустая.", ephemeral=True)
                return
            self.selected_key = selected
            entry = items_data.get("tech_library", {}).get(selected, {})
            detail_view = View(timeout=180)
            restore_button = Button(label="↩️ Вернуть в магазин", style=ButtonStyle.success)

            async def restore_callback(btn_interaction: Interaction):
                await self.restore_selected(btn_interaction)

            restore_button.callback = restore_callback
            detail_view.add_item(restore_button)
            await interaction.response.send_message(
                embed=Embed(
                    title=f"📚 Техника: {selected}",
                    description=(
                        f"💰 Цена: **{fmt_money(int(entry.get('price', 0)))}**\n"
                        f"🏷 Категория: **{entry.get('category', '—')}**\n"
                        f"📝 Источник сохранения: **{entry.get('last_removed_reason', 'создание/редактирование')}**\n\n"
                        "Если это нужный предмет — нажмите кнопку ниже."
                    ),
                    color=0x3498DB,
                ),
                view=detail_view,
                ephemeral=True,
            )

        async def restore_selected(self, interaction: Interaction):
            if not self.selected_key:
                await interaction.response.send_message("Сначала выберите предмет из списка.", ephemeral=True)
                return
            lib = items_data.get("tech_library", {})
            entry = lib.get(self.selected_key)
            if not isinstance(entry, dict):
                await interaction.response.send_message("❌ Предмет не найден в библиотеке.", ephemeral=True)
                return
            restored = dict(entry)
            restored.pop("last_removed_at", None)
            restored.pop("last_removed_reason", None)
            restored.pop("saved_season", None)
            restored["key"] = self.selected_key
            items_data.setdefault("items", {})[self.selected_key] = restored
            save_items()
            await interaction.response.send_message(
                f"✅ Предмет **{self.selected_key}** возвращён в магазин.",
                ephemeral=True,
            )

    class RPYearCooldownModal(Modal):
        def __init__(self):
            super().__init__(title="Кулдаун RP-года", timeout=300)
            rp = investments.setdefault("rp_year", {})
            self.cooldown = TextInput(label="КД года (например 24ч, 7д)", required=True, default=format_interval(max(60, int(rp.get("cooldown", 86400) or 86400))))
            self.add_item(self.cooldown)

        async def on_submit(self, interaction: Interaction):
            try:
                new_cd = max(60, parse_interval(str(self.cooldown.value).strip()))
            except Exception as e:
                await interaction.response.send_message(f"❌ Ошибка: {e}", ephemeral=True)
                return
            rp = investments.setdefault("rp_year", {})
            old_cd = max(60, int(rp.get("cooldown", 86400) or 86400))
            now_ts = int(time.time())
            next_tick = rp.get("next_tick_at")
            if next_tick:
                remaining = max(0, int(next_tick) - now_ts)
                progress = 1 - min(1, remaining / old_cd)
                rp["next_tick_at"] = now_ts + max(1, int(new_cd * (1 - progress)))
            rp["cooldown"] = int(new_cd)
            save_investments()
            await interaction.response.send_message(f"✅ КД RP-года обновлён: **{format_interval(new_cd)}**. Старое сообщение будет обновляться без пересоздания.", ephemeral=True)

    class AltBoxRewardSlotModal(Modal):
        def __init__(self, slot_index: int):
            super().__init__(title=f"Альта бокс: ячейка {slot_index + 1}", timeout=600)
            self.slot_index = int(slot_index)
            rewards = settings.setdefault("alt_box_rewards", [])
            existing = rewards[self.slot_index] if self.slot_index < len(rewards) else {}
            self.name_input = TextInput(
                label="Название",
                required=False,
                default=str(existing.get("name", "")),
                placeholder="Пустое название = ячейка игнорируется",
                max_length=120,
            )
            self.chance_input = TextInput(
                label="Шанс выпадения (%)",
                required=False,
                default=str(existing.get("chance", "")),
                placeholder="Например: 15",
                max_length=20,
            )
            self.rarity_input = TextInput(
                label="Редкость",
                required=False,
                default=get_alt_box_rarity_data(existing.get("rarity"))["label"],
                placeholder="простой / ценный / арканный / альтарийский",
                max_length=30,
            )
            self.add_item(self.name_input)
            self.add_item(self.chance_input)
            self.add_item(self.rarity_input)

        async def on_submit(self, interaction: Interaction):
            name = str(self.name_input.value).strip()
            chance_raw = str(self.chance_input.value).replace("%", "").replace(",", ".").strip()
            rewards = list(settings.setdefault("alt_box_rewards", []))
            while len(rewards) <= self.slot_index:
                rewards.append({"name": "", "chance": 0, "rarity": "simple"})
            if not name and not chance_raw:
                rewards[self.slot_index] = {"name": "", "chance": 0, "rarity": "simple"}
            elif not name or not chance_raw:
                await interaction.response.send_message(
                    "❌ Для заполненной ячейки нужны и название, и шанс.", ephemeral=True
                )
                return
            else:
                try:
                    chance = float(chance_raw)
                except ValueError:
                    await interaction.response.send_message("❌ Шанс должен быть числом.", ephemeral=True)
                    return
                if chance <= 0:
                    await interaction.response.send_message("❌ Шанс должен быть больше 0.", ephemeral=True)
                    return
                rewards[self.slot_index] = {
                    "name": name[:120],
                    "chance": chance,
                    "rarity": normalize_alt_box_rarity(self.rarity_input.value),
                }
            settings["alt_box_rewards"] = rewards
            save_json(SETTINGS_FILE, settings)
            ensure_alta_box_item()
            await interaction.response.send_message(
                f"✅ Ячейка {self.slot_index + 1} сохранена.", ephemeral=True
            )

