    class AltBoxRewardsModal(Modal):
        def __init__(self):
            super().__init__(title="Награды Альта бокса", timeout=600)
            self.rewards = TextInput(
                label="Предмет | шанс | редкость",
                style=discord.TextStyle.paragraph,
                required=True,
                default="\n".join(
                    f"{r.get('name')} | {r.get('chance')} | {get_alt_box_rarity_data(r.get('rarity'))['label']}"
                    for r in get_alt_box_rewards()
                ),
                placeholder="Награда | шанс% | простой",
                max_length=1800,
            )
            self.add_item(self.rewards)

        async def on_submit(self, interaction: Interaction):
            parsed = []
            try:
                for line in str(self.rewards.value).splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = [p.strip() for p in line.split("|")]
                    if len(parts) >= 2:
                        name, chance = parts[0], parts[1]
                        rarity = parts[2] if len(parts) >= 3 else "простой"
                    elif "—" in line:
                        name, chance = line.rsplit("—", 1)
                        rarity = "простой"
                    else:
                        raise ValueError(f"Нет разделителя `|` в строке: {line}")
                    name = name.strip(" •")
                    chance = float(str(chance).replace("%", "").replace(",", ".").strip())
                    if not name or chance <= 0:
                        raise ValueError("Название не может быть пустым, шанс должен быть больше 0.")
                    parsed.append({"name": name[:120], "chance": chance, "rarity": normalize_alt_box_rarity(rarity)})
                if not parsed:
                    raise ValueError("Добавьте хотя бы одну награду.")
            except Exception as e:
                await interaction.response.send_message(f"❌ Ошибка: {e}", ephemeral=True)
                return
            settings["alt_box_rewards"] = parsed
            save_json(SETTINGS_FILE, settings)
            ensure_alta_box_item()
            await interaction.response.edit_message(embed=build_panel_embed(), view=PanelView())

    class AltBoxIssueModal(Modal):
        def __init__(self):
            super().__init__(title="Выдать Альта боксы", timeout=600)
            self.target = TextInput(label="Кому", required=True, placeholder="игроки / @роль / @игрок / ID")
            self.ttl = TextInput(label="Срок", required=True, default="1д", placeholder="1д, 12ч, 30м")
            self.add_item(self.target)
            self.add_item(self.ttl)

        async def on_submit(self, interaction: Interaction):
            try:
                ttl_seconds = parse_interval(str(self.ttl.value).strip())
                if ttl_seconds <= 0:
                    raise ValueError
            except Exception:
                await interaction.response.send_message("❌ Некорректный срок.", ephemeral=True)
                return
            target_clean = str(self.target.value).strip()
            role_match = re.match(r"^<@&(\d+)>", target_clean)
            targets = []
            if target_clean.lower() == "игроки":
                targets = [m for m in interaction.guild.members if not m.bot]
            elif role_match:
                role = interaction.guild.get_role(int(role_match.group(1)))
                targets = [m for m in (role.members if role else []) if not m.bot]
            else:
                member = parse_member_ref(interaction.guild, target_clean)
                if member and not member.bot:
                    targets = [member]
            if not targets:
                await interaction.response.send_message("❌ Получатели не найдены.", ephemeral=True)
                return
            expires_at = int(time.time()) + ttl_seconds
            for member in targets:
                slot = server_inventory.setdefault("users", {}).setdefault(str(member.id), {}).setdefault("Альта бокс", {"qty": 0, "expires_at": expires_at, "issued_by": str(interaction.user.id)})
                slot["qty"] = int(slot.get("qty", 0)) + 1
                slot["expires_at"] = max(int(slot.get("expires_at", expires_at)), expires_at)
                slot["issued_by"] = str(interaction.user.id)
            save_server_inventory()
            await interaction.response.send_message(f"✅ Альта боксы выданы: {len(targets)} получателей, срок {format_interval(ttl_seconds)}.", ephemeral=True)

