@bot.command(name="отключить")
@admin_or_command_access()
async def отключить(ctx, *, target: str = None):
    if not target:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Использование команды",
                description=(
                    "`!отключить компании` — отключить систему компаний\n"
                    "`!отключить заявки` — отключить систему заявок\n"
                    "`!отключить экономика` — отключить экономику\n"
                    "`!отключить все` — отключить все системы\n"
                    "`!отключить работа` — отключить конкретную команду"
                ),
                color=0x3498DB,
            )
        )
        return

    mode, value = parse_disable_target(target)
    if mode is None:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=(
                    "Неизвестная система/команда.\n"
                    "Доступно: `компании`, `заявки`, `экономика`, `все` или конкретная команда."
                ),
                color=0xFF0000,
            )
        )
        return

    if mode == "all_systems":
        for system_name in SYSTEM_COMMAND_GROUPS:
            settings["disabled_systems"][system_name] = True
        save_json(SETTINGS_FILE, settings)
        await ctx.send(
            embed=Embed(
                title="⛔ Системы отключены",
                description="Отключены системы: **компании**, **заявки**, **экономика**.",
                color=0xFF0000,
            )
        )
        return

    if mode == "system":
        settings["disabled_systems"][value] = True
        save_json(SETTINGS_FILE, settings)
        await ctx.send(
            embed=Embed(
                title="⛔ Система отключена",
                description=f"Система **{value}** отключена до команды `!включить {value}`.",
                color=0xFF0000,
            )
        )
        return

    disabled_commands = {
        normalize_command_name(name)
        for name in settings.get("disabled_commands", [])
        if isinstance(name, str)
    }
    if value in disabled_commands:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Уже отключено",
                description=f"Команда `!{value}` уже отключена.",
                color=0x3498DB,
            )
        )
        return

    disabled_commands.add(value)
    settings["disabled_commands"] = sorted(disabled_commands)
    save_json(SETTINGS_FILE, settings)
    await ctx.send(
        embed=Embed(
            title="⛔ Команда отключена",
            description=f"Команда `!{value}` отключена до команды `!включить {value}`.",
            color=0xFF0000,
        )
    )


@bot.command(name="включить")
@admin_or_command_access()
async def включить(ctx, *, target: str = None):
    if not target:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Использование команды",
                description=(
                    "`!включить компании` — включить систему компаний\n"
                    "`!включить заявки` — включить систему заявок\n"
                    "`!включить экономика` — включить экономику\n"
                    "`!включить все` — включить все системы\n"
                    "`!включить работа` — включить конкретную команду"
                ),
                color=0x3498DB,
            )
        )
        return

    mode, value = parse_disable_target(target)
    if mode is None:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=(
                    "Неизвестная система/команда.\n"
                    "Доступно: `компании`, `заявки`, `экономика`, `все` или конкретная команда."
                ),
                color=0xFF0000,
            )
        )
        return

    if mode == "all_systems":
        for system_name in SYSTEM_COMMAND_GROUPS:
            settings["disabled_systems"][system_name] = False
        save_json(SETTINGS_FILE, settings)
        await ctx.send(
            embed=Embed(
                title="✅ Системы включены",
                description="Включены системы: **компании**, **заявки**, **экономика**.",
                color=0x00FF00,
            )
        )
        return

    if mode == "system":
        settings["disabled_systems"][value] = False
        save_json(SETTINGS_FILE, settings)
        await ctx.send(
            embed=Embed(
                title="✅ Система включена",
                description=f"Система **{value}** снова активна.",
                color=0x00FF00,
            )
        )
        return

    disabled_commands = {
        normalize_command_name(name)
        for name in settings.get("disabled_commands", [])
        if isinstance(name, str)
    }
    if value not in disabled_commands:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Уже включено",
                description=f"Команда `!{value}` уже активна.",
                color=0x3498DB,
            )
        )
        return

    disabled_commands.remove(value)
    settings["disabled_commands"] = sorted(disabled_commands)
    save_json(SETTINGS_FILE, settings)
    await ctx.send(
        embed=Embed(
            title="✅ Команда включена",
            description=f"Команда `!{value}` снова активна.",
            color=0x00FF00,
        )
    )


@bot.command(name="разрешить")
@admin_or_command_access()
async def разрешить(ctx, target: str = None, *, command_name: str = None):
    if not target or not command_name:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Использование команды",
                description=(
                    "**Формат:** `!разрешить <@пользователь|@роль> <команда>`\n\n"
                    "**Примеры:**\n"
                    "`!разрешить @Чибрик анрег`\n"
                    "`!разрешить @Куратор доходдобавить`"
                ),
                color=0x3498DB,
            )
        )
        return

    cmd_key = normalize_command_name(command_name)
    cmd_obj = bot.get_command(cmd_key)
    if cmd_obj is None:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Команда `{cmd_key}` не найдена.",
                color=0xFF0000,
            )
        )
        return

    access = get_command_access(cmd_key)

    user_id = None
    role_id = None
    if ctx.message.role_mentions:
        role_id = str(ctx.message.role_mentions[0].id)
    elif ctx.message.mentions:
        user_id = str(ctx.message.mentions[0].id)
    else:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Нужно указать **упоминание пользователя** или **упоминание роли**.",
                color=0xFF0000,
            )
        )
        return

    if user_id:
        if user_id in access["users"]:
            await ctx.send(
                embed=Embed(
                    title="ℹ️ Уже разрешено",
                    description="У этого пользователя уже есть доступ к команде.",
                    color=0x3498DB,
                )
            )
            return
        access["users"].append(user_id)
        subject = f"пользователь {ctx.message.mentions[0].mention}"
    else:
        if role_id in access["roles"]:
            await ctx.send(
                embed=Embed(
                    title="ℹ️ Уже разрешено",
                    description="У этой роли уже есть доступ к команде.",
                    color=0x3498DB,
                )
            )
            return
        access["roles"].append(role_id)
        subject = f"роль {ctx.message.role_mentions[0].mention}"

    save_command_access()
    await ctx.send(
        embed=Embed(
            title="✅ Доступ выдан",
            description=f"{subject} теперь может использовать команду `!{cmd_obj.qualified_name}`.",
            color=0x00FF00,
        )
    )


@bot.command(name="запретить")
@admin_or_command_access()
async def запретить(ctx, target: str = None, *, command_name: str = None):
    if not target or not command_name:
        await ctx.send(
            embed=Embed(
                title="ℹ️ Использование команды",
                description=(
                    "**Формат:** `!запретить <@пользователь|@роль> <команда>`\n\n"
                    "**Примеры:**\n"
                    "`!запретить @Чибрик анрег`\n"
                    "`!запретить @Куратор доходдобавить`"
                ),
                color=0x3498DB,
            )
        )
        return

    cmd_key = normalize_command_name(command_name)
    cmd_obj = bot.get_command(cmd_key)
    if cmd_obj is None:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Команда `{cmd_key}` не найдена.",
                color=0xFF0000,
            )
        )
        return

    access = get_command_access(cmd_key)

    user_id = None
    role_id = None
    if ctx.message.role_mentions:
        role_id = str(ctx.message.role_mentions[0].id)
    elif ctx.message.mentions:
        user_id = str(ctx.message.mentions[0].id)
    else:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Нужно указать **упоминание пользователя** или **упоминание роли**.",
                color=0xFF0000,
            )
        )
        return

    if user_id:
        if user_id in access["users"]:
            access["users"].remove(user_id)
        if user_id not in access["denied_users"]:
            access["denied_users"].append(user_id)
        subject = f"пользователь {ctx.message.mentions[0].mention}"
    else:
        if role_id in access["roles"]:
            access["roles"].remove(role_id)
        if role_id not in access["denied_roles"]:
            access["denied_roles"].append(role_id)
        subject = f"роль {ctx.message.role_mentions[0].mention}"

    save_command_access()
    await ctx.send(
        embed=Embed(
            title="⛔ Доступ запрещён",
            description=f"{subject} теперь не может использовать команду `!{cmd_obj.qualified_name}`.",
            color=0xFF0000,
        )
    )


@bot.command(name="разрешения")
@admin_or_command_access()
async def разрешения(ctx):
    commands_map = command_access.get("commands", {})
    lines = []

    for cmd_name, access in commands_map.items():
        users = access.get("users", [])
        roles = access.get("roles", [])
        denied_users = access.get("denied_users", [])
        denied_roles = access.get("denied_roles", [])

        if not (users or roles or denied_users or denied_roles):
            continue

        lines.append(f"**!{cmd_name}**")
        if users:
            lines.append(f"✅ Пользователи: {' '.join(f'<@{uid}>' for uid in users)}")
        if roles:
            lines.append(f"✅ Роли: {' '.join(f'<@&{rid}>' for rid in roles)}")
        if denied_users:
            lines.append(
                f"⛔ Запрет users: {' '.join(f'<@{uid}>' for uid in denied_users)}"
            )
        if denied_roles:
            lines.append(
                f"⛔ Запрет роли: {' '.join(f'<@&{rid}>' for rid in denied_roles)}"
            )
        lines.append("")

    if not lines:
        await ctx.send(
            embed=Embed(
                title="📋 Разрешения",
                description="Пока нет выданных или запрещённых разрешений.",
                color=0x3498DB,
            )
        )
        return

    description = "\n".join(lines).strip()
    if len(description) > 4000:
        description = description[:3990] + "\n..."

    await ctx.send(
        embed=Embed(
            title="📋 Настроенные разрешения",
            description=description,
            color=0x3498DB,
        )
    )


# ================== SEASONS / SPHERES ==================


def get_active_spheres():
    active = seasons_data.get("active_season")
    return [
        sp
        for sp in seasons_data.get("spheres", {}).values()
        if sp.get("season") == active
    ]


def build_sphere_id(season_name: str, sphere_name: str) -> str:
    return f"{str(season_name).strip()}::{str(sphere_name).strip().lower()}"


def get_season_progress_map(season_name: str | None = None) -> dict:
    season = str(season_name or seasons_data.get("active_season") or "").strip()
    if not season:
        return {}
    seasons_data.setdefault("season_user_progress", {})
    season_map = seasons_data["season_user_progress"].setdefault(season, {})
    if not isinstance(season_map, dict):
        seasons_data["season_user_progress"][season] = {}
        season_map = seasons_data["season_user_progress"][season]
    return season_map


def get_user_progress_for_season(user_id: str, season_name: str | None = None) -> dict:
    return get_season_progress_map(season_name).setdefault(str(user_id), {})


def rename_season_everywhere(old_name: str, new_name: str) -> int:
    old_key = str(old_name or "").strip()
    new_key = str(new_name or "").strip()
    changed = 0

    if not old_key or not new_key or old_key == new_key:
        return changed

    seasons = seasons_data.setdefault("seasons", {})
    if old_key in seasons:
        seasons[new_key] = seasons.pop(old_key)
        changed += 1

    if str(seasons_data.get("active_season") or "") == old_key:
        seasons_data["active_season"] = new_key
        changed += 1

    progress = seasons_data.setdefault("season_user_progress", {})
    if old_key in progress:
        old_progress = progress.pop(old_key)
        if new_key in progress and isinstance(progress[new_key], dict) and isinstance(old_progress, dict):
            merged = dict(progress[new_key])
            merged.update(old_progress)
            progress[new_key] = merged
        else:
            progress[new_key] = old_progress
        changed += 1

    for sphere in seasons_data.setdefault("spheres", {}).values():
        if isinstance(sphere, dict) and str(sphere.get("season") or "") == old_key:
            sphere["season"] = new_key
            changed += 1

    for record in country_stats.values():
        if not isinstance(record, dict):
            continue
        seasons_map = record.get("seasons")
        if isinstance(seasons_map, dict) and old_key in seasons_map:
            old_population = seasons_map.pop(old_key)
            seasons_map.setdefault(new_key, old_population)
            changed += 1

    season_country_to_user, season_user_to_country = ensure_registration_maps()
    for mapping_group in (season_country_to_user, season_user_to_country):
        if old_key in mapping_group:
            old_mapping = mapping_group.pop(old_key)
            if new_key in mapping_group and isinstance(mapping_group[new_key], dict) and isinstance(old_mapping, dict):
                merged = dict(mapping_group[new_key])
                merged.update(old_mapping)
                mapping_group[new_key] = merged
            else:
                mapping_group[new_key] = old_mapping
            changed += 1

    for profile in country_owners.setdefault("user_profiles", {}).values():
        if not isinstance(profile, dict):
            continue
        registrations = profile.get("registrations")
        if isinstance(registrations, dict) and old_key in registrations:
            reg_record = registrations.pop(old_key)
            if isinstance(reg_record, dict):
                reg_record["season"] = new_key
            registrations[new_key] = reg_record
            changed += 1
        if str(profile.get("active_season") or "") == old_key:
            profile["active_season"] = new_key
            changed += 1

    if str(seasons_data.get("active_season") or "") == new_key:
        country_owners["country_to_user"] = dict(season_country_to_user.get(new_key, {}))
        country_owners["user_to_country"] = dict(season_user_to_country.get(new_key, {}))

    return changed


def get_user_sphere_level(user_id: str, sphere_id_or_name: str, season_name: str | None = None) -> int:
    progress = get_user_progress_for_season(user_id, season_name)
    key = str(sphere_id_or_name)
    if key in progress:
        return int(progress.get(key, 0))

    normalized = str(sphere_id_or_name).strip().casefold()
    target_season = str(season_name or seasons_data.get("active_season") or "")
    for sid, level in progress.items():
        sp = seasons_data.setdefault("spheres", {}).get(str(sid), {})
        if target_season and str(sp.get("season")) != target_season:
            continue
        if str(sp.get("name", "")).strip().casefold() == normalized:
            return int(level)
    return 0


def resolve_sphere_id_by_name(sphere_name: str, season_name: str | None = None) -> str | None:
    normalized = str(sphere_name).strip().casefold()
    target_season = str(season_name or seasons_data.get("active_season") or "")
    for sid, sp in seasons_data.setdefault("spheres", {}).items():
        if target_season and str(sp.get("season")) != target_season:
            continue
        if str(sp.get("name", "")).strip().casefold() == normalized:
            return str(sid)
    return None


def get_user_sphere_level_by_requirement(user_id: str, sphere_name: str, season_name: str | None = None) -> int:
    """Возвращает уровень сферы по требованию с учетом сезона и регистра."""
    sid = resolve_sphere_id_by_name(sphere_name, season_name)
    if sid:
        return get_user_sphere_level(user_id, sid, season_name)
    return 0


def set_user_sphere_level(user_id: str, sphere_id: str, level: int, season_name: str | None = None):
    get_user_progress_for_season(user_id, season_name)[str(sphere_id)] = int(level)
    save_seasons_data()


def get_economy_level_config(level: int) -> dict:
    levels = seasons_data.setdefault("economy_levels", {})
    config = levels.setdefault(str(level), {"sphere_count": 0, "sphere_level": 0, "roles": []})
    config.setdefault("sphere_count", 0)
    config.setdefault("sphere_level", 0)
    config.setdefault("roles", [])
    return config


def parse_discord_id_token(raw: str) -> str | None:
    """Extract a Discord snowflake from ID, mention, or id/<id>-style text."""
    token = str(raw or "").strip()
    if not token:
        return None
    match = re.search(r"(?:id/)?<[@#&]!?([0-9]{15,25})>|(?:id/)([0-9]{15,25})|([0-9]{15,25})", token, re.IGNORECASE)
    if not match:
        return None
    return next((group for group in match.groups() if group), None)


def parse_role_ids_from_text(guild: discord.Guild, raw: str) -> tuple[list[str], list[str]]:
    role_ids: list[str] = []
    unknown: list[str] = []
    role_by_name = {role.name.casefold(): role for role in (guild.roles if guild else [])}
    for token in re.split(r"[\s,;]+", str(raw or "").strip()):
        if not token:
            continue
        role_id = parse_discord_id_token(token)
        role = guild.get_role(int(role_id)) if guild and role_id else role_by_name.get(token.lstrip("@").casefold())
        if not role:
            unknown.append(token)
            continue
        if str(role.id) not in role_ids:
            role_ids.append(str(role.id))
    return role_ids, unknown


def resolve_channel_from_text(guild: discord.Guild, raw: str):
    token = str(raw or "").strip()
    channel_id = parse_discord_id_token(token)
    if channel_id and guild:
        channel = guild.get_channel(int(channel_id))
        if channel:
            return channel
    channel_name = token.lstrip("#").casefold()
    for channel in (guild.channels if guild else []):
        if getattr(channel, "name", "").casefold() == channel_name:
            return channel
    return None


def get_user_economy_level(user_id: str, season_name: str | None = None) -> tuple[int, dict | None]:
    progress = get_user_progress_for_season(str(user_id), season_name)
    levels = seasons_data.setdefault("economy_levels", {})
    best_level = 0
    best_config = None
    for level_text, config in levels.items():
        try:
            level = int(level_text)
            sphere_count = int(config.get("sphere_count", 0))
            sphere_level = int(config.get("sphere_level", 0))
        except (TypeError, ValueError):
            continue
        if level < 1 or level > 5 or sphere_count <= 0 or sphere_level <= 0:
            continue
        matched_count = 0
        for value in progress.values():
            try:
                current_level = int(value or 0)
            except (TypeError, ValueError):
                current_level = 0
            if current_level >= sphere_level:
                matched_count += 1
        if matched_count >= sphere_count and level > best_level:
            best_level = level
            best_config = config
    return best_level, best_config


async def sync_member_economy_roles(member: discord.Member) -> tuple[int, list[discord.Role], list[discord.Role]]:
    target_level, target_config = get_user_economy_level(str(member.id), seasons_data.get("active_season"))
    configured_role_ids = {
        str(role_id)
        for config in seasons_data.setdefault("economy_levels", {}).values()
        for role_id in config.get("roles", [])
    }
    target_role_ids = {
        str(role_id) for role_id in (target_config or {}).get("roles", [])
    }
    to_remove = [
        role for role in member.roles
        if str(role.id) in configured_role_ids and str(role.id) not in target_role_ids
    ]
    to_add = [
        role for role_id in target_role_ids
        if str(role_id).isdigit()
        if (role := member.guild.get_role(int(role_id))) and role not in member.roles
    ]
    reason = f"Автосинхронизация уровня экономики: {target_level or 'нет уровня'}"
    if to_remove:
        await member.remove_roles(*to_remove, reason=reason)
    if to_add:
        await member.add_roles(*to_add, reason=reason)
    return target_level, to_add, to_remove




def get_sphere_reward_role_ids_for_user(user_id: str, season_name: str | None = None) -> set[str]:
    season_key = str(season_name or seasons_data.get("active_season") or "").strip()
    progress = get_user_progress_for_season(str(user_id), season_key)
    reward_ids: set[str] = set()
    for sphere_id, level in progress.items():
        sphere = seasons_data.setdefault("spheres", {}).get(str(sphere_id))
        if not isinstance(sphere, dict):
            continue
        try:
            current_level = max(0, int(level or 0))
        except (TypeError, ValueError):
            current_level = 0
        for level_data in sphere.get("levels", [])[:current_level]:
            if isinstance(level_data, dict):
                reward_ids.update(str(rid) for rid in level_data.get("rewards", []) if str(rid).isdigit())
    return reward_ids


async def sync_member_sphere_reward_roles(member: discord.Member, season_name: str | None = None) -> tuple[list[discord.Role], list[discord.Role]]:
    configured_role_ids = {
        str(rid)
        for sphere in seasons_data.setdefault("spheres", {}).values()
        if isinstance(sphere, dict) and (not season_name or str(sphere.get("season") or seasons_data.get("active_season") or "") == str(season_name))
        for level_data in sphere.get("levels", [])
        if isinstance(level_data, dict)
        for rid in level_data.get("rewards", [])
        if str(rid).isdigit()
    }
    target_role_ids = get_sphere_reward_role_ids_for_user(str(member.id), season_name)
    to_remove = [
        role for role in member.roles
        if str(role.id) in configured_role_ids and str(role.id) not in target_role_ids
    ]
    to_add = [
        role for role_id in target_role_ids
        if (role := member.guild.get_role(int(role_id))) and role not in member.roles
    ]
    reason = "Автосинхронизация наград уровней сфер"
    if to_remove:
        await member.remove_roles(*to_remove, reason=reason)
    if to_add:
        await member.add_roles(*to_add, reason=reason)
    return to_add, to_remove


async def sync_guild_economy_roles(guild: discord.Guild) -> dict[str, int]:
    """Синхронизирует роли экономики для всех игроков сервера."""
    stats = {"checked": 0, "changed": 0, "added": 0, "removed": 0, "failed": 0}
    for member in guild.members:
        if member.bot:
            continue
        stats["checked"] += 1
        try:
            _, roles_added, roles_removed = await sync_member_economy_roles(member)
        except (discord.Forbidden, discord.HTTPException):
            stats["failed"] += 1
            continue
        added_count = len(roles_added)
        removed_count = len(roles_removed)
        if added_count or removed_count:
            stats["changed"] += 1
            stats["added"] += added_count
            stats["removed"] += removed_count
    return stats


@bot.command(name="создатьсезон")
@admin_or_command_access()
async def создатьсезон(ctx):
    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel

    await ctx.send(
        embed=Embed(
            title="📅 Создание сезона",
            description="Укажите год сезона.",
            color=0x3498DB,
        )
    )
    try:
        msg = await bot.wait_for("message", check=check, timeout=120)
        year = msg.content.strip()
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Не удалось получить название сезона.",
                color=0xFF0000,
            )
        )
        return

    if not year:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Название сезона не может быть пустым.",
                color=0xFF0000,
            )
        )
        return

    seasons_data.setdefault("seasons", {}).setdefault(
        year, {"created_by": str(ctx.author.id), "created_at": int(time.time())}
    )
    save_seasons_data()
    await ctx.send(
        embed=Embed(
            title="✅ Сезон создан",
            description=f"Сезон **{year}** сохранён.",
            color=0x00FF00,
        )
    )


@bot.command(name="списоксезонов")
async def списоксезонов(ctx):
    seasons = list(seasons_data.get("seasons", {}).keys())
    if not seasons:
        await ctx.send(
            embed=Embed(
                title="📅 Сезоны", description="Сезоны ещё не созданы.", color=0xFFA500
            )
        )
        return

    active = seasons_data.get("active_season")
    lines = []
    for name in seasons:
        marker = " (активный)" if str(name) == str(active) else ""
        lines.append(f"• **{name}**{marker}")

    await ctx.send(
        embed=Embed(
            title="📅 Список сезонов", description="\n".join(lines), color=0x3498DB
        )
    )


@bot.command(name="установитьсезон")
@admin_or_command_access()
async def установитьсезон(ctx, year: str):
    seasons = list(seasons_data.get("seasons", {}).keys())
    if not seasons:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Сезоны не созданы. Сначала используйте !создатьсезон.",
                color=0xFF0000,
            )
        )
        return

    query = year.strip().casefold()
    exact = [s for s in seasons if str(s).casefold() == query]
    starts = [s for s in seasons if str(s).casefold().startswith(query)]
    contains = [s for s in seasons if query in str(s).casefold()]
    matches = exact or starts or contains

    if not matches:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Сезон не найден. Используйте `!списоксезонов` для просмотра доступных сезонов.",
                color=0xFF0000,
            )
        )
        return

    selected = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:20]))
        await ctx.send(
            embed=Embed(
                title="🔎 Найдено несколько сезонов",
                description=f"Уточните номер сезона:\n\n{options}",
                color=0x3498DB,
            )
        )

        def check(m):
            return m.author == ctx.author and m.channel == ctx.channel

        try:
            msg = await bot.wait_for("message", check=check, timeout=60)
            idx = int(msg.content.strip()) - 1
            if idx < 0 or idx >= min(len(matches), 20):
                raise ValueError
            selected = matches[idx]
        except Exception:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Неверный номер сезона.",
                    color=0xFF0000,
                )
            )
            return

    seasons_data["active_season"] = selected
    get_season_progress_map(selected)
    sync_legacy_occupied_maps_for_active_season()
    save_seasons_data()
    save_country_owners()
    await ctx.send(
        embed=Embed(
            title="✅ Активный сезон",
            description=f"Теперь активен сезон **{selected}**.",
            color=0x00FF00,
        )
    )
    await ensure_occupied_registrations_message()


@bot.command(name="редактсезон")
@admin_or_command_access()
async def редактсезон(ctx, старое_название: str, *, новое_название: str):
    old_name = str(старое_название or "").strip()
    new_name = str(новое_название or "").strip()
    seasons = seasons_data.setdefault("seasons", {})

    if not old_name or old_name not in seasons:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Сезон не найден. Используйте `!списоксезонов` для просмотра доступных сезонов.",
                color=0xFF0000,
            )
        )
        return

    if not new_name:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Новое название сезона не может быть пустым.",
                color=0xFF0000,
            )
        )
        return

    if new_name in seasons and new_name != old_name:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Сезон **{new_name}** уже существует.",
                color=0xFF0000,
            )
        )
        return

    changed = rename_season_everywhere(old_name, new_name)
    save_seasons_data()
    save_json(COUNTRY_STATS_FILE, country_stats)
    save_country_owners()

    await ctx.send(
        embed=Embed(
            title="✅ Сезон обновлён",
            description=f"Сезон **{old_name}** переименован в **{new_name}**. Обновлено связанных записей: **{changed}**.",
            color=0x00FF00,
        )
    )
    await ensure_occupied_registrations_message()


@bot.command(name="удалитьсферу")
@admin_or_command_access()
async def удалитьсферу(ctx, *, sphere_name: str):
    query = sphere_name.strip().casefold()
    active = seasons_data.get("active_season")
    matches = [
        (k, v)
        for k, v in seasons_data.get("spheres", {}).items()
        if str(v.get("season")) == str(active)
        and query in str(v.get("name", "")).strip().casefold()
    ]
    if not matches:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка", description="Сфера не найдена в активном сезоне.", color=0xFF0000
            )
        )
        return
    if len(matches) > 1:
        lines = "\n".join([f"• {v.get('name')}" for _, v in matches[:10]])
        await ctx.send(
            embed=Embed(
                title="⚠️ Несколько сфер",
                description=f"Уточните название:\n{lines}",
                color=0xFFA500,
            )
        )
        return
    key, sphere = matches[0]
    del seasons_data["spheres"][key]
    for _, progress in get_season_progress_map(active).items():
        progress.pop(str(key), None)
    save_seasons_data()
    await ctx.send(
        embed=Embed(
            title="✅ Сфера удалена",
            description=f"Сфера **{sphere.get('name', sphere_name)}** удалена.",
            color=0x00FF00,
        )
    )


@bot.command(name="удалитьсезон")
@admin_or_command_access()
async def удалитьсезон(ctx, year: str):
    if year not in seasons_data.get("seasons", {}):
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка", description="Сезон не найден.", color=0xFF0000
            )
        )
        return
    del seasons_data["seasons"][year]
    to_del = [
        k for k, v in seasons_data.get("spheres", {}).items() if v.get("season") == year
    ]
    for k in to_del:
        del seasons_data["spheres"][k]
    seasons_data.setdefault("season_user_progress", {}).pop(str(year), None)
    if seasons_data.get("active_season") == year:
        seasons_data["active_season"] = None
    save_seasons_data()
    await ctx.send(
        embed=Embed(
            title="✅ Сезон удалён",
            description=f"Сезон **{year}** удалён вместе со сферами ({len(to_del)} шт.).",
            color=0x00FF00,
        )
    )


