class EconomySettingsSelect(Select):
    def __init__(self, actor_id: int):
        self.actor_id = int(actor_id)
        options = []
        for level in range(1, 6):
            config = get_economy_level_config(level)
            count = int(config.get("sphere_count") or 0)
            sphere_level = int(config.get("sphere_level") or 0)
            status = f"{count} сфер ур. {sphere_level}+" if count and sphere_level else "не настроен"
            options.append(SelectOption(label=f"Экономика {level} уровень", value=f"economy:{level}", description=status[:100], emoji="🏛️"))
        for threshold in ARMY_RATIO_ROLE_THRESHOLDS:
            config = get_army_ratio_role_config(threshold)
            status = f"ролей: {len(config.get('roles', []))}" if config.get("roles") else "не настроен"
            options.append(SelectOption(label=f"Армия от {threshold}%", value=f"army:{threshold}", description=status, emoji="🪖"))
        super().__init__(placeholder="Выберите настройку экономики или роли армии", options=options, min_values=1, max_values=1)

    async def callback(self, interaction: Interaction):
        if interaction.user.id != self.actor_id:
            await interaction.response.send_message("Это меню открыто не для вас.", ephemeral=True)
            return
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message("⛔ Настраивать экономику может только администратор.", ephemeral=True)
            return
        kind, value = self.values[0].split(":", 1)
        if kind == "army":
            await interaction.response.send_modal(ArmyRatioRoleModal(int(value)))
        else:
            await interaction.response.send_modal(EconomyLevelModal(int(value)))


