@bot.command(name="экономика")
@admin_or_command_access()
async def экономика(ctx):
    lines = []
    for level in range(1, 6):
        config = get_economy_level_config(level)
        count = int(config.get("sphere_count") or 0)
        sphere_level = int(config.get("sphere_level") or 0)
        roles = [ctx.guild.get_role(int(role_id)) for role_id in config.get("roles", []) if str(role_id).isdigit()]
        roles_text = ", ".join(role.mention for role in roles if role) or "роль не указана"
        if count and sphere_level and roles:
            lines.append(f"**{level}.** {count} сфер уровня {sphere_level}+ → {roles_text}")
        else:
            lines.append(f"**{level}.** не настроен")

    army_lines = []
    for threshold in ARMY_RATIO_ROLE_THRESHOLDS:
        config = get_army_ratio_role_config(threshold)
        roles = [ctx.guild.get_role(int(role_id)) for role_id in config.get("roles", []) if str(role_id).isdigit()]
        roles_text = ", ".join(role.mention for role in roles if role) or "роль не указана"
        army_lines.append(f"**Армия от {threshold}%.** {roles_text}")

    await ctx.send(
        embed=Embed(
            title="🏛️ Уровни экономики и роли армии",
            description=(
                "Выберите пункт в списке ниже и заполните форму.\n\n"
                "**Уровни экономики:**\n"
                + "\n".join(lines)
                + "\n\n**Роли по доле армии от населения + армии:**\n"
                + "\n".join(army_lines)
                + "\n\nПример: `3 сферы` и `уровень 1` значит — любые 3 сферы должны быть 1 уровня или выше. "
                "Для армии бот выбирает наибольший настроенный порог, не превышающий текущий процент."
            ),
            color=0xF1C40F,
        ),
        view=EconomyLevelView(ctx.author.id),
    )


class SphereLevelSetModal(Modal):
    def __init__(self, target_member: discord.Member, sphere_id: str, season_name: str):
        sphere = seasons_data.get("spheres", {}).get(str(sphere_id), {})
        sphere_name = sphere.get("name", str(sphere_id))
        current_level = get_user_sphere_level(str(target_member.id), str(sphere_id), season_name)
        super().__init__(title=f"Изменить уровень: {sphere_name}", timeout=300)
        self.target_member = target_member
        self.sphere_id = str(sphere_id)
        self.sphere_name = sphere_name
        self.season_name = str(season_name)
        self.current_level = int(current_level)
        self.new_level = TextInput(
            label="Новый уровень (0+)",
            required=True,
            default=str(self.current_level),
            max_length=6,
        )
        self.add_item(self.new_level)

    async def on_submit(self, interaction: Interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message(
                "❌ Только администратор может менять уровни сфер.", ephemeral=True
            )
            return
        try:
            parsed = int(str(self.new_level.value).strip())
            if parsed < 0:
                raise ValueError
        except ValueError:
            await interaction.response.send_message(
                "❌ Уровень должен быть целым числом не ниже 0.", ephemeral=True
            )
            return

        set_user_sphere_level(
            str(self.target_member.id),
            self.sphere_id,
            parsed,
            self.season_name,
        )
        try:
            sphere_roles_added, sphere_roles_removed = await sync_member_sphere_reward_roles(self.target_member, self.season_name)
            economy_level, roles_added, roles_removed = await sync_member_economy_roles(self.target_member)
        except discord.Forbidden:
            await interaction.response.send_message(
                embed=Embed(
                    title="⚠️ Сфера обновлена, но роли экономики не изменены",
                    description=(
                        "У бота не хватает прав на управление одной из ролей экономики. "
                        "Проверьте право `Управление ролями` и позицию роли бота выше выдаваемых ролей."
                    ),
                    color=0xF1C40F,
                ),
                ephemeral=True,
            )
            return
        except discord.HTTPException:
            await interaction.response.send_message(
                embed=Embed(
                    title="⚠️ Сфера обновлена, но роли экономики не изменены",
                    description="Discord не принял изменение ролей. Попробуйте ещё раз или проверьте роли уровня экономики.",
                    color=0xF1C40F,
                ),
                ephemeral=True,
            )
            return
        all_added = list(dict.fromkeys([*sphere_roles_added, *roles_added]))
        all_removed = list(dict.fromkeys([*sphere_roles_removed, *roles_removed]))
        added_text = ", ".join(role.mention for role in all_added) or "—"
        removed_text = ", ".join(role.mention for role in all_removed) or "—"
        await interaction.response.send_message(
            embed=Embed(
                title="✅ Уровень сферы обновлён",
                description=(
                    f"{self.target_member.mention}: **{self.sphere_name}** "
                    f"(сезон {self.season_name}) — **{self.current_level} → {parsed}**.\n\n"
                    f"🏛️ Уровень экономики: **{economy_level or 'не подходит ни под один уровень'}**\n"
                    f"➕ Выданы роли: {added_text}\n"
                    f"➖ Сняты роли: {removed_text}"
                ),
                color=0x00FF00,
            ),
            ephemeral=True,
        )


