async def _edit_verdict_request_message(
    guild: discord.Guild, req: dict, status_text: str, color: discord.Color, view: View | None = None
):
    # Persist the displayed wording too: restored Components V2 messages must
    # not fall back to the default pending status after a bot restart.
    req["status_text"] = status_text
    save_verdicts_data()
    channel_id = req.get("request_channel_id")
    message_id = req.get("request_message_id")
    if not channel_id or not message_id:
        return
    ch = guild.get_channel(int(channel_id)) if guild else None
    if not ch:
        return
    try:
        msg = await ch.fetch_message(int(message_id))
        em = (
            msg.embeds[0]
            if msg.embeds
            else Embed(title=f"📨 Заявка на вердикт #{req.get('id')}", color=color)
        )
        em.color = color
        if em.fields:
            em.set_field_at(
                0, name="От", value=f"<@{req.get('author_id')}>", inline=False
            )
            if len(em.fields) > 1:
                em.set_field_at(
                    1,
                    name="Ссылка",
                    value=str(req.get("message_link") or "—"),
                    inline=False,
                )
            if len(em.fields) > 2:
                em.set_field_at(2, name="Статус", value=status_text, inline=False)
            else:
                em.add_field(name="Статус", value=status_text, inline=False)
        else:
            em.add_field(name="От", value=f"<@{req.get('author_id')}>", inline=False)
            em.add_field(
                name="Ссылка", value=str(req.get("message_link") or "—"), inline=False
            )
            em.add_field(name="Статус", value=status_text, inline=False)
        if container_components_available():
            blocks = build_verdict_request_message_blocks(req, guild, status_text)
            await msg.edit(content=None, embed=None, view=make_container_view(blocks, view_cls=type(view), view_args=(getattr(view, "req_id", str(req.get("id"))),), timeout=None) if view is not None else make_container_view(blocks))
        else:
            await msg.edit(embed=em, view=view)
    except Exception:
        logging.getLogger(__name__).exception(
            "Could not update verdict request message #%s", req.get("id")
        )


def verdict_request_status_text(req: dict) -> str:
    """Return the final persisted status text for a moderation request."""
    status = str(req.get("status") or "pending")
    if status == "rejected":
        reason = str(req.get("reject_reason") or "Причина не указана.")
        moderator = req.get("processed_by")
        reviewed = f", отклонил <@{moderator}>" if moderator else ", отклонено"
        return f"❌ Заявка #{req.get('id')}: отправил <@{req.get('author_id')}>{reviewed}: {reason}"
    if status == "finalized":
        moderator = req.get("processed_by")
        reviewed = f", принял <@{moderator}>" if moderator else ", принято"
        return f"✅ Заявка #{req.get('id')}: отправил <@{req.get('author_id')}>{reviewed}"
    claimed_by = req.get("claimed_by")
    claim_until = int(req.get("claim_until") or 0)
    if claimed_by and claim_until > int(time.time()):
        return f"<@{claimed_by}> взялся за рассмотрение. Рассматривается до <t:{claim_until}:F>"
    return str(req.get("status_text") or "**Сейчас не рассматривается**")


def verdict_is_claimed_by(req: dict, user_id: int | str) -> bool:
    return (
        str(req.get("claimed_by") or "") == str(user_id)
        and int(req.get("claim_until") or 0) > int(time.time())
    )


def build_verdict_player_info_embed(user_id: str, section: str) -> Embed:
    state = ensure_player_state(user_id)
    user = ensure_user(user_id)
    if section == "relations":
        return build_relations_embed(user_id)
    if section == "description":
        return Embed(title="📄 Описание игрока", description=str(state.get("admin_description") or "Описание пока не задано."), color=0x3498DB)
    if section == "balance":
        return Embed(title="💰 Баланс игрока", description=f"Наличка: **{fmt_money(int(user.get('наличка', 0)))}**\nЗаморожено: **{fmt_money(int(user.get('заморожено', 0)))}**", color=0x2ECC71)
    entries = get_passive_entries(user_id)
    stat_entries = state.get("stat_passives", [])
    lines = [f"• {'Расход' if e.get('type') == 'expense' else 'Доход'}: {fmt_passive_amount(e.get('amount', 0))} / {format_interval(int(e.get('cooldown', 86400)))} — {e.get('description', '—')}" for e in entries]
    lines.extend(f"• {'Репутация' if e.get('stat') == 'reputation' else 'Счастье'}: {e.get('amount', 0):+}% / {format_interval(int(e.get('cooldown', 86400)))} — {e.get('description', '—')}" for e in stat_entries)
    return Embed(title="⏱️ Пассивы игрока", description="\n".join(lines)[:4096] or "Пассивных операций нет.", color=0x3498DB)


def build_verdict_player_info_block(user_id: str, section: str) -> str:
    """Format verdict player data like the regular profile, without code-like keys."""
    embed = build_verdict_player_info_embed(user_id, section)
