def format_verdict_operation_result(op: dict, snapshot: dict | None = None) -> str:
    """Return a public verdict operation with its reason preserved."""
    label = str(op.get("label") or "операция")
    kind = str(op.get("kind") or "")
    result = label
    if snapshot and kind in {"reputation", "happiness", "science"}:
        state_key = {"reputation": "reputation", "happiness": "happiness", "science": "science"}[kind]
        old, new = snapshot.get(state_key), op.get("value")
        if old is not None and new is not None:
            title = {"reputation": "Репутация", "happiness": "Счастье", "science": "Наука"}[kind]
            suffix = "%" if kind in {"reputation", "happiness"} else ""
            result = f"{title}: **{old}{suffix} → {new}{suffix}**"
    elif snapshot and kind == "money" and snapshot.get("cash_before") is not None:
        delta = int(op.get("amount", 0))
        result = f"Деньги: **{'+' if delta >= 0 else '-'}{fmt_money(abs(delta))}**"
    elif snapshot and kind == "population" and snapshot.get("population_before") is not None:
        old = int(snapshot["population_before"])
        amount = int(op.get("amount", 0)) * (1 if op.get("mode") == "add" else -1)
        result = f"Население: **{fmt_num(old)} → {fmt_num(max(0, old + amount))}**"
    elif snapshot and kind == "army" and snapshot.get("soldiers") is not None:
        old = int(snapshot["soldiers"])
        amount = int(op.get("amount", 0)) * (1 if op.get("mode") == "add" else -1)
        result = f"Армия: **{fmt_num(old)} → {fmt_num(max(0, old + amount))}**"

    reason = str(op.get("reason") or op.get("description") or "").strip()
    if reason and reason.casefold() not in result.casefold():
        result += f" — **Причина:** {reason}"
    return result


def verdict_operation_key(op: dict) -> tuple:
    """Identify a configurable operation in a verdict draft.

    Reopening an action in the review menu changes this draft operation instead
    of silently adding another identical operation.
    """
    kind = str(op.get("kind") or "")
    return (
        kind,
        str(op.get("external_kind") or op.get("mode") or op.get("flow_type") or op.get("stat") or ""),
        str(op.get("other_id") or op.get("sphere_id") or op.get("item_key") or op.get("target") or op.get("index") or ""),
    )


def upsert_verdict_operation(req: dict, operation: dict) -> None:
    ops = req.setdefault("draft", {}).setdefault("ops", [])
    key = verdict_operation_key(operation)
    for index, existing in enumerate(ops):
        if isinstance(existing, dict) and verdict_operation_key(existing) == key:
            ops[index] = operation
            return
    ops.append(operation)


def build_verdict_pages(req: dict) -> list[Embed]:
    draft = req.get("draft", {})
    ops = draft.get("ops", [])
    processed_by = req.get("processed_by")
    status_map = {
        "pending": "⏳ На рассмотрении",
        "rejected": "❌ Отклонено",
        "finalized": "✅ Принято",
        "approved_with_note": "✅ Принято с оговоркой",
    }
    lines = [
        f"**Заявка:** #{req.get('id')}",
        f"**Автор запроса:** <@{req.get('author_id')}>",
        *([f"**Вердикт создан модератором:** <@{req.get('created_by_moderator_id')}>"] if req.get('created_by_moderator_id') else []),
        f"**Статус:** {status_map.get(req.get('status'), req.get('status') or '—')}",
        f"**Рассмотрел:** <@{processed_by}>" if processed_by else "**Рассмотрел:** —",
        f"**Ссылка:** {req.get('message_link')}",
        f"**Текст вердикта:**\n{draft.get('verdict_text') or '—'}",
        "",
        *([f"**Сделано по выбору игрока:** {req.get('player_choice_title', '—')}", f"**Описание выбора:** {req.get('player_choice_description', '—')}", ""] if req.get("source") == "event_choice" and req.get("show_player_choice_public") else []),
        "**Операции:**",
    ]
    snapshots = req.get("applied_snapshots", [])
    if ops:
        for idx, op in enumerate(ops, start=1):
            snapshot = snapshots[idx - 1] if isinstance(snapshots, list) and idx <= len(snapshots) else None
            lines.append(f"{idx}. {format_verdict_operation_result(op, snapshot)}")
    else:
        lines.append("—")

    chunks = chunk_lines_for_embed(lines, limit=3900)
    pages = []
    for i, chunk in enumerate(chunks, start=1):
        title = f"⚖️ Вердикт #{req.get('id')}" if req.get("status") in {"finalized", "rolled_back"} else "📋 Предпросмотр вердикта"
        em = Embed(title=title, description=chunk, color=0x3498DB)
        footer = f"Страница {i}/{len(chunks)}"
        if req.get("ai_suggestions_used"):
            footer += " • Сделано с использованием ИИ"
        if str(req.get("status")) == "rolled_back":
            footer += f" • Откатано модератором <@{req.get('rolled_back_by')}>"
            em.color = 0xE67E22
        em.set_footer(text=footer)
        pages.append(em)
    return pages or [
        Embed(title=f"⚖️ Вердикт #{req.get('id')}" if req.get("status") in {"finalized", "rolled_back"} else "📋 Предпросмотр вердикта", description="Пусто", color=0x3498DB)
    ]


class VerdictPagesView(LayoutViewBase if container_components_available() else View):
    def __init__(self, pages: list[Embed], user_id: int, index: int = 0):
        super().__init__(timeout=180)
        self.pages = pages
        self.user_id = user_id
        self.index = max(0, min(int(index), max(0, len(pages) - 1)))

    async def interaction_check(self, interaction: Interaction) -> bool:
        if interaction.user.id != self.user_id:
            await interaction.response.send_message(
                "❌ Это меню не для вас.", ephemeral=True
            )
            return False
        return True

    @discord.ui.button(label="⬅️", style=ButtonStyle.secondary)
    async def back(self, interaction: Interaction, button: Button):
        self.index = (self.index - 1) % len(self.pages)
        if container_components_available():
            block = str(self.pages[self.index])
            await interaction.response.edit_message(
                content=None,
                embed=None,
                view=make_container_view([block], view_cls=VerdictPagesView, view_args=(self.pages, self.user_id, self.index), timeout=180),
            )
        else:
            await interaction.response.edit_message(embed=self.pages[self.index], view=self)

    @discord.ui.button(label="➡️", style=ButtonStyle.secondary)
    async def next(self, interaction: Interaction, button: Button):
        self.index = (self.index + 1) % len(self.pages)
        if container_components_available():
            block = str(self.pages[self.index])
            await interaction.response.edit_message(
                content=None,
                embed=None,
                view=make_container_view([block], view_cls=VerdictPagesView, view_args=(self.pages, self.user_id, self.index), timeout=180),
            )
        else:
            await interaction.response.edit_message(embed=self.pages[self.index], view=self)


def parse_member_ref(guild: discord.Guild, raw: str):
    value = str(raw or "").strip()
    if not value or not guild:
        return None

    mention_id = value.replace("<@", "").replace("!", "").replace(">", "")
    if mention_id.isdigit():
        return guild.get_member(int(mention_id))

    # Use the same lookup as MemberQueryConverter, so item commands accept a
    # Discord username, server nickname, global display name, mention, or ID
    # consistently. Ambiguous partial matches are deliberately rejected.
    return resolve_member_query(guild, value)


def build_verdict_request_blocks(req: dict, status_text: str | None = None) -> list[str]:
    status_text = status_text or verdict_request_status_text(req)
    lines = [
        f"## 📨 Заявка на вердикт #{req.get('id')}",
        f"-# **От:** <@{req.get('author_id')}>",
        f"-# **Ссылка:** {req.get('message_link') or '—'}",
    ]
    if req.get("created_by_moderator_id"):
        lines.append(f"-# **Создано модератором:** <@{req.get('created_by_moderator_id')}>`)".replace('>`)', '>'))
    lines.append(f"-# **Статус:** {status_text}")
    draft = req.get("draft", {})
    draft_text = str(draft.get("verdict_text") or "").strip()
    draft_ops = draft.get("ops", [])
    if draft_text or draft_ops:
        lines.append("### 📝 Текущий черновик")
        lines.append(draft_text[:1000] or "Текст вердикта пока не задан.")
        if draft_ops:
            lines.append("**Операции:**")
            lines.extend(f"• {format_verdict_operation_result(op)}" for op in draft_ops if isinstance(op, dict))
    return ["\n".join(lines)[:3900]]


def build_verdict_request_message_blocks(req: dict, guild: discord.Guild | None, status_text: str | None = None) -> list[str]:
    """Build all text displayed in a verdict-request message.

    Components V2 messages cannot have a top-level ``content`` field.  Keep the
    moderator-role mentions in a TextDisplay block together with the request,
    rather than adding them to the payload after it has become a container.
    """
    ping_block = verdict_ping_roles_line(guild) if guild else ""
    request_blocks = build_verdict_request_blocks(req, status_text)
    return ([ping_block] if ping_block else []) + request_blocks


def build_verdict_page_blocks(req: dict) -> list[str]:
    embeds = build_verdict_pages(req)
    return [f"## {em.title}\n{em.description or ''}\n-# {getattr(em.footer, 'text', '') or ''}" for em in embeds]


async def send_verdict_pages_response(interaction: Interaction, req: dict, *, ephemeral: bool = True):
    """Refresh the shared review panel after a draft edit instead of posting a settings notice."""
    if str(req.get("status")) == "pending" and interaction.guild:
        await interaction.response.defer(ephemeral=True)
        await _edit_verdict_request_message(
            interaction.guild, req, verdict_request_status_text(req), discord.Color.blurple(),
            view=VerdictReviewView(str(req.get("id"))),
        )
        try:
            await interaction.delete_original_response()
        except (discord.NotFound, discord.HTTPException):
            pass
        return
    pages = build_verdict_pages(req)
    if container_components_available():
        blocks = build_verdict_page_blocks(req)
        first_block = blocks[0] if blocks else "## 📋 Предпросмотр вердикта\nПусто"
        await interaction.response.send_message(
            **send_payload_for_container([first_block], view=make_container_view([first_block], view_cls=VerdictPagesView, view_args=(blocks, interaction.user.id), timeout=180)),
            ephemeral=ephemeral,
        )
    else:
        await interaction.response.send_message(
            embed=pages[0],
            view=VerdictPagesView(pages, interaction.user.id),
            ephemeral=ephemeral,
        )


class VerdictRequestModal(Modal):
    def __init__(self):
        super().__init__(title="Запрос вердикта", timeout=300)
        self.link_input = TextInput(
            label="Ссылка на сообщение",
            required=False,
            placeholder="https://discord.com/channels/...",
        )
        self.add_item(self.link_input)

    async def on_submit(self, interaction: Interaction):
        if await deny_if_request_cooldown(interaction, "verdicts"):
            return
        active_id, _ = _find_active_verdict_by_author(str(interaction.user.id))
        if active_id is not None:
            await interaction.response.send_message(
                f"❌ У вас уже есть активная заявка на вердикт: **#{active_id}**. "
                "Дождитесь решения модерации или попросите администратора очистить её.",
                ephemeral=True,
            )
            return

        await interaction.response.defer(ephemeral=True, thinking=True)
        req, error = await create_verdict_request_for_author(interaction.guild, str(interaction.user.id), str(self.link_input.value).strip())
        if error:
            await interaction.followup.send(f"❌ {error}", ephemeral=True)
            return
        mark_request_submitted(str(interaction.user.id), "verdicts")
        await interaction.followup.send("✅ Заявка отправлена.", ephemeral=True)



async def create_verdict_request_for_author(guild: discord.Guild, author_id: str, link: str, moderator: discord.Member | None = None):
    req_id = int(verdicts_data.get("next_id", 1))
    verdicts_data["next_id"] = req_id + 1
    req = {
        "id": req_id,
        "author_id": str(author_id),
        "message_link": str(link).strip(),
        "status": "pending",
        "created_at": int(time.time()),
        "draft": {"verdict_text": "", "ops": []},
    }
    if moderator:
        req["created_by_moderator_id"] = str(moderator.id)
    verdicts_data.setdefault("requests", {})[str(req_id)] = req
    save_verdicts_data()
    req_channel_id = verdicts_data.get("requests_channel")
    req_channel = guild.get_channel(int(req_channel_id)) if req_channel_id and guild else None
    if not req_channel:
        return None, "Канал заявок вердиктов не настроен (`!вердзаявкиканал`)."
    request_blocks = build_verdict_request_message_blocks(req, guild)
    request_view = make_container_view(request_blocks, view_cls=VerdictReviewView, view_args=(str(req_id),), timeout=None)
    request_payload = send_payload_for_container(request_blocks, view=request_view)
    msg = await req_channel.send(**request_payload)
    req["request_message_id"] = msg.id
    req["request_channel_id"] = req_channel.id
    save_verdicts_data()
    return req, None


def build_ai_verdict_review_embed(review: dict) -> Embed:
    """Render a moderator-facing assessment; money is shown as a signed delta."""
    summary = str(review.get("verdict_text") or review.get("summary") or "ИИ не дал общего пояснения.").strip()
    embed = Embed(title="🤖 Оценка от ИИ", description=summary[:4000], color=0x5865F2)
    operation_names = {
        "money": "Деньги", "reputation": "Репутация", "happiness": "Счастье", "science": "Наука",
        "description": "Описание игрока", "passive_income": "Пассивный доход", "passive_expense": "Пассивный расход",
        "stat_passive": "Автоизменение характеристики", "population_passive": "Автоизменение населения",
        "population": "Население", "army": "Армия", "sphere_level": "Уровень сферы",
        "item": "Предметы", "achievement": "Ачивка", "relation": "Взаимные отношения",
    }
    operations = []
    for operation in review.get("operations", [])[:10]:
        if not isinstance(operation, dict):
            continue
        kind = str(operation.get("kind") or "изменение").strip()
        name = operation_names.get(kind, kind)
        old_value = operation.get("old_value")
        new_value = operation.get("new_value", operation.get("value"))
        transition = ""
        if kind == "money" and old_value is not None and new_value is not None:
            try:
                delta = int(float(new_value)) - int(float(old_value))
                transition = f"**Изменение денег:** `{delta:+,}`\n".replace(",", " ")
            except (TypeError, ValueError):
                transition = f"**Изменение денег:** `{new_value}`\n"
        elif kind == "description" and new_value is not None:
            transition = f"**Новое описание:** `{new_value}`\n"
        elif old_value is not None or new_value is not None:
            transition = f"**Было → станет:** `{old_value if old_value is not None else '—'} → {new_value if new_value is not None else '—'}`\n"
        reason = str(operation.get("reason") or "Описание не указано.").strip()
        operations.append(f"**{name}:**\n{transition}-# Что меняется: {reason}")
    embed.add_field(name="Предлагаемые операции", value="\n\n".join(operations)[:1024] if operations else "ИИ не предложил изменений.", inline=False)
    if review.get("rollback_recommended"):
        embed.add_field(name="⚠️ Рекомендация", value=str(review.get("rollback_reason") or "ИИ рекомендует проверить необходимость отката.")[:1024], inline=False)
    embed.set_footer(text="Оценка ИИ носит рекомендательный характер и не меняет вердикт")
    return embed


def _ai_review_number(value) -> int | None:
    """Parse a whole-number value returned by the AI without raising."""
    try:
        return int(float(str(value).replace(" ", "").replace(",", ".")))
    except (TypeError, ValueError):
        return None


def ai_review_operations_to_draft(req: dict, review: dict) -> tuple[list[dict], int]:
    """Convert actionable AI recommendations to the same operations as the verdict UI.

    The model's response is untrusted and may omit fields required by a specific
    operation.  Such recommendations are deliberately skipped instead of making
    an ambiguous change to a player's state.
    """
    uid = str(req.get("author_id") or "")
    mention = f"<@{uid}>"
    converted: list[dict] = []
    skipped = 0
    if not uid:
        return converted, len(review.get("operations", []) if isinstance(review.get("operations"), list) else [])

    for suggestion in review.get("operations", []):
        if not isinstance(suggestion, dict):
            skipped += 1
            continue
        kind = str(suggestion.get("kind") or "").strip().lower()
        reason = str(suggestion.get("reason") or "по рекомендации ИИ").strip() or "по рекомендации ИИ"
        old_value = _ai_review_number(suggestion.get("old_value"))
        new_value = _ai_review_number(suggestion.get("new_value", suggestion.get("value")))
        op = None

        if kind == "money" and old_value is not None and new_value is not None and new_value != old_value:
            amount = new_value - old_value
            op = {"kind": "money", "member_id": uid, "amount": amount, "reason": reason,
                  "label": f"{'Начислить' if amount > 0 else 'Снять'} {fmt_num(abs(amount))} {currency} для {mention} ({reason})"}
        elif kind in {"reputation", "happiness"} and new_value is not None:
            value = max(0, min(100, new_value))
            title = "Репутация" if kind == "reputation" else "Счастье"
            op = {"kind": kind, "member_id": uid, "value": value, "reason": reason,
                  "label": f"{title} {mention}: {value}% ({reason})"}
        elif kind == "science" and new_value is not None:
            value = max(0, new_value)
            op = {"kind": "science", "member_id": uid, "value": value, "reason": reason,
                  "label": f"Наука {mention}: {value} ({reason})"}
        elif kind == "description":
            text = str(suggestion.get("new_value") or suggestion.get("text") or "").strip()
            if text:
                op = {"kind": "description", "member_id": uid, "text": text,
                      "label": f"Изменить описание {mention}: новое описание задано ({reason})"}
        elif kind in {"population", "army"} and old_value is not None and new_value is not None and new_value != old_value:
            amount = abs(new_value - old_value)
            mode = "add" if new_value > old_value else "sub"
            title = "население" if kind == "population" else "армию"
            op = {"kind": kind, "member_id": uid, "mode": mode, "amount": amount, "reason": reason,
                  "label": f"{'Выдать' if mode == 'add' else 'Изъять'} {title} {fmt_num(amount)} для {mention} ({reason})"}
        elif kind == "sphere_level" and new_value is not None:
            sphere_id = str(suggestion.get("sphere_id") or "")
            sphere_name = str(suggestion.get("sphere") or suggestion.get("sphere_name") or "")
            if not sphere_id and sphere_name:
                sphere_id = next((str(sid) for sid, sphere in seasons_data.get("spheres", {}).items()
                                  if str(sphere.get("name", "")).casefold() == sphere_name.casefold()), "")
            sphere = seasons_data.get("spheres", {}).get(sphere_id, {})
            if sphere_id and isinstance(sphere, dict):
                sphere_name = str(sphere.get("name") or sphere_name or sphere_id)
                season_name = str(seasons_data.get("active_season") or "")
                current = get_user_sphere_level(uid, sphere_id, season_name)
                op = {"kind": "sphere_level", "member_id": uid, "sphere_id": sphere_id, "sphere_name": sphere_name,
                      "season_name": season_name, "old_level": current, "new_level": max(0, new_value), "reason": reason,
                      "label": f"Сменить уровень сферы {sphere_name} для {mention}: {current} → {max(0, new_value)} ({reason})"}
        elif kind == "item":
            item_key = str(suggestion.get("item_key") or suggestion.get("item") or "").strip()
            quantity = _ai_review_number(suggestion.get("quantity", suggestion.get("new_value")))
            mode = str(suggestion.get("mode") or "add").lower()
            if item_key in items_data.get("items", {}) and quantity and quantity > 0 and mode in {"add", "sub"}:
                op = {"kind": "item", "member_id": uid, "mode": mode, "item_key": item_key, "quantity": quantity, "reason": reason,
                      "label": f"{'Выдать' if mode == 'add' else 'Изъять'} {item_key} x{quantity} для {mention} ({reason})"}
        elif kind in {"passive_income", "passive_expense"}:
            amount = str(suggestion.get("amount") or suggestion.get("new_value") or "").strip()
            try:
                parse_money_value(amount.replace(" ", ""), 100)
                cooldown = parse_interval(str(suggestion.get("cooldown") or "24ч"))
            except (TypeError, ValueError):
                cooldown = 0
            if cooldown > 0:
                flow_type = "income" if kind == "passive_income" else "expense"
                op = {"kind": "passive", "member_id": uid, "flow_type": flow_type, "amount": amount,
                      "cooldown": cooldown, "expires_at": None, "description": reason,
                      "label": f"Добавить пас{'доход' if flow_type == 'income' else 'расход'} {fmt_passive_amount(amount)} для {mention}"}
        elif kind == "stat_passive":
            stat = str(suggestion.get("stat") or "").lower()
            amount = _ai_review_number(suggestion.get("amount", suggestion.get("new_value")))
            try:
                cooldown = parse_interval(str(suggestion.get("cooldown") or "24ч"))
            except (TypeError, ValueError):
                cooldown = 0
            if stat in {"reputation", "happiness"} and amount is not None and cooldown > 0:
                op = {"kind": "stat_passive", "member_id": uid, "stat": stat, "amount": amount,
                      "cooldown": cooldown, "description": reason, "expires_at": None,
                      "label": f"Автоизменение {stat} {amount:+d} для {mention}"}
        elif kind == "population_passive":
            amount = str(suggestion.get("amount") or suggestion.get("new_value") or "").strip()
            try:
                cooldown = parse_interval(str(suggestion.get("cooldown") or "24ч"))
                valid_amount = bool(amount) and (amount.endswith("%") or _ai_review_number(amount) is not None)
            except (TypeError, ValueError):
                cooldown, valid_amount = 0, False
            if cooldown > 0 and valid_amount:
                op = {"kind": "population_passive", "member_id": uid, "amount": amount, "cooldown": cooldown,
                      "description": reason, "label": f"Автоизменение населения {amount} для {mention}"}
        elif kind == "achievement":
            achievement_id = str(suggestion.get("achievement_id") or "")
            achievement = achievements_data.get("achievements", {}).get(achievement_id)
            if isinstance(achievement, dict):
                op = {"kind": "achievement", "member_id": uid, "achievement_id": achievement_id,
                      "label": f"Выдать ачивку {achievement.get('name', achievement_id)} для {mention}"}
        elif kind == "relation":
            target = str(suggestion.get("target") or "").strip()
            delta = _ai_review_number(suggestion.get("delta"))
            if delta is None and old_value is not None and new_value is not None:
                delta = new_value - old_value
            if target and delta is not None and delta != 0:
                target = relation_subject_key(target)
                op = {"kind": "relation", "source": uid, "target": target, "delta": delta, "reason": reason,
                      "label": f"Взаимные отношения {get_country_display(uid)} ↔ {get_country_display(target)} {delta:+d}"}

        if op is None:
            skipped += 1
        else:
            converted.append(op)
    return converted, skipped


class AIVerdictReviewView(View):
    """Persistent controls displayed directly below an AI verdict assessment."""
    def __init__(self, req_id: str, applied: bool = False):
        super().__init__(timeout=None)
        self.req_id = str(req_id)
        button = Button(
            label="Внесено в вердикт" if applied else "Внести в вердикт",
            style=ButtonStyle.success,
            emoji="📝",
            custom_id=f"verdict:ai:apply:{self.req_id}",
            disabled=applied,
        )
        button.callback = self.apply_to_draft
        self.add_item(button)

    async def apply_to_draft(self, interaction: Interaction):
        if not _can_manage_verdicts_member(interaction.user):
            await interaction.response.send_message("❌ Нет доступа к вердиктам.", ephemeral=True)
            return
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req or str(req.get("status")) != "pending":
            await interaction.response.send_message("❌ Эта заявка уже недоступна для изменения черновика.", ephemeral=True)
            return
        if not verdict_is_claimed_by(req, interaction.user.id):
            await interaction.response.send_message("❌ Вносить изменения может только куратор, взявший заявку в работу.", ephemeral=True)
            return
        reviews = req.get("ai_reviews", [])
        latest = reviews[-1].get("review") if reviews and isinstance(reviews[-1], dict) else None
        if not isinstance(latest, dict):
            await interaction.response.send_message("❌ Сохранённая оценка ИИ не найдена.", ephemeral=True)
            return
        if req.get("ai_review_applied"):
            await interaction.response.send_message("ℹ️ Изменения из этой оценки ИИ уже внесены в черновик.", ephemeral=True)
            return
        operations, skipped = ai_review_operations_to_draft(req, latest)
        if not operations:
            await interaction.response.send_message("⚠️ В оценке ИИ нет изменений, которые можно безопасно внести в черновик.", ephemeral=True)
            return
        for operation in operations:
            upsert_verdict_operation(req, operation)
        req["ai_review_applied"] = True
        req["ai_suggestions_used"] = True
        req["ai_review_applied_by"] = str(interaction.user.id)
        req["ai_review_applied_at"] = int(time.time())
        save_verdicts_data()
        skipped_note = f" Не внесено рекомендаций: {skipped}." if skipped else ""
        await interaction.response.edit_message(view=AIVerdictReviewView(self.req_id, applied=True))
        await interaction.followup.send(f"✅ В черновик внесено изменений: {len(operations)}.{skipped_note}", ephemeral=True)


async def delete_ai_verdict_review_message(req: dict):
    """Remove the public AI assessment once the moderator has made a decision."""
    channel_id = req.get("ai_review_channel_id")
    message_id = req.get("ai_review_message_id")
    if not channel_id or not message_id:
        return
    try:
        channel = await get_channel_safe(channel_id)
        if channel:
            message = await channel.fetch_message(int(message_id))
            await message.delete()
    except discord.NotFound:
        pass
    except (discord.Forbidden, discord.HTTPException):
        logging.getLogger(__name__).warning(
            "Could not delete AI verdict review message %s", message_id, exc_info=True
        )


def build_ai_investment_review_embed(review: dict) -> Embed:
    """Render an investment recommendation without filling the approval form."""
    investment = review.get("investment", {}) if isinstance(review.get("investment"), dict) else {}
    embed = Embed(title="🤖 Оценка от ИИ", description=str(review.get("summary") or review.get("verdict_text") or "ИИ не дал пояснения.")[:4000], color=0x5865F2)
    fields = (("Описание", investment.get("description")), ("Прибыль", investment.get("profit")), ("Начало", investment.get("start_year")), ("Кулдаун", investment.get("cooldown")), ("Срок", investment.get("duration")))
    suggestion = "\n".join(f"**{name}:** {value}" for name, value in fields if value)
    embed.add_field(name="Рекомендация по инвестиции", value=suggestion[:1024] or "ИИ не предложил параметры.", inline=False)
    embed.set_footer(text="Оценка ИИ носит рекомендательный характер и не заполняет форму")
    return embed


async def delete_ai_investment_review_message(req: dict):
    """Remove the public AI assessment after the investment is decided."""
    channel_id = req.get("ai_review_channel_id")
