        self.cooldown = TextInput(label="Кулдаун (например: 24ч, 30м)", required=True, default=format_interval(int(existing.get("cooldown", 86400))))
        self.description = TextInput(label="Описание", required=False, default=str(existing.get("description") or "по вердикту"))
