class VerdictEditPassiveModal(Modal):
    def __init__(self, req_id: str, index: int):
        self.req_id=str(req_id); self.index=int(index)
        req=verdicts_data.get("requests",{}).get(self.req_id,{})
        uid=str(req.get("author_id"))
        self.passive_kind = "stat" if self.index < 0 else "money"
        entry = (ensure_player_state(uid).setdefault("stat_passives", [])[abs(self.index)-1] if self.passive_kind == "stat" else get_passive_entries(uid)[self.index])
        super().__init__(title="Редактировать пассив", timeout=300)
        self.amount=TextInput(label="Сумма", required=True, default=str(entry.get("amount",0)))
        self.cooldown=TextInput(label="Кулдаун", required=True, default=format_interval(int(entry.get("cooldown",86400))))
        self.description=TextInput(label="Описание", required=False, default=str(entry.get("description","")))
        default_type = entry.get("stat") if self.passive_kind == "stat" else ("расход" if entry.get("type")=="expense" else "доход")
        self.flow_type=TextInput(label="Тип: доход/расход/репутация/счастье", required=True, default=default_type)
        self.add_item(self.amount); self.add_item(self.cooldown); self.add_item(self.description); self.add_item(self.flow_type)
    async def on_submit(self, interaction: Interaction):
        req=verdicts_data.get("requests",{}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Заявка не найдена.", ephemeral=True); return
        uid=str(req.get("author_id"))
        try:
            amount_raw=str(self.amount.value).strip().replace(" ",""); parse_money_value(amount_raw,100)
            cooldown=parse_interval(str(self.cooldown.value).strip())
            flow_type=str(self.flow_type.value).strip().lower()
            aliases={"доход":"income","income":"income","расход":"expense","expense":"expense","репутация":"reputation","reputation":"reputation","счастье":"happiness","happiness":"happiness"}
            if flow_type not in aliases: raise ValueError("Тип должен быть `доход`, `расход`, `репутация` или `счастье`")
            flow_type=aliases[flow_type]
        except Exception as e:
            await interaction.response.send_message(f"❌ Ошибка параметров: {e}", ephemeral=True); return
        await interaction.response.defer(ephemeral=True, thinking=True)
        upsert_verdict_operation(req, {"kind":"edit_passive","member_id":uid,"index":self.index,"passive_kind":self.passive_kind,"flow_type":flow_type,"amount":amount_raw,"cooldown":cooldown,"description":str(self.description.value or "по вердикту"),"label":f"Редактировать пассив #{abs(self.index) if self.index < 0 else self.index+1} для <@{uid}>"})
        save_verdicts_data()
        await interaction.followup.send("✅ Редактирование пассива добавлено в вердикт.", ephemeral=True)


