class VerdictItemModal(Modal):
    def __init__(self, req_id: str, mode: str):
        self.req_id = str(req_id)
        self.mode = mode
        existing = get_verdict_draft_operation(req_id, "item", mode=mode)
        super().__init__(title="Выдать предметы" if mode == "add" else "Изъять предметы", timeout=300)
        self.quantity = TextInput(label="Количество (минимум 1)", required=True, default=str(existing.get("quantity", 1)))
        self.item_key = TextInput(label="Название предмета (ключ)", required=True, max_length=120, default=str(existing.get("item_key") or ""))
        self.reason = TextInput(label="Описание причины", required=True, style=discord.TextStyle.paragraph, max_length=500, default=str(existing.get("reason") or "по вердикту"))
        self.add_item(self.quantity)
        self.add_item(self.item_key)
        self.add_item(self.reason)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Заявка не найдена.", ephemeral=True)
            return
        try:
            qty = max(1, int(float(str(self.quantity.value).replace(",", "."))))
        except Exception:
            await interaction.response.send_message("❌ Количество должно быть числом от 1.", ephemeral=True)
            return
        key = str(self.item_key.value or "").strip()
        if key not in items_data.get("items", {}):
            matches = resolve_item_key(key)
            if len(matches) == 1:
                key = matches[0]
            else:
                await interaction.response.send_message("❌ Предмет с таким ключом не найден.", ephemeral=True)
                return
        uid = str(req.get("author_id"))
        mention = f"<@{uid}>"
        reason = str(self.reason.value or "по вердикту").strip() or "по вердикту"
        upsert_verdict_operation(req, {
            "kind": "item",
            "member_id": uid,
            "mode": self.mode,
            "item_key": key,
            "quantity": qty,
            "reason": reason,
            "label": f"{'Выдать' if self.mode == 'add' else 'Изъять'} {key} x{qty} для {mention} ({reason})",
        })
        save_verdicts_data()
        await send_verdict_pages_response(interaction, req, ephemeral=True)


