class VerdictRejectReasonModal(Modal):
    def __init__(self, req_id: str):
        self.req_id = str(req_id)
        super().__init__(title="Причина отклонения вердикта", timeout=300)
        self.reason = TextInput(
            label="Причина",
            style=discord.TextStyle.paragraph,
            required=True,
            max_length=1000,
        )
        self.add_item(self.reason)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message(
                "❌ Заявка не найдена.", ephemeral=True
            )
            return
        await interaction.response.defer(ephemeral=True)

        reason = str(self.reason.value).strip()
        req["status"] = "rejected"
        req["reject_reason"] = reason
        req["processed_by"] = str(interaction.user.id)
        save_verdicts_data()
        await delete_ai_verdict_review_message(req)

        await _edit_verdict_request_message(
            interaction.guild,
            req,
            f"❌ Заявка #{self.req_id}: отправил <@{req.get('author_id')}>, принял {interaction.user.mention}, отклонил: {reason}",
            discord.Color.red(),
            view=VerdictResultView(self.req_id),
        )

        result_channel = (
            interaction.guild.get_channel(int(verdicts_data.get("result_channel")))
            if verdicts_data.get("result_channel")
            else None
        )
        if result_channel:
            author_mention = f"<@{req.get('author_id')}>"
            reject_block = (
                f"## ❌ Вердикт отклонён\n"
                f"Заявка #{self.req_id} отклонена.\n"
                f"**Причина:** {reason}\n"
                f"**Ссылка:** {req.get('message_link') or '—'}"
            )
            if container_components_available():
                reject_block = f"{author_mention}\n{reject_block}"
                await result_channel.send(
                    **send_payload_for_container([reject_block], view=make_container_view([reject_block], view_cls=VerdictAfterView, view_args=(self.req_id,), timeout=180))
                )
            else:
                await result_channel.send(
                    content=author_mention,
                    embed=Embed(
                        title="❌ Вердикт отклонён",
                        description=(
                            f"Заявка #{self.req_id} отклонена.\n"
                            f"**Причина:** {reason}\n"
                            f"**Ссылка:** {req.get('message_link') or '—'}"
                        ),
                        color=0xAA0000,
                    ),
                    view=VerdictAfterView(self.req_id),
                )

        await interaction.followup.send("✅ Отклонение сохранено и отправлено в итог-канал.", ephemeral=True)


class VerdictRelationModal(Modal):
    def __init__(self, req_id: str, mode: str = "outgoing"):
        self.req_id = str(req_id)
        self.mode = mode
        existing = next((op for op in verdicts_data.get("requests", {}).get(self.req_id, {}).get("draft", {}).get("ops", []) if isinstance(op, dict) and op.get("kind") == "relation"), {})
        title = "Взаимное отношение"
        super().__init__(title=title, timeout=300)
        other_label = "Другая страна/игрок"
        self.other = TextInput(label=other_label, required=True, default=str(existing.get("target") or ""))
        self.delta = TextInput(label="Изменение", required=True, placeholder="Например: -15", default=str(existing.get("delta")) if existing else None)
        self.reason = TextInput(label="Комментарий", required=False, default=str(existing.get("reason") or "по вердикту"), style=discord.TextStyle.paragraph)
        self.add_item(self.other); self.add_item(self.delta); self.add_item(self.reason)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Заявка не найдена.", ephemeral=True); return
        try:
            delta = int(str(self.delta.value).replace("+", "").strip())
        except Exception:
            await interaction.response.send_message("❌ Изменение должно быть числом.", ephemeral=True); return
        author_id = str(req.get("author_id") or "").strip()
        if not author_id:
            await interaction.response.send_message("❌ Автор заявки не найден.", ephemeral=True); return
        other = relation_subject_key(self.other.value)
        source, target = author_id, other
        for val in (source, target):
            if val and not val.isdigit(): relations_data.setdefault("pending_names", {})[val] = val
        upsert_verdict_operation(req, {"kind": "relation", "source": source, "target": target, "delta": delta, "reason": str(self.reason.value or "по вердикту"), "label": f"Взаимные отношения {get_country_display(source)} ↔ {get_country_display(target)} {delta:+d}"})
        save_relations_data(); save_verdicts_data()
        await send_verdict_pages_response(interaction, req, ephemeral=True)


async def lock_previous_verdict_rollbacks(guild: discord.Guild | None, author_id: str, current_req_id: str):
    """Disable rollback menus for earlier finalized verdicts of the same player."""
    changed = False
    for req_id, old_req in list(verdicts_data.setdefault("requests", {}).items()):
        if str(req_id) == str(current_req_id):
            continue
        if str(old_req.get("author_id")) != str(author_id):
            continue
        if str(old_req.get("status")) != "finalized":
            continue
        if old_req.get("rollback_locked"):
            continue
        old_req["rollback_locked"] = True
        old_req["rollback_locked_by_verdict"] = str(current_req_id)
        changed = True
        ch = await get_channel_safe(old_req.get("result_channel_id"))
        if ch and old_req.get("result_message_id"):
            try:
                msg = await ch.fetch_message(int(old_req.get("result_message_id")))
                await msg.edit(view=None)
            except Exception:
                pass
    if changed:
        save_verdicts_data()


def resolve_country_owner(raw: str) -> str | None:
    """Resolve a country name, member mention, or ID to its current owner."""
    key = relation_subject_key(raw)
    if key.isdigit() and is_registered_country_user(key):
        return key
    wanted = str(raw or "").strip().casefold()
    if not wanted:
        return None
    for uid in get_all_registered_user_ids():
        country = get_country_name_by_user_id(str(uid))
        if country and country.strip().casefold() == wanted:
            return str(uid)
    return None


def parse_rp_operation_duration(raw: str) -> int:
    """Parse duration in RP calendar units (e.g. 1год, 3 мес, 20д)."""
    text = str(raw or "").strip().lower()
    if not text:
        raise ValueError("Укажите срок, например: 1год, 3 мес или 20д")
    year_seconds = max(60, int(investments.setdefault("rp_year", {}).get("cooldown", 86400) or 86400))
    day_seconds = year_seconds / 365
    total_days = 0.0
    pattern = re.compile(r"(\d+)\s*(год(?:а|ов)?|г|мес(?:яц(?:а|ев)?)?|д(?:ень|ня|ней)?)")
    pos = 0
    for match in pattern.finditer(text):
        if text[pos:match.start()].strip(" ,"):
            raise ValueError("Срок: 1год, 3 мес, 20д")
        amount, unit = int(match.group(1)), match.group(2)
        if amount <= 0:
            raise ValueError("Срок должен быть больше нуля")
        total_days += amount * (365 if unit.startswith(("г", "год")) else 30 if unit.startswith("мес") else 1)
        pos = match.end()
    if not total_days or text[pos:].strip(" ,"):
        raise ValueError("Срок: 1год, 3 мес, 20д")
    return max(60, int(total_days * day_seconds))


class VerdictExternalOperationModal(Modal):
    """Form for recurring interactions created together with a verdict."""
    labels = {
        "migration": ("Миграция", "Страна, откуда мигрируют", "Количество населения", "RP-промежуток (1год, 3 мес, 20д)", "RP-срок действия (1год, 3 мес, 20д)", "Описание"),
        "immigration": ("Иммиграция", "Страна, куда иммигрируют", "Количество населения", "RP-промежуток (1год, 3 мес, 20д)", "RP-срок действия (1год, 3 мес, 20д)", "Описание"),
        "purchase": ("Автопокупка", "Страна продавца", "Покупаемый предмет", "Количество за RP-операцию", "Цена за раз", "RP-срок действия (1год, 3 мес, 20д)"),
        "payout": ("Автовыплата", "Страна-получатель", "Количество денег", "RP-промежуток (1год, 3 мес, 20д)", "RP-срок действия (1год, 3 мес, 20д)", "Описание"),
        "supply": ("Поставка", "Страна-поставщик", "Предмет", "Количество", "RP-промежуток (1год, 3 мес, 20д)", "RP-срок действия (1год, 3 мес, 20д)"),
    }
    def __init__(self, req_id: str, kind: str):
        self.req_id, self.kind = str(req_id), kind
        labels = self.labels[kind]
        super().__init__(title=labels[0], timeout=600)
        self.country = TextInput(label=labels[1], required=True, max_length=100)
        self.value = TextInput(label=labels[2], required=True, max_length=100)
        self.amount_or_interval = TextInput(label=labels[3], required=True, max_length=100)
        self.interval_or_price = TextInput(label=labels[4], required=True, max_length=100)
        self.duration = TextInput(label=labels[5], required=True, max_length=100)
        for field in (self.country, self.value, self.amount_or_interval, self.interval_or_price, self.duration): self.add_item(field)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        author = str((req or {}).get("author_id") or "")
        other = resolve_country_owner(self.country.value)
        if not req or not author or not other or other == author:
            await interaction.response.send_message("❌ Укажите существующую другую зарегистрированную страну.", ephemeral=True); return
        try:
            if self.kind in {"migration", "immigration", "payout"}:
                amount = max(1, int(self.value.value)); cooldown = parse_rp_operation_duration(self.amount_or_interval.value); duration = parse_rp_operation_duration(self.interval_or_price.value); description = str(self.duration.value)
                item_key = ""; price = 0
            elif self.kind == "purchase":
                item_key = str(self.value.value).strip(); amount = max(1, int(self.amount_or_interval.value)); price = max(0, int(self.interval_or_price.value)); cooldown = parse_rp_operation_duration("1год"); duration = parse_rp_operation_duration(self.duration.value); description = ""
            else:
                item_key = str(self.value.value).strip(); amount = max(1, int(self.amount_or_interval.value)); cooldown = parse_rp_operation_duration(self.interval_or_price.value); duration = parse_rp_operation_duration(self.duration.value); price = 0; description = ""
            if self.kind in {"purchase", "supply"} and item_key not in items_data.setdefault("items", {}):
                raise ValueError("Предмета нет в магазине")
        except ValueError as exc:
            await interaction.response.send_message(f"❌ {exc}", ephemeral=True); return
        # Author is player A; the country field identifies player B.
        op = {"kind": "external", "external_kind": self.kind, "member_id": author, "other_id": other, "amount": amount, "cooldown": cooldown, "duration": duration, "item_key": item_key, "price": price, "description": description,
              "label": f"{self.labels[self.kind][0]}: {get_country_display(author)} ↔ {get_country_display(other)}"}
        upsert_verdict_operation(req, op); save_verdicts_data()
        await send_verdict_pages_response(interaction, req, ephemeral=True)


