    async def callback(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message(
                "❌ Заявка не найдена.", ephemeral=True
            )
            return
        if str(req.get("status")) != "pending":
            await interaction.response.send_message(
                "❌ По этой заявке уже вынесен вердикт.", ephemeral=True
            )
            return
        choice = self.values[0]
        if choice == "text":
            await interaction.response.send_modal(VerdictTextModal(self.req_id))
            return
        if choice == "reject":
            await interaction.response.send_modal(VerdictRejectReasonModal(self.req_id))
            return
        if choice == "toggle_public_choice":
            if req.get("source") != "event_choice":
                await interaction.response.send_message("❌ Это доступно только для вердиктов по выбору игрока.", ephemeral=True)
                return
            req["show_player_choice_public"] = not bool(req.get("show_player_choice_public"))
            save_verdicts_data()
            await interaction.response.send_message(f"✅ Публикация выбора игрока: {'включена' if req.get('show_player_choice_public') else 'выключена'}.", ephemeral=True)
            return
        if choice == "preview":
            await send_verdict_pages_response(interaction, req, ephemeral=True)
            return
        if choice == "passive_edit":
            await interaction.response.send_message("Выберите пассивную операцию игрока:", view=VerdictEditPassiveView(self.req_id), ephemeral=True)
            return
        if choice == "achievement":
            await interaction.response.send_message("Выберите ачивку:", view=VerdictAchievementView(self.req_id), ephemeral=True)
            return
        if choice == "finalize":
            await interaction.response.defer(ephemeral=True)
            draft = req.get("draft", {})
            ops = draft.get("ops", [])
            applied_snapshots = []
            for op in ops:
                uid_snapshot = str(op.get("member_id"))
                kind_snapshot = op.get("kind")
                snap = {"kind": kind_snapshot, "member_id": uid_snapshot}
                if kind_snapshot == "money":
                    snap["cash_before"] = int(ensure_user(uid_snapshot).get("наличка", 0))
                elif kind_snapshot == "sphere_level":
                    snap["sphere_id"] = str(op.get("sphere_id"))
                    snap["season_name"] = str(op.get("season_name") or seasons_data.get("active_season") or "")
                    snap["level_before"] = get_user_sphere_level(uid_snapshot, snap["sphere_id"], snap["season_name"])
                elif kind_snapshot == "achievement":
                    snap["achievements_before"] = list(get_user_achievements(uid_snapshot))
                elif kind_snapshot in {"description", "reputation", "happiness", "science", "army"}:
                    st = ensure_player_state(uid_snapshot)
                    for key in ("admin_description", "reputation", "happiness", "science", "soldiers"):
                        snap[key] = st.get(key)
                elif kind_snapshot == "item":
                    snap["item_key"] = str(op.get("item_key") or "")
                    snap["qty_before"] = int(inventory.setdefault(uid_snapshot, {}).get(snap["item_key"], 0))
                elif kind_snapshot == "population":
                    pop_snapshot = load_json(POPULATION_FILE, {})
                    snap["population_before"] = int(pop_snapshot.get(uid_snapshot, 0))
                elif kind_snapshot == "relation":
                    snap["source"] = str(op.get("source")); snap["target"] = str(op.get("target"))
                    snap["relation_before"] = get_relation_value(snap["source"], snap["target"])
                elif kind_snapshot in {"passive", "stat_passive"}:
                    snap["count_before"] = len(get_passive_entries(uid_snapshot)) if kind_snapshot == "passive" else len(ensure_player_state(uid_snapshot).setdefault("stat_passives", []))
                elif kind_snapshot == "edit_passive":
                    snap["index"] = int(op.get("index", -1)); entries=get_passive_entries(uid_snapshot); snap["entry_before"] = make_json_snapshot(entries[snap["index"]]) if 0 <= snap["index"] < len(entries) else None
                applied_snapshots.append(snap)
                kind = op.get("kind")
                uid = str(op.get("member_id"))
                if kind == "money":
                    ensure_user(uid)["наличка"] += int(op.get("amount", 0))
                elif kind == "description":
                    ensure_player_state(uid)["admin_description"] = str(
                        op.get("text", "")
                    )
                elif kind == "reputation":
                    ensure_player_state(uid)["reputation"] = max(0, min(100, int(op.get("value", 50))))
                elif kind == "happiness":
                    ensure_player_state(uid)["happiness"] = max(
                        0, min(100, int(op.get("value", 50)))
                    )
                elif kind == "science":
                    ensure_player_state(uid)["science"] = max(0, int(op.get("value", 0)))
                elif kind == "achievement":
                    achs = get_user_achievements(uid)
                    ach_id = str(op.get("achievement_id"))
                    if ach_id not in achs:
                        achs.append(ach_id)
                elif kind == "sphere_level":
                    set_user_sphere_level(
                        uid,
                        str(op.get("sphere_id")),
                        max(0, int(op.get("new_level", 0))),
                        str(op.get("season_name") or seasons_data.get("active_season") or ""),
                    )
                    member = interaction.guild.get_member(int(uid)) if interaction.guild and str(uid).isdigit() else None
                    if member:
                        try:
                            await sync_member_sphere_reward_roles(member, str(op.get("season_name") or seasons_data.get("active_season") or ""))
                            await sync_member_economy_roles(member)
                        except (discord.Forbidden, discord.HTTPException):
                            pass
                elif kind == "item":
                    key = str(op.get("item_key") or "")
                    qty = max(1, int(op.get("quantity", 1)))
                    inventory.setdefault(uid, {})
                    if op.get("mode") == "sub":
                        inventory[uid][key] = max(0, int(inventory[uid].get(key, 0)) - qty)
                        if inventory[uid][key] <= 0:
                            inventory[uid].pop(key, None)
                    else:
                        inventory[uid][key] = int(inventory[uid].get(key, 0)) + qty
                elif kind == "population_passive":
                    ensure_player_state(uid).setdefault("population_passives", []).append({"amount": op.get("amount", 0), "cooldown": int(op.get("cooldown", 86400)), "last_run": int(time.time()), "description": op.get("description", "по вердикту")})
                elif kind == "population":
                    pop = load_json(POPULATION_FILE, {})
                    amount = max(1, int(op.get("amount", 1)))
                    current = int(pop.get(uid, 0))
                    pop[uid] = current + amount if op.get("mode") == "add" else max(0, current - amount)
                    save_json(POPULATION_FILE, pop)
                    member = interaction.guild.get_member(int(uid)) if interaction.guild and str(uid).isdigit() else None
                    if member:
                        try:
                            await sync_member_army_ratio_roles(member)
                        except (discord.Forbidden, discord.HTTPException):
                            pass
                elif kind == "army":
                    st = ensure_player_state(uid)
                    amount = max(1, int(op.get("amount", 1)))
                    current = int(st.get("soldiers", 0))
                    st["soldiers"] = current + amount if op.get("mode") == "add" else max(0, current - amount)
                    member = interaction.guild.get_member(int(uid)) if interaction.guild and str(uid).isdigit() else None
                    if member:
                        try:
                            await sync_member_army_ratio_roles(member)
                        except (discord.Forbidden, discord.HTTPException):
                            pass
                elif kind == "relation":
                    src = str(op.get("source")); target = str(op.get("target")); delta = int(op.get("delta", 0))
                    set_relation_value(src, target, get_relation_value(src, target) + delta)
                    relations_data.setdefault("changes", []).append({"source": src, "target": target, "delta": delta, "comment": op.get("reason", "по вердикту"), "link": req.get("message_link") or "", "year": current_rp_year_key(), "actor_id": str(interaction.user.id), "ts": int(time.time()), "verdict_id": self.req_id})
                    await publish_relation_change(interaction.guild, src, target, delta, op.get("reason", "по вердикту"), req.get("message_link") or "", interaction.user.id)
                elif kind == "stat_passive":
                    ensure_player_state(uid).setdefault("stat_passives", []).append({
                        "stat": op.get("stat", "happiness"),
                        "amount": int(op.get("amount", 0)),
                        "cooldown": int(op.get("cooldown", 86400)),
                        "last_run": int(time.time()),
                        "description": op.get("description", "по вердикту"),
                        "expires_at": op.get("expires_at"),
                    })
                elif kind == "edit_passive":
                    entries = get_passive_entries(uid); idx = int(op.get("index", -1))
                    if op.get("passive_kind") == "stat":
                        stat_entries = ensure_player_state(uid).setdefault("stat_passives", [])
                        stat_idx = abs(idx) - 1
                        if 0 <= stat_idx < len(stat_entries):
                            stat_entries[stat_idx].update({"stat": op.get("flow_type", "happiness"), "amount": int(float(str(op.get("amount", 0)).replace(",", "."))), "cooldown": int(op.get("cooldown", 86400)), "description": op.get("description", "по вердикту"), "last_run": int(time.time())})
                    elif 0 <= idx < len(entries):
                        entries[idx].update({"type": op.get("flow_type", "income"), "amount": str(op.get("amount", 0)), "cooldown": int(op.get("cooldown", 86400)), "description": op.get("description", "по вердикту"), "last_run": int(time.time())})
                elif kind == "external":
                    now = int(time.time())
                    ext = dict(op)
                    ext["id"] = str(verdicts_data.setdefault("next_external_operation_id", 1))
                    verdicts_data["next_external_operation_id"] = int(ext["id"]) + 1
                    ext.update({"status": "active", "started_at": now, "expires_at": now + max(60, int(op.get("duration", 60))), "next_at": now, "verdict_id": self.req_id})
                    verdicts_data.setdefault("external_operations", {})[ext["id"]] = ext
                elif kind == "passive":
                    get_passive_entries(uid).append(
                        {
                            "type": op.get("flow_type", "income"),
                            "amount": str(op.get("amount", 0)),
                            "cooldown": int(op.get("cooldown", 86400)),
                            "last_run": int(time.time()),
                            "description": op.get("description", "по вердикту"),
                            "expires_at": op.get("expires_at"),
                            "verdict_id": str(self.req_id),
                        }
                    )

            save_json(BALANCES_FILE, balances)
            save_inventory()
            save_player_state()
            save_passive_flows()
            save_relations_data()
            req["applied_snapshots"] = applied_snapshots
            req["status"] = "finalized"
            req["processed_by"] = str(interaction.user.id)
            increment_admin_counter(interaction.user.id, "verdicts_accepted")
            save_verdicts_data()
            await delete_ai_verdict_review_message(req)
            await lock_previous_verdict_rollbacks(interaction.guild, str(req.get("author_id")), self.req_id)

            await _edit_verdict_request_message(
                interaction.guild,
                req,
                f"✅ Заявка #{self.req_id}: отправил <@{req.get('author_id')}>, принял {interaction.user.mention}",
                discord.Color.green(),
                view=VerdictResultView(self.req_id),
            )

            result_channel = (
                interaction.guild.get_channel(int(verdicts_data.get("result_channel")))
                if verdicts_data.get("result_channel")
                else None
            )
            if result_channel:
                pages = build_verdict_pages(req)
                author_mention = f"<@{req.get('author_id')}>"
                if container_components_available():
                    blocks = build_verdict_page_blocks(req)[:10]
                    blocks = [author_mention] + blocks
                    result_payload = send_payload_for_container(blocks, view=make_container_view(blocks, view_cls=VerdictAfterView, view_args=(self.req_id,), timeout=180))
                    result_msg = await result_channel.send(**result_payload)
                else:
                    result_msg = await result_channel.send(content=author_mention, embeds=pages[:10], view=VerdictAfterView(self.req_id))
                req["result_message_url"] = result_msg.jump_url
                req["result_channel_id"] = result_msg.channel.id
                req["result_message_id"] = result_msg.id
                passive_link_changed = False
                for _uid, _entries in passive_flows.setdefault("users", {}).items():
                    if not isinstance(_entries, list):
                        continue
                    for _entry in _entries:
                        if isinstance(_entry, dict) and str(_entry.get("verdict_id")) == str(self.req_id):
                            _entry["verdict_result_url"] = result_msg.jump_url
                            passive_link_changed = True
                if container_components_available():
                    for block in build_verdict_page_blocks(req)[10:]:
                        await result_channel.send(**send_payload_for_container([block]))
                else:
                    for page in pages[10:]:
                        await result_channel.send(embed=page)
                save_verdicts_data()
                if passive_link_changed:
                    save_passive_flows()
