class VerdictReviewView(LayoutViewBase if container_components_available() else View):
    def __init__(self, req_id: str):
        super().__init__(timeout=None)
        self.req_id = str(req_id)
        self.add_item(VerdictReviewSelect(self.req_id))
        self.add_item(VerdictExternalSelect(self.req_id))

        req = verdicts_data.get("requests", {}).get(self.req_id, {})
        # While a curator's review reservation is active there must be no
        # competing claim control in the persistent message.
        if not (req.get("claimed_by") and int(req.get("claim_until") or 0) > int(time.time())):
            claim_button = Button(label="Взяться за выполнение", style=ButtonStyle.secondary, emoji="✋", custom_id=f"verdict:claim:{self.req_id}")
            claim_button.callback = self.claim
            self.add_item(claim_button)
        info_button = Button(label="Информация о игроке", style=ButtonStyle.secondary, emoji="👤", custom_id=f"verdict:player-info:{self.req_id}")
        info_button.callback = self.player_info
        self.add_item(info_button)

        if not req.get("ai_review_revealed"):
            ai_button = Button(
                label="Оценка от ИИ",
                style=ButtonStyle.secondary,
                emoji="🤖",
                custom_id=f"verdict:review:ai:{self.req_id}",
            )
            ai_button.callback = self.review_with_ai
            self.add_item(ai_button)

    async def interaction_check(self, interaction: Interaction) -> bool:
        if not _can_manage_verdicts_member(interaction.user):
            await interaction.response.send_message("❌ Нет доступа к вердиктам.", ephemeral=True)
            return False
        req = verdicts_data.get("requests", {}).get(self.req_id, {})
        custom_id = str((interaction.data or {}).get("custom_id") or "")
        if custom_id.endswith(f":claim:{self.req_id}") or custom_id.endswith(f":player-info:{self.req_id}"):
            return True
        if verdict_is_claimed_by(req, interaction.user.id):
            return True
        await interaction.response.send_message("❌ Сначала нажмите «Взяться за выполнение», либо заявка закреплена за другим куратором.", ephemeral=True)
        return False

    async def claim(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req or str(req.get("status")) != "pending":
            await interaction.response.send_message("❌ Эта заявка уже недоступна.", ephemeral=True)
            return
        if req.get("claimed_by") and not verdict_is_claimed_by(req, interaction.user.id):
            await interaction.response.send_message("❌ Другой куратор уже рассматривает эту заявку.", ephemeral=True)
            return
        req["claimed_by"] = str(interaction.user.id)
        req["claim_until"] = int(time.time()) + 600
        req.pop("status_text", None)
        save_verdicts_data()
        await _edit_verdict_request_message(interaction.guild, req, verdict_request_status_text(req), discord.Color.blurple(), view=VerdictReviewView(self.req_id))
        await interaction.response.send_message("✅ Заявка закреплена за вами на 10 минут.", ephemeral=True)

    async def player_info(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Заявка не найдена.", ephemeral=True)
            return
        uid = str(req.get("author_id"))
        if container_components_available():
            block = f"## 👤 Информация об игроке\nИгрок: <@{uid}>\n-# Выберите раздел профиля в меню ниже."
            await interaction.response.send_message(
                **send_payload_for_container([block], view=VerdictPlayerInfoView(uid)), ephemeral=True
            )
        else:
            await interaction.response.send_message(
                embed=Embed(title="👤 Информация об игроке", description=f"Игрок: <@{uid}>\nВыберите раздел профиля в меню ниже.", color=0x3498DB),
                view=VerdictPlayerInfoView(uid), ephemeral=True,
            )

    async def review_with_ai(self, interaction: Interaction):
        """Send an AI recommendation without touching the moderator's draft."""
        req = verdicts_data.get("requests", {}).get(self.req_id)
        if not req or str(req.get("status")) != "pending":
            await interaction.response.send_message("❌ Эта заявка уже недоступна для оценки ИИ.", ephemeral=True)
            return
        link = str(req.get("message_link") or "").strip()
        if not is_ai_reviewable_link(link):
            await interaction.response.send_message(
                "❌ Для оценки ИИ нужна корректная ссылка на сообщение этого сервера.",
                ephemeral=True,
            )
            return

        if req.get("ai_review_revealed"):
            await interaction.response.send_message("❌ Оценка ИИ для этой заявки уже опубликована.", ephemeral=True)
            return
        await interaction.response.defer()
        source_message = await fetch_ai_review_message(interaction.guild, link)
        if source_message is None:
            await interaction.followup.send("❌ Не удалось прочитать сообщение по ссылке.", ephemeral=True)
            return
        post_text = source_message.content or ""
        if source_message.attachments:
            post_text += "\n[Вложения: " + ", ".join(a.filename for a in source_message.attachments[:10]) + "]"
        review = await request_ai_post_review(
            "verdict", post_text, ai_registration_context(str(req.get("author_id") or ""))
        )
        if not review:
            await interaction.followup.send("❌ ИИ не вернул корректную оценку. Попробуйте ещё раз.", ephemeral=True)
            return

        req.setdefault("ai_reviews", []).append({
            "reviewed_at": int(time.time()),
            "reviewed_by": str(interaction.user.id),
            "review": review,
        })
        req["ai_review_revealed"] = True
        save_verdicts_data()
        review_message = await interaction.channel.send(
            embed=build_ai_verdict_review_embed(review),
            view=AIVerdictReviewView(self.req_id),
        )
        req["ai_review_channel_id"] = review_message.channel.id
        req["ai_review_message_id"] = review_message.id
        save_verdicts_data()
        if container_components_available():
            blocks = build_verdict_request_message_blocks(req, interaction.guild)
            view = make_container_view(
                blocks,
                view_cls=VerdictReviewView,
                view_args=(self.req_id,),
                timeout=None,
            )
            await interaction.edit_original_response(content=None, embed=None, view=view)
        else:
            await interaction.edit_original_response(view=VerdictReviewView(self.req_id))


