async def send_verdict_feedback_to_channel(interaction: Interaction, req: dict, kind: str, text: str):
    channel_id = verdicts_data.get("requests_channel")
    channel = interaction.guild.get_channel(int(channel_id)) if interaction.guild and channel_id else None
    if not channel:
        await interaction.response.send_message("❌ Канал для обращений по вердиктам не настроен.", ephemeral=True)
        return
    labels = {"problem": "Сообщить о проблеме", "appeal": "Оспорить вердикт", "question": "Задать вопрос по вердикту"}
    embed = Embed(title=f"📨 {labels.get(kind, kind)}", description=text, color=0x3498DB)
    player_id = str(req.get("author_id") or req.get("target_id") or "")
    embed.add_field(name="Игрок", value=f"<@{player_id}> (`{player_id}`)", inline=False)
    embed.add_field(name="Вердикт/ивент", value=str(req.get("id") or "—"), inline=True)
    embed.add_field(name="Ссылка", value=str(req.get("result_message_url") or req.get("result_message_url") or req.get("message_link") or "—"), inline=False)
    msg = await channel.send(embed=embed, view=VerdictModeratorReplyView(player_id, req_id=str(req.get("id") or ""), feedback_kind=kind, feedback_text=text))
    req.setdefault("feedback_messages", {})[str(msg.id)] = {"channel_id": msg.channel.id, "message_id": msg.id, "kind": kind, "text": text, "player_id": player_id, "status": "pending"}
    if req.get("id") and str(req.get("id")) in verdicts_data.setdefault("requests", {}):
        save_verdicts_data()
    else:
        save_events_data()
    await interaction.response.send_message("✅ Обращение отправлено модераторам.", ephemeral=True)


class VerdictFeedbackModal(Modal):
    def __init__(self, req_id: str, kind: str):
        self.req_id = str(req_id); self.kind = kind
        titles = {"problem": "Сообщить о проблеме", "appeal": "Оспорить вердикт", "question": "Вопрос по вердикту"}
        super().__init__(title=titles.get(kind, "Обращение"), timeout=300)
        self.text = TextInput(label="Текст обращения", style=discord.TextStyle.paragraph, required=True, max_length=1500)
        self.add_item(self.text)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id) or events_data.get("requests", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Запись не найдена.", ephemeral=True); return
        if str(req.get("author_id") or req.get("target_id")) != str(interaction.user.id):
            await interaction.response.send_message("❌ Это меню доступно только игроку, для которого был вердикт.", ephemeral=True); return
        await send_verdict_feedback_to_channel(interaction, req, self.kind, str(self.text.value).strip())


class VerdictRatingModal(Modal):
    def __init__(self, req_id: str):
        self.req_id = str(req_id)
        super().__init__(title="Оценка администрации", timeout=300)
        self.role_input = TextInput(label="Назначение участника", required=True, max_length=120, default="Модератор вердикта")
        self.score_input = TextInput(label="Оценка (1-10)", required=True, max_length=2)
        self.comment_input = TextInput(label="Комментарий", required=True, style=discord.TextStyle.paragraph, max_length=1000)
        self.add_item(self.role_input)
        self.add_item(self.score_input)
        self.add_item(self.comment_input)

    async def on_submit(self, interaction: Interaction):
        req = verdicts_data.get("requests", {}).get(self.req_id) or events_data.get("requests", {}).get(self.req_id) or {}
        target_id = str(req.get("processed_by") or req.get("creator_id") or "")
        target = interaction.guild.get_member(int(target_id)) if interaction.guild and target_id.isdigit() else None
        if not target:
            await interaction.response.send_message("❌ Модератор для оценки не найден.", ephemeral=True); return
        try:
            score = int(str(self.score_input.value).strip())
            if score < 1 or score > 10:
                raise ValueError
        except Exception:
            await interaction.response.send_message("❌ Оценка должна быть числом от 1 до 10.", ephemeral=True); return
        now_ts = int(time.time())
        target_votes = ratings_data.setdefault("votes", {}).setdefault(str(target.id), [])
        payload = {
            "id": str(ratings_data.setdefault("next_vote_id", 1)),
            "from": str(interaction.user.id),
            "score": score,
            "comment": str(self.comment_input.value),
            "role_text": str(self.role_input.value),
            "time": now_ts,
            "source": "verdict",
            "source_id": self.req_id,
        }
        target_votes.append(payload)
        ratings_data["next_vote_id"] = int(ratings_data.get("next_vote_id", 1)) + 1
        save_ratings_data()
        channel = interaction.guild.get_channel(int(ratings_data.get("channel_id"))) if interaction.guild and ratings_data.get("channel_id") else None
        if channel:
            embed = Embed(title="📝 Новая оценка", color=0x3498DB)
            embed.add_field(name="Оценка от", value=interaction.user.mention, inline=False)
            embed.add_field(name="Назначение", value=str(self.role_input.value), inline=False)
            embed.add_field(name="Оценка", value=f"{score}/10", inline=True)
            embed.add_field(name="Комментарий", value=str(self.comment_input.value), inline=False)
            msg = await channel.send(content=target.mention, embed=embed, view=RatingPublishedActionView())
            payload["channel_id"] = msg.channel.id; payload["message_id"] = msg.id; save_ratings_data()
        try:
            await target.send(embed=Embed(title="⭐ Вам оставили оценку", description=(f"**От:** {interaction.user.mention}\n**Оценка:** {score}/10\n**Назначение:** {str(self.role_input.value)}\n**Комментарий:** {str(self.comment_input.value)}"), color=0x3498DB))
        except Exception:
            pass
        await interaction.response.send_message("✅ Оценка отправлена.", ephemeral=True)

class VerdictReplyModal(Modal):
    def __init__(self, target_id: str, req_id: str = "", feedback_message_id: str = ""):
        self.target_id = str(target_id)
        self.req_id = str(req_id)
        self.feedback_message_id = str(feedback_message_id)
        super().__init__(title="Ответ игроку", timeout=300)
        self.text = TextInput(label="Ответ", style=discord.TextStyle.paragraph, required=True, max_length=1500)
        self.add_item(self.text)

    async def on_submit(self, interaction: Interaction):
        try:
            user = await bot.fetch_user(int(self.target_id))
            answer_text = str(self.text.value).strip()
            await user.send(embed=Embed(title="📬 Ответ модератора", description=answer_text, color=0x3498DB))
        except Exception:
            await interaction.response.send_message("❌ Не удалось отправить ЛС игроку.", ephemeral=True); return
        req = verdicts_data.setdefault("requests", {}).get(self.req_id) or events_data.setdefault("requests", {}).get(self.req_id)
        if req and self.feedback_message_id:
            fb = req.setdefault("feedback_messages", {}).get(self.feedback_message_id, {})
            fb.update({"status": "answered", "answered_by": str(interaction.user.id), "answer": answer_text})
            emb = Embed(title="✅ Обращение отвечено", description=fb.get("text") or "—", color=0x2ECC71)
            emb.add_field(name="Игрок", value=f"<@{self.target_id}>", inline=False)
            emb.add_field(name="Ответ модератора", value=answer_text[:1024], inline=False)
            try:
                await interaction.message.edit(embed=emb, view=None)
            except Exception:
                pass
            save_verdicts_data(); save_events_data()
        await interaction.response.send_message("✅ Ответ отправлен в ЛС.", ephemeral=True)


