@bot.command(name="принятьинвестицию")
async def принятьинвестицию(ctx, number: int):
    if not (ctx.author.guild_permissions.administrator or has_custom_command_access(ctx.author, "инвестиции")):
        await ctx.send(
            embed=Embed(
                title="❌ Нет доступа",
                description="Команда доступна администрации или ролям с правом `инвестиции`.",
                color=0xE74C3C,
            )
        )
        return

    req = investments.setdefault("requests", {}).get(str(number))
    if not req:
        await ctx.send(
            embed=Embed(
                title="❌ Заявка не найдена",
                description=f"Заявка инвестиции **#{number}** отсутствует.",
                color=0xE74C3C,
            )
        )
        return

    if str(req.get("status")) != "pending":
        await ctx.send(
            embed=Embed(
                title="⚠️ Уже рассмотрено",
                description=f"Заявка инвестиции **#{number}** уже имеет статус: `{req.get('status')}`.",
                color=0xF1C40F,
            )
        )
        return

    req_channel = await get_channel_safe(investments.get("requests_channel")) or ctx.channel
    content = investment_ping_roles_line(req_channel.guild) if getattr(req_channel, "guild", None) else ""
    msg = await req_channel.send(
        content=content or None,
        embed=build_investment_request_embed(req),
        view=InvestmentReviewView(str(number)),
    )
    req["request_channel_id"] = msg.channel.id
    req["request_message_id"] = msg.id
    save_investments()

    await ctx.send(
        embed=Embed(
            title="✅ Меню инвестиции восстановлено",
            description=f"Для заявки **#{number}** отправлено новое меню рассмотрения в {msg.channel.mention}.",
            color=0x2ECC71,
        )
    )


