@bot.command(name="принятькомпанию")
async def принятькомпанию(ctx, number: int):
    if not (ctx.author.guild_permissions.administrator or has_custom_command_access(ctx.author, "компании")):
        await ctx.send(
            embed=Embed(
                title="❌ Нет доступа",
                description="Команда доступна администрации или ролям с правом `компании`.",
                color=0xE74C3C,
            )
        )
        return

    req = companies_data.setdefault("requests", {}).get(str(number))
    if not req:
        await ctx.send(
            embed=Embed(
                title="❌ Заявка не найдена",
                description=f"Заявка компании **#{number}** отсутствует.",
                color=0xE74C3C,
            )
        )
        return

    if str(req.get("status")) not in {"pending", "pending_moderation"}:
        await ctx.send(
            embed=Embed(
                title="⚠️ Нельзя восстановить меню",
                description=f"Заявка компании **#{number}** имеет статус: `{req.get('status')}`.",
                color=0xF1C40F,
            )
        )
        return

    req_channel = await get_channel_safe(companies_data.get("requests_channel")) or ctx.channel
    content = company_ping_roles_line(req_channel.guild) if getattr(req_channel, "guild", None) else ""
    msg = await req_channel.send(
        content=content or None,
        embed=build_company_request_embed(req),
        view=CompanyReviewView(str(number)),
    )
    req["request_channel_id"] = msg.channel.id
    req["request_message_id"] = msg.id
    save_companies_data()

    await ctx.send(
        embed=Embed(
            title="✅ Меню компании восстановлено",
            description=f"Для заявки **#{number}** отправлено новое меню рассмотрения в {msg.channel.mention}.",
            color=0x2ECC71,
        )
    )


def company_ping_roles_line(guild: discord.Guild):
    access = get_command_access("компании")
    role_ids = access.get("roles", [])
    mentions = []
    for rid in role_ids:
        role = guild.get_role(int(rid)) if guild and str(rid).isdigit() else None
        if role:
            mentions.append(role.mention)
    return " ".join(mentions).strip()


async def get_channel_safe(channel_id):
    if not channel_id:
        return None
    try:
        cid = int(channel_id)
    except (TypeError, ValueError):
        return None
    ch = bot.get_channel(cid)
    if ch:
        return ch
    try:
        fetched = await bot.fetch_channel(cid)
        return fetched if isinstance(fetched, discord.abc.Messageable) else None
    except Exception:
        return None


def find_companies_by_name(query: str, owner_id: str | None = None):
    q = str(query or "").strip().lower()
    all_companies = list(companies_data.setdefault("companies", {}).values())
    if owner_id is not None:
        all_companies = [c for c in all_companies if str(c.get("owner_id")) == str(owner_id)]
    if q == "*":
        return all_companies
    if not q:
        return []
    exact = [c for c in all_companies if str(c.get("name", "")).strip().lower() == q]
    if exact:
        return exact
    return [c for c in all_companies if q in str(c.get("name", "")).strip().lower()]


def ensure_company_country_presence_struct(company: dict):
    if not isinstance(company.get("country_presence"), dict):
        company["country_presence"] = {}
    return company["country_presence"]


def get_country_name_by_user_id(user_id: str) -> str | None:
    uid = str(user_id)
    active_season = get_active_registration_season()
    _, user_to_country = get_occupied_country_map(active_season or None)
    current = user_to_country.get(uid)
    if current:
        return current
    profile = country_owners.setdefault("user_profiles", {}).get(uid, {})
    if isinstance(profile, dict):
        registrations = profile.get("registrations", {})
        if active_season and isinstance(registrations, dict):
            active_record = registrations.get(str(active_season), {})
            if isinstance(active_record, dict):
                country_name = str(active_record.get("country") or "").strip()
                if country_name:
                    return country_name
        if not active_season:
            return profile.get("active_country")
    return None




def relation_subject_key(raw: str) -> str:
    text = str(raw or "").strip()
    mention_match = re.fullmatch(r"<@!?(\d+)>", text)
    if mention_match:
        return mention_match.group(1)
    if text.isdigit():
        return text

    country_name = resolve_country_name(text)
    if country_name:
        active_season = get_active_registration_season()
        country_to_user, _ = get_occupied_country_map(active_season or None)
        owner_id = country_to_user.get(country_name)
        if owner_id:
            return str(owner_id)
        return country_name

    return text


def relation_pair_key(source: str, target: str) -> tuple[str, str]:
    return tuple(sorted((str(source or "").strip(), str(target or "").strip())))


def get_relation_value(source: str, target: str) -> int:
    source_key, target_key = relation_pair_key(source, target)
    if not source_key or not target_key or source_key == target_key:
        return 0
    relation_map = relations_data.setdefault("relations", {})
    values = relation_map.get(source_key, {})
    if not isinstance(values, dict):
        return 0
    try:
        return int(values.get(target_key, 0) or 0)
    except (TypeError, ValueError):
        return 0


def set_relation_value(source: str, target: str, value: int) -> int:
    source_key, target_key = relation_pair_key(source, target)
    if not source_key or not target_key or source_key == target_key:
        return 0
    try:
        new_value = int(value or 0)
    except (TypeError, ValueError):
        new_value = 0
    relation_map = relations_data.setdefault("relations", {})
    values = relation_map.setdefault(source_key, {})
    if not isinstance(values, dict):
        values = {}
        relation_map[source_key] = values
    if new_value == 0:
        values.pop(target_key, None)
        if not values:
            relation_map.pop(source_key, None)
    else:
        values[target_key] = new_value
    return new_value


def get_country_display(subject: str) -> str:
    key = str(subject or "").strip()
    if not key:
        return "—"
    if key.isdigit():
        country_name = get_country_name_by_user_id(key)
        return country_name or f"<@{key}>"
    return str(relations_data.setdefault("pending_names", {}).get(key) or key)


def snapshot_relations_for_subject(subject: str) -> dict:
    key = str(subject)
    outgoing = make_json_snapshot(relations_data.setdefault("relations", {}).get(key, {}))
    incoming = {
        str(src): int(vals.get(key, 0) or 0)
        for src, vals in relations_data.setdefault("relations", {}).items()
        if isinstance(vals, dict) and key in vals
    }
    changes = [
        make_json_snapshot(change)
        for change in relations_data.setdefault("changes", [])
        if str((change or {}).get("source")) == key or str((change or {}).get("target")) == key
    ]
    return {"outgoing": outgoing, "incoming": incoming, "changes": changes}


def relation_snapshot_has_data(snapshot: dict) -> bool:
    return bool(
        isinstance(snapshot, dict)
        and (snapshot.get("outgoing") or snapshot.get("incoming") or snapshot.get("changes"))
    )


def remove_relations_for_subject(subject: str) -> bool:
    key = str(subject)
    changed = False
    if key in relations_data.setdefault("relations", {}):
        relations_data["relations"].pop(key, None)
        changed = True
    for vals in relations_data.setdefault("relations", {}).values():
        if isinstance(vals, dict) and key in vals:
            vals.pop(key, None)
            changed = True
    old_len = len(relations_data.setdefault("changes", []))
    relations_data["changes"] = [
        change for change in relations_data.setdefault("changes", [])
        if str((change or {}).get("source")) != key and str((change or {}).get("target")) != key
    ]
    return changed or len(relations_data["changes"]) != old_len


def restore_relations_for_subject(new_subject: str, snapshot: dict, old_subject: str | None = None):
    if not isinstance(snapshot, dict):
        return
    new_key = str(new_subject)
    old_key = str(old_subject or new_key)
    remove_relations_for_subject(new_key)
    outgoing = snapshot.get("outgoing", {}) if isinstance(snapshot.get("outgoing"), dict) else {}
    for target, value in outgoing.items():
        mapped_target = new_key if str(target) == old_key else str(target)
        set_relation_value(new_key, mapped_target, int(value or 0))
    incoming = snapshot.get("incoming", {}) if isinstance(snapshot.get("incoming"), dict) else {}
    for source, value in incoming.items():
        mapped_source = new_key if str(source) == old_key else str(source)
        set_relation_value(mapped_source, new_key, int(value or 0))
    for change in snapshot.get("changes", []) if isinstance(snapshot.get("changes"), list) else []:
        if not isinstance(change, dict):
            continue
        restored = make_json_snapshot(change)
        if str(restored.get("source")) == old_key:
            restored["source"] = new_key
        if str(restored.get("target")) == old_key:
            restored["target"] = new_key
        relations_data.setdefault("changes", []).append(restored)


def get_owner_country_of_company(company: dict) -> str | None:
    return get_country_name_by_user_id(str(company.get("owner_id") or ""))


def effective_company_share(company: dict, user_id: str, country_name: str | None = None) -> float:
    owner_id = str(company.get("owner_id") or "")
    if str(user_id) == owner_id:
        return 1.0
    if not country_name:
        country_name = get_country_name_by_user_id(str(user_id))
    if not country_name:
        return 0.0
    presence = ensure_company_country_presence_struct(company).get(str(country_name))
    if not isinstance(presence, dict) or str(presence.get("status")) != "active":
        return 0.0
    share_percent = int(presence.get("share_percent", 10) or 10)
    return max(0.0, min(1.0, share_percent / 100.0))


COMPANY_REQUEST_TYPE_LABELS = {
    "create": "Создание компании",
    "foreign_entry": "Вход компании в другую страну",
    "buy": "Покупка компании",
    "sell": "Продажа компании",
    "upgrade": "Улучшение компании",
}


def company_request_type_label(req_type: str) -> str:
    return COMPANY_REQUEST_TYPE_LABELS.get(str(req_type), str(req_type) or "Неизвестно")


def get_company_request_company_name(req: dict) -> str:
    payload = req.get("payload", {}) if isinstance(req.get("payload", {}), dict) else {}
    for key in ("Название", "Название компании"):
        value = str(payload.get(key) or "").strip()
        if value:
            return value

    company_id = str(req.get("company_id") or "").strip()
    company = companies_data.setdefault("companies", {}).get(company_id) if company_id else None
    if isinstance(company, dict):
        value = str(company.get("name") or "").strip()
        if value:
            return value
    return "—"


COMPANY_MONEY_PAYLOAD_KEYS = {"Первый вклад", "Вклад", "Предложение", "Цена", "Стоимость входа", "Лимит вложений", "Оценка цены"}


def format_company_payload_value(key: str, value) -> str:
    if str(key) in COMPANY_MONEY_PAYLOAD_KEYS:
        return format_money_like_text(value, 1_000_000_000)
    return str(value)


def build_company_request_embed(req: dict, color=0x3498DB):
    em = Embed(
        title=f"🏢 Заявка компании #{req.get('id')}",
        color=color,
    )
    em.add_field(name="Тип заявки", value=company_request_type_label(req.get("type")), inline=False)
    em.add_field(name="Компания", value=get_company_request_company_name(req), inline=False)
    em.add_field(name="Автор", value=f"<@{req.get('author_id')}>", inline=False)
    em.add_field(name="Статус", value=req.get("status_text", "⏳ На рассмотрении"), inline=False)
    payload = req.get("payload", {})
    for key, value in payload.items():
        em.add_field(name=str(key), value=format_company_payload_value(str(key), value), inline=False)
    change_lines = []
    for entry in req.get("review_change_log", [])[-15:]:
        change_key = str(entry.get("key", ""))
        pretty_label = str(entry.get("label") or COMPANY_CHANGE_LABELS.get(change_key, change_key)) if "COMPANY_CHANGE_LABELS" in globals() else str(entry.get("label") or change_key)
        old_text = format_company_change_value(change_key, entry.get("old")) if "format_company_change_value" in globals() else str(entry.get("old"))
        new_text = format_company_change_value(change_key, entry.get("new")) if "format_company_change_value" in globals() else str(entry.get("new"))
        change_lines.append(f"• {pretty_label}: {old_text} → {new_text}")
    if change_lines:
        em.add_field(name="Введённые изменения", value=("\n".join(change_lines))[:1024], inline=False)
    return em


async def notify_company_request_author_dm(req: dict, title: str, description: str, color: int):
    author_id = str(req.get("author_id") or "")
    if not author_id.isdigit():
        return

    user = bot.get_user(int(author_id))
    if user is None:
        try:
            user = await bot.fetch_user(int(author_id))
        except Exception:
            return

    try:
        await user.send(
            embed=Embed(
                title=title,
                description=description,
                color=color,
            )
        )
    except Exception:
        pass


class CompanyCreateModal(Modal):
    def __init__(self):
        super().__init__(title="Создание компании", timeout=600)
        self.post_url = TextInput(label="Ссылка на пост", required=True, max_length=400)
        self.company_name = TextInput(label="Название компании", required=True, max_length=120)
        self.specialization = TextInput(label="Специализация (номер)", required=True, max_length=20)
        self.first_invest = TextInput(label="Первый вклад", required=True, max_length=100)
        self.add_item(self.post_url)
        self.add_item(self.company_name)
        self.add_item(self.specialization)
        self.add_item(self.first_invest)

    async def on_submit(self, interaction: Interaction):
        if await deny_if_request_cooldown(interaction, "companies"):
            return
        author_id = str(interaction.user.id)
        required_role_id = companies_data.get("create_role_id")
        if required_role_id:
            role = interaction.guild.get_role(int(required_role_id)) if interaction.guild and str(required_role_id).isdigit() else None
            if not role or role not in getattr(interaction.user, "roles", []):
                role_text = role.mention if role else f"`{required_role_id}`"
                await interaction.response.send_message(
                    f"❌ Для создания компании нужна роль {role_text}.",
                    ephemeral=True,
                )
                return

        if not is_registered_player(author_id):
            await interaction.response.send_message("❌ Компании доступны только зарегистрированным игрокам (`!рег`).", ephemeral=True)
            return

        try:
            specialization_name = resolve_company_specialization(str(self.specialization.value))
        except Exception:
            available = "\n".join(f"{num}. {name}" for num, name in COMPANY_SPECIALIZATIONS.items())
            await interaction.response.send_message(
                f"❌ Неверная специализация. Укажите номер из списка:\n{available}",
                ephemeral=True,
            )
            return

        user = ensure_user(author_id)
        raw_first_invest = str(self.first_invest.value).strip()
        try:
            first_invest = parse_money_value(raw_first_invest, int(user.get("наличка", 0)))
        except Exception:
            await interaction.response.send_message(
                "❌ Неверный формат `Первый вклад`. Укажите сумму числом, например `10000000` или `10кк`.",
                ephemeral=True,
            )
            return

        if int(first_invest) <= 0:
            await interaction.response.send_message("❌ Первый вклад должен быть больше нуля.", ephemeral=True)
            return
        science_auto_bonus = 0

        available_cash = int(user.get("наличка", 0)) - int(user.get("заморожено", 0))
        if int(first_invest) > available_cash:
            await interaction.response.send_message(
                f"❌ Недостаточно средств для первого вклада. Доступно: {fmt_money(available_cash)}. Нужно: {fmt_money(first_invest)}.",
                ephemeral=True,
            )
            return

        user["наличка"] = int(user.get("наличка", 0)) - int(first_invest)
        await log_economy_change(
            interaction.guild,
            author_id,
            "Подача заявки на создание компании: первый вклад",
            cash_delta=-int(first_invest),
        )
        save_json(BALANCES_FILE, balances)

        req_id = int(companies_data.get("next_request_id", 1))
        companies_data["next_request_id"] = req_id + 1
        req = {
            "id": req_id,
            "type": "create",
            "author_id": author_id,
            "status": "pending",
            "status_text": "⏳ На рассмотрении",
            "payload": {
                "Ссылка на пост": str(self.post_url.value).strip(),
                "Название": str(self.company_name.value).strip(),
                "Специализация": specialization_name,
                "Первый вклад": raw_first_invest,
                "Автонадбавка науки": str(science_auto_bonus),
            },
            "first_invest_charged": int(first_invest),
            "first_invest_refunded": False,
            "created_at": int(time.time()),
        }
        companies_data.setdefault("requests", {})[str(req_id)] = req
        save_companies_data()

        ch_id = companies_data.get("requests_channel")
        ch = interaction.guild.get_channel(int(ch_id)) if ch_id else None
        if not ch:
            await interaction.response.send_message("❌ Канал заявок компаний не настроен (`!заявкикомпаний`).", ephemeral=True)
            return

        content = company_ping_roles_line(interaction.guild) or None
        msg = await ch.send(content=content, embed=build_company_request_embed(req), view=CompanyReviewView(str(req_id)))
        req["request_channel_id"] = msg.channel.id
        req["request_message_id"] = msg.id
        save_companies_data()
        mark_request_submitted(author_id, "companies")
        await interaction.response.send_message(f"✅ Заявка #{req_id} отправлена.", ephemeral=True)


class CompanyBuyModal(Modal):
    def __init__(self):
        super().__init__(title="Купить компанию", timeout=600)
        self.company_name = TextInput(label="Название компании (можно частично)", required=True, max_length=120)
        self.post_url = TextInput(label="Пост", required=True, max_length=400)
        self.offer = TextInput(label="Сколько денег предлагаете", required=True, max_length=100)
        self.reason = TextInput(label="Причина", style=discord.TextStyle.paragraph, required=True, max_length=1000)
        for item in (self.company_name, self.post_url, self.offer, self.reason):
            self.add_item(item)

    async def on_submit(self, interaction: Interaction):
        if await deny_if_request_cooldown(interaction, "companies"):
            return
        buyer_id = str(interaction.user.id)
        if not is_registered_player(buyer_id):
            await interaction.response.send_message("❌ Купить компанию могут только зарегистрированные игроки.", ephemeral=True)
            return

        matches = find_companies_by_name(str(self.company_name.value), owner_id=None)
        if not matches:
            await interaction.response.send_message("❌ Компания с таким названием не найдена.", ephemeral=True)
            return
        if len(matches) > 1:
            names = "\n".join([f"• {c.get('name', 'Без названия')} (владелец: <@{c.get('owner_id')}>)" for c in matches[:10]])
            await interaction.response.send_message(
                "⚠️ Найдено несколько компаний. Уточните название и подтвердите выбор:\n" + names,
                ephemeral=True,
            )
            return
        company = matches[0]
        if str(company.get("owner_id")) == buyer_id:
            await interaction.response.send_message("❌ Вы уже владелец этой компании.", ephemeral=True)
            return

        req_id = int(companies_data.get("next_request_id", 1))
        companies_data["next_request_id"] = req_id + 1
        req = {
            "id": req_id,
            "type": "buy",
            "author_id": buyer_id,
            "owner_id": str(company.get("owner_id")),
            "decision_user_id": str(company.get("owner_id")),
            "company_id": str(company.get("id")),
            "status": "pending_owner",
            "status_text": "⏳ Ожидает решения владельца",
            "payload": {
                "Пост": str(self.post_url.value).strip(),
                "Предложение": str(self.offer.value).strip(),
                "Причина": str(self.reason.value).strip(),
            },
            "created_at": int(time.time()),
        }
        companies_data.setdefault("requests", {})[str(req_id)] = req
        save_companies_data()

        owner = interaction.guild.get_member(int(req["owner_id"])) if interaction.guild else None
        if owner:
            try:
                dm_msg = await owner.send(
                    content=f"📩 Новое предложение о покупке вашей компании **{company.get('name')}** от {interaction.user.mention}",
                    embed=build_company_request_embed(req),
                    view=CompanyOwnerDecisionView(str(req_id)),
                )
                req["decision_channel_id"] = dm_msg.channel.id
                req["decision_message_id"] = dm_msg.id
                save_companies_data()
            except Exception:
                pass

        mark_request_submitted(buyer_id, "companies")
        await interaction.response.send_message("✅ Предложение отправлено владельцу компании в ЛС.", ephemeral=True)


