class CompanyForeignEntryRequestModal(Modal):
    def __init__(self):
        super().__init__(title="Вход компании в другую страну", timeout=600)
        self.post_url = TextInput(label="Ссылка на пост", required=True, max_length=400)
        self.company_name = TextInput(label="Название компании", required=True, max_length=120)
        self.target_owner = TextInput(label="Кому (@юз/ID/ник владельца страны)", required=True, max_length=80)
        self.add_item(self.post_url)
        self.add_item(self.company_name)
        self.add_item(self.target_owner)

    async def on_submit(self, interaction: Interaction):
        if await deny_if_request_cooldown(interaction, "companies"):
            return
        owner_id = str(interaction.user.id)
        matches = find_companies_by_name(str(self.company_name.value), owner_id=owner_id)
        if not matches:
            await interaction.response.send_message("❌ У вас нет компании с таким названием.", ephemeral=True)
            return
        if len(matches) > 1:
            await interaction.response.send_message("❌ Уточните название компании (найдено несколько совпадений).", ephemeral=True)
            return
        company = matches[0]

        target_member = resolve_member_query(
            interaction.guild,
            str(self.target_owner.value),
        ) if interaction.guild else None
        if not target_member:
            await interaction.response.send_message(
                "❌ Укажите владельца страны через @юз, ID или точный ник.",
                ephemeral=True,
            )
            return
        raw = str(target_member.id)
        target_country = get_country_name_by_user_id(raw)
        if not target_country:
            await interaction.response.send_message("❌ Указанный пользователь не является владельцем страны.", ephemeral=True)
            return

        req_id = int(companies_data.get("next_request_id", 1))
        companies_data["next_request_id"] = req_id + 1
        req = {
            "id": req_id,
            "type": "foreign_entry",
            "author_id": owner_id,
            "company_id": str(company.get("id")),
            "target_country": target_country,
            "target_country_owner_id": str(raw),
            "status": "pending_moderation",
            "status_text": "⏳ На рассмотрении модерации",
            "payload": {
                "Ссылка на пост": str(self.post_url.value).strip(),
                "Название компании": str(company.get("name", "")),
                "Кому": f"<@{raw}>",
            },
            "created_at": int(time.time()),
        }
        companies_data.setdefault("requests", {})[str(req_id)] = req
        save_companies_data()

        ch_id = companies_data.get("entry_requests_channel") or companies_data.get("requests_channel")
        ch = interaction.guild.get_channel(int(ch_id)) if ch_id else None
        if ch:
            msg = await ch.send(content=company_ping_roles_line(interaction.guild) or None, embed=build_company_request_embed(req), view=CompanyReviewView(str(req_id)))
            req["request_channel_id"] = msg.channel.id
            req["request_message_id"] = msg.id
            save_companies_data()
        mark_request_submitted(owner_id, "companies")
        await interaction.response.send_message(f"✅ Заявка #{req_id} на вход отправлена модераторам.", ephemeral=True)


COMPANY_CHANGE_LABELS = {
    "income_amount": "Доход",
    "income_cooldown": "КД дохода",
    "expense_amount": "Траты",
    "expense_cooldown": "КД трат",
    "advert_level": "Уровень рекламы",
    "min_value": "Оценка цены",
    "science_auto_bonus": "Автонадбавка науки",
    "investment_limit": "Лимит вложений",
    "reputation": "Репутация",
    "happiness": "Счастье",
    "stat_passive_reputation": "Автопассив репутации",
    "stat_passive_happiness": "Автопассив счастья",
}


def format_company_change_value(key: str, value) -> str:
    if key == "investment_limit":
        if str(value).strip().lower() in {"", "none", "null", "безлимит", "unlimited"}:
            return "Без лимита"
        return format_money_like_text(value, 1_000_000_000)
    if key in {"income_amount", "expense_amount", "min_value"}:
        return format_money_like_text(value, 1_000_000_000)
    if key in {"reputation", "happiness"}:
        return f"{value}%"
    if key.startswith("stat_passive_") and isinstance(value, dict):
        return f"{int(value.get('amount', 0)):+d}% / {format_interval(int(value.get('cooldown', 86400)))}"
    if key in {"income_cooldown", "expense_cooldown"}:
        try:
            return format_interval(max(0, parse_interval(str(value))))
        except Exception:
            return str(value)
    return str(value)


def get_company_request_target_user_id(req: dict) -> str:
    return str(req.get("owner_id") or req.get("author_id") or "")


def get_company_review_current_value(req: dict, key: str):
    payload = req.get("payload", {}) if isinstance(req.get("payload"), dict) else {}
    company = companies_data.get("companies", {}).get(str(req.get("company_id") or ""), {})
    if key == "name":
        return payload.get("Название") or company.get("name") or "—"
    if key == "specialization":
        return payload.get("Специализация") or company.get("specialization") or "—"
    if key == "first_invest":
        return payload.get("Первый вклад") or company.get("first_invest") or "—"
    if key == "science_auto_bonus" and str(req.get("type")) == "create":
        return payload.get("Автонадбавка науки", 0)
    if key in {"reputation", "happiness"}:
        uid = get_company_request_target_user_id(req)
        return ensure_player_state(uid).get(key, 50) if uid else 50
    return company.get(key, "—")


def _append_company_review_change(req: dict, key: str, value, label: str, reviewer: discord.Member):
    changes = req.setdefault("review_changes", {})
    old_value = get_company_review_current_value(req, str(key))
    changes[str(key)] = value
    req.setdefault("review_change_log", []).append({
        "key": str(key),
        "label": label,
        "old": old_value,
        "new": value,
        "reviewer_id": str(reviewer.id),
        "ts": int(time.time()),
    })

    lines = []
    for entry in req.get("review_change_log", [])[-15:]:
        change_key = str(entry.get("key", ""))
        pretty_label = str(entry.get("label") or COMPANY_CHANGE_LABELS.get(change_key, change_key))
        old_text = format_company_change_value(change_key, entry.get("old"))
        new_text = format_company_change_value(change_key, entry.get("new"))
        lines.append(f"• {pretty_label}: {old_text} → {new_text}")

    req["status_text"] = "📝 Изменения подготовлены:\n" + "\n".join(lines)
    req["processed_by"] = str(reviewer.id)


