class CompanyRawEditModal(Modal):
    def __init__(self, company_id: str):
        self.company_id = str(company_id)
        company = companies_data.get("companies", {}).get(self.company_id, {})
        raw = json.dumps(company, ensure_ascii=False, indent=2)
        if len(raw) > 3900:
            raw = json.dumps(company, ensure_ascii=False)
        super().__init__(title="Полное редактирование компании", timeout=900)
        self.raw_json = TextInput(
            label="JSON компании",
            style=discord.TextStyle.paragraph,
            required=True,
            max_length=4000,
            default=raw[:4000],
        )
        self.add_item(self.raw_json)

    async def on_submit(self, interaction: Interaction):
        current = companies_data.get("companies", {}).get(self.company_id)
        if not current:
            await interaction.response.send_message("❌ Компания не найдена.", ephemeral=True)
            return
        raw = str(self.raw_json.value).strip()
        try:
            payload = json.loads(raw)
        except Exception:
            await interaction.response.send_message("❌ Некорректный JSON.", ephemeral=True)
            return
        if not isinstance(payload, dict):
            await interaction.response.send_message("❌ JSON должен быть объектом.", ephemeral=True)
            return
        payload["id"] = str(self.company_id)
        payload["owner_id"] = str(payload.get("owner_id", current.get("owner_id", "")))
        update_company_derived_fields(payload)
        companies_data.setdefault("companies", {})[self.company_id] = payload
        save_companies_data()
        await interaction.response.send_message(
            "✅ Компания полностью обновлена из JSON (включая страны пребывания и другие поля).",
            ephemeral=True,
        )


class CompanyAutoBuyModal(Modal):
    def __init__(self, company_id: str):
        self.company_id = str(company_id)
        super().__init__(title="Автопокупка предмета", timeout=600)
        self.item_key = TextInput(label="Название предмета", required=True, max_length=120)
        self.quantity = TextInput(label="Количество за цикл", required=True, max_length=20, default="1")
        self.cooldown = TextInput(label="Кулдаун (например 30м, 4ч)", required=True, max_length=100, default="24ч")
        self.add_item(self.item_key)
        self.add_item(self.quantity)
        self.add_item(self.cooldown)

    async def on_submit(self, interaction: Interaction):
        company = companies_data.get("companies", {}).get(self.company_id)
        if not company:
            await interaction.response.send_message("❌ Компания не найдена.", ephemeral=True)
            return
        matches = resolve_item_key(str(self.item_key.value))
        if not matches:
            await interaction.response.send_message("❌ Предмет не найден.", ephemeral=True)
            return
        item_key = matches[0]
        try:
            qty = max(1, int(str(self.quantity.value).strip()))
            cd = max(60, parse_interval(str(self.cooldown.value).strip()))
        except Exception:
            await interaction.response.send_message("❌ Неверный формат количества или кулдауна.", ephemeral=True)
            return
        autobuy = company.setdefault("autobuy", [])
        autobuy.append({"item_key": item_key, "quantity": qty, "cooldown": cd, "last_at": 0})
        save_companies_data()
        await interaction.response.send_message("✅ Правило автопокупки добавлено.", ephemeral=True)


