def find_rating_vote_by_message(message_id: int | str):
    for target_id, votes in ratings_data.setdefault("votes", {}).items():
        if not isinstance(votes, list):
            continue
        for vote in votes:
            if str(vote.get("message_id")) == str(message_id):
                return str(target_id), vote
    return None, None


class RatingPublishedActionSelect(Select):
    def __init__(self):
        super().__init__(
            placeholder="Действия с вашей оценкой",
            min_values=1,
            max_values=1,
            options=[
                SelectOption(label="Отредактировать оценку и комментарий", value="edit", emoji="✏️"),
                SelectOption(label="Удалить оценку", value="delete", emoji="🗑️"),
            ],
            custom_id="ratings:published_actions",
        )

    async def callback(self, interaction: Interaction):
        target_id, vote = find_rating_vote_by_message(interaction.message.id)
        if not vote:
            await interaction.response.send_message("❌ Оценка не найдена в базе.", ephemeral=True)
            return
        if str(vote.get("from")) != str(interaction.user.id):
            await interaction.response.send_message("❌ Управлять этой оценкой может только её публикатор.", ephemeral=True)
            return
        if self.values[0] == "edit":
            await interaction.response.send_modal(RatingModal(target_id, vote))
            return
        votes = ratings_data.setdefault("votes", {}).get(str(target_id), [])
        ratings_data["votes"][str(target_id)] = [v for v in votes if str(v.get("id")) != str(vote.get("id"))]
        save_ratings_data()
        try:
            await interaction.message.delete()
        except Exception:
            pass
        if not interaction.response.is_done():
            await interaction.response.send_message("✅ Оценка удалена.", ephemeral=True)


class RatingPublishedActionView(View):
    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(RatingPublishedActionSelect())


class RatingModal(Modal):
    def __init__(self, target_id: str, existing_vote: dict | None = None):
        self.target_id = str(target_id)
        self.existing_vote_id = str((existing_vote or {}).get("id") or "")
        super().__init__(title="Оценка администрации", timeout=300)
        self.role_input = TextInput(
            label="Назначение участника", required=True, max_length=120, default=str((existing_vote or {}).get("role_text") or "")
        )
        self.score_input = TextInput(label="Оценка (1-10)", required=True, max_length=2, default=str((existing_vote or {}).get("score") or ""))
        self.comment_input = TextInput(
            label="Комментарий",
            required=True,
            style=discord.TextStyle.paragraph,
            max_length=1000,
            default=str((existing_vote or {}).get("comment") or ""),
        )
        self.add_item(self.role_input)
        self.add_item(self.score_input)
        self.add_item(self.comment_input)

    async def on_submit(self, interaction: Interaction):
        target = (
            interaction.guild.get_member(int(self.target_id))
            if interaction.guild
            else None
        )
        if target and interaction.user.id == target.id:
            await interaction.response.send_message(
                "❌ Нельзя ставить оценку самому себе.", ephemeral=True
            )
            return

        if not target:
            await interaction.response.send_message(
                "❌ Администратор не найден.", ephemeral=True
            )
            return

        now_ts = int(time.time())
        voter_id = str(interaction.user.id)

        try:
            score = int(str(self.score_input.value).strip())
            if score < 1 or score > 10:
                raise ValueError
        except Exception:
            await interaction.response.send_message(
                "❌ Оценка должна быть числом от 1 до 10.", ephemeral=True
            )
            return

        target_votes = ratings_data.setdefault("votes", {}).setdefault(
            str(target.id), []
        )
        existing_vote = next(
            (v for v in target_votes if str(v.get("from")) == voter_id), None
        )
        action_text = "обновлена" if existing_vote else "отправлена"

        payload = {
            "id": self.existing_vote_id or str(ratings_data.setdefault("next_vote_id", 1)),
            "from": voter_id,
            "score": score,
            "comment": str(self.comment_input.value),
            "role_text": str(self.role_input.value),
            "time": now_ts,
        }
        if existing_vote:
            payload["channel_id"] = existing_vote.get("channel_id")
            payload["message_id"] = existing_vote.get("message_id")
            existing_vote.update(payload)
            stored_vote = existing_vote
        else:
            target_votes.append(payload)
            ratings_data["next_vote_id"] = int(ratings_data.get("next_vote_id", 1)) + 1
            stored_vote = payload

        save_ratings_data()

        channel = (
            interaction.guild.get_channel(int(ratings_data.get("channel_id")))
            if ratings_data.get("channel_id")
            else None
        )
        if channel:
            embed = Embed(
                title=("✏️ Оценка обновлена" if existing_vote else "📝 Новая оценка"),
                color=0x3498DB,
            )
            embed.add_field(
                name="Оценка от", value=interaction.user.mention, inline=False
            )
            embed.add_field(
                name="Назначение", value=str(self.role_input.value), inline=False
            )
            embed.add_field(name="Оценка", value=f"{score}/10", inline=True)
            embed.add_field(
                name="Комментарий", value=str(self.comment_input.value), inline=False
            )
            try:
                if existing_vote and stored_vote.get("message_id"):
                    msg = await channel.fetch_message(int(stored_vote.get("message_id")))
                    await msg.edit(content=target.mention, embed=embed, view=RatingPublishedActionView())
                else:
                    msg = await channel.send(content=target.mention, embed=embed, view=RatingPublishedActionView())
                    stored_vote["channel_id"] = msg.channel.id
                    stored_vote["message_id"] = msg.id
                    save_ratings_data()
            except Exception:
                pass

        try:
            await target.send(
                embed=Embed(
                    title="⭐ Вам оставили оценку",
                    description=(
                        f"**От:** {interaction.user.mention}\n"
                        f"**Оценка:** {score}/10\n"
                        f"**Назначение:** {str(self.role_input.value)}\n"
                        f"**Комментарий:** {str(self.comment_input.value)}"
                    ),
                    color=0x3498DB,
                )
            )
        except Exception:
            pass

        await interaction.response.send_message(
            f"✅ Оценка {action_text}.", ephemeral=True
        )


