async def send_my_admin_stats(destination, member: discord.Member, *, ephemeral: bool = False):
    uid = str(member.id)
    votes = ratings_data.setdefault("votes", {}).get(uid, [])
    counters = get_admin_counters(uid)
    avg_text = "—"
    if votes:
        avg = sum(int(v.get("score", 0)) for v in votes) / len(votes)
        avg_text = f"{avg:.2f}/10 ({len(votes)} оценок)"

    lines = [f"**Средняя оценка:** {avg_text}"]
    for key, label in ADMIN_COUNTER_LABELS.items():
        lines.append(f"**{label}:** {fmt_num(int(counters.get(key, 0)))}")

    class MyStatsRatingSelect(Select):
        def __init__(self):
            options = []
            for idx, vote in enumerate(votes[:25], start=1):
                voter = member.guild.get_member(int(vote.get("from", 0))) if str(vote.get("from", "")).isdigit() else None
                voter_name = voter.display_name if voter else f"ID {vote.get('from')}"
                options.append(SelectOption(label=f"{idx}) {voter_name} — {vote.get('score', 0)}/10", value=str(idx - 1), description=str(vote.get("comment") or "Без комментария")[:100]))
            super().__init__(placeholder="Посмотреть оценку и комментарий", options=options or [SelectOption(label="Оценок нет", value="none")])

        async def callback(self, interaction: Interaction):
            if interaction.user.id != member.id:
                await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True)
                return
            if self.values[0] == "none":
                await interaction.response.send_message("Оценок пока нет.", ephemeral=True)
                return
            vote = votes[int(self.values[0])]
            voter = interaction.guild.get_member(int(vote.get("from", 0))) if interaction.guild and str(vote.get("from", "")).isdigit() else None
            voter_label = voter.mention if voter else f"<@{vote.get('from')}>"
            await interaction.response.send_message(embed=Embed(title="⭐ Оценка администратора", description=(f"**От:** {voter_label}\n**Оценка:** {vote.get('score', 0)}/10\n**Назначение:** {vote.get('role_text', '—')}\n\n**Комментарий:**\n{vote.get('comment', '—')}"), color=0x3498DB), ephemeral=True)

    view = View(timeout=180)
    view.add_item(MyStatsRatingSelect())
    payload = {"embed": Embed(title="📊 Мой стат", description="\n".join(lines), color=0x3498DB), "view": view}
    if isinstance(destination, Interaction):
        await destination.response.send_message(**payload, ephemeral=ephemeral)
    else:
        await destination.send(**payload)


