@bot.command(name="регроли")
@admin_or_command_access()
async def регроли(ctx):
    reg_settings.setdefault("type_roles", {})
    for reg_type in ("country", "region", "pmc", "rebels", "organization"):
        reg_settings["type_roles"].setdefault(reg_type, {"roles_add": [], "roles_remove": []})

    async def parse_roles_text(raw_text: str):
        role_ids = []
        for token in re.split(r"[,\s]+", str(raw_text or "")):
            raw = token.strip()
            if not raw or raw.lower() == "скип":
                continue
            try:
                role = await commands.RoleConverter().convert(ctx, raw)
                role_ids.append(str(role.id))
            except Exception:
                continue
        return list(dict.fromkeys(role_ids))

    def role_mentions(role_ids):
        mentions = []
        for rid in role_ids:
            role = ctx.guild.get_role(int(rid)) if str(rid).isdigit() else None
            if role:
                mentions.append(role.mention)
        return ", ".join(mentions) if mentions else "—"

    def type_label(reg_type: str) -> str:
        cfg = REGISTRATION_TYPE_CONFIG.get(reg_type, {}) if "REGISTRATION_TYPE_CONFIG" in globals() else {}
        return str(cfg.get("title") or cfg.get("label") or reg_type)

    def build_embed(selected_type: str | None = None):
        lines = []
        for reg_type in ("country", "region", "pmc", "rebels", "organization"):
            cfg = reg_settings.setdefault("type_roles", {}).setdefault(reg_type, {"roles_add": [], "roles_remove": []})
            prefix = "▶️ " if reg_type == selected_type else "• "
            lines.append(
                f"{prefix}**{type_label(reg_type)}**\n"
                f"  Выдавать: {role_mentions(cfg.get('roles_add', []))}\n"
                f"  Снимать: {role_mentions(cfg.get('roles_remove', []))}"
            )
        legacy_add = role_mentions(reg_settings.get("roles_add", []))
        legacy_remove = role_mentions(reg_settings.get("roles_remove", []))
        return Embed(
            title="⚙️ Настройка !регроли по видам регистрации",
            description=(
                "Выберите вид регистрации в меню, затем заполните форму ролей.\n"
                "Роли можно указать через пробел или запятую; `скип` очищает список.\n\n"
                + "\n\n".join(lines)
                + f"\n\n**Старые общие роли (fallback):**\nВыдавать: {legacy_add}\nСнимать: {legacy_remove}"
            ),
            color=0x3498DB,
        )

    class RegTypeRolesModal(Modal):
        def __init__(self, parent_view, reg_type: str):
            self.parent_view = parent_view
            self.reg_type = reg_type
            cfg = reg_settings.setdefault("type_roles", {}).setdefault(reg_type, {"roles_add": [], "roles_remove": []})
            super().__init__(title=f"Роли: {type_label(reg_type)}", timeout=300)
            self.roles_add_input = TextInput(
                label="Выдаваемые роли",
                required=False,
                default=" ".join(f"<@&{rid}>" for rid in cfg.get("roles_add", [])) or "скип",
                max_length=1000,
            )
            self.roles_remove_input = TextInput(
                label="Снимаемые роли",
                required=False,
                default=" ".join(f"<@&{rid}>" for rid in cfg.get("roles_remove", [])) or "скип",
                max_length=1000,
            )
            self.add_item(self.roles_add_input)
            self.add_item(self.roles_remove_input)

        async def on_submit(self, interaction: Interaction):
            add_ids = await parse_roles_text(str(self.roles_add_input.value or ""))
            remove_ids = await parse_roles_text(str(self.roles_remove_input.value or ""))
            cfg = reg_settings.setdefault("type_roles", {}).setdefault(self.reg_type, {})
            cfg["roles_add"] = add_ids
            cfg["roles_remove"] = remove_ids
            save_reg_settings()
            self.parent_view.selected_type = self.reg_type
            await interaction.response.edit_message(embed=build_embed(self.reg_type), view=self.parent_view)

    class RegRolesTypeSelect(Select):
        def __init__(self, parent_view):
            self.parent_view = parent_view
            options = [
                SelectOption(label="Государство", value="country", emoji="🌍"),
                SelectOption(label="Регион", value="region", emoji="🏳️"),
                SelectOption(label="ЧВК", value="pmc", emoji="🛡️"),
                SelectOption(label="Повстанцы", value="rebels", emoji="🔥"),
                SelectOption(label="Организация", value="organization", emoji="🏢"),
            ]
            super().__init__(placeholder="Выберите вид регистрации", min_values=1, max_values=1, options=options)

        async def callback(self, interaction: Interaction):
            reg_type = self.values[0]
            await interaction.response.send_modal(RegTypeRolesModal(self.parent_view, reg_type))

    class RegRolesView(View):
        def __init__(self, author_id: int):
            super().__init__(timeout=300)
            self.author_id = author_id
            self.selected_type = None
            self.add_item(RegRolesTypeSelect(self))

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != self.author_id:
                await interaction.response.send_message("❌ Только автор команды может менять настройки.", ephemeral=True)
                return False
            return True

    await ctx.send(embed=build_embed(), view=RegRolesView(ctx.author.id))

@bot.command(name="вайпроли")
@admin_or_command_access()
async def вайпроли(ctx, *, roles_csv: str = None):
    async def parse_roles(raw_csv: str):
        role_ids = []
        for token in raw_csv.split(","):
            raw = token.strip()
            if not raw:
                continue
            try:
                role = await commands.RoleConverter().convert(ctx, raw)
                role_ids.append(str(role.id))
            except Exception:
                continue
        return list(dict.fromkeys(role_ids))

    def current_mentions():
        return [
            ctx.guild.get_role(int(rid)).mention
            for rid in reg_settings.get("wipe_roles", [])
            if str(rid).isdigit() and ctx.guild.get_role(int(rid))
        ]

    def current_exclusion_mentions():
        return [
            ctx.guild.get_role(int(rid)).mention
            for rid in reg_settings.get("wipe_role_exclusions", [])
            if str(rid).isdigit() and ctx.guild.get_role(int(rid))
        ]

    if roles_csv is not None:
        reg_settings["wipe_roles"] = await parse_roles(roles_csv)
        save_reg_settings()
        mentions = current_mentions()
        await ctx.send(
            embed=Embed(
                title="✅ Вайп-роли обновлены",
                description=(", ".join(mentions) if mentions else "Список пуст."),
                color=0x00FF00,
            )
        )
        return

    class WipeRolesView(View):
        def __init__(self, author_id: int):
            super().__init__(timeout=180)
            self.author_id = author_id

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != self.author_id:
                await interaction.response.send_message(
                    "❌ Только автор команды может менять настройки.", ephemeral=True
                )
                return False
            return True

        async def _wait_roles_message(self, interaction: Interaction):
            def check(m):
                return (
                    m.author.id == self.author_id
                    and m.channel.id == interaction.channel_id
                )

            try:
                return await bot.wait_for("message", check=check, timeout=180)
            except Exception:
                await interaction.followup.send(
                    "⏰ Время ожидания истекло.", ephemeral=True
                )
                return None

        @discord.ui.button(label="Обновить вайп-роли", style=ButtonStyle.danger)
        async def set_roles(self, interaction: Interaction, button: Button):
            await interaction.response.send_message(
                embed=Embed(
                    title="📝 Ввод ролей",
                    description="Укажите роли через запятую (упоминания).",
                    color=0x3498DB,
                ),
                ephemeral=True,
            )
            msg = await self._wait_roles_message(interaction)
            if not msg:
                return
            reg_settings["wipe_roles"] = await parse_roles(msg.content)
            save_reg_settings()
            mentions = current_mentions()
            await interaction.followup.send(
                embed=Embed(
                    title="✅ Вайп-роли обновлены",
                    description=(", ".join(mentions) if mentions else "Список пуст."),
                    color=0x00FF00,
                ),
                ephemeral=True,
            )

        @discord.ui.button(label="Исключения", style=ButtonStyle.primary)
        async def set_exclusions(self, interaction: Interaction, button: Button):
            await interaction.response.send_message(
                embed=Embed(
                    title="🛡️ Роли-исключения",
                    description="Укажите роли через запятую. Эти роли не будут сняты при !вайп.",
                    color=0x3498DB,
                ),
                ephemeral=True,
            )
            msg = await self._wait_roles_message(interaction)
            if not msg:
                return
            reg_settings["wipe_role_exclusions"] = await parse_roles(msg.content)
            save_reg_settings()
            mentions = current_exclusion_mentions()
            await interaction.followup.send(
                embed=Embed(
                    title="✅ Исключения обновлены",
                    description=(", ".join(mentions) if mentions else "Список пуст."),
                    color=0x00FF00,
                ),
                ephemeral=True,
            )

        @discord.ui.button(label="Очистить", style=ButtonStyle.secondary)
        async def clear_roles(self, interaction: Interaction, button: Button):
            reg_settings["wipe_roles"] = []
            reg_settings["wipe_role_exclusions"] = []
            save_reg_settings()
            await interaction.response.send_message(
                embed=Embed(
                    title="✅ Вайп-роли и исключения очищены",
                    description="Списки пусты.",
                    color=0x00FF00,
                ),
                ephemeral=True,
            )

    mentions = current_mentions()
    exclusion_mentions = current_exclusion_mentions()
    await ctx.send(
        embed=Embed(
            title="⚙️ Настройка !вайпроли",
            description=(
                f"**Снимать при вайпе:** {', '.join(mentions) if mentions else '—'}\n"
                f"**Исключения (не снимать):** {', '.join(exclusion_mentions) if exclusion_mentions else '—'}"
            ),
            color=0x3498DB,
        ),
        view=WipeRolesView(ctx.author.id),
    )


@bot.command(name="счастьестоп")
@admin_or_command_access()
async def счастьестоп(ctx, member: MemberQueryConverter, duration: str):
    try:
        secs = parse_interval(duration)
    except Exception as e:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Неверный формат времени: {e}",
                color=0xFF0000,
            )
        )
        return
    st = ensure_player_state(str(member.id))
    st["happiness_pause_until"] = max(
        int(st.get("happiness_pause_until", 0)), int(time.time()) + secs
    )
    save_player_state()
    await ctx.send(
        embed=Embed(
            title="✅ Счастье на паузе",
            description=f"Для {member.mention}: {format_interval(secs)}",
            color=0x00FF00,
        )
    )


@bot.command(name="счастьевыдать")
@admin_or_command_access()
async def счастьевыдать(ctx, member: MemberQueryConverter, amount: str):
    st = ensure_player_state(str(member.id))
    current = int(st.get("happiness", 50))
    try:
        if str(amount).strip().endswith("%"):
            val = int(str(amount).strip().replace("%", ""))
        else:
            val = int(float(amount))
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Введите число или процент (например `70` или `70%`).",
                color=0xFF0000,
            )
        )
        return
    st["happiness"] = max(0, min(100, val))
    save_player_state()
    await ctx.send(
        embed=Embed(
            title="✅ Счастье обновлено",
            description=f"{member.mention}: {current}% → {st['happiness']}%",
            color=0x00FF00,
        )
    )


def _parse_target_member(guild: discord.Guild, player_query: str):
    member = resolve_member_query(guild, player_query)
    if member:
        return member
    return parse_member_ref(guild, player_query)


