def build_mute_error_embed(title: str, details: str, payload: str = "") -> Embed:
    embed = Embed(title=title, color=0xFF0000)
    usage = "`!мут @игрок 4ч причина`\n`!мут 4ч причина` — ответом на сообщение"
    examples = "`!мут @User 30м флуд`\n`!мут @User 2ч оскорбления`\n`!мут @User 1д нарушение правил`"
    description = f"**Что не так:** {details}\n\n**Формат:**\n{usage}\n\n**Примеры:**\n{examples}"
    if payload:
        description += f"\n\n**Ваш ввод:** `{payload[:300]}`"
    embed.description = description
    return embed


@bot.command(name="мут")
@commands.has_permissions(moderate_members=True)
async def мут(ctx, *, payload: str = ""):
    member, duration, reason = await resolve_target_member_from_payload(ctx, payload)
    if not member:
        await ctx.send(embed=build_mute_error_embed("❌ Не удалось разобрать мут", "укажите участника или ответьте командой на его сообщение.", payload))
        return

    if not await ensure_punishment_hierarchy(ctx, member):
        return

    if duration:
        try:
            secs = parse_interval(duration)
        except Exception as e:
            await ctx.send(embed=build_mute_error_embed("❌ Неверный срок мута", f"{e}", payload))
            return
    else:
        secs = 28 * 24 * 3600

    until = discord.utils.utcnow() + __import__("datetime").timedelta(seconds=secs)
    try:
        await member.timeout(until, reason=f"{ctx.author}: {reason}")
    except Exception as e:
        await ctx.send(embed=build_mute_error_embed("❌ Discord отклонил мут", f"{e}", payload))
        return

    embed = Embed(title="🔇 Выдан мут", color=0xFFA500)
    embed.add_field(name="Нарушитель", value=member.mention, inline=False)
    embed.add_field(name="Срок", value=format_interval(secs), inline=True)
    embed.add_field(name="Причина", value=reason, inline=False)
    embed.add_field(name="Модератор", value=ctx.author.mention, inline=False)
    await ctx.send(embed=embed)
    await send_mod_log(ctx.guild, embed)


