async def perform_rp_warn_wipe(ctx, member: discord.Member, reason: str):
    user_id = str(member.id)
    population = load_json(POPULATION_FILE, {})
    prev_user = balances.get(user_id, {}) if isinstance(balances.get(user_id), dict) else {}
    balances[user_id] = {
        "наличка": 0,
        "банк": 0,
        "заморожено": 0,
        "коины": int(prev_user.get("коины", 0)),
    }
    inventory.pop(user_id, None)
    population.pop(user_id, None)
    passive_flows.setdefault("users", {}).pop(user_id, None)
    for season_map in seasons_data.setdefault("season_user_progress", {}).values():
        if isinstance(season_map, dict):
            season_map.pop(user_id, None)
    investments.setdefault("users", {}).pop(user_id, None)
    remove_active_investments_for_user(user_id)
    companies_data["companies"] = {
        cid: c for cid, c in companies_data.setdefault("companies", {}).items()
        if str(c.get("owner_id")) != user_id
    }
    remove_user_registration(user_id)
    remove_relations_for_subject(user_id)
    save_json(BALANCES_FILE, balances); save_inventory(); save_json(POPULATION_FILE, population)
    save_passive_flows(); save_seasons_data(); save_investments(); save_companies_data(); save_country_owners(); save_relations_data()
    try:
        await member.edit(nick=None, reason=reason)
    except Exception:
        pass


