@bot.command(name="рп-варн")
@admin_or_command_access()
async def рп_варн(ctx, member: MemberQueryConverter, *, reason: str):
    if member.bot:
        await ctx.send(embed=Embed(title="❌ Ошибка", description="Нельзя выдать RP-варн боту.", color=0xFF0000)); return
    season = current_rp_year_key()
    limit = int(moderation_data.setdefault("rp_warn_limit", {}).get("count", 4) or 4)
    warns_root = moderation_data.setdefault("rp_warns", {})
    season_warns = warns_root.setdefault(str(season), {}).setdefault(str(member.id), [])
    season_warns.append({"moderator": str(ctx.author.id), "reason": reason, "ts": int(time.time())})
    count = len(season_warns)
    auto_wiped = False
    if limit > 0 and count >= limit:
        await perform_rp_warn_wipe(ctx, member, f"Авто-вайп по RP-варнам: {reason}")
        season_warns.clear()
        count = 0
        auto_wiped = True
    save_moderation_data()
    embed = Embed(title="⚠️ Выдан RP-варн", color=0xFFD966)
    embed.add_field(name="Игрок", value=member.mention, inline=False)
    embed.add_field(name="RP-год/вайп", value=str(season), inline=True)
    embed.add_field(name="Варнов", value=f"{count}/{limit}", inline=True)
    embed.add_field(name="Причина", value=reason, inline=False)
    embed.add_field(name="Модератор", value=ctx.author.mention, inline=False)
    if auto_wiped:
        embed.add_field(name="Автодействие", value="Выполнен `анрег`.", inline=False)
    await ctx.send(embed=embed)
    await send_mod_log(ctx.guild, embed)


