@bot.command(name="наказания")
@commands.has_permissions(moderate_members=True)
async def наказания(ctx):
    now_dt = discord.utils.utcnow()

    muted_lines = []
    for m in ctx.guild.members:
        end_dt = getattr(m, "timed_out_until", None) or getattr(
            m, "communication_disabled_until", None
        )
        if end_dt and end_dt > now_dt:
            left = int((end_dt - now_dt).total_seconds())
            muted_lines.append(f"• {m.mention} — ещё {format_seconds_left(left)}")

    warn_limit = int(moderation_data.get("warn_limit", {}).get("count", 3))
    warn_lines = []
    for uid, entries in moderation_data.get("warns", {}).items():
        if not entries:
            continue
        member = ctx.guild.get_member(int(uid))
        label = member.mention if member else f"<@{uid}>"
        count = len(entries)
        left_to_limit = warn_limit - (count % warn_limit) if warn_limit > 0 else 0
        if left_to_limit == 0 and warn_limit > 0:
            left_to_limit = warn_limit
        warn_lines.append(
            f"• {label} — варнов: **{count}**, до наказания: **{left_to_limit}**"
        )

    desc = ""
    desc += "**Активные муты:**\n" + ("\n".join(muted_lines) if muted_lines else "нет")
    desc += "\n\n**Варны:**\n" + ("\n".join(warn_lines) if warn_lines else "нет")

    await ctx.send(
        embed=Embed(title="📋 Активные наказания", description=desc, color=0x3498DB)
    )


# ================== ROLE INCOME ==================
@bot.command()
async def коллект(ctx):
    user_id = str(ctx.author.id)
    user = ensure_user(user_id)

    now = int(time.time())
    total_earned = 0
    collected_roles = []  # list[tuple[str, int]]
    cooldown_wait = []
    has_manual_income_role = False

    for rid, data in role_income.get("roles", {}).items():
        if data.get("auto", True):
            continue

        role = ctx.guild.get_role(int(rid))
        if not role or role not in ctx.author.roles:
            continue

        has_manual_income_role = True
        cooldown = int(data.get("cooldown", 0))
        last = role_income.get("last_claim", {}).get(user_id, {}).get(rid, 0)
        elapsed = now - last
        if elapsed < cooldown:
            cooldown_wait.append((role.mention, cooldown - elapsed))
            continue

        mode = str(data.get("mode", "manual")).lower()
        if mode == "accumulative":
            cycles = elapsed // max(1, cooldown)
            limit_cfg = data.get("accum_limit", {}) or {}
            limit_type = str(limit_cfg.get("type", "none")).lower()
            limit_value = int(limit_cfg.get("value", 0) or 0)
            if limit_type == "cycles" and limit_value > 0:
                cycles = min(cycles, limit_value)
            elif limit_type == "time" and limit_value > 0 and cooldown > 0:
                cycles = min(cycles, max(1, limit_value // cooldown))
            amount = compute_accumulative_income(data, max(0, user["наличка"] + user.get("банк", 0) - user.get("заморожено", 0)), int(cycles))
        else:
            try:
                amount = parse_money_value(str(data.get("amount", 0)), max(0, user["наличка"] + user.get("банк", 0) - user.get("заморожено", 0)))
            except Exception:
                amount = 0

        total_earned += amount
        collected_roles.append((role.mention, amount))
        role_income.setdefault("last_claim", {}).setdefault(user_id, {})[rid] = now

    gross_income_pool = max(0, total_earned)
    frozen_added, freeze_lines, _ = apply_freeze_roles_for_member(
        ctx.guild, ctx.author, now, gross_income_pool
    )
    final_cash_delta = total_earned - frozen_added
    user["наличка"] += final_cash_delta

    save_json(BALANCES_FILE, balances)
    save_json(ROLE_INCOME_FILE, role_income)

    if not collected_roles and not freeze_lines:
        if cooldown_wait:
            wait_lines = "\n".join(
                f"• {role_mention}: можно собрать в {cooldown_ready_time(now, left)}"
                for role_mention, left in cooldown_wait
            )
            await ctx.send(
                embed=Embed(
                    title="⏳ Коллект на кулдауне",
                    description=f"{ctx.author.mention}, доход временно недоступен.\n\nСледующий сбор:\n{wait_lines}",
                    color=0xFFAA00,
                )
            )
            return

        if has_manual_income_role:
            await ctx.send(
                embed=Embed(
                    title="⚠️ Доход не начислен",
                    description=f"{ctx.author.mention}, роли найдены, но сумма начисления сейчас равна 0. Проверьте настройку дохода роли.",
                    color=0xFFAA00,
                )
            )
            return

        await ctx.send(
            embed=Embed(
                title="💤 Нечего собирать",
                description=(
                    f"{ctx.author.mention}, у вас нет ролей с ручным доходом для `!коллект`.\n\n"
                    "Как получить роль для дохода, смотрите в https://discord.com/channels/1029776124915490928/1531806142148120606 в разделе экономики."
                ),
                color=0xFF0000,
            )
        )
        return

    role_lines = "\n\n".join(
        f"• **{name}** — {fmt_money(amount)}" for name, amount in collected_roles
    )
    desc = f"{ctx.author.mention}, итог по коллекту: **{final_cash_delta:+,} {currency}**.\n\n**Роли с доходом:**\n{role_lines}".replace(
        ",", "."
    )
    if freeze_lines:
        desc += f"\n\n**Заморозка средств:**\n" + "\n".join(freeze_lines)
        desc += f"\n\nИтого заморожено: **{fmt_money(frozen_added)}**"

    await ctx.send(
        embed=Embed(title="💰 Коллект выполнен", description=desc, color=0x00FF00)
    )
    await log_economy_change(
        ctx.guild,
        ctx.author.id,
        "Коллект",
        cash_delta=final_cash_delta,
        frozen_delta=frozen_added,
    )


@bot.command(name="список-доходов", aliases=["доходсписок"])
async def список_доходов(ctx):
    def income_entries_for(mode_filter: str):
        entries = []
        for rid, data in role_income.setdefault("roles", {}).items():
            role = ctx.guild.get_role(int(rid)) if ctx.guild else None
            if not role:
                continue
            mode = str(data.get("mode", "auto" if data.get("auto", True) else "manual")).lower()
            if mode_filter != "all" and mode != mode_filter:
                continue
            raw_amount = str(data.get("amount", 0)).strip()
            amount_view = raw_amount if raw_amount.endswith("%") else format_money_like_text(raw_amount)
            cooldown_view = format_interval(int(data.get("cooldown", 0) or 0))
            mode_label = {"auto": "автоколлект", "manual": "обычный", "accumulative": "накопительный"}.get(mode, mode)
            lines = [
                f"**{role.name}**",
                f"-# **Роль:** {role.mention}",
                f"-# **Доход:** {amount_view}",
                f"-# **Кулдаун:** {cooldown_view}",
                f"-# **Режим:** {mode_label}",
            ]
            if mode == "accumulative":
                limit_cfg = data.get("accum_limit", {}) or {}
                lt = str(limit_cfg.get("type", "none")).lower()
                lv = int(limit_cfg.get("value", 0) or 0)
                limit_text = format_interval(lv) if lt == "time" and lv > 0 else (f"{lv} проп." if lt == "cycles" and lv > 0 else "без лимита")
                lines.append(f"-# **Лимит:** {limit_text}")
                lines.append(f"-# **Срез:** {fmt_money(int(data.get('accum_cut', 0) or 0))}")
            entries.append("\n".join(lines))
        if mode_filter in {"all", "freeze"}:
            for rid, data in role_income.setdefault("freeze_roles", {}).items():
                role = ctx.guild.get_role(int(rid)) if ctx.guild else None
                if not role:
                    continue
                raw_value = str(data.get("value", 0)).strip()
                value_view = raw_value if raw_value.endswith("%") else format_money_like_text(raw_value)
                entries.append("\n".join([
                    f"**🧊 {role.name}**",
                    f"-# **Роль:** {role.mention}",
                    f"-# **Доход:** заморозка {value_view}",
                    f"-# **Кулдаун:** {format_interval(int(data.get('cooldown', 0) or 0))}",
                    "-# **Режим:** заморозка",
                ]))
        return entries

    mode_labels = {
        "all": "Все доходы", "auto": "Автоколлект", "manual": "Обычные", "accumulative": "Накопительные", "freeze": "Заморозка",
    }

    def build_income_view(selected_mode: str = "all"):
        entries = income_entries_for(selected_mode)
        view = LayoutViewBase(timeout=300) if shop_supports_components_v2() else View(timeout=300)
        if shop_supports_components_v2():
            container = V2Container()
            container.add_item(V2TextDisplay(f"## 💰 {mode_labels.get(selected_mode, 'Доходы ролей')}"))
            if not entries:
                container.add_item(V2TextDisplay("Список доходов пуст."))
            for idx, block in enumerate(entries[:12]):
                if idx > 0:
                    container.add_item(V2Separator())
                container.add_item(V2TextDisplay(block))
            view.add_item(container)
        class IncomeModeSelect(Select):
            def __init__(self):
                super().__init__(placeholder="Выберите режим доходов", min_values=1, max_values=1, options=[
                    SelectOption(label=label, value=value, default=value == selected_mode)
                    for value, label in mode_labels.items()
                ])
            async def callback(self, interaction: Interaction):
                await interaction.response.edit_message(content=None if shop_supports_components_v2() else build_income_text(self.values[0]), view=build_income_view(self.values[0]))
        if shop_supports_components_v2():
            row = V2ActionRow(); row.add_item(IncomeModeSelect()); view.add_item(row)
        else:
            view.add_item(IncomeModeSelect())
        return view

    def build_income_text(selected_mode: str = "all"):
        entries = income_entries_for(selected_mode)
        return f"💰 **{mode_labels.get(selected_mode, 'Доходы ролей')}**\n" + ("\n\n".join(entries) if entries else "Список доходов пуст.")

    await ctx.send(content=None if shop_supports_components_v2() else build_income_text("all"), view=build_income_view("all"))


