class TopView(View):
    def __init__(self, mode: str = "economy"):
        super().__init__(timeout=180)
        self.mode = mode
        self.page = 0
        self.mode_select = TopModeSelect(self)
        self.add_item(self.mode_select)

    def _dataset(self):
        if self.mode == "population":
            pop = load_json(POPULATION_FILE, {})
            return (
                sorted(
                    ((uid, int(pop.get(uid, 0))) for uid in pop.keys() if is_registered_country_user(uid)),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:einwohner:1543381695888101427> Топ по населению",
            )
        if self.mode == "army":
            users = player_state.get("users", {})
            return (
                sorted(
                    (
                        (uid, int((users.get(uid) or {}).get("soldiers", 0)))
                        for uid in users.keys() if is_registered_country_user(uid)
                    ),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:soldat:1543381492359630868> Топ по армии",
            )
        if self.mode == "posts":
            users = player_state.get("users", {})
            return (
                sorted(
                    (
                        (uid, int((users.get(uid) or {}).get("posts_count", 0)))
                        for uid in users.keys() if is_registered_country_user(uid)
                    ),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:nachricten:1543381584521072830> Топ по постам",
            )
        if self.mode == "reputation":
            users = player_state.get("users", {})
            return (
                sorted(
                    (
                        (uid, int((users.get(uid) or {}).get("reputation", 0)))
                        for uid in users.keys() if is_registered_country_user(uid)
                    ),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:stern:1543296488019595295> Топ по репутации (%)",
            )
        if self.mode == "science":
            users = player_state.get("users", {})
            return (
                sorted(
                    (
                        (uid, int((users.get(uid) or {}).get("science", 0)))
                        for uid in users.keys() if is_registered_country_user(uid)
                    ),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:wissenschaft:1543381799785468118> Топ по науке",
            )
        if self.mode == "happiness":
            users = player_state.get("users", {})
            return (
                sorted(
                    (
                        (uid, int((users.get(uid) or {}).get("happiness", 0)))
                        for uid in users.keys() if is_registered_country_user(uid)
                    ),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:lustig:1543381984695296020> Топ по счастью (%)",
            )
        if self.mode == "news_streak":
            users = player_state.get("users", {})
            return (
                sorted(
                    ((uid, int((users.get(uid) or {}).get("news_streak", 0))) for uid in users.keys() if is_registered_country_user(uid)),
                    key=lambda x: x[1],
                    reverse=True,
                ),
                "<:feuer:1543301108137730199> Топ по стрикам",
            )
        if self.mode.startswith("admin_"):
            key = self.mode.replace("admin_", "", 1)
            if key == "rating":
                rows = []
                for uid, votes in ratings_data.setdefault("votes", {}).items():
                    if not isinstance(votes, list) or not votes:
                        continue
                    scores = [int(v.get("score", 0)) for v in votes if isinstance(v, dict)]
                    if scores:
                        rows.append((str(uid), round(sum(scores) / len(scores), 2), len(scores)))
                rows.sort(key=lambda x: (x[1], x[2]), reverse=True)
                return rows, "<:stern:1543296488019595295> Админтоп: оценки"
            rows = []
            for uid in player_state.get("users", {}).keys():
                counters = get_admin_counters(uid)
                val = sum(int(counters.get(k, 0)) for k in ADMIN_COUNTER_LABELS) if key == "total" else int(counters.get(key, 0))
                if val:
                    rows.append((uid, val))
            rows.sort(key=lambda x: x[1], reverse=True)
            title = "<:schild:1543382091067162694> Админтоп: всего действий" if key == "total" else f"<:schild:1543382091067162694> Админтоп: {ADMIN_COUNTER_LABELS.get(key, key)}"
            return rows, title
        if self.mode == "companies_price":
            companies = []
            for company in companies_data.setdefault("companies", {}).values():
                update_company_derived_fields(company)
                companies.append((
                    str(company.get("name") or "Без названия"),
                    int(company_estimated_price(company)),
                    str(company.get("owner_id") or "0"),
                ))
            companies.sort(key=lambda x: x[1], reverse=True)
            return companies, "🏢 Топ компаний по цене"
        data = []
        for uid, user in balances.items():
            if uid == "валюта" or not isinstance(user, dict) or not is_registered_country_user(uid):
                continue
            available_total = (
                int(user.get("наличка", 0))
                - int(user.get("заморожено", 0))
                + int(user.get("банк", 0))
            )
            data.append((uid, available_total))
        return sorted(data, key=lambda x: x[1], reverse=True), "<:kaution:1543269330592989185> Топ по экономике"

    def build_embed(self):
        data, title = self._dataset()
        if not data:
            return Embed(title=title, description="Список пуст.", color=0x3498DB)
        pages = [data[i : i + 10] for i in range(0, len(data), 10)]
        self.page = max(0, min(self.page, len(pages) - 1))
        chunk = pages[self.page]
        desc = ""
        start = self.page * 10 + 1
        for idx, row in enumerate(chunk, start=start):
            if self.mode == "companies_price":
                company_name, val, owner_id = row
                desc += f"{idx}. **{company_name}** — {fmt_num(val)} {currency} (владелец: <@{owner_id}>)\n"
            elif self.mode == "admin_rating":
                uid, avg, count = row
                desc += f"{idx}. <@{uid}> — {avg:.2f}/10 ({count} оценок)\n"
            else:
                uid, val = row
                suffix = currency if self.mode == "economy" else ""
                desc += f"{idx}. <@{uid}> — {fmt_num(val)} {suffix}\n".rstrip() + "\n"
        em = Embed(title=title, description=desc, color=0x3498DB)
        em.set_footer(text=f"Страница {self.page + 1}/{len(pages)}")

        mode_map = {
            "economy": "Топ по экономике",
            "population": "Топ по населению",
            "army": "Топ по армии",
            "posts": "Топ по постам",
            "reputation": "Топ по репутации",
            "science": "Топ по науке",
            "happiness": "Топ по счастью",
            "news_streak": "Топ по стрикам",
        }
        current = mode_map.get(self.mode, "")
        for option in self.mode_select.options:
            option.default = option.label == current

        return em

    async def refresh(self, interaction: Interaction):
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.gray)
    async def back(self, interaction: Interaction, button: Button):
        self.page -= 1
        await self.refresh(interaction)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.gray)
    async def forward(self, interaction: Interaction, button: Button):
        self.page += 1
        await self.refresh(interaction)


