class AdminRatingCommentsView(LayoutViewBase if container_components_available() else View):
    def __init__(self, target_id: str, guild: discord.Guild | None, page: int = 0):
        super().__init__(timeout=180)
        self.target_id = str(target_id)
        self.guild = guild
        self.votes = list(ratings_data.setdefault("votes", {}).get(self.target_id, []))
        self.page = max(0, min(page, max(0, len(self.votes) - 1)))
        if container_components_available():
            add_v2_text_blocks(self, self.build_blocks())

    def build_blocks(self):
        target = self.guild.get_member(int(self.target_id)) if self.guild and self.target_id.isdigit() else None
        title = f"## <:nachricht:1543297085892206734> Комментарии оценок — {target.display_name if target else f'ID {self.target_id}'}"
        total = max(1, len(self.votes))
        if not self.votes:
            return [title, "Оценок и комментариев пока нет.", "-# Страница 1/1"]
        vote = self.votes[self.page]
        voter_id = str(vote.get("from", "0"))
        voter = self.guild.get_member(int(voter_id)) if self.guild and voter_id.isdigit() else None
        voter_label = voter.mention if voter else f"<@{voter_id}>"
        return [
            title,
            "\n".join([
                f"**От:** {voter_label}",
                f"-# **Оценка:** {int(vote.get('score', 0) or 0)}/10",
                f"-# **Назначение:** {vote.get('role_text') or '—'}",
                f"-# **Комментарий:** {vote.get('comment') or '—'}",
            ]),
            f"-# Страница {self.page + 1}/{total}",
        ]

    def build_content(self):
        return "\n\n".join(self.build_blocks())

    async def refresh(self, interaction: Interaction):
        view = AdminRatingCommentsView(self.target_id, interaction.guild, self.page)
        if container_components_available():
            add_v2_action_rows(view)
            await interaction.response.edit_message(content=None, embed=None, view=view)
        else:
            await interaction.response.edit_message(content=view.build_content(), embed=None, view=view)

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.gray)
    async def back(self, interaction: Interaction, button: Button):
        self.page = (self.page - 1) % max(1, len(self.votes))
        await self.refresh(interaction)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.gray)
    async def forward(self, interaction: Interaction, button: Button):
        self.page = (self.page + 1) % max(1, len(self.votes))
        await self.refresh(interaction)


