class AdminTopView(LayoutViewBase if container_components_available() else View):
    def __init__(self, mode: str = "admin_total", page: int = 0, guild: discord.Guild | None = None):
        super().__init__(timeout=180)
        self.mode = mode
        self.page = page
        self.guild = guild
        if container_components_available():
            add_v2_text_blocks(self, self.build_blocks())
        self.add_item(AdminTopModeSelect(self))
        self.add_item(AdminRatingCommentsSelect(self, guild))
        add_v2_action_rows(self)

    def _dataset(self):
        return TopView._dataset(self)

    def build_blocks(self):
        data, title = self._dataset()
        if not data:
            return [f"## {title}", "Список пуст."]
        pages = [data[i : i + 10] for i in range(0, len(data), 10)]
        self.page = max(0, min(self.page, len(pages) - 1))
        chunk = pages[self.page]
        start = self.page * 10 + 1
        lines = []
        for idx, row in enumerate(chunk, start=start):
            if self.mode == "admin_rating":
                uid, avg, count = row
                lines.append(f"{idx}. <@{uid}> — {avg:.2f}/10 ({count} оценок)")
            else:
                uid, val = row
                lines.append(f"{idx}. <@{uid}> — {fmt_num(val)}")
        return [f"## {title}", "\n".join(lines), f"-# Страница {self.page + 1}/{len(pages)}"]

    def build_content(self):
        return "\n\n".join(self.build_blocks())

    async def refresh(self, interaction: Interaction):
        view = AdminTopView(mode=self.mode, page=self.page, guild=interaction.guild)
        await interaction.response.edit_message(
            content=None if container_components_available() else view.build_content(),
            embed=None,
            view=view,
        )

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.gray)
    async def back(self, interaction: Interaction, button: Button):
        self.page -= 1
        await self.refresh(interaction)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.gray)
    async def forward(self, interaction: Interaction, button: Button):
        self.page += 1
        await self.refresh(interaction)


