@bot.command(name="постыочистить")
@admin_or_command_access()
async def постыочистить(ctx):
    users = player_state.setdefault("users", {})
    changed = 0
    for st in users.values():
        if int(st.get("posts_count", 0)) != 0:
            changed += 1
        st["posts_count"] = 0

    save_player_state()
    cleared_countries, cleared_users = clear_all_registrations()
    await ctx.send(
        embed=Embed(
            title="✅ Счётчик постов очищен",
            description=(
                f"Обнулён счётчик постов у **{changed}** участников.\n"
                f"Также очищены регистрации **{cleared_countries}** занятых стран у **{cleared_users}** игроков"
                " (включая тех, кто уже вышел с сервера). Роли не трогались, сообщения не удалялись."
            ),
            color=0x00FF00,
        )
    )


@bot.command()
@admin_or_command_access()
async def начислить(ctx, member: MemberQueryConverter, amount: str):
    user = ensure_user(str(member.id))
    try:
        amount_value = parse_money_value(amount, user["наличка"])
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Введите число или процент (например `500` или `10%`).",
                color=0xFF0000,
            )
        )
        return

    if amount_value <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Сумма должна быть больше 0.",
                color=0xFF0000,
            )
        )
        return

    user["наличка"] += amount_value
    save_json(BALANCES_FILE, balances)

    await ctx.send(
        embed=Embed(
            title="✅ Деньги начислены",
            description=f"{ctx.author.mention} начислил **{fmt_money(amount_value)}** {member.mention}!",
            color=0x00FF00,
        )
    )
    await log_economy_change(
        ctx.guild,
        member.id,
        f"Начисление админом {ctx.author}",
        cash_delta=amount_value,
    )


