@bot.command(name="продать", aliases=["продатьпредмет"])
async def продать(
    ctx, member: discord.Member, количество: int, item_key: str, предложенная_цена: str
):
    if member.id == ctx.author.id:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Нельзя продавать предметы самому себе.",
                color=0xFF0000,
            )
        )
        return
    if количество <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Количество должно быть больше 0.",
                color=0xFF0000,
            )
        )
        return

    sell_role_id = settings.get("sell_role_id")
    if sell_role_id and not any(r.id == int(sell_role_id) for r in ctx.author.roles):
        role = ctx.guild.get_role(int(sell_role_id))
        role_text = role.mention if role else "специальной роли"
        await ctx.send(
            embed=Embed(
                title="⛔ Недостаточно прав",
                description=f"Для использования **!продать** нужна роль {role_text}.",
                color=0xFF0000,
            )
        )
        return

    matches = resolve_item_key(item_key)
    if not matches:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка", description="Предмет не найден.", color=0xFF0000
            )
        )
        return

    selected_key = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:50]))
        await ctx.send(
            embed=Embed(
                title="🔎 Уточнение предмета",
                description=f"Найдено несколько совпадений. Выберите номер:\n\n{options}",
                color=0x3498DB,
            )
        )

        def choice_check(m):
            return m.author == ctx.author and m.channel == ctx.channel

        try:
            msg = await bot.wait_for("message", check=choice_check, timeout=60)
            idx = int(msg.content.strip()) - 1
            if idx < 0 or idx >= min(len(matches), 50):
                raise ValueError
            selected_key = matches[idx]
        except Exception:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Неверный выбор предмета.",
                    color=0xFF0000,
                )
            )
            return

    seller_id = str(ctx.author.id)
    buyer_id = str(member.id)
    seller_items = inventory.get(seller_id, {})
    if seller_items.get(selected_key, 0) < количество:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"У вас недостаточно предметов **{selected_key}**.",
                color=0xFF0000,
            )
        )
        return

    try:
        price_value = parse_money_value(
            предложенная_цена, ensure_user(buyer_id).get("наличка", 0)
        )
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Цена должна быть числом или процентом.",
                color=0xFF0000,
            )
        )
        return

    if price_value <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Цена должна быть больше 0.",
                color=0xFF0000,
            )
        )
        return

    if ensure_user(buyer_id).get("наличка", 0) < price_value:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"У покупателя недостаточно налички для сделки (**{fmt_money(price_value)}**).",
                color=0xFF0000,
            )
        )
        return

    class TradeOfferView(View):
        def __init__(self):
            super().__init__(timeout=300)
            self._seller_notified = False

        async def notify_seller(self, accepted: bool, extra_text: str | None = None):
            if self._seller_notified:
                return
            self._seller_notified = True
            title = "✅ Ваше предложение принято" if accepted else "❌ Ваше предложение не принято"
            description = (
                f"Покупатель: {member.mention}\n"
                f"Предмет: **{selected_key} × {количество}**\n"
                f"Цена: **{fmt_money(price_value)}**"
            )
            if extra_text:
                description += f"\n\n{extra_text}"
            seller_notice = Embed(title=title, description=description, color=0x00FF00 if accepted else 0xFF0000)
            try:
                await ctx.author.send(content=ctx.author.mention, embed=seller_notice)
            except Exception:
                pass

        async def on_timeout(self):
            await self.notify_seller(
                accepted=False,
                extra_text="Покупатель не ответил на предложение вовремя.",
            )

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != member.id:
                await interaction.response.send_message(
                    "❌ Только покупатель может ответить на эту сделку.", ephemeral=True
                )
                return False
            return True

        @discord.ui.button(label="✅ Принять", style=ButtonStyle.success)
        async def accept(self, interaction: Interaction, button: Button):
            seller_balance = ensure_user(seller_id)
            buyer_balance = ensure_user(buyer_id)
            seller_inv = inventory.get(seller_id, {})
            if seller_inv.get(selected_key, 0) < количество:
                await self.notify_seller(
                    accepted=False,
                    extra_text="Сделка отменена: у вас больше нет нужного количества предметов.",
                )
                await interaction.response.edit_message(
                    embed=Embed(
                        title="❌ Сделка отменена",
                        description="У продавца больше нет нужного количества предметов.",
                        color=0xFF0000,
                    ),
                    view=None,
                )
                self.stop()
                return
            if buyer_balance.get("наличка", 0) < price_value:
                await self.notify_seller(
                    accepted=False,
                    extra_text="Сделка отменена: у покупателя уже недостаточно налички.",
                )
                await interaction.response.edit_message(
                    embed=Embed(
                        title="❌ Сделка отменена",
                        description="У покупателя больше недостаточно налички.",
                        color=0xFF0000,
                    ),
                    view=None,
                )
                self.stop()
                return

            seller_inv[selected_key] -= количество
            if seller_inv[selected_key] <= 0:
                del seller_inv[selected_key]
            inventory.setdefault(buyer_id, {})
            inventory[buyer_id][selected_key] = (
                inventory[buyer_id].get(selected_key, 0) + количество
            )

            buyer_balance["наличка"] -= price_value
            seller_balance["наличка"] += price_value

            save_inventory()
            save_json(BALANCES_FILE, balances)

            done = Embed(title="✅ Сделка проведена", color=0x00FF00)
            done.add_field(name="Продавец", value=ctx.author.mention, inline=True)
            done.add_field(name="Покупатель", value=member.mention, inline=True)
            done.add_field(
                name="Предмет", value=f"{selected_key} × {количество}", inline=False
            )
            done.add_field(name="Цена", value=fmt_money(price_value), inline=False)
            await interaction.response.edit_message(embed=done, view=None)
            await self.notify_seller(accepted=True)
            await log_economy_change(
                ctx.guild,
                member.id,
                f"Покупка у {ctx.author}: {selected_key} x{количество}",
                cash_delta=-price_value,
            )
            await log_economy_change(
                ctx.guild,
                ctx.author.id,
                f"Продажа {member}: {selected_key} x{количество}",
                cash_delta=price_value,
            )
            self.stop()

        @discord.ui.button(label="❌ Отклонить", style=ButtonStyle.danger)
        async def decline(self, interaction: Interaction, button: Button):
            await self.notify_seller(
                accepted=False,
                extra_text="Покупатель вручную отклонил предложение.",
            )
            await interaction.response.edit_message(
                embed=Embed(
                    title="❌ Сделка отклонена",
                    description=f"{member.mention} отклонил предложение.",
                    color=0xFF0000,
                ),
                view=None,
            )
            self.stop()

    offer = Embed(title="💼 Предложение сделки", color=0x3498DB)
    offer.description = (
        f"{ctx.author.mention} предлагает продать вам предмет.\n\n"
        f"**Предмет:** {selected_key}\n"
        f"**Количество:** {количество}\n"
        f"**Цена:** {fmt_money(price_value)}"
    )
    offer.set_footer(text="Нажмите кнопку ниже: принять или отклонить.")
    try:
        await member.send(embed=offer, view=TradeOfferView())
    except (discord.Forbidden, discord.HTTPException):
        fallback = Embed(
            title="💼 Предложение сделки",
            description=(
                f"{member.mention}, {ctx.author.mention} предлагает купить предмет прямо здесь.\n\n"
                f"**Предмет:** {selected_key}\n"
                f"**Количество:** {количество}\n"
                f"**Цена:** {fmt_money(price_value)}\n\n"
                "Кнопки ниже доступны только покупателю."
            ),
            color=0x3498DB,
        )
        fallback.set_footer(text="ЛС закрыты или недоступны — предложение перенесено в этот чат.")
        await ctx.send(
            content=member.mention,
            embed=fallback,
            view=TradeOfferView(),
            allowed_mentions=discord.AllowedMentions(users=True, roles=False, everyone=False),
        )
        return

    await ctx.send(
        embed=Embed(
            title="📨 Предложение отправлено",
            description=f"Предложение продажи отправлено в ЛС пользователю {member.mention}.",
            color=0x00FF00,
        )
    )


@tasks.loop(seconds=60)
async def auto_role_income_loop():
    now = int(time.time())
    for guild in bot.guilds:
        if guild.id != ALLOWED_GUILD:
            print(
                f"[AUTO_LOOP] Пропуск guild={guild.id}: не совпадает с ALLOWED_GUILD={ALLOWED_GUILD}"
            )
            continue

        try:
            await sync_guild_economy_roles(guild)
        except Exception as e:
            print(f"[AUTO_LOOP] sync_guild_economy_roles failed: {e}")

        channel_id = settings.get("autocollect_channel")
        channel = guild.get_channel(channel_id) if channel_id else None
        me = guild.me or guild.get_member(bot.user.id)

        if me is None:
            print(f"[AUTO_LOOP] Пропуск guild={guild.id}: не удалось получить бота как member")
            continue

        if not channel or not channel.permissions_for(me).send_messages:
            channel = next(
                (c for c in guild.text_channels if c.permissions_for(me).send_messages),
                None,
            )
        if not channel:
            print(f"[AUTO_LOOP] Автоколлект без публичного уведомления: нет доступного канала для отправки")

        for member in guild.members:
            user_id = str(member.id)
            if should_skip_afk_user(user_id, now):
                continue
            ensure_user(user_id)
            total_earned = 0
            roles_earned = []

            for rid, data in role_income.get("roles", {}).items():
                try:
                    role = guild.get_role(int(rid))
                except (TypeError, ValueError):
                    print(f"[AUTO_LOOP] Некорректный role_id в role_income: rid={rid!r}")
                    continue
                if not role or role not in member.roles or not data.get("auto", True):
                    continue

                last_map = role_income.setdefault("last_claim", {}).setdefault(
                    user_id, {}
                )
                try:
                    cooldown = max(1, int(data.get("cooldown", 1)))
                except (TypeError, ValueError):
                    print(
                        f"[AUTO_LOOP] Некорректный cooldown в role_income: rid={rid} value={data.get('cooldown')!r}"
                    )
                    continue
                if rid not in last_map:
                    # Первое автоначисление: не ждём полный кулдаун.
                    # Do not log this per user/role: large guilds turn it into
                    # a noisy console flood on every fresh role assignment.
                    last_map[rid] = now - cooldown
                last = int(last_map.get(rid, now))

                if now - last >= cooldown:
                    try:
                        amount = parse_money_value(
                            str(data["amount"]), max(0, ensure_user(user_id)["наличка"] + ensure_user(user_id).get("банк", 0) - ensure_user(user_id).get("заморожено", 0))
                        )
                    except Exception:
                        amount = 0
                    last_map[rid] = now
                    add_balance(user_id, amount)
                    total_earned += amount
                    roles_earned.append(role.name)

            if total_earned != 0:
                save_json(ROLE_INCOME_FILE, role_income)
                desc = f"{member.mention} итог по ролям: **{total_earned:+} {currency}**\nРоли: {', '.join(roles_earned) if roles_earned else 'нет'}"
                if channel:
                    await channel.send(
                        embed=Embed(
                            title="💰 Автоколлект!",
                            description=desc,
                            color=0x00FF00,
                        )
                    )
                await log_economy_change(
                    guild,
                    member.id,
                    "Автоколлект (роли)",
                    cash_delta=total_earned,
                )

        # Пассивные доходы/расходы от куратора
        users_flows = passive_flows.setdefault("users", {})
        changed = False
        now_ts = int(time.time())
        for user_id, entries in users_flows.items():
            if should_skip_afk_user(user_id, now_ts):
                continue
            if not isinstance(entries, list):
                continue
            user = ensure_user(user_id)
            for entry in list(entries):
                try:
                    expires_at = entry.get("expires_at")
                    if expires_at is not None and now_ts >= int(expires_at):
                        entries.remove(entry)
                        changed = True
                        continue

                    cooldown = int(entry.get("cooldown", 0) or 0)
                    amount_raw = str(entry.get("amount", 0))
                    if cooldown <= 0:
                        continue
                    if "last_run" not in entry:
                        last_ts = int(entry.get("last_ts", 0) or 0)
                        entry["last_run"] = last_ts if last_ts > 0 else now_ts
                        entry.pop("last_ts", None)
                        changed = True
                        continue
                    last_run = int(entry.get("last_run", now_ts) or now_ts)
                    if last_run > now_ts:
                        entry["last_run"] = now_ts
                        changed = True
                        continue
                except (TypeError, ValueError):
                    print(f"[AUTO_LOOP] Некорректная пассивная операция: user={user_id} entry={entry!r}")
                    continue
                if now_ts - last_run < cooldown:
                    continue

                cycles = (now_ts - last_run) // cooldown
                try:
                    per_cycle = parse_money_value(amount_raw, user.get("наличка", 0))
                except Exception:
                    per_cycle = 0
                if per_cycle <= 0:
                    entry["last_run"] = last_run + cycles * cooldown
                    changed = True
                    continue

                delta = per_cycle * cycles
                if entry.get("type") == "expense":
                    user["наличка"] -= delta
                    delta = -delta
                else:
                    user["наличка"] += delta

                entry["last_run"] = last_run + cycles * cooldown
                changed = True
                await log_economy_change(
                    guild,
                    user_id,
                    f"Автопассив ({'расход' if entry.get('type') == 'expense' else 'доход'}): {entry.get('description', 'без описания')}",
                    cash_delta=int(delta),
                )

        # Пассивные изменения счастья/репутации из вердиктов и ручных настроек
        state_changed = False
        for user_id, st in player_state.setdefault("users", {}).items():
            if should_skip_afk_user(user_id, now_ts):
                continue
            entries = st.setdefault("stat_passives", [])
            if not isinstance(entries, list):
                continue
            for entry in list(entries):
                try:
                    expires_at = entry.get("expires_at")
                    if expires_at is not None and now_ts >= int(expires_at):
                        entries.remove(entry)
                        state_changed = True
                        continue

                    cooldown = int(entry.get("cooldown", 0) or 0)
                    if cooldown <= 0:
                        continue
                    if "last_run" not in entry:
                        last_ts = int(entry.get("last_ts", 0) or 0)
                        entry["last_run"] = last_ts if last_ts > 0 else now_ts - cooldown
                        entry.pop("last_ts", None)
                        state_changed = True
                    last_run = int(entry.get("last_run", now_ts) or now_ts)
                    if last_run > now_ts:
                        entry["last_run"] = now_ts
                        state_changed = True
                        continue
                except (TypeError, ValueError):
                    print(f"[AUTO_LOOP] Некорректная пассивная операция статов: user={user_id} entry={entry!r}")
                    continue

                if now_ts - last_run < cooldown:
                    continue
                cycles = (now_ts - last_run) // cooldown
                stat = "reputation" if entry.get("stat") == "reputation" else "happiness"
                current = max(0, min(100, int(st.get(stat, 50))))
                delta = int(entry.get("amount", 0) or 0) * cycles
                new_value = max(0, min(100, current + delta))
                st[stat] = new_value
                entry["last_run"] = last_run + cycles * cooldown
                state_changed = True
                await log_stat_change(
                    guild,
                    user_id,
                    f"Автопассив ({'репутация' if stat == 'reputation' else 'счастье'}): {entry.get('description', 'без описания')}",
                    stat,
                    current,
                    new_value,
                )

        # Low wellbeing and public standing reinforce each other.  These are
        # separate from configurable stat passives and retain their own clocks.
        for user_id, st in player_state.setdefault("users", {}).items():
            if should_skip_afk_user(user_id, now_ts):
                continue
            happiness = max(0, min(100, int(st.get("happiness", 50))))
            reputation = max(0, min(100, int(st.get("reputation", 50))))
            if happiness < 30:
                last = int(st.get("last_low_happiness_reputation_tick", now_ts) or now_ts)
                cycles = max(0, (now_ts - last) // (4 * 3600))
                if cycles:
                    new_value = max(0, reputation - cycles)
                    st["reputation"] = new_value
                    st["last_low_happiness_reputation_tick"] = last + cycles * 4 * 3600
                    state_changed = True
                    await log_stat_change(guild, user_id, "Счастье ниже 30%", "reputation", reputation, new_value)
            else:
                st["last_low_happiness_reputation_tick"] = now_ts
            if reputation < 30:
                last = int(st.get("last_low_reputation_happiness_tick", now_ts) or now_ts)
                cycles = max(0, (now_ts - last) // (8 * 3600))
                if cycles:
                    new_value = max(0, happiness - 2 * cycles)
                    st["happiness"] = new_value
                    st["last_low_reputation_happiness_tick"] = last + cycles * 8 * 3600
                    state_changed = True
                    await log_stat_change(guild, user_id, "Репутация ниже 30%", "happiness", happiness, new_value)
            else:
                st["last_low_reputation_happiness_tick"] = now_ts

        if changed:
            save_json(BALANCES_FILE, balances)
            save_passive_flows()
            for changed_uid in users_flows.keys():
                snapshot_player_statistics(str(changed_uid), reason="passive_money_update", save=False)
            await save_stats_library_async()
        population_passive_changed = False
        population_passive_changed_users = set()
        population_store = load_json(POPULATION_FILE, {})
        for user_id, st in player_state.setdefault("users", {}).items():
            if should_skip_afk_user(user_id, now_ts):
                continue
            entries = st.setdefault("population_passives", [])
            if not isinstance(entries, list):
                continue
            for entry in list(entries):
                try:
                    cooldown = int(entry.get("cooldown", 0) or 0); last_run = int(entry.get("last_run", now_ts) or now_ts)
                    if cooldown <= 0 or now_ts - last_run < cooldown:
                        continue
                    cycles = (now_ts - last_run) // cooldown
                    current_pop = int(population_store.get(user_id, 0) or 0)
                    amount_raw = str(entry.get("amount", 0)).strip()
                    if amount_raw.endswith("%"):
                        delta_one = int(current_pop * (float(amount_raw[:-1].replace(",", ".")) / 100.0))
                    else:
                        delta_one = int(float(amount_raw.replace(",", ".")))
                    population_store[user_id] = max(0, current_pop + delta_one * cycles)
                    entry["last_run"] = last_run + cycles * cooldown
                    population_passive_changed = True
                    population_passive_changed_users.add(str(user_id))
                except Exception:
                    print(f"[AUTO_LOOP] Некорректная пассивная операция населения: user={user_id} entry={entry!r}")
        if population_passive_changed:
            save_json(POPULATION_FILE, population_store)
            save_player_state()
            for changed_uid in population_passive_changed_users:
                try:
                    await sync_army_ratio_roles_for_user(guild, changed_uid)
                except (discord.Forbidden, discord.HTTPException):
                    pass
        if state_changed:
            save_player_state()
            for changed_uid in player_state.setdefault("users", {}).keys():
                snapshot_player_statistics(str(changed_uid), reason="passive_stat_update", save=False)
            await save_stats_library_async()

        # Автоначисление инвестиций (без ручного !коллект)
        inv_changed = False
        balances_changed = False
        now_ts = int(time.time())
        for inv_id, inv in list(investments.setdefault("active_investments", {}).items()):
            status = str(inv.get("status", "active"))
            if status != "active":
                continue

            user_id = str(inv.get("user_id") or "")
            if not user_id:
                continue

            start_at = int(inv.get("start_at", now_ts))
            if now_ts < start_at:
                continue

            cooldown = max(60, int(inv.get("cooldown", 3600)))
            next_at = int(inv.get("next_at", start_at))
            if now_ts < next_at:
                continue

            total_return = max(0, int(inv.get("total_return", 0)))
            cycles_total = max(1, int(inv.get("cycles_total", 1)))
            cycles_paid = max(0, int(inv.get("cycles_paid", 0)))
            paid_amount = max(0, int(inv.get("paid_amount", 0)))

            if cycles_paid >= cycles_total or paid_amount >= total_return:
                inv["status"] = "expired"
                investments["active_investments"][str(inv_id)] = inv
                inv_changed = True
                continue

            cycles_due = max(1, (now_ts - next_at) // cooldown + 1)
            cycles_to_pay = min(cycles_due, cycles_total - cycles_paid)
            if cycles_to_pay <= 0:
                continue

            base_part = total_return // cycles_total
            remainder = total_return % cycles_total
            payout_now = 0
            for i in range(cycles_to_pay):
                cycle_index = cycles_paid + i
                payout_now += base_part + (1 if cycle_index < remainder else 0)

            inv["cycles_paid"] = cycles_paid + cycles_to_pay
            inv["paid_amount"] = paid_amount + payout_now
            inv["next_at"] = next_at + cycles_to_pay * cooldown

            expires_at = inv.get("expires_at")
            if expires_at is not None and now_ts >= int(expires_at):
                inv["status"] = "expired"
            if inv["cycles_paid"] >= cycles_total or inv["paid_amount"] >= total_return:
                inv["status"] = "expired"

            investments["active_investments"][str(inv_id)] = inv
            inv_changed = True

            if payout_now > 0:
                user = ensure_user(user_id)
                user["наличка"] = int(user.get("наличка", 0)) + int(payout_now)
                balances_changed = True
                await log_economy_change(
                    guild,
                    user_id,
                    f"Автовыплата инвестиции #{inv_id}",
                    cash_delta=int(payout_now),
                )

        if inv_changed:
            save_investments()
        if balances_changed:
            save_json(BALANCES_FILE, balances)

        # Автоначисление компаний
        comp_changed = False
        balances_changed_comp = False
        now_comp = int(time.time())
        for company in companies_data.setdefault("companies", {}).values():
            owner_id = str(company.get("owner_id") or "")
            if not owner_id:
                continue
            update_company_derived_fields(company)
            user = ensure_user(owner_id)
            company_base = max(1, int(company_estimated_price(company)))

            income_cd = max(60, int(company.get("income_cooldown", 3600)))
            last_income = int(company.get("last_income_at", now_comp))
            if now_comp - last_income >= income_cd:
                cycles = (now_comp - last_income) // income_cd
                income_raw = str(company.get("income_amount", "0"))
                total_income = 0
                for _ in range(max(0, cycles)):
                    try:
                        inc = parse_money_value(income_raw, company_base)
                    except Exception:
                        inc = 0
                    if inc:
                        owner_gain = int(inc)
                        victim_company_id = str(company.get("id") or "")
                        active_attackers = []
                        for attacker in companies_data.setdefault("companies", {}).values():
                            if str(attacker.get("owner_id") or "") == owner_id:
                                continue
                            if str(attacker.get("active_ad_attack_target") or "") != victim_company_id:
                                continue
                            if now_comp > int(attacker.get("active_ad_attack_until", 0) or 0):
                                continue
                            if int(attacker.get("advert_level", 1)) <= int(company.get("advert_level", 1)):
                                continue
                            active_attackers.append(attacker)
                        if active_attackers:
                            attacker = max(active_attackers, key=lambda c: int(c.get("advert_level", 1)))
                            steal_percent = int(attacker.get("active_ad_attack_percent", 15) or 15)
                            steal_percent = max(1, min(15, steal_percent))
                            stolen = max(1, int(owner_gain * (steal_percent / 100.0)))
                            owner_gain -= stolen
                            attacker_owner_id = str(attacker.get("owner_id") or "")
                            if attacker_owner_id:
                                ensure_user(attacker_owner_id)["наличка"] = int(ensure_user(attacker_owner_id).get("наличка", 0)) + stolen

                            victim_member = guild.get_member(int(owner_id)) if owner_id.isdigit() else None
                            if victim_member:
                                try:
                                    attack_left = max(0, int(attacker.get("active_ad_attack_until", 0) or 0) - now_comp)
                                    await victim_member.send(
                                        embed=Embed(
                                            title="💸 Доход компании частично украден",
                                            description=(
                                                f">>> Компания **{company.get('name', 'Без названия')}** под атакой.\n"
                                                f"• Украдено: **{fmt_num(stolen)} {currency}**\n"
                                                f"  ↳ Процент кражи: **{steal_percent}%**\n"
                                                f"  ↳ Осталось времени атаки: **{format_seconds_left(attack_left) if attack_left > 0 else 'завершена'}**"
                                            ),
                                            color=0xE67E22,
                                        )
                                    )
                                except Exception:
                                    pass
                        user["наличка"] = int(user.get("наличка", 0)) + owner_gain
                        total_income += owner_gain
                        balances_changed_comp = True

                        # Доход из присутствия компании в других странах:
                        # начисляется владельцу и владельцу целевой страны одинаковой суммой,
                        # но зависит от % предметов компании у владельца целевой страны.
                        for country_name, pres in ensure_company_country_presence_struct(company).items():
                            if not isinstance(pres, dict) or str(pres.get("status")) != "active":
                                continue
                            buyer_id = str(pres.get("buyer_user_id") or "")
                            if not buyer_id:
                                continue
                            share = effective_company_share(company, buyer_id, country_name)
                            if share <= 0:
                                continue
                            extra_income = int(owner_gain * share)
                            if extra_income <= 0:
                                continue
                            user["наличка"] = int(user.get("наличка", 0)) + extra_income
                            ensure_user(buyer_id)["наличка"] = int(ensure_user(buyer_id).get("наличка", 0)) + extra_income
                            total_income += extra_income
                            balances_changed_comp = True
                company["last_income_at"] = last_income + cycles * income_cd
                comp_changed = True
                if total_income:
                    await log_economy_change(
                        guild,
                        owner_id,
                        f"Доход компании «{company.get('name', 'Без названия')}»",
                        cash_delta=total_income,
                    )

            expense_cd = max(60, int(company.get("expense_cooldown", 3600)))
            last_expense = int(company.get("last_expense_at", now_comp))
            if now_comp - last_expense >= expense_cd:
                cycles = (now_comp - last_expense) // expense_cd
                expense_raw = str(company.get("expense_amount", "0"))
                total_expense = 0
                for _ in range(max(0, cycles)):
                    try:
                        exp = parse_money_value(expense_raw, company_base)
                    except Exception:
                        exp = 0
                    if exp:
                        user["наличка"] = int(user.get("наличка", 0)) - int(exp)
                        total_expense += int(exp)
                        balances_changed_comp = True

                        for country_name, pres in ensure_company_country_presence_struct(company).items():
                            if not isinstance(pres, dict) or str(pres.get("status")) != "active":
                                continue
                            buyer_id = str(pres.get("buyer_user_id") or "")
                            if not buyer_id:
                                continue
                            share = effective_company_share(company, buyer_id, country_name)
                            if share <= 0:
                                continue
                            extra_expense = int(int(exp) * share)
                            if extra_expense <= 0:
                                continue
                            user["наличка"] = int(user.get("наличка", 0)) - extra_expense
                            ensure_user(buyer_id)["наличка"] = int(ensure_user(buyer_id).get("наличка", 0)) - extra_expense
                            total_expense += extra_expense
                            balances_changed_comp = True
                company["last_expense_at"] = last_expense + cycles * expense_cd
                comp_changed = True
                if total_expense:
                    await log_economy_change(
                        guild,
                        owner_id,
                        f"Расход компании «{company.get('name', 'Без названия')}»",
                        cash_delta=-total_expense,
                    )

            autobuy_rules = company.get("autobuy", []) if isinstance(company.get("autobuy"), list) else []
            for rule in autobuy_rules:
                try:
                    item_key = str(rule.get("item_key") or "")
                    qty = max(1, int(rule.get("quantity", 1)))
                    cooldown = max(60, int(rule.get("cooldown", 86400)))
                    last_at = int(rule.get("last_at", 0) or 0)
                except Exception:
                    continue
                if now_comp - last_at < cooldown:
                    continue
                item = items_data.get("items", {}).get(item_key)
                if not item or not bool(item.get("can_buy", True)):
                    rule["last_at"] = now_comp
                    comp_changed = True
                    continue
                if item.get("stock", 0) != -1 and int(item.get("stock", 0)) < qty:
                    # Если товара не хватает, не переводим правило в КД:
                    # автопокупка попробует снова на следующем тике.
                    continue
                total_price = int(item.get("price", 0)) * qty
                if int(user.get("наличка", 0)) < total_price:
                    # Недостаточно налички — просто пропускаем без сдвига last_at,
                    # чтобы автопокупка возобновилась сразу после пополнения баланса.
                    continue
                user["наличка"] = int(user.get("наличка", 0)) - total_price
                balances_changed_comp = True
                inventory.setdefault(owner_id, {})
                inventory[owner_id][item_key] = int(inventory[owner_id].get(item_key, 0)) + qty
                if item.get("stock", 0) != -1:
                    item["stock"] = int(item.get("stock", 0)) - qty
                rule["last_at"] = now_comp
                comp_changed = True
                await log_economy_change(
                    guild,
                    owner_id,
                    f"Автопокупка компании «{company.get('name', 'Без названия')}»: {item_key} x{qty}",
                    cash_delta=-total_price,
                )

        if comp_changed:
            save_companies_data()
        if balances_changed_comp:
            save_json(BALANCES_FILE, balances)
            save_inventory()
            save_items()

        # Recurring country-to-country operations approved in verdicts.
        # They are stored with absolute timestamps, therefore a restart does not
        # reset their cooldown or duration.
        external_changed = False
        external_balances = False
        external_inventory = False
        external_population = None
        now_external = int(time.time())
        for op_id, op in list(verdicts_data.setdefault("external_operations", {}).items()):
            if not isinstance(op, dict) or str(op.get("status")) != "active":
                continue
            if now_external >= int(op.get("expires_at", 0) or 0):
                op["status"] = "expired"; external_changed = True; continue
            cooldown = max(60, int(op.get("cooldown", 60) or 60))
            next_at = int(op.get("next_at", now_external) or now_external)
            if now_external < next_at:
                continue
            source, other = str(op.get("member_id") or ""), str(op.get("other_id") or "")
            amount = max(1, int(op.get("amount", 1) or 1)); kind = str(op.get("external_kind") or "")
            if not source or not other:
                op["status"] = "invalid"; external_changed = True; continue
            # Migration: B -> A. Immigration: A -> B.
            if kind in {"migration", "immigration"}:
                if external_population is None: external_population = load_json(POPULATION_FILE, {})
                donor, recipient = (other, source) if kind == "migration" else (source, other)
                moved = min(amount, max(0, int(external_population.get(donor, 0) or 0)))
                if moved:
                    external_population[donor] = int(external_population.get(donor, 0)) - moved
                    external_population[recipient] = int(external_population.get(recipient, 0)) + moved
                op["last_amount"] = moved
            elif kind == "payout":
                paid = min(amount, max(0, int(ensure_user(source).get("наличка", 0))))
                if paid:
                    ensure_user(source)["наличка"] -= paid; ensure_user(other)["наличка"] += paid; external_balances = True
                op["last_amount"] = paid
            elif kind == "purchase":
                key, price = str(op.get("item_key") or ""), max(0, int(op.get("price", 0) or 0))
                qty = min(amount, max(0, int(inventory.setdefault(other, {}).get(key, 0))))
                total_price = qty * price
                if total_price > int(ensure_user(source).get("наличка", 0)):
                    qty = int(ensure_user(source).get("наличка", 0)) // max(1, price) if price else qty; total_price = qty * price
                if qty:
                    inventory[other][key] -= qty
                    if inventory[other][key] <= 0: inventory[other].pop(key, None)
                    inventory.setdefault(source, {})[key] = int(inventory.setdefault(source, {}).get(key, 0)) + qty
                    ensure_user(source)["наличка"] -= total_price; ensure_user(other)["наличка"] += total_price
                    external_inventory = external_balances = True
                op["last_amount"] = qty
            elif kind == "supply":
                key = str(op.get("item_key") or ""); qty = min(amount, max(0, int(inventory.setdefault(other, {}).get(key, 0))))
                if qty:
                    inventory[other][key] -= qty
                    if inventory[other][key] <= 0: inventory[other].pop(key, None)
                    inventory.setdefault(source, {})[key] = int(inventory.setdefault(source, {}).get(key, 0)) + qty
                    external_inventory = True
                op["last_amount"] = qty
            else:
                op["status"] = "invalid"
            op["last_run"] = now_external; op["next_at"] = next_at + ((now_external - next_at) // cooldown + 1) * cooldown
            external_changed = True
        if external_population is not None:
            save_json(POPULATION_FILE, external_population)
        if external_balances: save_json(BALANCES_FILE, balances)
        if external_inventory: save_inventory()
        if external_changed: save_verdicts_data()

        factories_changed = False
        factory_owners_changed: set[str] = set()
        now_factory = int(time.time())
        for owner_id, factories in factories_data.setdefault("users", {}).items():
            if not isinstance(factories, list):
                continue
            for factory in factories:
                if int(factory.get("busy_until", 0) or 0) <= 0:
                    continue
                total = max(0, int(factory.get("quantity_total", 0) or 0))
                done = max(0, int(factory.get("quantity_done", 0) or 0))
                if done >= total:
                    factory.update({"status": "free", "busy_until": 0})
                    factories_changed = True
                    factory_owners_changed.add(str(owner_id))
                    continue
                item = items_data.setdefault("items", {}).get(str(factory.get("item_key") or ""), {})
                batch = max(1, int(factory.get("batch_size") or item.get("production_batch_min", item.get("min_production", 1)) or 1))
                # A minimum production batch completes once per RP year.  This
                # ensures that interruption can refund every uncompleted batch.
                interval = max(1, (int(factory.get("busy_until", now_factory)) - int(factory.get("started_at", now_factory))) // max(1, total // batch))
                next_unit_at = int(factory.get("next_unit_at", now_factory) or now_factory)
                produced = 0
                while done < total and now_factory >= next_unit_at:
                    completed = min(batch, total - done)
                    done += completed; produced += completed; next_unit_at += interval
                # A delayed auto-loop (or an older job with a stale
                # next_unit_at) must never release a factory before crediting
                # the remainder of the requested production.  Once its
                # deadline has passed, the entire ordered quantity is ready.
                if now_factory >= int(factory.get("busy_until", 0) or 0) and done < total:
                    completed = total - done
                    done += completed
                    produced += completed
                if produced:
                    key = str(factory.get("item_key") or "")
                    if key:
                        item = items_data.setdefault("items", {}).get(key)
                        if item is not None and int(item.get("stock", 0)) != -1:
                            item["stock"] = int(item.get("stock", 0)) + produced
                    factory["quantity_done"] = done
                    factory["next_unit_at"] = next_unit_at
                    factories_changed = True
                    factory_owners_changed.add(str(owner_id))
                if now_factory >= int(factory.get("busy_until", 0) or 0) or done >= total:
                    factory.update({"status": "free", "busy_until": 0, "quantity_done": total})
                    factories_changed = True
                    factory_owners_changed.add(str(owner_id))
        if factories_changed:
            save_items(); save_factories_data()
            for owner_id in factory_owners_changed:
                await refresh_open_factory_menus(owner_id)
        status_until = settings.get("status_until")
        if status_until is not None and int(time.time()) >= int(status_until):
            settings["status_emoji"] = None
            settings["status_text"] = None
            settings["status_until"] = None
            save_json(SETTINGS_FILE, settings)
            try:
                await bot.change_presence(activity=None)
            except Exception:
                pass

        progressed_year = False
        progressed_year_count = 0

        # RP-год: автоматическое обновление одного сообщения + триггер инвестиций по году
        rp = investments.setdefault("rp_year", {})
        rp_channel_id = rp.get("channel_id")
        rp_year = rp.get("year")
        rp_cooldown = max(60, int(rp.get("cooldown", 86400)))
        science_increment = max(0, int(rp.get("science_limit_increment", 0) or 0))
        science_limit_current = max(0, int(rp.get("science_limit_current", rp.get("science_limit_start", 0)) or 0))
        next_tick_at = rp.get("next_tick_at")
        if rp_channel_id and rp_year is not None:
            rp_channel = guild.get_channel(int(rp_channel_id))
            if rp_channel:
                now_rp = int(time.time())
                if next_tick_at is None:
                    rp["next_tick_at"] = now_rp + rp_cooldown
                    next_tick_at = rp["next_tick_at"]

                while now_rp >= int(next_tick_at):
                    rp_year = int(rp.get("year", rp_year)) + 1
                    rp["year"] = rp_year
                    science_limit_current += science_increment
                    rp["science_limit_current"] = science_limit_current
                    next_tick_at = int(next_tick_at) + rp_cooldown
                    rp["next_tick_at"] = next_tick_at
                    progressed_year = True
                    progressed_year_count += 1

                    for inv_id, inv in investments.setdefault("active_investments", {}).items():
                        if str(inv.get("status")) != "pending_year":
                            continue
                        pending_year = inv.get("pending_year")
                        if pending_year is not None and int(pending_year) <= rp_year:
                            inv["status"] = "active"
                            inv["start_at"] = now_rp
                            inv["next_at"] = now_rp
                            inv["expires_at"] = now_rp + int(inv.get("duration", rp_cooldown))
                            investments["active_investments"][str(inv_id)] = inv

                elapsed = max(0, rp_cooldown - max(0, int(next_tick_at) - now_rp))
                quarter = int((elapsed * 4) / rp_cooldown) % 4
                total_population, total_science, registered_count = calculate_world_stats(guild)
                em = format_rp_year_embed(
                    int(rp.get("year", rp_year)),
                    quarter,
                    int(rp.get("science_limit_current", science_limit_current)),
                    total_population,
                    total_science,
                    registered_count,
                    elapsed,
                    rp_cooldown,
                )
                msg = None
                msg_id = rp.get("message_id")
                should_send_new = msg_id is None
                if msg_id:
                    try:
                        msg = await rp_channel.fetch_message(int(msg_id))
                    except discord.NotFound:
                        should_send_new = True
                    except (discord.DiscordServerError, discord.HTTPException):
                        # Временная ошибка API Discord: не создаём новое сообщение,
                        # чтобы не спамить канал дубликатами.
                        msg = None
                        should_send_new = False
                    except Exception:
                        should_send_new = True
                # RP calendar panels are intentionally rotated every five real
                # days. On restart an old panel is also replaced on the first
                # loop pass, rather than leaving an obsolete date in the channel.
                panel_age = now_rp - int(rp.get("panel_published_at", 0) or 0)
                rotate_panel = bool(msg and panel_age >= 5 * 86400)
                if rotate_panel:
                    try:
                        await msg.delete()
                    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                        pass
                    msg = None
                    should_send_new = True
                if msg:
                    # The active panel stays current between rotations.
                    try:
                        await msg.edit(embed=em)
                    except (discord.DiscordServerError, discord.HTTPException):
                        pass
                    except Exception:
                        pass
                elif should_send_new:
                    try:
                        sent = await rp_channel.send(embed=em)
                        rp["message_id"] = sent.id
                        rp["panel_published_at"] = now_rp
                        save_investments()
                    except Exception:
                        pass

                if progressed_year:
                    rp_science_changed = False
                    for company in companies_data.setdefault("companies", {}).values():
                        owner_id = str(company.get("owner_id") or "")
                        if not owner_id:
                            continue
                        science_gain_per_year = max(0, int(company.get("science_auto_bonus", 0) or 0))
                        if science_gain_per_year <= 0:
                            continue
                        state = ensure_player_state(owner_id)
                        state["science"] = int(state.get("science", 0) or 0) + (science_gain_per_year * progressed_year_count)
                        rp_science_changed = True

                    if rp_science_changed:
                        save_player_state()
                    save_investments()

                try:
                    await ensure_occupied_registrations_message()
                except Exception as e:
                    print(f"[AUTO_LOOP] ensure_occupied_registrations_message failed: {e}")

        # Счастье / население: один раз за прошедший RP-год.
        # Если RP-календарь ещё не настроен, остаётся старый таймер из settings.
        pop = load_json(POPULATION_FILE, {})
        state_changed = False
        now_tick = int(time.time())
        for user_id, st in player_state.setdefault("users", {}).items():
            ensure_user(user_id)
            happiness = int(st.get("happiness", 50))
            shield_until = int(st.get("shield_until", 0))
            pause_until = int(st.get("happiness_pause_until", 0))
            soldiers = int(st.get("soldiers", 0))

            happiness_tick = max(60, int(settings.get("happiness_tick_seconds", 86400)))
            last_h = int(st.get("last_happiness_tick", now_tick))
            happiness_cycles = int(progressed_year_count) if progressed_year_count > 0 else 0
            if happiness_cycles <= 0 and now_tick - last_h >= happiness_tick:
                happiness_cycles = max(1, (now_tick - last_h) // happiness_tick)
            if happiness_cycles > 0:
                st["last_happiness_tick"] = now_tick
                if now_tick >= shield_until and now_tick >= pause_until:
                    pop_val = int(pop.get(user_id, 0))
                    for _ in range(max(1, happiness_cycles)):
                        drain = get_mobilization_happiness_penalty(pop_val, soldiers)
                        happiness = max(0, happiness - drain)
                        st["happiness"] = happiness

                        if happiness <= 0:
                            channel_id = settings.get("message_log_channel")
                            if st.get("autowipe_status") != "pending":
                                st["autowipe_status"] = "pending"
                                st["autowipe_requested_at"] = now_tick
                                remove_user_registration(user_id)
                                member = guild.get_member(int(user_id)) if guild and str(user_id).isdigit() else None
                                em = Embed(
                                    title="⚠️ Запрос на автовайп",
                                    description=(
                                        f"У игрока {member.mention if member else f'<@{user_id}>'} счастье достигло **0**.\n"
                                        "Нужно решение куратора: одобрить автoвайп или отклонить.\n"
                                        "При отклонении игрок остаётся незарегистрированным с нулевым счастьем."
                                    ),
                                    color=0xF39C12,
                                )
                                await send_message_log_embed(guild, em)
                                channel = guild.get_channel(int(channel_id)) if channel_id and guild else None
                                if channel:
                                    try:
                                        await channel.send(
                                            embed=Embed(
                                                title="🧾 Решение по автовайпу",
                                                description=f"Игрок: <@{user_id}>",
                                                color=0xF39C12,
                                            ),
                                            view=AutoWipeDecisionView(user_id),
                                        )
                                    except Exception:
                                        pass
                                mod_log_channel_id = moderation_data.get("log_channel")
                                mod_log_channel = (
                                    guild.get_channel(int(mod_log_channel_id))
                                    if mod_log_channel_id and guild
                                    else None
                                )
                                if (
                                    mod_log_channel
                                    and (not channel or int(mod_log_channel.id) != int(channel.id))
                                ):
                                    try:
                                        await mod_log_channel.send(
                                            embed=Embed(
                                                title="🧾 Запрос на решение автовайпа",
                                                description=(
                                                    f"Игрок: <@{user_id}> (`{user_id}`)\n"
                                                    "Причина: счастье достигло 0."
                                                ),
                                                color=0xF39C12,
                                            ),
                                            view=AutoWipeDecisionView(user_id),
                                        )
                                    except Exception:
                                        pass
                            else:
                                requested_at = int(st.get("autowipe_requested_at", now_tick))
                                waited = max(0, now_tick - requested_at)
                                print(
                                    f"[AUTO_WIPE] Ожидание решения: user={user_id} elapsed={format_interval(waited)} happiness=0"
                                )
                            state_changed = True
                            break

                    growth_pct = get_population_growth_percent(happiness)
                    if growth_pct is not None and pop_val > 0:
                        pop_val = max(0, int(round(pop_val * (1 + growth_pct / 100.0))))
                        pop[user_id] = pop_val
                    try:
                        await sync_army_ratio_roles_for_user(guild, user_id)
                    except (discord.Forbidden, discord.HTTPException):
                        pass
                    state_changed = True

            last_m = int(st.get("last_mobilization_cost_tick", now_tick))
            if now_tick - last_m >= 43200 and soldiers > 0:
                cycles = (now_tick - last_m) // 43200
                st["last_mobilization_cost_tick"] = last_m + cycles * 43200
                per_cost = 7 if st.get("war_mode", False) else 1
                ensure_user(user_id)["наличка"] -= per_cost * soldiers * cycles
                state_changed = True

        if state_changed:
            save_json(POPULATION_FILE, pop)
            save_player_state()
            save_json(BALANCES_FILE, balances)


@auto_role_income_loop.error
async def auto_role_income_loop_error(exc):
    logging.getLogger(__name__).error(
        "Критическая ошибка цикла автоколлекта",
        exc_info=exc,
    )


