@bot.command(name="категориядобавить")
@admin_or_command_access()
async def категориядобавить(ctx):
    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel

    await ctx.send(
        embed=Embed(
            title="🧩 Новая категория",
            description="Введите название категории.",
            color=0x3498DB,
        )
    )
    try:
        name = (await bot.wait_for("message", check=check, timeout=180)).content.strip()
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка", description="Время ожидания истекло.", color=0xFF0000
            )
        )
        return

    if not name:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Название не может быть пустым.",
                color=0xFF0000,
            )
        )
        return

    if any(
        str(v).casefold() == name.casefold()
        for v in items_data.get("categories", {}).values()
    ):
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Категория с таким названием уже существует.",
                color=0xFF0000,
            )
        )
        return

    await ctx.send(
        embed=Embed(
            title="🧩 Новая категория",
            description="Введите эмодзи категории (или `скип`).",
            color=0x3498DB,
        )
    )
    try:
        emoji_raw = (
            await bot.wait_for("message", check=check, timeout=180)
        ).content.strip()
    except Exception:
        emoji_raw = "скип"

    await ctx.send(
        embed=Embed(
            title="🧩 Новая категория",
            description="Введите обязательные роли для покупки предметов этой категории (упоминания/ID через пробел или `скип`).",
            color=0x3498DB,
        )
    )
    try:
        require_roles_raw = (await bot.wait_for("message", check=check, timeout=180)).content.strip()
        category_require_roles = parse_role_mentions(require_roles_raw or "скип")
    except Exception:
        category_require_roles = []

    cat_ids = [
        int(k)
        for k in items_data.setdefault("categories", {}).keys()
        if str(k).isdigit()
    ]
    new_id = str(max(cat_ids) + 1 if cat_ids else 1)

    items_data.setdefault("categories", {})[new_id] = name
    if emoji_raw.lower() != "скип":
        items_data.setdefault("category_emojis", {})[new_id] = emoji_raw
    else:
        items_data.setdefault("category_emojis", {}).setdefault(new_id, "")
    items_data.setdefault("category_require_roles", {})[new_id] = category_require_roles

    save_items()
    emoji_view = items_data.get("category_emojis", {}).get(new_id, "") or "—"
    roles_view = ", ".join(f"<@&{rid}>" for rid in category_require_roles) or "—"
    await ctx.send(
        embed=Embed(
            title="✅ Категория добавлена",
            description=f"**Номер:** {new_id}\n**Название:** {name}\n**Эмодзи:** {emoji_view}\n**Обязательные роли:** {roles_view}",
            color=0x00FF00,
        )
    )


@bot.command(name="редактировать-категорию")
@admin_or_command_access()
async def редактировать_категорию(ctx, category_ref: str):
    categories = items_data.setdefault("categories", {})
    target_id = category_ref.strip() if category_ref.strip() in categories else None
    if target_id is None:
        for cid, cname in categories.items():
            if str(cname).casefold() == category_ref.strip().casefold():
                target_id = str(cid)
                break
    if target_id is None:
        await ctx.send(embed=Embed(title="❌ Категория не найдена", description="Укажите номер или точное название категории.", color=0xFF0000))
        return

    class CategoryEditModal(Modal):
        def __init__(self):
            super().__init__(title="Редактировать категорию", timeout=600)
            roles = items_data.setdefault("category_require_roles", {}).get(target_id, [])
            self.name = TextInput(label="Новое название", required=True, max_length=100, default=str(categories.get(target_id, "")))
            self.emoji = TextInput(label="Эмодзи (или скип)", required=False, max_length=100, default=str(items_data.setdefault("category_emojis", {}).get(target_id, "")))
            self.roles = TextInput(label="Обязательные роли покупки (или скип)", required=False, max_length=500, default=" ".join(f"<@&{rid}>" for rid in roles))
            self.add_item(self.name); self.add_item(self.emoji); self.add_item(self.roles)

        async def on_submit(self, interaction: Interaction):
            new_name = str(self.name.value).strip()
            if not new_name:
                await interaction.response.send_message("❌ Название не может быть пустым.", ephemeral=True)
                return
            for cid, cname in categories.items():
                if str(cid) != target_id and str(cname).casefold() == new_name.casefold():
                    await interaction.response.send_message("❌ Категория с таким названием уже существует.", ephemeral=True)
                    return
            try:
                roles = parse_role_mentions(str(self.roles.value or "скип").strip() or "скип")
            except Exception:
                await interaction.response.send_message("❌ Укажите роли упоминаниями/ID через пробел или `скип`.", ephemeral=True)
                return
            categories[target_id] = new_name
            emoji = str(self.emoji.value or "").strip()
            items_data.setdefault("category_emojis", {})[target_id] = "" if emoji.lower() == "скип" else emoji
            items_data.setdefault("category_require_roles", {})[target_id] = roles
            save_items()
            await interaction.response.send_message(
                embed=Embed(
                    title="✅ Категория обновлена",
                    description=f"**Номер:** {target_id}\n**Название:** {new_name}\n**Эмодзи:** {items_data['category_emojis'].get(target_id) or '—'}\n**Обязательные роли:** {', '.join(f'<@&{rid}>' for rid in roles) or '—'}",
                    color=0x00FF00,
                ),
                ephemeral=True,
            )

    class CategoryEditView(View):
        def __init__(self):
            super().__init__(timeout=300)

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True)
                return False
            return True

        @discord.ui.button(label="Открыть форму редактирования", style=ButtonStyle.primary)
        async def open_modal(self, interaction: Interaction, button: Button):
            await interaction.response.send_modal(CategoryEditModal())

    await ctx.send(
        embed=Embed(
            title="✏️ Редактирование категории",
            description=f"Выбрана категория №{target_id}: **{categories.get(target_id)}**. Нажмите кнопку ниже, чтобы изменить название, эмодзи и обязательную роль покупки.",
            color=0x3498DB,
        ),
        view=CategoryEditView(),
    )


@bot.command(name="категорияудалить")
@admin_or_command_access()
async def категорияудалить(ctx, *, category_ref: str):
    categories = items_data.setdefault("categories", {})
    target_id = None
    ref = category_ref.strip()

    if ref in categories:
        target_id = ref
    else:
        for cid, cname in categories.items():
            if str(cname).casefold() == ref.casefold():
                target_id = cid
                break

    if target_id is None:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Категория не найдена. Укажите номер или точное название.",
                color=0xFF0000,
            )
        )
        return

    used_items = [
        k
        for k, item in items_data.get("items", {}).items()
        if str(item.get("category")) == str(target_id)
    ]
    if used_items:
        preview = "\n".join(f"• {k}" for k in used_items[:10])
        more = "" if len(used_items) <= 10 else f"\n... и ещё {len(used_items)-10}"
        await ctx.send(
            embed=Embed(
                title="❌ Нельзя удалить категорию",
                description=f"В этой категории есть предметы:\n{preview}{more}\n\nСначала удалите/перенесите эти предметы.",
                color=0xFF0000,
            )
        )
        return

    removed_name = categories.pop(target_id)
    items_data.setdefault("category_emojis", {}).pop(target_id, None)
    items_data.setdefault("category_require_roles", {}).pop(target_id, None)
    save_items()

    await ctx.send(
        embed=Embed(
            title="✅ Категория удалена",
            description=f"Удалена категория **{removed_name}** (№{target_id}).",
            color=0x00FF00,
        )
    )


@bot.command()
@admin_or_command_access()
async def создатьпредмет(ctx):
    draft = {
        "key": "",
        "price": 0,
        "category": "1",
        "stock": -1,
        "expires_at": None,
        "description": "",
        "require_roles": [],
        "give_roles": [],
        "remove_roles": [],
        "use_text": None,
        "wipe_delete": False,
        "save_to_library": False,
        "item_kind": "item",
        "tech_type": "",
        "tech_rating": 0,
        "required_item": "",
        "required_quantity": 0,
        "production_batch_min": 1,
    }

    FIELD_LABELS = {
        "key": "Ключ",
        "price": "Цена",
        "category": "Категория",
        "stock": "Количество",
        "ttl": "Время жизни",
        "description": "Описание",
        "require_roles": "Обязательные роли",
        "give_roles": "Выдаёт роли",
        "remove_roles": "Забирает роли",
        "use_text": "Текст использования",
        "wipe_delete": "Удалять при вайпе",
        "save_to_library": "Сохранять в библиотеку",
        "item_kind": "Сценарий",
        "tech_type": "Тип техники",
        "tech_rating": "Оценка техники",
        "production": "Производство",
    }

    def categories_text():
        lines = []
        for cid, cname in sorted(
            items_data.get("categories", {}).items(),
            key=lambda x: int(x[0]) if str(x[0]).isdigit() else 99999,
        ):
            emoji = items_data.get("category_emojis", {}).get(str(cid), "")
            marker = " ✅" if str(cid) == str(draft["category"]) else ""
            emoji_part = f"{emoji} " if emoji else ""
            lines.append(f"`{cid}` — {emoji_part}{cname}{marker}")
        return "\n".join(lines) if lines else "—"

    def format_roles(role_ids):
        if not role_ids:
            return "—"
        vals = []
        for rid in role_ids:
            role = ctx.guild.get_role(int(rid)) if ctx.guild else None
            vals.append(role.mention if role else f"<@&{rid}>")
        return ", ".join(vals) if vals else "—"

    def validate_give_roles_hierarchy(role_ids: list[int]):
        if not ctx.guild:
            return
        creator_top_role = ctx.author.top_role
        for rid in role_ids:
            role = ctx.guild.get_role(int(rid))
            if role and role.position > creator_top_role.position:
                raise ValueError(
                    f"Нельзя выдавать роль {role.mention}: она выше вашей самой высокой роли ({creator_top_role.mention})."
                )

    def format_item_validation_error(err: Exception) -> str:
        if isinstance(err, ValueError):
            return str(err)
        return "Проверьте введённые данные (числа, категорию и упоминания ролей)."

    def build_embed():
        e = Embed(title="📝 Создание техники" if draft.get("item_kind") == "tech" else "📝 Создание предмета", color=0x3498DB)
        ttl_text = (
            "∞"
            if draft["expires_at"] is None
            else format_seconds_left(int(draft["expires_at"]) - int(time.time()))
        )
        stock_text = "∞" if int(draft["stock"]) == -1 else str(draft["stock"])
        cat_id = str(draft["category"])
        cat_name = items_data.get("categories", {}).get(cat_id, cat_id)
        e.add_field(name="Сценарий", value="Техника" if draft.get("item_kind") == "tech" else "Предмет", inline=True)
        if draft.get("item_kind") == "tech":
            e.add_field(name="Тип техники", value=draft.get("tech_type") or "—", inline=True)
            e.add_field(name="Оценка", value=f"{int(draft.get('tech_rating', 0))}/100", inline=True)
            e.add_field(name="Производство", value=f"Минимум: {int(draft.get('production_batch_min', 1) or 1)}; ресурсы: {format_production_requirements(draft.get('required_item'), draft.get('required_quantity'))}", inline=False)
        e.add_field(name="Ключ", value=draft["key"] or "—", inline=True)
        e.add_field(
            name="Цена",
            value=(fmt_money(draft["price"]) if draft["price"] else "—"),
            inline=True,
        )
        e.add_field(name="Категория", value=f"№{cat_id} — {cat_name}", inline=True)
        e.add_field(name="Количество", value=stock_text, inline=True)
        e.add_field(name="Время жизни", value=ttl_text, inline=True)
        e.add_field(name="Описание", value=draft["description"] or "—", inline=False)
        e.add_field(
            name="Обязательные роли",
            value=format_roles(item_required_role_ids(draft)),
            inline=False,
        )
        e.add_field(
            name="Выдаёт роли", value=format_roles(draft["give_roles"]), inline=False
        )
        e.add_field(
            name="Забирает роли",
            value=format_roles(draft["remove_roles"]),
            inline=False,
        )
        e.add_field(
            name="Текст использования", value=draft["use_text"] or "✅", inline=False
        )
        e.add_field(
            name="Удалять ли при вайпе",
            value=bool_to_yes_no(draft["wipe_delete"]),
            inline=True,
        )
        e.add_field(
            name="Сохранять в библиотеку техники",
            value=bool_to_yes_no(draft["save_to_library"]),
            inline=True,
        )
        categories_value = categories_text()
        if len(categories_value) > 1024:
            categories_value = categories_value[:1021] + "..."
        e.add_field(
            name="Категории (номер — название)", value=categories_value, inline=False
        )
        e.set_footer(
            text="Выберите пункт из меню ниже, чтобы открыть форму редактирования"
        )
        return e

    def build_create_item_sections():
        e = build_embed()
        sections = [f"## {e.title}"]
        for field in e.fields:
            sections.append(f"**{field.name}:**\n{field.value}")
        footer_text = getattr(e.footer, "text", "") or "Выберите пункт из меню ниже, чтобы открыть форму редактирования"
        sections.append(f"-# {footer_text}")
        return sections

    def build_create_item_text():
        return "\n\n".join(build_create_item_sections())

    def create_item_uses_components_v2() -> bool:
        return shop_supports_components_v2()

    def add_text_sections_with_separators(container, sections: list[str]):
        for idx, section in enumerate(sections):
            if idx > 0:
                container.add_item(V2Separator())
            container.add_item(V2TextDisplay(section))

    async def edit_create_message(interaction: Interaction):
        if create_item_uses_components_v2():
            await interaction.response.edit_message(content=None, embed=None, view=CreateItemView())
        else:
            await interaction.response.edit_message(content=build_create_item_text(), embed=None, view=CreateItemView())

    class EditFieldModal(Modal):
        def __init__(self, field_name: str):
            super().__init__(
                title=f"Редактирование: {FIELD_LABELS[field_name]}", timeout=600
            )
            self.field_name = field_name

            defaults = {
                "key": draft["key"],
                "price": str(draft["price"]) if draft["price"] else "",
                "category": str(draft["category"]),
                "stock": "скип" if int(draft["stock"]) == -1 else str(draft["stock"]),
                "ttl": (
                    "скип"
                    if draft["expires_at"] is None
                    else str(max(0, int(draft["expires_at"]) - int(time.time())))
                ),
                "description": draft["description"],
                "require_roles": " ".join(f"<@&{x}>" for x in draft["require_roles"]),
                "give_roles": " ".join(f"<@&{x}>" for x in draft["give_roles"]),
                "remove_roles": " ".join(f"<@&{x}>" for x in draft["remove_roles"]),
                "use_text": draft["use_text"] or "скип",
                "wipe_delete": bool_to_yes_no(draft["wipe_delete"]),
                "save_to_library": bool_to_yes_no(draft["save_to_library"]),
                "item_kind": "техника" if draft.get("item_kind") == "tech" else "предмет",
                "tech_type": draft.get("tech_type", ""),
                "tech_rating": str(draft.get("tech_rating", 0)),
                "production": (
                    f"{draft.get('required_item') or 'скип'} / "
                    f"{draft.get('required_quantity', 0) or 0} / "
                    f"{int(draft.get('production_batch_min', 1) or 1)}"
                ),
            }

            labels = {
                "key": "Ключ предмета",
                "price": "Цена",
                "category": "Категория (номер)",
                "stock": "Количество (или скип)",
                "ttl": "Время жизни в сек (или скип)",
                "description": "Описание",
                "require_roles": "Обязательные роли (или скип)",
                "give_roles": "Выдаёт роли (или скип)",
                "remove_roles": "Забирает роли (или скип)",
                "use_text": "Текст использования (или скип)",
                "wipe_delete": "Удалять при вайпе? (да/нет)",
                "save_to_library": "Сохранять в библиотеку? (да/нет)",
                "item_kind": "Сценарий: предмет/техника",
                "tech_type": "Тип техники",
                "tech_rating": "Оценка техники (0-100)",
                "production": "Производство: предмет / расход / минимум",
            }

            styles = {
                "description": discord.TextStyle.paragraph,
                "use_text": discord.TextStyle.paragraph,
            }

            if field_name == "production":
                self.required_item_input = TextInput(
                    label="Требуемый предмет (или скип)",
                    required=True,
                    default=draft.get("required_item") or "скип",
                    max_length=100,
                )
                self.required_quantity_input = TextInput(
                    label="Расход ресурса на минимум",
                    required=True,
                    default=str(draft.get("required_quantity", 0) or 0),
                    max_length=20,
                )
                self.production_batch_input = TextInput(
                    label="Минимум производства",
                    required=True,
                    default=str(int(draft.get("production_batch_min", 1) or 1)),
                    max_length=20,
                )
                self.add_item(self.required_item_input)
                self.add_item(self.required_quantity_input)
                self.add_item(self.production_batch_input)
            else:
                self.value_input = TextInput(
                    label=labels[field_name],
                    required=True,
                    default=(
                        defaults[field_name][:1000]
                        if isinstance(defaults[field_name], str)
                        else str(defaults[field_name])
                    ),
                    style=styles.get(field_name, discord.TextStyle.short),
                    max_length=1000,
                )
                self.add_item(self.value_input)

        async def on_submit(self, interaction: Interaction):
            raw = "" if self.field_name == "production" else str(self.value_input.value).strip()
            try:
                if self.field_name == "key":
                    draft["key"] = raw
                elif self.field_name == "price":
                    draft["price"] = int(raw)
                elif self.field_name == "item_kind":
                    val = raw.lower().replace("ё", "е")
                    if val not in {"предмет", "техника", "item", "tech"}:
                        raise ValueError("Укажите `предмет` или `техника`.")
                    draft["item_kind"] = "tech" if val in {"техника", "tech"} else "item"
                    if draft["item_kind"] == "tech":
                        draft["stock"] = 0
                        draft["wipe_delete"] = True; draft["save_to_library"] = True
                elif self.field_name == "tech_type":
                    if raw not in items_data.setdefault("tech_types", {}):
                        raise ValueError("Тип техники не найден. Добавьте его в !панель.")
                    draft["tech_type"] = raw
                    cfg = items_data["tech_types"][raw]
                    draft["required_item"] = str(cfg.get("required_item") or "")
                    draft["required_quantity"] = cfg.get("required_quantity", 0) or 0
                    draft["production_batch_min"] = int(cfg.get("production_batch_min", 1) or 1)
                    draft["production_seconds_per_batch"] = max(1, int(cfg.get("production_seconds_per_batch", 3600) or 3600))
                    base = int(cfg.get("min_price", 0))
                    draft["price"] = int(base * (1 + int(draft.get("tech_rating", 0)) / 100))
                elif self.field_name == "production":
                    req_item_raw = str(self.required_item_input.value or "").strip()
                    draft["required_item"] = "" if req_item_raw.lower() == "скип" else req_item_raw
                    draft["required_quantity"] = str(self.required_quantity_input.value or "0").strip()
                    draft["production_batch_min"] = max(1, int(str(self.production_batch_input.value or "1").strip()))
                elif self.field_name == "tech_rating":
                    rating = max(0, min(100, int(raw)))
                    draft["tech_rating"] = rating
                    if draft.get("tech_type") in items_data.setdefault("tech_types", {}):
                        base = int(items_data["tech_types"][draft["tech_type"]].get("min_price", 0))
                        draft["price"] = int(base * (1 + rating / 100))
                elif self.field_name == "category":
                    if raw not in items_data.get("categories", {}):
                        raise ValueError("Категория не существует")
                    draft["category"] = raw
                elif self.field_name == "stock":
                    draft["stock"] = -1 if raw.lower() == "скип" else int(raw)
                elif self.field_name == "ttl":
                    draft["expires_at"] = (
                        None if raw.lower() == "скип" else int(time.time()) + int(raw)
                    )
                elif self.field_name == "description":
                    draft["description"] = raw
                elif self.field_name == "require_roles":
                    draft["require_roles"] = parse_role_mentions(raw or "скип")
                elif self.field_name == "give_roles":
                    parsed = parse_role_mentions(raw or "скип")
                    validate_give_roles_hierarchy(parsed)
                    draft["give_roles"] = parsed
                elif self.field_name == "remove_roles":
                    draft["remove_roles"] = parse_role_mentions(raw or "скип")
                elif self.field_name == "use_text":
                    draft["use_text"] = None if raw.lower() == "скип" else (raw or None)
                elif self.field_name == "wipe_delete":
                    draft["wipe_delete"] = parse_yes_no(raw)
                elif self.field_name == "save_to_library":
                    draft["save_to_library"] = parse_yes_no(raw)
            except Exception as e:
                await interaction.response.send_message(
                    f"❌ Ошибка: {format_item_validation_error(e)}", ephemeral=True
                )
                return
            await edit_create_message(interaction)

    def tech_type_options_for_page(page: int, page_size: int = 25):
        tech_types = sorted(items_data.setdefault("tech_types", {}).items(), key=lambda x: str(x[0]).casefold())
        start = max(0, page) * page_size
        options = []
        for name, cfg in tech_types[start : start + page_size]:
            options.append(SelectOption(label=str(name)[:100], value=str(name)[:100], description=f"Минимум: {fmt_money(int(cfg.get('min_price', 0) or 0))}"[:100], emoji="🚜"))
        return options

    async def apply_tech_type(interaction: Interaction, tech_type_name: str):
        draft["tech_type"] = tech_type_name
        cfg = items_data.setdefault("tech_types", {})[tech_type_name]
        draft["required_item"] = str(cfg.get("required_item") or "")
        draft["required_quantity"] = cfg.get("required_quantity", 0) or 0
        draft["production_batch_min"] = int(cfg.get("production_batch_min", 1) or 1)
        draft["production_seconds_per_batch"] = max(1, int(cfg.get("production_seconds_per_batch", 3600) or 3600))
        base = int(cfg.get("min_price", 0))
        draft["price"] = int(base * (1 + int(draft.get("tech_rating", 0)) / 100))
        await edit_create_message(interaction)

    class TechTypeSelect(Select):
        def __init__(self, page: int = 0):
            self.page = page
            options = tech_type_options_for_page(page)
            if not options:
                options = [SelectOption(label="Типы техники не настроены", value="__none__", emoji="⚠️")]
            super().__init__(placeholder="Выберите тип техники", min_values=1, max_values=1, options=options)

        async def callback(self, interaction: Interaction):
            selected_type = self.values[0]
            if selected_type == "__none__":
                await interaction.response.send_message("❌ Сначала добавьте типы техники в `!панель`.", ephemeral=True)
                return
            await apply_tech_type(interaction, selected_type)

    class TechTypePickView(View):
        def __init__(self, page: int = 0):
            super().__init__(timeout=300)
            self.page = page
            self.add_item(TechTypeSelect(page))
            total = len(items_data.setdefault("tech_types", {}))
            if total > 25:
                prev_btn = Button(label="←", style=ButtonStyle.secondary, disabled=page <= 0)
                next_btn = Button(label="→", style=ButtonStyle.secondary, disabled=(page + 1) * 25 >= total)
                async def prev_cb(i: Interaction):
                    await i.response.edit_message(view=TechTypePickView(max(0, self.page - 1)))
                async def next_cb(i: Interaction):
                    await i.response.edit_message(view=TechTypePickView(self.page + 1))
                prev_btn.callback = prev_cb; next_btn.callback = next_cb
                self.add_item(prev_btn); self.add_item(next_btn)

    class EditSelect(Select):
        def __init__(self):
            options = [
                SelectOption(label="Ключ / название", value="key", emoji="<:name:1543296192694460567>"),
                SelectOption(label="Категория", value="category", emoji="<:kategorie:1543296268674273280>"),
            ]
            if draft.get("item_kind") == "tech":
                options.extend([
                    SelectOption(label="Тип техники", value="tech_type", emoji="<:lkw:1543296378942394529>"),
                    SelectOption(label="Оценка техники", value="tech_rating", emoji="<:stern:1543296488019595295>"),
                    SelectOption(label="Производство", value="production", emoji="<:fabrik:1543269526399881256>", description="Предмет / расход / минимум"),
                ])
            else:
                options.append(SelectOption(label="Цена", value="price", emoji="<:kosten:1543296052147519579>"))
            options.append(SelectOption(label="Количество", value="stock", emoji="<:plus:1543296630747566111>"))
            if draft.get("item_kind") != "tech":
                options.append(SelectOption(label="Время жизни", value="ttl", emoji="<:uhr:1543295815978717314>"))
            options.extend([
                SelectOption(label="Описание", value="description", emoji="<:info:1543296714621059112>"),
                SelectOption(
                    label="Обязательные роли", value="require_roles", emoji="<:turschloss:1543296783642525726>"
                ),
                SelectOption(label="Выдаёт роли", value="give_roles", emoji="<:geben:1543296937191800852>"),
                SelectOption(label="Забирает роли", value="remove_roles", emoji="<:abgeben:1543297001322586162>"),
                SelectOption(label="Текст использования", value="use_text", emoji="<:nachricht:1543297085892206734>"),
            ])
            if draft.get("item_kind") != "tech":
                options.extend([
                    SelectOption(label="Удалять при вайпе", value="wipe_delete", emoji="<:loschen:1543295744881197176>"),
                    SelectOption(label="Сохранять в библиотеку", value="save_to_library", emoji="<:sichbehalten:1543297234425090090>"),
                ])
            options.extend([
                SelectOption(label="Сохранить технику" if draft.get("item_kind") == "tech" else "Сохранить предмет", value="save", emoji="<:sichbehalten:1543297234425090090>"),
                SelectOption(label="Отмена", value="cancel", emoji="<:achtung:1543297333779898368>"),
            ])
            super().__init__(
                placeholder="Выберите пункт для редактирования",
                min_values=1,
                max_values=1,
                options=options,
            )

        async def callback(self, interaction: Interaction):
            selected = self.values[0]
            if selected == "save":
                key = draft["key"].strip()
                if draft.get("item_kind") == "tech":
                    draft["wipe_delete"] = True; draft["save_to_library"] = True
                    if not draft.get("tech_type"):
                        await interaction.response.send_message("❌ Для техники укажите тип техники.", ephemeral=True); return
                if not key or int(draft["price"]) <= 0:
                    await interaction.response.send_message(
                        "❌ Заполните ключ и цену (>0).", ephemeral=True
                    )
                    return
                if key in items_data.get("items", {}):
                    await interaction.response.send_message(
                        "❌ Предмет с таким названием уже есть.", ephemeral=True
                    )
                    return
                try:
                    validate_give_roles_hierarchy(list(draft.get("give_roles", [])))
                except Exception as e:
                    await interaction.response.send_message(f"❌ {e}", ephemeral=True)
                    return
                item_payload = {
                    "key": key,
                    "price": int(draft["price"]),
                    "description": draft["description"],
                    "category": str(draft["category"]),
                    "stock": int(draft["stock"]),
                    "expires_at": draft["expires_at"],
                    "require_roles": draft["require_roles"],
                    "give_roles": draft["give_roles"],
                    "remove_roles": draft["remove_roles"],
                    "use_text": draft["use_text"],
                    "wipe_delete": bool(draft["wipe_delete"]),
                    "save_to_library": bool(draft["save_to_library"]),
                    "created_at": int(time.time()),
                    "item_kind": draft.get("item_kind", "item"),
                    "tech_type": draft.get("tech_type", ""),
                    "tech_rating": int(draft.get("tech_rating", 0)),
                    "required_item": draft.get("required_item", ""),
                    "required_quantity": draft.get("required_quantity", 0) or 0,
                    "production_batch_min": int(draft.get("production_batch_min", 1) or 1),
                    "production_seconds_per_batch": int(draft.get("production_seconds_per_batch", 3600) or 3600),
                }
                items_data.setdefault("items", {})[key] = item_payload
                preserve_item_in_tech_library(key, item_payload, reason="создание предмета")
                save_items()
                if create_item_uses_components_v2():
                    done_view = LayoutViewBase(timeout=120)
                    container = V2Container()
                    container.add_item(V2TextDisplay(f"## <:sichbehalten:1543297234425090090> Предмет создан\nПредмет **{key}** успешно сохранён."))
                    done_view.add_item(container)
                    await interaction.response.edit_message(content=None, embed=None, view=done_view)
                else:
                    await interaction.response.edit_message(
                        content=f"<:sichbehalten:1543297234425090090> **Предмет создан**\nПредмет **{key}** успешно сохранён.",
                        embed=None,
                        view=None,
                    )
                return

            if selected == "cancel":
                if create_item_uses_components_v2():
                    cancel_view = LayoutViewBase(timeout=120)
                    container = V2Container()
                    container.add_item(V2TextDisplay("## <:achtung:1543297333779898368> Создание отменено"))
                    cancel_view.add_item(container)
                    await interaction.response.edit_message(content=None, embed=None, view=cancel_view)
                else:
                    await interaction.response.edit_message(
                        content="<:achtung:1543297333779898368> **Создание отменено**", embed=None, view=None
                    )
                return

            if selected == "tech_type":
                await interaction.response.edit_message(view=TechTypePickView(0))
                return

            await interaction.response.send_modal(EditFieldModal(selected))

    class CreateItemView(LayoutViewBase):
        def __init__(self):
            super().__init__(timeout=900)
            if create_item_uses_components_v2():
                container = V2Container()
                add_text_sections_with_separators(container, build_create_item_sections())
                self.add_item(container)
                action_row = V2ActionRow()
                action_row.add_item(EditSelect())
                self.add_item(action_row)
            else:
                self.add_item(EditSelect())

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message(
                    "❌ Только автор команды может настраивать.", ephemeral=True
                )
                return False
            return True

    class KindSelect(Select):
        def __init__(self):
            super().__init__(placeholder="Что создаём?", min_values=1, max_values=1, options=[
                SelectOption(label="Обычный предмет", value="item", emoji="<:gang:1543295967615393983>", description="Стандартный товар магазина"),
                SelectOption(label="Техника", value="tech", emoji="<:technik:1543295638656258119>", description="Товар с типом техники, оценкой и библиотекой"),
            ])

        async def callback(self, interaction: Interaction):
            draft["item_kind"] = self.values[0]
            if draft["item_kind"] == "tech":
                draft["stock"] = 0
                draft["wipe_delete"] = True
                draft["save_to_library"] = True
            await edit_create_message(interaction)

    class KindView(LayoutViewBase):
        def __init__(self):
            super().__init__(timeout=300)
            if create_item_uses_components_v2():
                container = V2Container()
                add_text_sections_with_separators(
                    container,
                    ["## 🛠️ Создание товара", "Сначала выберите сценарий: обычный предмет или техника."],
                )
                self.add_item(container)
                action_row = V2ActionRow()
                action_row.add_item(KindSelect())
                self.add_item(action_row)
            else:
                self.add_item(KindSelect())

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message("❌ Только автор команды может выбрать сценарий.", ephemeral=True)
                return False
            return True

    if create_item_uses_components_v2():
        await ctx.send(view=KindView())
    else:
        await ctx.send("🛠️ **Создание товара**\nСначала выберите сценарий: обычный предмет или техника.", view=KindView())


@bot.command()
async def магазин(ctx):
    if not items_data["items"]:
        if shop_supports_components_v2():
            view = LayoutViewBase(timeout=120)
            container = V2Container()
            container.add_item(V2TextDisplay("## 🛒 Магазин пуст\nВ магазине нет предметов."))
            view.add_item(container)
            await ctx.send(view=view)
        else:
            await ctx.send("🛒 **Магазин пуст**\nВ магазине нет предметов.")
        return

    categories = items_data["categories"]
    category_emojis = items_data.get("category_emojis", {})
    options = []
    for key, name in categories.items():
        emoji = parse_select_emoji(
            (category_emojis.get(str(key), "") or "").strip()[:64]
        )
        if emoji is not None:
            options.append(SelectOption(label=name, value=key, emoji=emoji))
        else:
            options.append(SelectOption(label=name, value=key))
    select = Select(placeholder="Выберите категорию", options=options)

    async def select_callback(interaction: Interaction):
        selected_key = select.values[0]
        category_name = categories[selected_key]

        items_list = [
            item
            for item in items_data["items"].values()
            if item["category"] == selected_key
            and bool(item.get("can_buy", True))
            and (item["expires_at"] is None or item["expires_at"] > int(time.time()))
        ]

        if not items_list:
            if shop_supports_components_v2():
                empty_view = LayoutViewBase(timeout=120)
                container = V2Container()
                container.add_item(V2TextDisplay(f"## 🛒 {category_name}\nНет доступных предметов."))
                empty_view.add_item(container)
                await interaction.response.send_message(view=empty_view, ephemeral=True)
            else:
                await interaction.response.send_message(
                    f"🛒 **{category_name}**\nНет доступных предметов.",
                    ephemeral=True,
                )
            return

        items_list.sort(key=lambda x: str(x.get("key", "")).casefold())
        # Components V2 limits the *combined* displayable text in a message to
        # 4,000 characters. It also limits a LayoutView's complete component
        # tree to 40 children. A shop page has 2 * item_count + 7 children:
        # the container, title, one display per item, separators, page footer,
        # two action rows, two navigation buttons, and the item selector.
        # Keep V2 pages at 16 items (39 children) so adding the action rows
        # cannot exceed that limit.
        component_page_limit = 3_500 if shop_supports_components_v2() else 1_800
        max_items_per_page = 16 if shop_supports_components_v2() else 25

        def component_preview_text(item: dict) -> str:
            count = "∞" if item["stock"] == -1 else str(item["stock"])
            text = format_shop_item_description(item, count)
            # One unusually long item must not make a single page invalid. Its
            # full information remains available through the item selector.
            if len(text) > component_page_limit:
                suffix = "\n-# Полное описание доступно в карточке предмета."
                text = text[: component_page_limit - len(suffix)].rstrip() + suffix
            return text

        page_item_groups = []
        current_page = []
        current_size = 0
        for item in items_list:
            item_size = len(component_preview_text(item))
            separator_size = 1 if current_page else 0
            if current_page and (
                len(current_page) >= max_items_per_page
                or current_size + separator_size + item_size > component_page_limit
            ):
                page_item_groups.append(current_page)
                current_page = []
                current_size = 0
            current_page.append(item)
            current_size += (1 if len(current_page) > 1 else 0) + item_size
        if current_page:
            page_item_groups.append(current_page)
        total_pages = len(page_item_groups)

        def page_items_for(page_index: int):
            return page_item_groups[page_index]

        def build_page_content(page_index: int):
            blocks = []
            for item in page_items_for(page_index):
                count = "∞" if item["stock"] == -1 else str(item["stock"])
                blocks.append(component_preview_text(item))
            body = "\n\n".join(blocks) if blocks else "Нет предметов."
            return f"## 🛒 {category_name}\n{body}\n-# Страница {page_index + 1}/{max(1, total_pages)}"

        def add_shop_page_container(view_obj, page_index: int):
            container = V2Container()
            container.add_item(V2TextDisplay(f"## 🛒 {category_name}"))
            page_blocks = page_items_for(page_index)
            if not page_blocks:
                container.add_item(V2TextDisplay("Нет предметов."))
            for idx, item in enumerate(page_blocks):
                count = "∞" if item["stock"] == -1 else str(item["stock"])
                if idx > 0:
                    container.add_item(V2Separator())
                container.add_item(V2TextDisplay(component_preview_text(item)))
            container.add_item(V2TextDisplay(f"-# Страница {page_index + 1}/{max(1, total_pages)}"))
            view_obj.add_item(container)

        class ShopItemInfoSelect(Select):
            def __init__(self, parent_view):
                self.parent_view = parent_view
                options = [
                    SelectOption(
                        label=str(item.get("key", "Предмет"))[:100],
                        value=str(index),
                        description=strip_legacy_tech_description(str(item.get("description") or ""))[:100] or "Полная информация",
                        emoji="ℹ️",
                    )
                    for index, item in enumerate(page_items_for(parent_view.page))
                ]
                if not options:
                    options = [SelectOption(label="Нет предметов", value="__none__", emoji="⚠️")]
                super().__init__(placeholder="Выберите предмет для полной информации", min_values=1, max_values=1, options=options)

            async def callback(self, i: Interaction):
                if self.values[0] == "__none__":
                    await i.response.send_message("❌ На этой странице нет предметов.", ephemeral=True)
                    return
                current_items = page_items_for(self.parent_view.page)
                try:
                    item = current_items[int(self.values[0])]
                except Exception:
                    item = None
                if not item:
                    await i.response.send_message("❌ Предмет не найден на текущей странице.", ephemeral=True)
                    return
                class ShopBuyModal(Modal):
                    def __init__(self):
                        super().__init__(title=f"Купить: {item.get('key', 'предмет')}", timeout=300)
                        self.qty = TextInput(label="Количество", required=True, default="1", max_length=20)
                        self.add_item(self.qty)
                    async def on_submit(self, mi: Interaction):
                        try:
                            qty = int(str(self.qty.value).strip())
                            if qty <= 0:
                                raise ValueError
                        except Exception:
                            await mi.response.send_message("❌ Введите положительное число.", ephemeral=True); return
                        price = int(item.get("price", 0)) * qty
                        confirm_view = View(timeout=120)
                        yes = Button(label="Подтвердить покупку", style=ButtonStyle.success)
                        no = Button(label="Отмена", style=ButtonStyle.secondary)
                        async def yes_cb(ci: Interaction):
                            try:
                                ok, msg = await perform_purchase(ci.user, ci.guild, str(item.get("key")), qty)
                            except discord.Forbidden:
                                ok, msg = False, "❌ Бот не может изменить роли: проверьте права и иерархию ролей."
                            await ci.response.edit_message(content=msg, view=None)
                        async def no_cb(ci: Interaction):
                            await ci.response.edit_message(content="❌ Покупка отменена.", view=None)
                        yes.callback = yes_cb; no.callback = no_cb
                        confirm_view.add_item(yes); confirm_view.add_item(no)
                        await mi.response.send_message(f"Хотите ли вы купить **{qty} × {item.get('key')}** за **{fmt_money(price)}**?", view=confirm_view, ephemeral=True)
                info_embeds = build_item_info_embeds(item, i.guild, str(item.get('key')))

                class ItemInfoActionView(View):
                    def __init__(self, page: int = 0):
                        super().__init__(timeout=180)
                        self.page = max(0, min(page, len(info_embeds) - 1))
                        if len(info_embeds) > 1:
                            previous = Button(label="⬅️", style=ButtonStyle.secondary, disabled=self.page == 0)
                            following = Button(label="➡️", style=ButtonStyle.secondary, disabled=self.page >= len(info_embeds) - 1)
                            previous.callback = lambda pi: pi.response.edit_message(embed=info_embeds[self.page - 1], view=ItemInfoActionView(self.page - 1))
                            following.callback = lambda ni: ni.response.edit_message(embed=info_embeds[self.page + 1], view=ItemInfoActionView(self.page + 1))
                            self.add_item(previous); self.add_item(following)
                        buy = Button(label="Купить предмет", style=ButtonStyle.success); buy.callback = lambda bi: bi.response.send_modal(ShopBuyModal()); self.add_item(buy)
                await i.response.send_message(embed=info_embeds[0], view=ItemInfoActionView(), ephemeral=True)

        class ShopItemInfoView(LayoutViewBase):
            def __init__(self, parent_view):
                super().__init__(timeout=120)
                if shop_supports_components_v2():
                    container = V2Container()
                    container.add_item(V2TextDisplay("Выберите предмет с текущей страницы:"))
                    self.add_item(container)
                    action_row = V2ActionRow()
                    action_row.add_item(ShopItemInfoSelect(parent_view))
                    self.add_item(action_row)
                else:
                    self.add_item(ShopItemInfoSelect(parent_view))

        class ShopPageView(LayoutViewBase):
            def __init__(self, owner_id: int, page: int = 0):
                super().__init__(timeout=300)
                self.owner_id = owner_id
                self.page = page

                back_button = Button(label="⬅️", style=ButtonStyle.gray)
                forward_button = Button(label="➡️", style=ButtonStyle.gray)
                info_select = ShopItemInfoSelect(self)
                back_button.callback = self.back_callback
                forward_button.callback = self.forward_callback

                if shop_supports_components_v2():
                    add_shop_page_container(self, self.page)
                    action_row = V2ActionRow()
                    action_row.add_item(back_button)
                    action_row.add_item(forward_button)
                    self.add_item(action_row)
                    info_row = V2ActionRow(); info_row.add_item(info_select); self.add_item(info_row)
                else:
                    self.add_item(back_button)
                    self.add_item(forward_button)
                    self.add_item(info_select)

            async def interaction_check(self, i: Interaction) -> bool:
                if i.user.id != self.owner_id:
                    await i.response.send_message(
                        "❌ Это меню не для вас.", ephemeral=True
                    )
                    return False
                return True

            async def back_callback(self, i: Interaction):
                self.page = (self.page - 1) % total_pages
                if shop_supports_components_v2():
                    await i.response.edit_message(content=None, view=ShopPageView(self.owner_id, self.page))
                else:
                    await i.response.edit_message(content=build_page_content(self.page), view=self)

            async def forward_callback(self, i: Interaction):
                self.page = (self.page + 1) % total_pages
                if shop_supports_components_v2():
                    await i.response.edit_message(content=None, view=ShopPageView(self.owner_id, self.page))
                else:
                    await i.response.edit_message(content=build_page_content(self.page), view=self)


        view_pages = ShopPageView(interaction.user.id)
        await interaction.response.send_message(
            content=None if shop_supports_components_v2() else build_page_content(0),
            view=view_pages,
            ephemeral=True,
        )

    select.callback = select_callback
    if shop_supports_components_v2():
        view = LayoutViewBase(timeout=180)
        container = V2Container()
        container.add_item(V2TextDisplay("## 🛒 Магазин\nВыберите категорию предметов ниже:"))
        view.add_item(container)
        action_row = V2ActionRow()
        action_row.add_item(select)
        view.add_item(action_row)
        await ctx.send(view=view)
    else:
        view = View(timeout=180)
        view.add_item(select)
        await ctx.send("🛒 **Магазин**\nВыберите категорию предметов ниже:", view=view)


@bot.command()
async def купить(ctx, количество: int, *, item_key: str):
    matches = resolve_item_key(item_key)
    if not matches:
        await ctx.send(embed=Embed(title="❌ Ошибка", description=f"Предмет **{item_key}** не найден.", color=0xFF0000))
        return
    selected_key = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:50]))
        await ctx.send(embed=Embed(title="🔎 Найдены совпадения", description=f"Уточните номер товара:\n{options}", color=0x3498DB))
        def check(m): return m.author == ctx.author and m.channel == ctx.channel
        try:
            msg = await bot.wait_for("message", check=check, timeout=60)
            idx = int(msg.content.strip()) - 1
            selected_key = matches[idx]
        except Exception:
            await ctx.send(embed=Embed(title="❌ Ошибка", description="Не удалось выбрать товар по номеру.", color=0xFF0000))
            return
    try:
        ok, msg = await perform_purchase(ctx.author, ctx.guild, selected_key, количество)
    except discord.Forbidden:
        ok, msg = False, "❌ Бот не может изменить роли: проверьте права и иерархию ролей."
    await ctx.send(embed=Embed(title=("💰 Покупка успешна" if ok else "❌ Ошибка"), description=msg, color=(0x00FF00 if ok else 0xFF0000)))


@bot.command()
@admin_or_command_access()
async def пополнитьпредмет(ctx, количество: int, *, item_key: str):
    if количество <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Количество должно быть больше нуля.",
                color=0xFF0000,
            )
        )
        return

    selected_key = await pick_item_key_by_query(ctx, item_key)
    if not selected_key:
        return

    item = items_data["items"].get(selected_key)
    if not item:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Предмет **{selected_key}** не найден.",
                color=0xFF0000,
            )
        )
        return

    if item["stock"] == -1:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="У предмета бесконечное количество.",
                color=0xFFA500,
            )
        )
        return

    item["stock"] += количество
    save_items()

    await ctx.send(
        embed=Embed(
            title="✅ Предмет пополнен",
            description=f"Предмет **{selected_key}** пополнен на **{количество}**. Теперь: **{item['stock']}**.",
            color=0x00FF00,
        )
    )


@bot.command()
@admin_or_command_access()
async def удалитьпредмет(ctx, *, item_key: str):
    selected_key = await pick_item_key_by_query(ctx, item_key)
    if not selected_key:
        return

    if selected_key not in items_data["items"]:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Предмет **{selected_key}** не найден.",
                color=0xFF0000,
            )
        )
        return

    item_payload = dict(items_data["items"][selected_key])
    preserve_item_in_tech_library(selected_key, item_payload, reason="ручное удаление")
    del items_data["items"][selected_key]
    save_items()

    await ctx.send(
        embed=Embed(
            title="✅ Предмет удалён",
            description=f"Предмет **{selected_key}** удалён.",
            color=0x00FF00,
        )
    )


async def show_item_info_by_query(ctx, item_query: str, *, item_kind: str | None = None):
    """Show one item card, asking the user to disambiguate partial matches."""
    matches = resolve_item_key(item_query)
    if item_kind is not None:
        matches = [
            key for key in matches
            if items_data.get("items", {}).get(key, {}).get("item_kind") == item_kind
        ]
    if not matches:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Техника не найдена." if item_kind == "tech" else "Предмет не найден.",
                color=0xFF0000,
            )
        )
        return

    selected_key = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:50]))
        await ctx.send(
            embed=Embed(
                title="🔎 Уточнение предмета",
                description=f"Найдено несколько совпадений. Выберите номер:\n\n{options}",
                color=0x3498DB,
            )
        )

        def choice_check(m):
            return m.author == ctx.author and m.channel == ctx.channel

        try:
            msg = await bot.wait_for("message", check=choice_check, timeout=60)
            idx = int(msg.content.strip()) - 1
            if idx < 0 or idx >= min(len(matches), 50):
                raise ValueError
            selected_key = matches[idx]
        except Exception:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Неверный выбор предмета.",
                    color=0xFF0000,
                )
            )
            return

    item = items_data.get("items", {}).get(selected_key)
    if not item:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Предмет не найден в базе.",
                color=0xFF0000,
            )
        )
        return

    info_embeds = build_item_info_embeds(item, ctx.guild, selected_key)
    for start in range(0, len(info_embeds), 10):
        await ctx.send(embeds=info_embeds[start : start + 10])


@bot.command(name="предметинфо")
async def предметинфо(ctx, *, item_query: str):
    await show_item_info_by_query(ctx, item_query)


@bot.command(name="техника")
async def техника(ctx, *, item_query: str):
    """Show a tech item by full or partial name."""
    await show_item_info_by_query(ctx, item_query, item_kind="tech")


@bot.command(name="редактироватьпредмет")
@admin_or_command_access()
async def редактироватьпредмет(ctx, *, item_query: str):
    selected_key = await pick_item_key_by_query(ctx, item_query)
    if not selected_key:
        return
    item = items_data.get("items", {}).get(selected_key)
    if not item:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Предмет не найден в базе.",
                color=0xFF0000,
            )
        )
        return

    draft = {
        "key": item.get("key", selected_key),
        "price": int(item.get("price", 0)),
        "category": str(item.get("category", "1")),
        "stock": int(item.get("stock", -1)),
        "expires_at": item.get("expires_at"),
        "description": item.get("description", ""),
        "require_roles": list(item.get("require_roles", [])),
        "give_roles": list(item.get("give_roles", [])),
        "remove_roles": list(item.get("remove_roles", [])),
        "use_text": item.get("use_text"),
        "wipe_delete": bool(item.get("wipe_delete", False)),
        "save_to_library": bool(item.get("save_to_library", False)),
        "item_kind": item.get("item_kind", "item"),
        "tech_type": item.get("tech_type", ""),
        "tech_rating": int(item.get("tech_rating", 0) or 0),
        "required_item": item.get("required_item", item.get("production_required_item", "")),
        "required_quantity": item.get("required_quantity", item.get("production_required_quantity", 0)) or 0,
        "production_batch_min": int(item.get("production_batch_min", item.get("min_production", 1)) or 1),
    }

    def validate_give_roles_hierarchy(role_ids: list[int]):
        if not ctx.guild:
            return
        editor_top_role = ctx.author.top_role
        for rid in role_ids:
            role = ctx.guild.get_role(int(rid))
            if role and role.position > editor_top_role.position:
                raise ValueError(
                    f"Нельзя выдавать роль {role.mention}: она выше вашей самой высокой роли ({editor_top_role.mention})."
                )

    def format_item_validation_error(err: Exception) -> str:
        if isinstance(err, ValueError):
            return str(err)
        return "Проверьте введённые данные (числа, категорию и упоминания ролей)."

    def format_roles(role_ids: list[int | str]) -> str:
        """Render item role IDs as mentions for the edit-menu preview."""
        if not role_ids:
            return "—"
        mentions = []
        for role_id in role_ids:
            role = ctx.guild.get_role(int(role_id)) if ctx.guild else None
            mentions.append(role.mention if role else f"<@&{role_id}>")
        return ", ".join(mentions)

    def build_embed():
        e = Embed(title=f"🛠 Редактирование — {selected_key}", color=0x3498DB)
        ttl_text = (
            "∞"
            if draft["expires_at"] is None
            else format_seconds_left(int(draft["expires_at"]) - int(time.time()))
        )
        stock_text = "∞" if int(draft["stock"]) == -1 else str(draft["stock"])
        cat_name = items_data.get("categories", {}).get(
            str(draft["category"]), str(draft["category"])
        )
        e.add_field(name="Сценарий", value="Техника" if draft.get("item_kind") == "tech" else "Предмет", inline=True)
        if draft.get("item_kind") == "tech":
            e.add_field(name="Тип техники", value=draft.get("tech_type") or "—", inline=True)
            e.add_field(name="Оценка", value=f"{int(draft.get('tech_rating', 0))}/100", inline=True)
            e.add_field(name="Производство", value=f"Минимум: {int(draft.get('production_batch_min', 1) or 1)}; ресурсы: {format_production_requirements(draft.get('required_item'), draft.get('required_quantity'))}", inline=False)
        e.add_field(name="Ключ", value=draft["key"] or "—", inline=True)
        e.add_field(name="Цена", value=fmt_money(draft["price"]), inline=True)
        e.add_field(name="Категория", value=cat_name, inline=True)
        e.add_field(name="Количество", value=stock_text, inline=True)
        e.add_field(name="Время жизни", value=ttl_text, inline=True)
        e.add_field(name="Описание", value=draft["description"] or "—", inline=False)
        e.add_field(
            name="Обязательные роли",
            value=format_roles(item_required_role_ids(draft)),
            inline=False,
        )
        e.add_field(
            name="Удалять ли при вайпе",
            value=bool_to_yes_no(draft["wipe_delete"]),
            inline=True,
        )
        e.add_field(
            name="Сохранять в библиотеку техники",
            value=bool_to_yes_no(draft["save_to_library"]),
            inline=True,
        )
        return e

    class EditBaseModal(Modal):
        def __init__(self):
            super().__init__(title="Основные параметры", timeout=600)
            self.key = TextInput(
                label="Ключ предмета",
                required=True,
                max_length=120,
                default=draft["key"],
            )
            self.price = TextInput(
                label="Цена", required=True, default=str(draft["price"])
            )
            self.category = TextInput(
                label="Категория (номер)", required=True, default=str(draft["category"])
            )
            self.stock = TextInput(
                label="Количество (или скип)",
                required=True,
                default=("скип" if int(draft["stock"]) == -1 else str(draft["stock"])),
            )
            ttl_default = (
                "скип"
                if draft["expires_at"] is None
                else str(max(0, int(draft["expires_at"]) - int(time.time())))
            )
            self.ttl = TextInput(
                label="Время жизни в сек (или скип)", required=True, default=ttl_default
            )
            for it in (self.key, self.price, self.category, self.stock, self.ttl):
                self.add_item(it)

        async def on_submit(self, interaction: Interaction):
            try:
                draft["key"] = str(self.key.value).strip()
                draft["price"] = int(str(self.price.value).strip())
                cat = str(self.category.value).strip()
                if cat not in items_data.get("categories", {}):
                    raise ValueError("Категория не существует")
                draft["category"] = cat
                raw_stock = str(self.stock.value).strip().lower()
                draft["stock"] = -1 if raw_stock == "скип" else int(raw_stock)
                raw_ttl = str(self.ttl.value).strip().lower()
                draft["expires_at"] = (
                    None if raw_ttl == "скип" else int(time.time()) + int(raw_ttl)
                )
            except Exception as e:
                await interaction.response.send_message(
                    f"❌ Ошибка: {format_item_validation_error(e)}", ephemeral=True
                )
                return
            await interaction.response.edit_message(embed=build_embed(), view=view)

    class EditTechModal(Modal):
        def __init__(self):
            super().__init__(title="Параметры техники", timeout=600)
            self.tech_type = TextInput(
                label="Тип техники",
                required=True,
                default=str(draft.get("tech_type") or ""),
                placeholder="Выберите/введите тип из !панель → Типы техники",
            )
            self.tech_rating = TextInput(
                label="Оценка техники (0-100)",
                required=True,
                default=str(int(draft.get("tech_rating", 0) or 0)),
            )
            self.required_item = TextInput(label="Требуемый предмет (или скип)", required=False, default=str(draft.get("required_item") or "скип"))
            self.required_quantity = TextInput(label="Кол-во ресурса на минимум", required=False, default=str(draft.get("required_quantity", 0) or 0))
            self.batch = TextInput(label="Минимум производства", required=False, default=str(int(draft.get("production_batch_min", 1) or 1)))
            self.add_item(self.tech_type)
            self.add_item(self.tech_rating)
            self.add_item(self.required_item)
            self.add_item(self.required_quantity)
            self.add_item(self.batch)

        async def on_submit(self, interaction: Interaction):
            raw_type = str(self.tech_type.value or "").strip()
            try:
                if raw_type not in items_data.setdefault("tech_types", {}):
                    raise ValueError("Такого типа техники нет. Добавьте его в `!панель` → `Типы техники`.")
                rating = max(0, min(100, int(float(str(self.tech_rating.value).replace(",", ".")))))
                draft["item_kind"] = "tech"
                draft["tech_type"] = raw_type
                draft["tech_rating"] = rating
                req_item = str(self.required_item.value or "").strip()
                draft["required_item"] = "" if req_item.lower() == "скип" else req_item
                draft["required_quantity"] = str(self.required_quantity.value or "0").strip()
                draft["production_batch_min"] = max(1, int(str(self.batch.value or "1").strip()))
                base = int(items_data["tech_types"][raw_type].get("min_price", 0) or 0)
                if base > 0:
                    draft["price"] = int(base * (1 + rating / 100))
            except Exception as e:
                await interaction.response.send_message(f"❌ Ошибка: {e}", ephemeral=True)
                return
            await interaction.response.edit_message(embed=build_embed(), view=view)

    class EditExtraModal(Modal):
        def __init__(self):
            super().__init__(title="Описание и роли", timeout=600)
            self.description = TextInput(
                label="Описание",
                required=True,
                style=discord.TextStyle.paragraph,
                max_length=1000,
                default=str(draft["description"])[:1000],
            )
            self.roles = TextInput(
                label="Роли (req|give|remove) через ;",
                required=False,
                default=f"{' '.join(f'<@&{x}>' for x in draft['require_roles'])};{' '.join(f'<@&{x}>' for x in draft['give_roles'])};{' '.join(f'<@&{x}>' for x in draft['remove_roles'])}",
            )
            self.use_text = TextInput(
                label="Текст использования (или скип)",
                required=False,
                default=(draft["use_text"] or "скип"),
            )
            self.wipe_delete = TextInput(
                label="Удалять при вайпе? (да/нет)",
                required=True,
                default=bool_to_yes_no(draft["wipe_delete"]),
            )
            self.save_to_library = TextInput(
                label="Сохранять в библиотеку? (да/нет)",
                required=True,
                default=bool_to_yes_no(draft["save_to_library"]),
            )
            self.add_item(self.description)
            self.add_item(self.roles)
            self.add_item(self.use_text)
            self.add_item(self.wipe_delete)
            self.add_item(self.save_to_library)

        async def on_submit(self, interaction: Interaction):
            draft["description"] = str(self.description.value).strip()
            raw = str(self.roles.value or "").strip()
            parts = [p.strip() for p in raw.split(";")]
            while len(parts) < 3:
                parts.append("")
            try:
                draft["require_roles"] = parse_role_mentions(parts[0] or "скип")
                parsed_give_roles = parse_role_mentions(parts[1] or "скип")
                validate_give_roles_hierarchy(parsed_give_roles)
                draft["give_roles"] = parsed_give_roles
                draft["remove_roles"] = parse_role_mentions(parts[2] or "скип")
            except Exception as e:
                await interaction.response.send_message(
                    f"❌ Ошибка: {format_item_validation_error(e)}", ephemeral=True
                )
                return
            txt = str(self.use_text.value or "").strip()
            draft["use_text"] = None if txt.lower() == "скип" else (txt or None)
            draft["wipe_delete"] = parse_yes_no(str(self.wipe_delete.value).strip())
            draft["save_to_library"] = parse_yes_no(str(self.save_to_library.value).strip())
            await interaction.response.edit_message(embed=build_embed(), view=view)

    class EditView(View):
        def __init__(self):
            super().__init__(timeout=900)

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message(
                    "❌ Только автор команды может настраивать.", ephemeral=True
                )
                return False
            return True

        @discord.ui.button(label="Основные данные", style=ButtonStyle.primary)
        async def base(self, interaction: Interaction, button: Button):
            await interaction.response.send_modal(EditBaseModal())

        @discord.ui.button(label="Описание/роли", style=ButtonStyle.primary)
        async def extra(self, interaction: Interaction, button: Button):
            await interaction.response.send_modal(EditExtraModal())

        @discord.ui.button(label="Техника", style=ButtonStyle.secondary)
        async def tech(self, interaction: Interaction, button: Button):
            if draft.get("item_kind") != "tech":
                await interaction.response.send_message("❌ Этот предмет не отмечен как техника.", ephemeral=True)
                return
            await interaction.response.send_modal(EditTechModal())

        @discord.ui.button(label="Выдаваемый ник", style=ButtonStyle.secondary)
        async def registration_nick(self, interaction: Interaction, button: Button):
            await interaction.response.send_modal(RegistrationNickModal())

        @discord.ui.button(label="✅ Сохранить", style=ButtonStyle.success)
        async def save(self, interaction: Interaction, button: Button):
            nonlocal selected_key
            old_price = int(item.get("price", 0))
            try:
                validate_give_roles_hierarchy(list(draft.get("give_roles", [])))
            except Exception as e:
                await interaction.response.send_message(
                    f"❌ Ошибка: {format_item_validation_error(e)}", ephemeral=True
                )
                return
            item.update(
                {
                    "key": draft["key"],
                    "price": int(draft["price"]),
                    "category": str(draft["category"]),
                    "stock": int(draft["stock"]),
                    "expires_at": draft["expires_at"],
                    "description": draft["description"],
                    "require_roles": draft["require_roles"],
                    "give_roles": draft["give_roles"],
                    "remove_roles": draft["remove_roles"],
                    "use_text": draft["use_text"],
                    "wipe_delete": bool(draft["wipe_delete"]),
                    "save_to_library": bool(draft["save_to_library"]),
                    "item_kind": draft.get("item_kind", "item"),
                    "tech_type": draft.get("tech_type", ""),
                    "tech_rating": int(draft.get("tech_rating", 0) or 0),
                    "required_item": draft.get("required_item", ""),
                    "required_quantity": draft.get("required_quantity", 0) or 0,
                    "production_batch_min": int(draft.get("production_batch_min", 1) or 1),
                    "production_seconds_per_batch": int(draft.get("production_seconds_per_batch", 3600) or 3600),
                }
            )
            if draft["key"] != selected_key:
                if draft["key"] in items_data.get("items", {}):
                    await interaction.response.send_message(
                        "❌ Такой ключ уже существует.", ephemeral=True
                    )
                    return
                items_data["items"][draft["key"]] = item
                del items_data["items"][selected_key]
                for uid, user_items in inventory.items():
                    if selected_key in user_items:
                        user_items[draft["key"]] = user_items.get(
                            draft["key"], 0
                        ) + user_items.pop(selected_key)
                selected_key = draft["key"]
                save_inventory()

            new_price = int(draft["price"])
            if new_price < old_price:
                diff = old_price - new_price
                refunded_total = 0
                for uid, user_items in inventory.items():
                    qty = int(user_items.get(selected_key, 0))
                    if qty > 0:
                        user_ref = ensure_user(str(uid))
                        refund = diff * qty
                        user_ref["наличка"] += refund
                        refunded_total += refund
                if refunded_total > 0:
                    save_json(BALANCES_FILE, balances)

            preserve_item_in_tech_library(selected_key, item, reason="редактирование предмета")
            save_items()
            await interaction.response.edit_message(
                embed=Embed(
                    title="✅ Предмет обновлён",
                    description=f"Сохранено: **{selected_key}**",
                    color=0x00FF00,
                ),
                view=None,
            )
            self.stop()

        @discord.ui.button(label="❌ Отмена", style=ButtonStyle.secondary)
        async def cancel(self, interaction: Interaction, button: Button):
            await interaction.response.edit_message(
                embed=Embed(title="❎ Редактирование отменено", color=0xAAAAAA),
                view=None,
            )
            self.stop()

    view = EditView()
    await ctx.send(embed=build_embed(), view=view)


@bot.command()
async def серверныйинвентарь(ctx, member: MemberQueryConverter = None):
    member = member or ctx.author
    user_id = str(member.id)
    _cleanup_expired_server_items(user_id)
    entries = server_inventory.setdefault("users", {}).get(user_id, {})

    if not entries:
        await ctx.send(
            embed=Embed(
                title="📦 Серверный инвентарь пуст",
                description=f"У {member.mention} нет активных подарочных предметов.",
                color=0xFFA500,
            )
        )
        return

    now_ts = int(time.time())
    lines = []
    for key, entry in entries.items():
        qty = int(entry.get("qty", 0))
        expires_at = entry.get("expires_at")
        ttl_txt = (
            "без срока"
            if expires_at is None
            else format_seconds_left(int(expires_at) - now_ts)
        )
        lines.append(f"**{key}** — {qty} шт. | ⏳ {ttl_txt}")

    await ctx.send(
        embed=Embed(
            title=f"📦 Серверный инвентарь — {member.display_name}",
            description="\n".join(lines),
            color=0x3498DB,
        )
    )


@bot.command()
async def инвентарь(ctx, member: MemberQueryConverter = None):
    member = member or ctx.author
    user_id = str(member.id)
    user_items = {k: int(v) for k, v in inventory.get(user_id, {}).items() if int(v or 0) > 0}
    _cleanup_expired_server_items(user_id)
    gifted_items = server_inventory.setdefault("users", {}).get(user_id, {})

    if not user_items and not gifted_items:
        if shop_supports_components_v2():
            await ctx.send(view=build_container_view("## 🎒 Инвентарь пуст", [f"У {member.mention} пока нет предметов."], timeout=120))
        else:
            await ctx.send(f"🎒 **Инвентарь пуст**\nУ {member.mention} пока нет предметов.")
        return

    categories = items_data["categories"]
    category_emojis = items_data.get("category_emojis", {})

    def category_has_items(category_key: str) -> bool:
        for key, amount in user_items.items():
            info = items_data.get("items", {}).get(key)
            if info and str(info.get("category")) == str(category_key) and amount > 0:
                return True
        return str(category_key) == "3" and any(int(e.get("qty", 0) or 0) > 0 for e in gifted_items.values() if isinstance(e, dict))

    options = []
    for key, name in categories.items():
        if not category_has_items(str(key)):
            continue
        emoji = parse_select_emoji((category_emojis.get(str(key), "") or "").strip()[:64])
        options.append(SelectOption(label=name, value=str(key), emoji=emoji) if emoji is not None else SelectOption(label=name, value=str(key)))
    if not options:
        await ctx.send("🎒 **Инвентарь пуст**\nНет предметов с известными категориями.")
        return

    def category_items_for(selected_key: str):
        result = []
        for key, amount in user_items.items():
            info = items_data.get("items", {}).get(key)
            if info and str(info.get("category")) == str(selected_key):
                result.append((key, amount, "regular", None))
        if selected_key == "3":
            now_ts = int(time.time())
            for key, entry in gifted_items.items():
                qty = int(entry.get("qty", 0) or 0)
                if qty <= 0:
                    continue
                expires_at = entry.get("expires_at")
                ttl_txt = "без срока" if expires_at is None else format_seconds_left(int(expires_at) - now_ts)
                result.append((key, qty, "gift", ttl_txt))
        return sorted(result, key=lambda x: x[0].casefold())

    class InventoryView(LayoutViewBase if shop_supports_components_v2() else View):
        def __init__(self, selected_key: str | None = None):
            super().__init__(timeout=300)
            self.selected_key = selected_key or options[0].value
            self.items = category_items_for(self.selected_key)
            self.add_content()
            if shop_supports_components_v2():
                category_row = V2ActionRow(); category_row.add_item(InventoryCategorySelect(self.selected_key)); self.add_item(category_row)
                if self.items:
                    info_row = V2ActionRow(); info_row.add_item(InventoryItemSelect(self)); self.add_item(info_row)
            else:
                self.add_item(InventoryCategorySelect(self.selected_key))
                if self.items:
                    self.add_item(InventoryItemSelect(self))

        async def interaction_check(self, interaction: Interaction) -> bool:
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True)
                return False
            return True

        def add_content(self):
            category_name = categories.get(self.selected_key, self.selected_key)
            blocks = []
            for key, amount, source_kind, ttl_txt in self.items[:20]:
                info = items_data.get("items", {}).get(key, {})
                extra = f"\n-# **Серверный подарок:** ⏳ {ttl_txt}" if source_kind == "gift" else ""
                blocks.append(f"{format_inventory_item_description(info, amount)}{extra}")
            if shop_supports_components_v2():
                container = V2Container(); container.add_item(V2TextDisplay(f"## 🎒 {category_name} — {member.display_name}"))
                for idx, block in enumerate((blocks or ["Нет предметов в этой категории."])[:12]):
                    if idx > 0: container.add_item(V2Separator())
                    container.add_item(V2TextDisplay(block))
                self.add_item(container)

    class InventoryCategorySelect(Select):
        def __init__(self, selected_key: str):
            opts = [SelectOption(label=o.label, value=o.value, emoji=o.emoji, default=o.value == selected_key) for o in options]
            super().__init__(placeholder="Выберите категорию", min_values=1, max_values=1, options=opts)
        async def callback(self, interaction: Interaction):
            await interaction.response.edit_message(content=None if shop_supports_components_v2() else None, view=InventoryView(self.values[0]))

    class InventoryItemSelect(Select):
        def __init__(self, inventory_view: InventoryView):
            self.inventory_view = inventory_view
            opts = [SelectOption(label=key[:100], value=str(idx), description=f"{amount} шт."[:100], emoji="ℹ️") for idx, (key, amount, *_rest) in enumerate(inventory_view.items[:25])]
            super().__init__(placeholder="Информация о предмете", min_values=1, max_values=1, options=opts)
        async def callback(self, interaction: Interaction):
            key, amount, source_kind, _ttl = self.inventory_view.items[int(self.values[0])]
            item = items_data.get("items", {}).get(key)
            if not item:
                await interaction.response.send_message("❌ Предмет не найден в магазине.", ephemeral=True); return
            class SellModal(Modal):
                def __init__(self):
                    super().__init__(title=f"Продать: {key}", timeout=300)
                    self.target = TextInput(label="Кому (@юз / юз / ID)", required=True, max_length=120)
                    self.qty = TextInput(label="Количество", required=True, default="1", max_length=20)
                    self.price = TextInput(label="Предложенная цена", placeholder="15000 или 10%", required=True, max_length=50)
                    self.add_item(self.target); self.add_item(self.qty); self.add_item(self.price)
                async def on_submit(self, mi: Interaction):
                    target = resolve_member_query(mi.guild, str(self.target.value)) if mi.guild else None
                    try: qty = int(str(self.qty.value).strip())
                    except Exception: qty = 0
                    if not target or target.bot:
                        await mi.response.send_message("❌ Игрок не найден.", ephemeral=True); return
                    await mi.response.defer(ephemeral=True)
                    await продать(ctx, target, qty, key, str(self.price.value))
                    await mi.followup.send("✅ Предложение продажи обработано через общий сценарий `!продать`.", ephemeral=True)
            info_embeds = build_item_info_embeds(item, interaction.guild, key)

            class ItemActionView(View):
                def __init__(self, page: int = 0):
                    super().__init__(timeout=180)
                    self.page = max(0, min(page, len(info_embeds) - 1))
                    if len(info_embeds) > 1:
                        previous = Button(label="⬅️", style=ButtonStyle.secondary, disabled=self.page == 0)
                        following = Button(label="➡️", style=ButtonStyle.secondary, disabled=self.page >= len(info_embeds) - 1)
                        previous.callback = lambda pi: pi.response.edit_message(embed=info_embeds[self.page - 1], view=ItemActionView(self.page - 1))
                        following.callback = lambda ni: ni.response.edit_message(embed=info_embeds[self.page + 1], view=ItemActionView(self.page + 1))
                        self.add_item(previous)
                        self.add_item(following)
                    sell = Button(label="Продать", style=ButtonStyle.success, disabled=(member.id != interaction.user.id or source_kind != "regular")); sell.callback = lambda bi: bi.response.send_modal(SellModal()); self.add_item(sell)
            await interaction.response.send_message(
                embed=info_embeds[0],
                view=ItemActionView(),
                ephemeral=True,
            )

    await ctx.send(content=None if shop_supports_components_v2() else f"🎒 **Инвентарь — {member.display_name}**", view=InventoryView())


@bot.command()
async def использовать(ctx, *args):
    if not args:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Использование: `!использовать <кол-во> <предмет>` или `!использовать <предмет>`.",
                color=0xFF0000,
            )
        )
        return

    количество = 1
    if str(args[0]).isdigit() and len(args) >= 2:
        количество = int(args[0])
        item_key = " ".join(args[1:]).strip()
    else:
        item_key = " ".join(args).strip()

    user_id = str(ctx.author.id)
    user_items = inventory.get(user_id, {})

    if количество <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Количество должно быть больше нуля.",
                color=0xFF0000,
            )
        )
        return

    selected_key = await pick_item_key_by_query(ctx, item_key)
    if not selected_key:
        return

    if selected_key.lower() == "альта бокс":
        if количество != 1:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="`Альта бокс` можно открывать только по 1 за раз.",
                    color=0xFF0000,
                )
            )
            return

        server_qty = get_server_item_qty(user_id, selected_key)
        regular_qty = int(user_items.get(selected_key, 0))
        total_qty = server_qty + regular_qty
        if total_qty < 1:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description=(
                        "У вас нет `Альта бокса`.\n"
                        "Если вы выдавали через старый формат `!выдать @игрок 1 альта бокс`, "
                        "предмет лежит в обычном инвентаре; используйте новый формат выдачи "
                        'с временем: `!выдать "игроки/роль/игрок" "альта бокс" "1д"`.'
                    ),
                    color=0xFF0000,
                )
            )
            return

        await ctx.send(
            embed=Embed(
                title="🎁 Альта бокс",
                description="Открываем бокс... Интрижка 5 секунд ⏳",
                color=0xF1C40F,
            )
        )
        await asyncio.sleep(5)

        rewards = get_alt_box_rewards()
        if not rewards:
            await ctx.send(
                embed=Embed(
                    title="❌ Альта бокс не настроен",
                    description="Администрация ещё не добавила ни одной награды.",
                    color=0xFF0000,
                )
            )
            return
        picked_reward = random.choices(
            rewards,
            weights=[float(r.get("chance", 0) or 0) for r in rewards],
            k=1,
        )[0]
        picked = str(picked_reward.get("name"))
        rarity_data = get_alt_box_rarity_data(picked_reward.get("rarity"))
        if server_qty >= 1:
            consumed = consume_server_item(user_id, selected_key, 1)
            if not consumed and regular_qty > 0:
                user_items[selected_key] = max(0, regular_qty - 1)
                if user_items[selected_key] <= 0:
                    del user_items[selected_key]
                save_inventory()
        else:
            user_items[selected_key] = max(0, regular_qty - 1)
            if user_items[selected_key] <= 0:
                del user_items[selected_key]
            save_inventory()
        result_embed = Embed(
            title="🌈 Альта бокс открыт!",
            description=(
                f"**Кому:** {ctx.author.mention}\n"
                f"**Награда:** **{picked}**\n"
                f"**Редкость:** {rarity_data['label']}\n\n"
                "⚠️ Бот ничего не начисляет автоматически — это текстовая награда для ручного использования."
            ),
            color=int(rarity_data["color"]),
        )
        await ctx.send(embed=result_embed)
        result_channel_id = settings.get("alt_box_result_channel")
        result_channel = ctx.guild.get_channel(int(result_channel_id)) if result_channel_id and ctx.guild else None
        if result_channel and int(result_channel.id) != int(ctx.channel.id):
            try:
                await result_channel.send(embed=result_embed)
            except Exception:
                pass
        return

    if selected_key not in user_items or int(user_items[selected_key]) < количество:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"У вас нет **{количество} × {selected_key}**.",
                color=0xFF0000,
            )
        )
        return

    item = items_data["items"].get(selected_key)
    if not item:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Предмет **{selected_key}** не найден.",
                color=0xFF0000,
            )
        )
        return

    required_role_ids = item_required_role_ids(item)
    missing_roles = []
    for rid in dict.fromkeys(required_role_ids):
        role = ctx.guild.get_role(int(rid))
        if role and role not in ctx.author.roles:
            missing_roles.append(role.mention)

    if missing_roles:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Требуются роли: {', '.join(missing_roles)}",
                color=0xFF0000,
            )
        )
        return

    user_items[selected_key] -= количество
    if user_items[selected_key] <= 0:
        del user_items[selected_key]
    save_inventory()

    for rid in item.get("give_roles", []):
        role = ctx.guild.get_role(rid)
        if role:
            await ctx.author.add_roles(role)

    for rid in item.get("remove_roles", []):
        role = ctx.guild.get_role(rid)
        if role:
            await ctx.author.remove_roles(role)

    use_text = item.get("use_text") or "✅"
    await ctx.send(
        embed=Embed(
            title=f"🎁 Использован предмет — {selected_key}",
            description=f"{ctx.author.mention} использовал **{количество} × {selected_key}**.\n{use_text}",
            color=0x00FF00,
        )
    )



async def pick_item_key_by_query_interaction(
    interaction: Interaction,
    item_query: str,
    *,
    item_kind: str | None = None,
    not_found_description: str | None = None,
):
    matches = resolve_item_key(item_query)
    if item_kind is not None:
        matches = [
            key for key in matches
            if items_data.get("items", {}).get(key, {}).get("item_kind") == item_kind
        ]
    if not matches:
        embed = Embed(
            title="❌ Ошибка",
            description=not_found_description or f"Предмет **{item_query}** не найден в магазине.",
            color=0xFF0000,
        )
        if interaction.response.is_done():
            await interaction.followup.send(embed=embed, ephemeral=True)
        else:
            await interaction.response.send_message(embed=embed, ephemeral=True)
        return None

    selected_key = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:50]))
        embed = Embed(
            title="🔎 Уточнение предмета",
            description=f"Найдено несколько совпадений. Выберите номер:\n\n{options}",
            color=0x3498DB,
        )
        if interaction.response.is_done():
            await interaction.followup.send(embed=embed, ephemeral=True)
        else:
            await interaction.response.send_message(embed=embed, ephemeral=True)

        def choice_check(m):
            return m.author == interaction.user and m.channel == interaction.channel

        try:
            msg = await bot.wait_for("message", check=choice_check, timeout=60)
            idx = int(msg.content.strip()) - 1
            if idx < 0 or idx >= min(len(matches), 50):
                raise ValueError
            selected_key = matches[idx]
        except Exception:
            await interaction.followup.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Неверный выбор предмета.",
                    color=0xFF0000,
                ),
                ephemeral=True,
            )
            return None
    return selected_key

async def pick_item_key_by_query(ctx, item_query: str):
    matches = resolve_item_key(item_query)
    if not matches:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Предмет **{item_query}** не найден.",
                color=0xFF0000,
            )
        )
        return None

    selected_key = matches[0]
    if len(matches) > 1:
        options = "\n".join(f"{i+1} — {name}" for i, name in enumerate(matches[:50]))
        await ctx.send(
            embed=Embed(
                title="🔎 Уточнение предмета",
                description=f"Найдено несколько совпадений. Выберите номер:\n\n{options}",
                color=0x3498DB,
            )
        )

        def choice_check(m):
            return m.author == ctx.author and m.channel == ctx.channel

        try:
            msg = await bot.wait_for("message", check=choice_check, timeout=60)
            idx = int(msg.content.strip()) - 1
            if idx < 0 or idx >= min(len(matches), 50):
                raise ValueError
            selected_key = matches[idx]
        except Exception:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Неверный выбор предмета.",
                    color=0xFF0000,
                )
            )
            return None
    return selected_key


@bot.command()
@admin_or_command_access()
async def выдать(ctx, target: str, количество_или_предмет: str, *rest: str):
    # Старый формат: !выдать @Игрок 2 Предмет
    # Новый формат (подарки сервера): !выдать "игроки/роль/игрок" "альта бокс" "1д"
    if str(количество_или_предмет).isdigit() and rest:
        количество = int(количество_или_предмет)
        if количество <= 0:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Количество должно быть больше нуля.",
                    color=0xFF0000,
                )
            )
            return

        member = parse_member_ref(ctx.guild, target)
        if not member:
            await ctx.send(
                embed=Embed(
                    title="❌ Ошибка",
                    description="Для количественной выдачи укажите одного игрока (упоминание/ID).",
                    color=0xFF0000,
                )
            )
            return

        item_key = " ".join(rest).strip()
        selected_key = await pick_item_key_by_query(ctx, item_key)
        if not selected_key:
            return

        if selected_key.lower() == "альта бокс":
            # resolved merge: для Альта бокса в старом режиме выдачи всегда даём подсказку по TTL-формату
            await ctx.send(
                embed=Embed(
                    title="⚠️ Нужен формат с временем",
                    description=(
                        "`Альта бокс` нельзя выдавать старым количественным форматом.\n"
                        'Используйте: `!выдать "игроки/роль/игрок" "альта бокс" "1д"`.'
                    ),
                    color=0xFFA500,
                )
            )
            return

        user_id = str(member.id)
        inventory.setdefault(user_id, {})
        inventory[user_id][selected_key] = (
            int(inventory[user_id].get(selected_key, 0)) + количество
        )
        save_inventory()

        await ctx.send(
            embed=Embed(
                title="✅ Предмет выдан",
                description=f"**Администратор:** {ctx.author.mention}\n**Получатель:** {member.mention}\n**Предмет:** {selected_key}\n**Количество:** {количество}",
                color=0x00FF00,
            )
        )
        return

    item_key = str(количество_или_предмет).strip()
    ttl_raw = " ".join(rest).strip()
    selected_key = await pick_item_key_by_query(ctx, item_key)
    if not selected_key:
        return

    if selected_key.lower() != "альта бокс":
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Формат без количества поддерживается только для `Альта бокс`.",
                color=0xFF0000,
            )
        )
        return

    if not ttl_raw:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Укажите время использования (например: `1д`, `12ч`, `3600с`).",
                color=0xFF0000,
            )
        )
        return

    try:
        ttl_seconds = parse_interval(ttl_raw)
        if ttl_seconds <= 0:
            raise ValueError
    except Exception:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Некорректное время. Пример: `1д`, `12ч`, `30м`.",
                color=0xFF0000,
            )
        )
        return

    targets = []
    target_clean = target.strip()
    role_match = re.match(r"^<@&(\d+)>$", target_clean)
    if target_clean.lower() == "игроки":
        targets = [m for m in ctx.guild.members if not m.bot]
    elif role_match:
        role = ctx.guild.get_role(int(role_match.group(1)))
        if role:
            targets = [m for m in role.members if not m.bot]
    else:
        member = parse_member_ref(ctx.guild, target_clean)
        if member and not member.bot:
            targets = [member]

    if not targets:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Не удалось определить получателей. Используйте `игроки`, упоминание роли или игрока.",
                color=0xFF0000,
            )
        )
        return

    expires_at = int(time.time()) + ttl_seconds
    changed = 0
    for member in targets:
        uid = str(member.id)
        user_slots = server_inventory.setdefault("users", {}).setdefault(uid, {})
        slot = user_slots.get(
            selected_key,
            {"qty": 0, "expires_at": expires_at, "issued_by": str(ctx.author.id)},
        )
        slot["qty"] = int(slot.get("qty", 0)) + 1
        slot["expires_at"] = max(int(slot.get("expires_at", expires_at)), expires_at)
        slot["issued_by"] = str(ctx.author.id)
        user_slots[selected_key] = slot
        changed += 1

    if changed > 0:
        save_server_inventory()

    await ctx.send(
        embed=Embed(
            title="✅ Альта боксы выданы",
            description=(
                f"**Администратор:** {ctx.author.mention}\n"
                f"**Предмет:** {selected_key}\n"
                f"**Получателей:** {changed}\n"
                f"**Срок использования:** {format_interval(ttl_seconds)}"
            ),
            color=0x00FF00,
        )
    )


@bot.command()
@admin_or_command_access()
async def изъять(ctx, member: MemberQueryConverter, количество: int, *, item_key: str):
    if количество <= 0:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description="Количество должно быть больше нуля.",
                color=0xFF0000,
            )
        )
        return

    user_id = str(member.id)
    user_items = inventory.get(user_id, {})

    selected_key = await pick_item_key_by_query(ctx, item_key)
    if not selected_key:
        return

    if selected_key not in user_items:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"У {member.mention} нет предмета **{selected_key}**.",
                color=0xFF0000,
            )
        )
        return

    if user_items[selected_key] < количество:
        await ctx.send(
            embed=Embed(
                title="❌ Ошибка",
                description=f"Недостаточно предметов. Есть: {user_items[selected_key]}",
                color=0xFF0000,
            )
        )
        return

    user_items[selected_key] -= количество
    if user_items[selected_key] <= 0:
        del user_items[selected_key]
    save_inventory()

    await ctx.send(
        embed=Embed(
            title="⚠️ Предмет изъят",
            description=f"**Администратор:** {ctx.author.mention}\n**Игрок:** {member.mention}\n**Предмет:** {selected_key}\n**Количество:** {количество}",
            color=0xFFA500,
        )
    )


