@bot.command(name="вайп")
@admin_or_command_access()
async def wipe_all(ctx):
    backup = {
        "time": int(time.time()),
        "balances": make_json_snapshot(balances),
        "inventory": make_json_snapshot(inventory),
        "population": load_json(POPULATION_FILE, {}),
        "player_stats": load_json(PLAYER_STATS_FILE, {}),
        "passive_flows": make_json_snapshot(passive_flows),
        "season_user_progress": make_json_snapshot(seasons_data.get("season_user_progress", {})),
        "player_state": make_json_snapshot(player_state),
        "investments": make_json_snapshot(investments),
        "companies": make_json_snapshot(companies_data),
        "country_owners": make_json_snapshot(country_owners),
        "items": make_json_snapshot(items_data),
        "verdicts": make_json_snapshot(verdicts_data),
        "relations": make_json_snapshot(relations_data),
        "factories": make_json_snapshot(factories_data),
        "stats_library": make_json_snapshot(stats_library),
        "members": {
            str(m.id): {"role_ids": [r.id for r in m.roles if r != ctx.guild.default_role and not r.managed], "nick": m.nick}
            for m in ctx.guild.members
            if not m.bot
        },
    }
    save_json(WIPE_BACKUP_FILE, backup)

    class ConfirmView(View):
        def __init__(self):
            super().__init__(timeout=None)

        async def interaction_check(self, interaction: Interaction):
            if interaction.user.id != ctx.author.id:
                await interaction.response.send_message(
                    "❌ Только инициатор команды может подтвердить вайп.",
                    ephemeral=True,
                )
                return False
            return True

        @discord.ui.button(label="✅ Подтвердить", style=ButtonStyle.danger)
        async def confirm(self, interaction: Interaction, button: Button):
            active_global_wipe["cancel_requested"] = False
            try:
                await interaction.response.defer()
            except Exception:
                pass

            for uid, data in list(balances.items()):
                if uid == "валюта" or not isinstance(data, dict):
                    continue
                balances[uid] = {
                    "наличка": 0,
                    "банк": 0,
                    "заморожено": 0,
                    "коины": int(data.get("коины", 0)),
                }
            balances["валюта"] = currency
            inventory.clear()
            save_json(BALANCES_FILE, balances)
            save_inventory()
            save_json(POPULATION_FILE, {})
            save_json(PLAYER_STATS_FILE, {})
            passive_flows["users"] = {}
            save_passive_flows()
            seasons_data["season_user_progress"] = {}
            save_seasons_data()
            pre_reg_roles_map = {
                str(uid): list((data or {}).get("pre_reg_role_ids", []))
                for uid, data in player_state.get("users", {}).items()
                if isinstance(data, dict)
            }
            moderator_audit_state_map = {
                str(uid): {
                    "admin_counters": dict((data or {}).get("admin_counters", {})),
                    "moderator_actions": (data or {}).get("moderator_actions"),
                    "admin_actions": (data or {}).get("admin_actions"),
                }
                for uid, data in player_state.get("users", {}).items()
                if isinstance(data, dict)
            }
            registered_user_ids = get_all_registered_user_ids()
            player_state["users"] = {}
            for uid, audit_state in moderator_audit_state_map.items():
                preserve_moderator_audit_fields(uid, audit_state)
            reset_investment_runtime(reset_rp_year=True)
            companies_data["companies"] = {}
            companies_data["requests"] = {}
            companies_data["next_company_id"] = 1
            companies_data["next_request_id"] = 1
            factories_data["users"] = {}
            factories_data["next_id"] = 1
            verdicts_data["requests"] = {}
            verdicts_data["next_id"] = 1
            save_verdicts_data()
            relations_channel_id = relations_data.get("channel_id")
            relations_data["relations"] = {}
            relations_data["pending_names"] = {}
            relations_data["changes"] = []
            relations_data["channel_id"] = relations_channel_id
            save_relations_data()
            country_owners["country_to_user"] = {}
            country_owners["user_to_country"] = {}
            country_owners["season_country_to_user"] = {}
            country_owners["season_user_to_country"] = {}
            country_owners["user_profiles"] = {}
            country_owners["orphaned_country_stats"] = {}
            country_owners["legacy_registration_migration_done"] = True
            stats_library["countries"] = {}
            removed_shop_items = 0
            for item_key in list(items_data.setdefault("items", {}).keys()):
                payload = items_data["items"].get(item_key, {})
                if not bool(payload.get("wipe_delete", False)):
                    continue
                preserve_item_in_tech_library(item_key, payload, reason="вайп")
                items_data["items"].pop(item_key, None)
                removed_shop_items += 1
            save_player_state()
            save_investments()
            save_companies_data()
            save_factories_data()
            save_country_owners()
            save_stats_library()
            save_relations_data()
            save_items()

            for m in ctx.guild.members:
                if active_global_wipe.get("cancel_requested"):
                    await restore_global_wipe_backup(ctx, backup, title="♻️ ГЛОБАЛЬНЫЙ ВАЙП ПРЕРВАН")
                    try:
                        await interaction.message.edit(embed=Embed(title="♻️ ГЛОБАЛЬНЫЙ ВАЙП ПРЕРВАН", description="Команда !отменитьвайп остановила вайп и восстановила данные.", color=0x00FF00), view=None)
                    except Exception:
                        pass
                    self.stop()
                    return
                if m.bot or str(m.id) not in registered_user_ids:
                    continue
                try:
                    await restore_member_roles_after_wipe(
                        m,
                        pre_reg_roles_map.get(str(m.id), []),
                        reason="Глобальный вайп",
                    )
                    await m.edit(nick=None, reason="Глобальный вайп")
                except Exception:
                    pass

            try:
                await interaction.message.edit(
                    embed=Embed(
                        title="💥 ГЛОБАЛЬНЫЙ ВАЙП ВЫПОЛНЕН",
                        description=(
                            "Обнулены балансы, инвентари, население, пассивные операции, прогресс сфер, компании, вердикты и счётчик постов.\n"
                            f"Из магазина удалено предметов по флагу вайпа: **{removed_shop_items}**."
                        ),
                        color=0x00FF00,
                    ),
                    view=None,
                )
            except Exception:
                pass
            self.stop()

        @discord.ui.button(label="❌ Отмена", style=ButtonStyle.secondary)
        async def cancel(self, interaction: Interaction, button: Button):
            try:
                await interaction.response.edit_message(
                    embed=Embed(title="❎ ВАЙП ОТМЕНЁН", color=0xAAAAAA), view=None
                )
            except Exception:
                try:
                    await interaction.message.edit(
                        embed=Embed(title="❎ ВАЙП ОТМЕНЁН", color=0xAAAAAA), view=None
                    )
                except Exception:
                    pass
            self.stop()

    await ctx.send(
        embed=Embed(
            title="⚠️ ПОДТВЕРЖДЕНИЕ ГЛОБАЛЬНОГО ВАЙПА",
            description=(
                "Нажмите ✅ чтобы подтвердить или ❌ чтобы отменить.\n\n"
                "После вайпа можно вернуть данные командой **!отменитьвайп** в течение **1 часа**."
            ),
            color=0xFF0000,
        ),
        view=ConfirmView(),
    )


