def parse_event_date_to_ts(raw: str) -> int | None:
    raw = str(raw or "").strip()
    if not raw:
        return None
    formats = ("%d.%m.%Y %H:%M", "%d.%m.%Y")
    last_error = None
    for fmt in formats:
        try:
            dt = datetime.strptime(raw, fmt)
            if fmt == "%d.%m.%Y":
                dt = dt.replace(hour=23, minute=59)
            return int(dt.replace(second=0, microsecond=0, tzinfo=timezone.utc).timestamp())
        except ValueError as e:
            last_error = e
    raise last_error or ValueError("Дата должна быть в формате ДД.ММ.ГГГГ или ДД.ММ.ГГГГ ЧЧ:ММ")

def event_schedule_text(ts: int | None) -> str:
    return f"<t:{int(ts)}:D>" if ts else "сразу"

def parse_member_ids_text(guild: discord.Guild, text: str) -> tuple[list[int], list[str]]:
    ids, unknown = [], []
    members = [m for m in (guild.members if guild else []) if not m.bot]
    by_name = {}
    for member in members:
        for alias in {member.name, member.display_name, str(member)}:
            if alias:
                by_name[alias.lstrip("@").casefold()] = member
    for token in re.split(r"[\s,;]+", str(text or "")):
        token = token.strip()
        if not token:
            continue
        member = None
        mid_text = parse_discord_id_token(token)
        if mid_text and guild:
            member = guild.get_member(int(mid_text))
        if member is None:
            member = by_name.get(token.lstrip("@").casefold())
        if member:
            ids.append(int(member.id))
        else:
            unknown.append(token)
    return list(dict.fromkeys(ids)), unknown

def member_has_event_stat(member_id: int, stat_names: list[str]) -> bool:
    if not stat_names:
        return False
    uid = str(member_id)
    st = ensure_player_state(uid)
    active = seasons_data.get("active_season")
    progress = get_user_progress_for_season(uid, active)
    profile = country_owners.setdefault("user_profiles", {}).get(uid, {})
    country_aliases = set()
    if isinstance(profile, dict):
        for reg in (profile.get("registrations", {}) or {}).values():
            if isinstance(reg, dict) and reg.get("country"):
                country_aliases.add(str(reg.get("country")).strip().casefold())
    for user_map in country_owners.setdefault("season_user_to_country", {}).values():
        if isinstance(user_map, dict) and user_map.get(uid):
            country_aliases.add(str(user_map.get(uid)).strip().casefold())
    available = {
        "счастье": int(st.get("happiness", 50)), "репутация": int(st.get("reputation", 50)),
        "наука": int(st.get("science", 0)), "армия": int(st.get("soldiers", 0)),
        "население": int(load_json(POPULATION_FILE, {}).get(uid, 0)),
    }
    sphere_names = {str(sp.get("name", "")).strip().casefold(): sid for sid, sp in seasons_data.get("spheres", {}).items()}
    for raw in stat_names:
        q = str(raw).strip().casefold()
        if not q:
            continue
        if q in available and available[q] > 0:
            return True
        if q in country_aliases:
            return True
        sid = sphere_names.get(q)
        if sid and int(progress.get(str(sid), 0) or 0) > 0:
            return True
    return False

def build_event_player_embed(req: dict, page: int = 0):
    options = req.get("options", [])
    total = max(1, math.ceil(len(options) / 5))
    page = max(0, min(page, total - 1))
    start = page * 5
    end = start + 5
    chunk = options[start:end]

    main_description = (req.get("main_description") or "").strip()
    embed_description = "Выберите вариант в меню ниже и нажмите **Отправить выбор**."
    if main_description:
        embed_description = (
            f"**Описание ивента:**\n{main_description}\n\n"
            "Выберите вариант в меню ниже и нажмите **Отправить выбор**."
        )

    embed = Embed(
        title="🎯 Ивент: выберите один вариант",
        description=embed_description,
        color=0x5865F2,
    )
    for idx, option in enumerate(chunk, start=start + 1):
        embed.add_field(
            name=f"{idx}. {option.get('title', 'Без названия')}",
            value=option.get("description", "—"),
            inline=False,
        )

    selected_idx = req.get("selected_index")
    selected_text = "Не выбран"
    if isinstance(selected_idx, int) and 0 <= selected_idx < len(options):
        selected_text = options[selected_idx].get("title", "Без названия")

    embed.set_footer(text=f"Страница {page + 1}/{total} • Выбранный вариант: {selected_text}")
    return embed, total


def get_event_access_mentions(guild: discord.Guild):
    access = get_command_access("ивенты")
    mentions = []
    for role_id in access.get("roles", []):
        role = guild.get_role(int(role_id)) if str(role_id).isdigit() else None
        if role:
            mentions.append(role.mention)
    for user_id in access.get("users", []):
        member = guild.get_member(int(user_id)) if str(user_id).isdigit() else None
        if member:
            mentions.append(member.mention)
    return " ".join(dict.fromkeys(mentions))


class EventOptionModal(Modal):
    def __init__(self, owner_view: "EventOptionsFillView", option_number: int):
        super().__init__(title=f"Вариант {option_number}")
        self.owner_view = owner_view
        self.option_number = option_number
        existing = owner_view.options_map.get(option_number - 1, {})

        self.title_input = TextInput(
            label="Название",
            placeholder="Введите название варианта",
            required=True,
            max_length=100,
            default=existing.get("title", ""),
        )
        self.description_input = TextInput(
            label="Описание",
            style=discord.TextStyle.paragraph,
            placeholder="Введите описание варианта",
            required=True,
            max_length=500,
            default=existing.get("description", ""),
        )
        self.add_item(self.title_input)
        self.add_item(self.description_input)

    async def on_submit(self, interaction: Interaction):
        title = str(self.title_input.value).strip()
        description = str(self.description_input.value).strip()
        if not title or not description:
            await interaction.response.send_message("❌ Заполните название и описание.", ephemeral=True)
            return

        self.owner_view.options_map[self.option_number - 1] = {
            "title": title,
            "description": description,
        }
        self.owner_view.sync_send_button_state()

        if self.owner_view.message:
            await self.owner_view.message.edit(embed=self.owner_view.build_embed(), view=self.owner_view)

        await interaction.response.send_message(
            f"✅ Вариант {self.option_number} сохранён.", ephemeral=True
        )


