class ServerEventSetupView(View):
    def __init__(self, existing: dict | None = None):
        super().__init__(timeout=600)
        existing = existing or {}
        self.message = None
        self.channel_id = str(existing.get("channel_id") or "")
        self.description = str(existing.get("description") or "")
        self.schedule_date = str(existing.get("schedule_date") or "")
        self.roles_text = str(existing.get("roles_text") or "")
        self.players_text = str(existing.get("players_text") or "")
        self.stats_text = str(existing.get("stats_text") or "")
        self.effects = dict(existing.get("effects") or {})
        for label, style, cid, cb in (("Основное", ButtonStyle.secondary, "server_event:main", self.open_main),("Цели", ButtonStyle.secondary, "server_event:targets", self.open_targets),("Эффекты", ButtonStyle.primary, "server_event:effects", self.open_effects)):
            b=Button(label=label, style=style, custom_id=cid); b.callback=cb; self.add_item(b)
        send=Button(label="Запустить/запланировать", style=ButtonStyle.success, custom_id="server_event:send", disabled=True); send.callback=self.send_event; self.add_item(send)
        self.sync_send_button_state()

    def sync_send_button_state(self):
        ready = bool(self.channel_id and self.description and self.effects and (self.roles_text or self.players_text or self.stats_text))
        for c in self.children:
            if isinstance(c, Button) and c.custom_id == "server_event:send": c.disabled = not ready

    def build_embed(self):
        effects = "\n".join(f"• {server_event_effect_label(k)}: {v.get('amount')} / {v.get('cooldown_text')} / {v.get('duration_text')} / {v.get('description') or 'серверный ивент'}" for k,v in self.effects.items()) or "—"
        return Embed(title="🌍 Настройка серверного ивента", description=f"**Канал:** {self.channel_id or '—'}\n**Дата:** {self.schedule_date or 'сразу'}\n**Описание:** {self.description or '—'}\n\n**Роли:** {self.roles_text or '—'}\n**Игроки:** {self.players_text or '—'}\n**Статы/сферы:** {self.stats_text or '—'}\n\n**Эффекты:**\n{effects}", color=0x9B59B6)

    async def open_main(self, interaction): await interaction.response.send_modal(ServerEventMainModal(self))
    async def open_targets(self, interaction): await interaction.response.send_modal(ServerEventTargetsModal(self))
    async def open_effects(self, interaction): await interaction.response.send_message("Выберите эффект:", view=ServerEventEffectView(self), ephemeral=True)

    def to_request(self, interaction):
        return {"type":"server", "guild_id": interaction.guild.id, "creator_id": interaction.user.id, "channel_id": self.channel_id, "description": self.description, "schedule_date": self.schedule_date, "send_at": parse_server_event_rp_date_to_ts(self.schedule_date) if self.schedule_date else None, "roles_text": self.roles_text, "players_text": self.players_text, "stats_text": self.stats_text, "effects": self.effects, "created_at": int(time.time())}

    async def send_event(self, interaction):
        req = self.to_request(interaction)
        if req.get("send_at") and req["send_at"] > int(time.time()):
            sid=str(events_data.get("next_id",1)); events_data["next_id"]=int(events_data.get("next_id",1))+1; req["id"]=sid; req["status"]="scheduled"; events_data.setdefault("scheduled",{})[sid]=req; save_events_data()
            await interaction.response.send_message(f"✅ Серверный ивент запланирован на {server_event_schedule_text(req)}. ID `{sid}`", ephemeral=True); return
        ok, msg = await publish_server_event(interaction.guild, req)
        await interaction.response.send_message(msg, ephemeral=True)


async def publish_server_event(guild: discord.Guild, req: dict) -> tuple[bool, str]:
    if not guild:
        return False, "❌ Сервер не найден."
    channel = resolve_channel_from_text(guild, str(req.get("channel_id") or ""))
    if not channel:
        return False, "❌ Канал публикации не найден. Укажите канал как #канал, <#id>, id/<id> или ID."
    role_ids, _ = parse_role_ids_from_text(guild, req.get("roles_text", ""))
    user_ids, unknown_users = parse_member_ids_text(guild, req.get("players_text", ""))
    stat_names = [x.strip() for x in re.split(r"[,;\n]+", str(req.get("stats_text") or "")) if x.strip()]
    members = []
    for rid in role_ids:
        role = guild.get_role(int(rid))
        if role:
            members.extend([m for m in role.members if not m.bot])
    for uid in user_ids:
        member = guild.get_member(int(uid))
        if member and not member.bot:
            members.append(member)
    if stat_names:
        for member in await fetch_human_members(guild):
            if member_has_event_stat(member.id, stat_names):
                members.append(member)
    members = list({m.id: m for m in members}.values())
    if not members:
        extra = f" Не распознано игроков: {', '.join(unknown_users[:5])}." if unknown_users else ""
        return False, "❌ Не найдено ни одного участника." + extra
    now_ts = int(time.time())
    effects = req.get("effects") or {}
    em = Embed(title="🌍 Серверный ивент", description=str(req.get("description") or "—"), color=0x9B59B6)
    em.add_field(name="Участники", value=f"{len(members)} игроков", inline=True)
    em.add_field(name="Цели", value=(req.get("roles_text") or req.get("players_text") or req.get("stats_text") or "—")[:1024], inline=False)
    lines = [f"• {server_event_effect_label(k)}: {v.get('amount')} раз в {v.get('cooldown_text')} (срок: {v.get('duration_text')}; описание: {v.get('description') or 'серверный ивент'})" for k, v in effects.items()]
    em.add_field(name="Эффекты", value="\n".join(lines) or "—", inline=False)
    mentions = " ".join([f"<@&{rid}>" for rid in role_ids] + [m.mention for m in members if m.id in user_ids])
    event_message = await channel.send(content=mentions or None, embed=em, allowed_mentions=discord.AllowedMentions(roles=True, users=True))
    event_url = getattr(event_message, "jump_url", "")
    event_id = str(req.get("id") or "")
    for member in members:
        uid = str(member.id)
        st = ensure_player_state(uid)
        for kind, data in effects.items():
            cooldown = int(data.get("cooldown") or 86400)
            dur_raw = str(data.get("duration_text") or "скип").strip().lower()
            expires_at = None if dur_raw in {"", "скип", "нет", "∞"} else now_ts + parse_interval(dur_raw)
            amount = str(data.get("amount") or "0")
            source = {"description": str(data.get("description") or "серверный ивент").strip() or "серверный ивент", "source_event_id": event_id, "source_event_url": event_url}
            if kind in {"income", "expense"}:
                get_passive_entries(uid).append({"type": kind, "amount": amount, "cooldown": cooldown, "last_run": now_ts, "expires_at": expires_at, **source})
            elif kind in {"happiness", "reputation"}:
                st.setdefault("stat_passives", []).append({"stat": kind, "amount": int(float(amount.replace(',', '.'))), "cooldown": cooldown, "last_run": now_ts, "expires_at": expires_at, **source})
            elif kind == "population":
                st.setdefault("population_passives", []).append({"amount": amount, "cooldown": cooldown, "last_run": now_ts, "expires_at": expires_at, **source})
    save_passive_flows(); save_player_state()
    return True, f"✅ Серверный ивент опубликован для {len(members)} участников."


