def build_scheduled_events_embed():
    items = events_data.setdefault("scheduled", {})
    lines = []
    for sid, req in sorted(items.items(), key=lambda x: int((x[1] or {}).get("send_at") or 0))[:25]:
        kind = "сервер" if req.get("type") == "server" else "игрок"
        schedule = server_event_schedule_text(req) if req.get("type") == "server" else event_schedule_text(req.get("send_at"))
        description = str(req.get("description") or req.get("main_description") or "—")[:60]
        lines.append(f"`{sid}` • {kind} • {schedule} • {description}")
    return Embed(title="🗓️ Запланированные ивенты", description="\n".join(lines) or "Запланированных ивентов нет.", color=0x5865F2)


