class ScheduledEventActionView(View):
    def __init__(self, req_id: str):
        super().__init__(timeout=180); self.req_id=str(req_id)
    @discord.ui.button(label="▶️ Начать досрочно", style=ButtonStyle.success)
    async def start_now(self, interaction: Interaction, button: Button):
        req = events_data.setdefault("scheduled", {}).pop(self.req_id, None)
        if not req:
            await interaction.response.send_message("❌ Ивент не найден.", ephemeral=True); return
        if req.get("type") == "server":
            ok, msg = await publish_server_event(interaction.guild, req)
        else:
            ok, msg = await send_player_event_request(interaction.guild, req)
        req["status"] = "sent" if ok else "schedule_failed"; save_events_data()
        await interaction.response.send_message(msg, ephemeral=True)
    @discord.ui.button(label="✏️ Продолжить редактирование", style=ButtonStyle.primary)
    async def edit(self, interaction: Interaction, button: Button):
        req = events_data.setdefault("scheduled", {}).get(self.req_id)
        if not req:
            await interaction.response.send_message("❌ Ивент не найден.", ephemeral=True); return
        if req.get("type") == "server":
            view = ServerEventSetupView(req)
            await interaction.response.send_message(embed=view.build_embed(), view=view, ephemeral=True)
            view.message = await interaction.original_response()
        else:
            await interaction.response.send_message("ℹ️ Для ивента игроку можно начать досрочно; повторное редактирование вариантов пока выполняется через создание нового ивента.", ephemeral=True)


