def grant_factories_to_user(user_id: str, amount: int) -> list[str]:
    uid = str(user_id)
    created_ids: list[str] = []
    factories = factories_data.setdefault("users", {}).setdefault(uid, [])
    for _ in range(max(0, int(amount))):
        fid = str(factories_data.setdefault("next_id", 1))
        factories_data["next_id"] = int(fid) + 1
        factories.append({"id": fid, "status": "free", "busy_until": 0})
        created_ids.append(fid)
    save_factories_data()
    snapshot_player_statistics(uid, reason="admin_grant_factories")
    return created_ids


def take_factories_from_user(user_id: str, amount: int) -> list[str]:
    uid = str(user_id)
    factories = factories_data.setdefault("users", {}).setdefault(uid, [])
    amount = max(0, int(amount))
    removed = factories[-amount:] if amount else []
    if amount:
        del factories[-amount:]
    save_factories_data()
    snapshot_player_statistics(uid, reason="admin_take_factories")
    return [str(factory.get("id")) for factory in removed]


@bot.command(name="выдать-завод")
@admin_or_command_access()
async def выдать_завод(ctx, member: MemberQueryConverter, amount: int = 1):
    if amount <= 0:
        await ctx.send(embed=Embed(title="❌ Ошибка", description="Количество должно быть больше нуля.", color=0xFF0000))
        return
    created_ids = grant_factories_to_user(str(member.id), amount)
    await refresh_open_factory_menus(str(member.id))
    await ctx.send(
        embed=Embed(
            title="✅ Заводы выданы",
            description=f"{member.mention} получил(а) **{len(created_ids)}** завод(ов).\nID: `{', '.join(created_ids[:20])}`",
            color=0x00FF00,
        )
    )


@bot.command(name="забрать-завод")
@admin_or_command_access()
async def забрать_завод(ctx, member: MemberQueryConverter, amount: int = 1):
    if amount <= 0:
        await ctx.send(embed=Embed(title="❌ Ошибка", description="Количество должно быть больше нуля.", color=0xFF0000))
        return
    existing = factories_data.setdefault("users", {}).setdefault(str(member.id), [])
    if not existing:
        await ctx.send(embed=Embed(title="❌ Заводов нет", description=f"У {member.mention} нет заводов.", color=0xFF0000))
        return
    removed_ids = take_factories_from_user(str(member.id), min(amount, len(existing)))
    await refresh_open_factory_menus(str(member.id))
    await ctx.send(
        embed=Embed(
            title="✅ Заводы забраны",
            description=f"У {member.mention} забрано **{len(removed_ids)}** завод(ов).\nID: `{', '.join(removed_ids[:20])}`",
            color=0x00FF00,
        )
    )


def available_factory_tech(member: discord.Member | None) -> list[dict]:
    """Return shop technologies that the player may produce by their licences."""
    role_ids = {str(role.id) for role in member.roles} if member else set()
    tech = []
    for key, item in items_data.setdefault("items", {}).items():
        if not isinstance(item, dict) or item.get("item_kind") != "tech":
            continue
        required_roles = {str(role_id) for role_id in item_required_role_ids(item)}
        if required_roles.issubset(role_ids):
            tech.append({**item, "key": str(key)})
    return sorted(tech, key=lambda item: str(item["key"]).casefold())


class FactoryProductionQuantityModal(Modal):
    def __init__(self, factory_id: str, item_key: str):
        self.factory_id = str(factory_id)
        self.item_key = str(item_key)
        item = items_data.setdefault("items", {}).get(self.item_key, {})
        batch = max(1, int(item.get("production_batch_min", item.get("min_production", 1)) or 1))
        super().__init__(title=f"Производство: {self.item_key}"[:45], timeout=300)
        self.qty = TextInput(
            label="Количество для производства",
            required=True,
            default=str(batch),
            placeholder=f"Минимум: {batch}",
        )
        self.add_item(self.qty)

    async def on_submit(self, interaction: Interaction):
        uid = str(interaction.user.id)
        factories = factories_data.setdefault("users", {}).setdefault(uid, [])
        factory = next((f for f in factories if str(f.get("id")) == self.factory_id), None)
        if not factory or factory.get("busy_until", 0) > int(time.time()):
            await interaction.response.send_message("❌ Завод не найден или занят.", ephemeral=True)
            return
        item = items_data.setdefault("items", {}).get(self.item_key)
        if not item or item.get("item_kind") != "tech":
            await interaction.response.send_message("❌ Выбранная техника больше недоступна.", ephemeral=True)
            return
        member = interaction.guild.get_member(interaction.user.id) if interaction.guild else None
        required_roles = {str(role) for role in item_required_role_ids(item)}
        member_roles = {str(role.id) for role in member.roles} if member else set()
        if not required_roles.issubset(member_roles):
            await interaction.response.send_message("❌ У вас нет обязательной роли-лицензии для этой техники.", ephemeral=True)
            return
        try:
            qty = int(str(self.qty.value).strip())
        except ValueError:
            await interaction.response.send_message("❌ Количество должно быть числом.", ephemeral=True)
            return
        batch = max(1, int(item.get("production_batch_min", item.get("min_production", 1)) or 1))
        if qty < batch or qty % batch != 0:
            await interaction.response.send_message(f"❌ Минимум производства — **{batch}**; количество должно быть ему кратно.", ephemeral=True)
            return
        try:
            configured_requirements = parse_production_requirements(
                item.get("required_item") or item.get("production_required_item"),
                item.get("required_quantity", item.get("production_required_quantity", 0)),
            )
        except ValueError as exc:
            await interaction.response.send_message(f"❌ Некорректные ресурсы техники: {exc}", ephemeral=True)
            return
        requirements = []
        for resource_query, per_batch in configured_requirements:
            matches = resolve_item_key(resource_query)
            if len(matches) != 1:
                await interaction.response.send_message(f"❌ Требуемый ресурс **{resource_query}** не найден или указан неоднозначно.", ephemeral=True)
                return
            resource_key = matches[0]
            required_total = (qty // batch) * per_batch
            if int(inventory.setdefault(uid, {}).get(resource_key, 0)) < required_total:
                await interaction.response.send_message(f"❌ Недостаточно **{resource_key}**. Нужно: **{required_total}**.", ephemeral=True)
                return
            requirements.append((resource_key, required_total))
        batches = qty // batch
        production_seconds = batches * max(1, int(item.get("production_seconds_per_batch", 3600) or 3600))
        requirement_text = ", ".join(f"**{need} × {resource}**" for resource, need in requirements) or "ресурсы не требуются"
        await interaction.response.send_message(
            f"Для производства **{self.item_key} x{qty}** потребуется: {requirement_text}. "
            f"Длительность: **{format_duration(production_seconds)}**. Вы уверены?",
            view=FactoryConfirmView(self.factory_id, self.item_key, qty, requirements, production_seconds),
            ephemeral=True,
        )


class FactoryProductionView(View):
    def __init__(self, owner_id: int, factory_id: str, tech: list[dict], page: int = 0):
        super().__init__(timeout=300)
        self.owner_id, self.factory_id, self.tech = int(owner_id), str(factory_id), tech
        self.page = max(0, min(page, max(0, math.ceil(len(tech) / 25) - 1)))
        self._build_items()

    def _page_tech(self) -> list[dict]:
        return self.tech[self.page * 25 : self.page * 25 + 25]

    def build_embed(self) -> Embed:
        lines = [format_shop_item_description(item, "производство") for item in self._page_tech()]
        pages = max(1, math.ceil(len(self.tech) / 25))
        return Embed(
            title="⚙️ Выбор техники для производства",
            description=("\n\n".join(lines) or "Нет доступной техники по вашим ролям-лицензиям.")[:4096],
            color=0x3498DB,
        ).set_footer(text=f"Страница {self.page + 1}/{pages}. Выберите технику в меню.")

    def _build_items(self):
        self.clear_items()
        options = [SelectOption(label=str(item["key"])[:100], value=str(item["key"])[:100]) for item in self._page_tech()]
        if options:
            select = Select(placeholder="Выберите технику для производства", options=options)
            select.callback = self.select_tech
            self.add_item(select)
        if len(self.tech) > 25:
            prev = Button(label="⬅️", style=ButtonStyle.secondary)
            next_ = Button(label="➡️", style=ButtonStyle.secondary)
            prev.callback = self.prev_page; next_.callback = self.next_page
            self.add_item(prev); self.add_item(next_)

    async def interaction_check(self, interaction: Interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True)
            return False
        return True

    async def select_tech(self, interaction: Interaction):
        selected = next((item for item in self.tech if str(item["key"]) == self.children[0].values[0]), None)
        if not selected:
            await interaction.response.send_message("❌ Техника не найдена.", ephemeral=True)
            return
        await interaction.response.send_modal(FactoryProductionQuantityModal(self.factory_id, str(selected["key"])))

    async def prev_page(self, interaction: Interaction):
        self.page = (self.page - 1) % max(1, math.ceil(len(self.tech) / 25)); self._build_items()
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

    async def next_page(self, interaction: Interaction):
        self.page = (self.page + 1) % max(1, math.ceil(len(self.tech) / 25)); self._build_items()
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

class FactoryConfirmView(View):
    def __init__(self, factory_id: str, item_key: str, qty: int, requirements: list[tuple[str, int]], production_seconds: int):
        super().__init__(timeout=120)
        self.factory_id, self.item_key, self.qty = factory_id, item_key, qty
        self.requirements = requirements
        self.production_seconds = max(1, int(production_seconds))

    async def on_error(self, interaction: Interaction, error: Exception, item: Button) -> None:
        logging.getLogger(__name__).exception("Ошибка кнопки подтверждения производства", exc_info=error)
        message = "❌ Не удалось запустить производство. Ошибка записана в лог бота."
        if interaction.response.is_done():
            await interaction.followup.send(message, ephemeral=True)
        else:
            await interaction.response.send_message(message, ephemeral=True)

    @discord.ui.button(label="Запустить производство", style=ButtonStyle.success)
    async def start(self, interaction: Interaction, button: Button):
        # Refreshing every open factory menu performs Discord API requests and
        # can take longer than the three-second component acknowledgement
        # window. Acknowledge first so the button never expires silently.
        await interaction.response.defer()
        uid = str(interaction.user.id)
        factories = factories_data.setdefault("users", {}).setdefault(uid, [])
        factory = next((f for f in factories if str(f.get("id")) == self.factory_id), None)
        if not factory or factory.get("busy_until", 0) > int(time.time()):
            await interaction.edit_original_response(content="❌ Завод уже занят.", view=None); return
        inv = inventory.setdefault(uid, {})
        for resource, need in self.requirements:
            if int(inv.get(resource, 0)) < need:
                await interaction.edit_original_response(content=f"❌ Ресурсов **{resource}** уже недостаточно.", view=None); return
        for resource, need in self.requirements:
            inv[resource] = int(inv.get(resource, 0)) - need
            if inv[resource] <= 0: inv.pop(resource, None)
        if self.requirements: save_inventory()
        item = items_data.setdefault("items", {}).get(self.item_key, {})
        batch = max(1, int(item.get("production_batch_min", item.get("min_production", 1)) or 1))
        cooldown, now = self.production_seconds, int(time.time())
        # next_unit_at is informational only; production completion is based on real time.
        factory.update({"status":"busy", "item_key":self.item_key, "quantity_total":self.qty, "quantity_done":0, "started_at":now, "busy_until":now+cooldown, "next_unit_at":now+cooldown, "production_seconds":cooldown, "batch_size":batch, "resource_requirements":dict(self.requirements)})
        save_factories_data()
        await refresh_open_factory_menus(uid)
        await interaction.edit_original_response(content=f"✅ Производство **{self.item_key} x{self.qty}** запущено на **{format_duration(cooldown)}**. Завод освободится <t:{now+cooldown}:R>.", view=None)

    @discord.ui.button(label="Отменить", style=ButtonStyle.danger)
    async def cancel(self, interaction: Interaction, button: Button):
        await interaction.response.edit_message(content="❌ Производство отменено.", view=None)


async def show_military_factories_menu(ctx, member: discord.Member, viewer_id: int | None = None):
    uid = str(member.id)
    view = MilitaryFactoriesView(uid, page=0)
    message = await ctx.send(**factory_page_payload(uid, 0, view=view))
    register_factory_menu(message, uid, page=0)


@bot.command(name="заводы")
async def заводы(ctx):
    """Open the same military-factories menu as the player menu."""
    await show_military_factories_menu(ctx, ctx.author, viewer_id=ctx.author.id)


def register_factory_menu(message: discord.Message, uid: str, *, page: int) -> None:
    """Track a factory-menu message while its five-minute controls are active."""
    FACTORY_MENU_SESSIONS[message.id] = {
        "message": message,
        "uid": str(uid),
        "page": max(0, int(page)),
        "expires_at": time.monotonic() + 300,
    }


async def refresh_open_factory_menus(uid: str) -> None:
    """Refresh active factory containers for a player after production changes."""
    now = time.monotonic()
    for message_id, session in list(FACTORY_MENU_SESSIONS.items()):
        if session["expires_at"] <= now:
            FACTORY_MENU_SESSIONS.pop(message_id, None)
            continue
        if session["uid"] != str(uid):
            continue
        factories = factories_data.setdefault("users", {}).setdefault(str(uid), [])
        page = max(0, min(int(session["page"]), max(0, len(factories) - 1)))
        try:
            await session["message"].edit(
                **factory_page_payload(str(uid), page, view=MilitaryFactoriesView(str(uid), page))
            )
            session["page"] = page
        except (discord.NotFound, discord.Forbidden):
            FACTORY_MENU_SESSIONS.pop(message_id, None)
        except discord.HTTPException:
            logging.getLogger(__name__).warning(
                "Не удалось обновить меню заводов для пользователя %s", uid,
                exc_info=True,
            )


def build_factory_page_text(uid: str, page: int = 0) -> str:
    factories = factories_data.setdefault("users", {}).setdefault(str(uid), [])
    if not factories:
        return "## 🏭 Военные заводы\n-# Заводов пока нет."
    page = max(0, min(int(page), len(factories) - 1))
    factory = factories[page]
    now = int(time.time())
    busy = int(factory.get("busy_until", 0) or 0) > now
    status = "занят" if busy else "свободен"
    total = max(0, int(factory.get("quantity_total", 0) or 0))
    done = max(0, int(factory.get("quantity_done", 0) or 0))
    production = f"{done} / {total}" if busy else "— / —"
    produced_tech = str(factory.get("item_key") or "не указана") if busy else "—"
    ready = f"<t:{int(factory.get('busy_until', 0))}:R>" if busy else "сейчас"
    return (
        f"## Завод No{factory.get('id')}\n\n"
        f"-# **Статус:** {status}\n"
        f"-# **Техника на производстве:** {produced_tech}\n"
        f"-# **Производство:** {production}\n"
        f"-# **Полная готовность:** {ready}\n\n"
        f"-# Страница {page + 1}/{len(factories)}"
    )


def factory_page_payload(uid: str, page: int = 0, *, view=None, notice: str | None = None):
    """Build a factory page response compatible with both component versions."""
    blocks = ([notice] if notice else []) + [build_factory_page_text(uid, page)]
    if view is None:
        view = MilitaryFactoriesView(uid, page=page, notice=notice)
    payload = send_payload_for_container(blocks, view=view)
    # ``silent`` is valid when sending a message, but the installed Discord
    # library does not accept it on InteractionResponse.edit_message() or
    # Message.edit().  Factory pages are also refreshed through both methods,
    # so exclude it from their shared payload.
    payload.pop("silent", None)
    return payload


def cancel_factory_production(uid: str, factory: dict) -> tuple[int, int, str]:
    """Cancel a job, retaining only completed production batches and their cost."""
    total = max(0, int(factory.get("quantity_total", 0) or 0))
    item = items_data.setdefault("items", {}).get(str(factory.get("item_key") or ""), {})
    batch = max(1, int(factory.get("batch_size") or item.get("production_batch_min", item.get("min_production", 1)) or 1))
    done = min(total, max(0, int(factory.get("quantity_done", 0) or 0)))
    # Old jobs may have accumulated individual units; a cancelled job keeps
    # only complete production minima.
    retained = (done // batch) * batch
    partial = done - retained
    if partial:
        item_key = str(factory.get("item_key") or "")
        produced_item = items_data.setdefault("items", {}).get(item_key)
        if produced_item is not None and int(produced_item.get("stock", 0) or 0) != -1:
            produced_item["stock"] = max(0, int(produced_item.get("stock", 0) or 0) - partial)

    total_batches = total // batch
    completed_batches = retained // batch
    remaining_batches = max(0, total_batches - completed_batches)
    configured_refunds = factory.get("resource_requirements")
    if isinstance(configured_refunds, dict):
        refunds = {str(resource): max(0, int(total)) * remaining_batches // max(1, total_batches) for resource, total in configured_refunds.items()}
    else:
        resource_item = str(factory.get("resource_item") or "")
        resource_per_batch = max(0, int(factory.get("resource_per_batch", 0) or 0))
        refunds = {resource_item: remaining_batches * resource_per_batch} if resource_item else {}
    refunds = {resource: amount for resource, amount in refunds.items() if amount > 0}
    for resource, amount in refunds.items():
        inventory.setdefault(str(uid), {})[resource] = int(inventory.setdefault(str(uid), {}).get(resource, 0)) + amount
    refund = sum(refunds.values())
    resource_item = ", ".join(refunds) or ""

    factory.update({
        "status": "free", "busy_until": 0, "quantity_done": retained,
        "next_unit_at": 0, "cancelled_at": int(time.time()),
    })
    return retained, refund, resource_item


class FactoryBuyConfirmView(View):
    def __init__(self, uid: str, price: int):
        super().__init__(timeout=120); self.uid=str(uid); self.price=int(price)
    async def interaction_check(self, interaction: Interaction):
        if str(interaction.user.id)!=self.uid:
            await interaction.response.send_message("❌ Это подтверждение не для вас.", ephemeral=True); return False
        return True
    @discord.ui.button(label="Да, купить завод", style=ButtonStyle.success, emoji="🏭")
    async def confirm(self, interaction: Interaction, button: Button):
        # See FactoryConfirmView.start: the shared-menu refresh can exceed
        # Discord's acknowledgement deadline.
        await interaction.response.defer()
        uid=str(interaction.user.id); price=int(self.price); bal=ensure_user(uid)
        factory_limit = get_puppet_limits(uid).get("factories")
        owned_factories = len(factories_data.setdefault("users", {}).setdefault(uid, []))
        if factory_limit is not None and owned_factories >= max(0, int(factory_limit)):
            await interaction.edit_original_response(content=f"❌ Владелец регистрации установил лимит: **{factory_limit}** военных заводов.", view=None); return
        if int(bal.get("наличка",0))<price:
            await interaction.edit_original_response(content=f"❌ Недостаточно средств. Нужно {fmt_money(price)}.", view=None); return
        bal["наличка"]-=price
        fid=str(factories_data.setdefault("next_id",1)); factories_data["next_id"]=int(fid)+1
        factories_data.setdefault("users",{}).setdefault(uid,[]).append({"id":fid,"status":"free","busy_until":0})
        save_json(BALANCES_FILE, balances); save_factories_data()
        await refresh_open_factory_menus(uid)
        await interaction.edit_original_response(content=f"✅ Завод `{fid}` куплен за {fmt_money(price)}.", view=None)
    @discord.ui.button(label="Отмена", style=ButtonStyle.danger)
    async def cancel(self, interaction: Interaction, button: Button):
        await interaction.response.edit_message(content="❌ Покупка завода отменена.", view=None)


class MilitaryFactoriesView(LayoutViewBase if container_components_available() else View):
    def __init__(self, uid: str, page: int = 0, *, timeout: int = 300, notice: str | None = None):
        super().__init__(timeout=timeout)
        self.uid = str(uid)
        factories = factories_data.setdefault("users", {}).setdefault(self.uid, [])
        self.page = max(0, min(int(page), max(0, len(factories) - 1)))
        busy = False
        if factories:
            busy = int(factories[self.page].get("busy_until", 0) or 0) > int(time.time())

        # Add the text container before action rows so Components V2 renders
        # the controls below the factory information instead of above it.
        blocks = ([notice] if notice else []) + [build_factory_page_text(self.uid, self.page)]
        add_v2_text_blocks(self, blocks)

        controls = (
            Button(label="⬅️", style=ButtonStyle.secondary),
            Button(label="➡️", style=ButtonStyle.secondary),
            Button(label="+ завод", style=ButtonStyle.primary, emoji="🏭"),
            Button(
                label="Прервать производство" if busy else "Запустить производство",
                style=ButtonStyle.danger if busy else ButtonStyle.success,
                emoji="⏹️" if busy else "⚙️",
                disabled=not bool(factories),
            ),
        )
        callbacks = (self.prev, self.next, self.buy, self.produce)
        for control, callback in zip(controls, callbacks):
            control.callback = callback
        if container_components_available() and V2ActionRow is not None:
            # A V2 action row can contain up to five buttons.  Keep the factory
            # controls in one row rather than letting add_v2_action_rows() put
            # every direct child into a separate row.
            row = V2ActionRow()
            for control in controls:
                row.add_item(control)
            self.add_item(row)
        else:
            for control in controls:
                self.add_item(control)
        # Buttons are added dynamically instead of via @discord.ui.button
        # because decorator-created items on LayoutView can be lost when moved
        # into Components V2 action rows.

    async def interaction_check(self, interaction: Interaction):
        if str(interaction.user.id) != self.uid:
            await interaction.response.send_message("❌ Это меню не для вас.", ephemeral=True); return False
        return True

    async def on_error(self, interaction: Interaction, error: Exception, item) -> None:
        """Acknowledge failed factory interactions and retain the traceback in logs."""
        logging.getLogger(__name__).exception("Ошибка кнопки меню военных заводов", exc_info=error)
        message = "❌ Не удалось выполнить действие с заводом. Ошибка записана в лог бота."
        if interaction.response.is_done():
            await interaction.followup.send(message, ephemeral=True)
        else:
            await interaction.response.send_message(message, ephemeral=True)

    async def refresh(self, interaction: Interaction):
        FACTORY_MENU_SESSIONS[interaction.message.id] = {
            "message": interaction.message,
            "uid": self.uid,
            "page": self.page,
            "expires_at": time.monotonic() + 300,
        }
        await interaction.response.edit_message(**factory_page_payload(self.uid, self.page, view=MilitaryFactoriesView(self.uid, self.page)))

    async def prev(self, interaction: Interaction):
        factories = factories_data.setdefault("users", {}).setdefault(self.uid, [])
        if factories:
            self.page = (self.page - 1) % len(factories)
        await self.refresh(interaction)

    async def next(self, interaction: Interaction):
        factories = factories_data.setdefault("users", {}).setdefault(self.uid, [])
        if factories:
            self.page = (self.page + 1) % len(factories)
        await self.refresh(interaction)

    async def buy(self, interaction: Interaction):
        uid = str(interaction.user.id); price = int(factories_data.get("price", 0) or 0); bal = ensure_user(uid)
        if int(bal.get("наличка", 0)) < price:
            await interaction.response.send_message(f"❌ Недостаточно средств. Нужно {fmt_money(price)}.", ephemeral=True); return
        await interaction.response.send_message(f"🏭 Купить военный завод за **{fmt_money(price)}**?", view=FactoryBuyConfirmView(uid, price), ephemeral=True)

    async def produce(self, interaction: Interaction):
        factories = factories_data.setdefault("users", {}).setdefault(self.uid, [])
        if not factories:
            await interaction.response.send_message("❌ Нет заводов.", ephemeral=True); return
        factory = factories[max(0, min(self.page, len(factories) - 1))]
        if int(factory.get("busy_until", 0) or 0) > int(time.time()):
            retained, refund, resource_item = cancel_factory_production(self.uid, factory)
            save_inventory()
            save_items()
            save_factories_data()
            refund_text = f" Возвращено: **{refund} × {resource_item}**." if refund else ""
            await interaction.response.edit_message(
                **factory_page_payload(
                    self.uid,
                    self.page,
                    view=MilitaryFactoriesView(self.uid, self.page, notice=(
                        f"⏹️ Производство прервано. Сохранено готовой техники: "
                        f"**{retained}**.{refund_text}"
                    )),
                    notice=(
                        f"⏹️ Производство прервано. Сохранено готовой техники: "
                        f"**{retained}**.{refund_text}"
                    ),
                )
            )
            return
        tech = available_factory_tech(interaction.user)
        if not tech:
            await interaction.response.send_message("❌ Нет доступной техники по вашим ролям-лицензиям.", ephemeral=True)
            return
        production_view = FactoryProductionView(interaction.user.id, str(factory.get("id")), tech)
        await interaction.response.send_message(embed=production_view.build_embed(), view=production_view, ephemeral=True)


@bot.command(name="остановить")
@admin_or_command_access()
async def остановить(ctx, member: MemberQueryConverter, duration: str):
    try:
        seconds = max(60, parse_interval(str(duration).strip()))
    except Exception as e:
        await ctx.send(embed=Embed(title="❌ Ошибка", description=f"Неверный срок: {e}", color=0xFF0000)); return
    uid = str(member.id); until = int(time.time()) + seconds
    st = ensure_player_state(uid); st["afk_until"] = until; st["afk_reason"] = f"остановлен {ctx.author.id}"
    save_player_state()
    await ctx.send(embed=Embed(title="⏸️ Игрок остановлен", description=f"{member.mention} переведён в AFK до <t:{until}:F> (<t:{until}:R>). Балансы, счастье, население, стрик, пассивы и команды заработка заморожены.", color=0xF1C40F))


@bot.command(name="возобновить")
@admin_or_command_access()
async def возобновить(ctx, member: MemberQueryConverter):
    uid = str(member.id); st = ensure_player_state(uid); st["afk_until"] = 0; st["afk_reason"] = ""
    now_ts = int(time.time())
    for entry in get_passive_entries(uid):
        entry["last_run"] = now_ts
    for entry in st.setdefault("stat_passives", []):
        entry["last_run"] = now_ts
    for entry in st.setdefault("population_passives", []):
        entry["last_run"] = now_ts
    save_player_state(); save_passive_flows()
    await ctx.send(embed=Embed(title="▶️ Игрок возобновлён", description=f"AFK-заморозка для {member.mention} снята.", color=0x00FF00))

